(window.GIM_TP=window.GIM_TP||{})["Yevamot.1"]={"from":203,"a":[[["רעה היא אצל צדיקים שנא' (בראשית לא, כד) השמר לך פן תדבר עם יעקב מטוב עד רע בשלמא רע לחיי אלא טוב אמאי לא אלא ש\"מ טובתן של רשעים רעה היא אצל צדיקים","בשלמא התם דלמא מדכר ליה שמא דעבודת כוכבים אלא הכא מאי רעה איכא","דקא שדי בה זוהמא דא\"ר יוחנן בשעה שבא נחש על חוה הטיל בה זוהמא ישראל שעמדו על הר סיני פסקה זוהמתן עובדי כוכבים שלא עמדו בהר סיני לא פסקה זוהמתן:","חלצה במנעל שאינו שלו וכו': תנו רבנן נעלו אין לי אלא נעלו נעל של כל אדם מנין ת\"ל נעל נעל מכל מקום","א\"כ מה ת\"ל נעלו נעלו הראוי לו פרט לגדול שאין יכול להלוך בו ופרט לקטן שאינו חופה רוב רגלו ופרט לסנדל המסוליים שאין לו עקב","אביי הוה קאי קמיה דרב יוסף אתאי יבמה לחלוץ אמר ליה הב ליה סנדלך יהיב ליה סנדלא דשמאלא א\"ל אימר דאמור רבנן דיעבד לכתחלה מי אמר","א\"ל אי הכי סנדל שאין שלו נמי אימר דאמור רבנן דיעבד לכתחלה מי אמור א\"ל הכי קאמינא לך הב ליה ואקני ליה:","סנדל של עץ: מאן תנא אמר שמואל ר\"מ היא דתנן הקיטע יוצא בקב שלו דברי ר\"מ ר' יוסי אוסר אבוה דשמואל אומר במחופה עור ודברי הכל:","אמר רב פפי משמיה דרבא סנדל המוסגר לא תחלוץ בו ואם חלצה חליצתה כשרה סנדל המוחלט לא תחלוץ בו ואם חלצה חליצתה פסולה","רב פפא משמיה דרבא אמר אחד סנדל המוסגר ואחד סנדל המוחלט לא תחלוץ בו ואם חלצה חליצתה כשרה","מיתיבי בית המוסגר מטמא מתוכו מוחלט מתוכו ומאחוריו וזה וזה מטמאין בביאה","ואי ס\"ד כדמכתת דמי והא בעינן (ויקרא יד, מו) והבא אל הבית וליכא","שאני התם דאמר קרא (ויקרא יד, מה) ונתץ את הבית אפילו בשעת נתיצה קרוי בית","ת\"ש מטלית שיש בו שלש על שלש אף על פי שאין בו כזית כיון שנכנס רובה לבית טהור טמאתהו מאי לאו מוחלטת לא מוסגרת","אי הכי אימא סיפא היו בה כמה זיתים כיון שנכנס ממנה כזית לבית טהור טמאתהו","אי אמרת בשלמא מוחלטת היינו דאיתקש למת אלא אי אמרת מוסגרת אמאי איתקש למת","שאני התם דאמר קרא (ויקרא יג, נב) ושרף את הבגד אפילו בשעת שריפה קרוי בגד","וליגמר מיניה איסור מטומאה לא גמרינן","אמר רבא הלכתא אחד סנדל המוסגר ואחד סנדל שמוחלט ואחד סנדל של עבודת כוכבים לא תחלוץ ואם חלצה חליצתה כשרה של תקרובת עבודת כוכבים"],[[0,"רעה היא","ששונאים הרשעים וקצה נפש צדיק בהנאתן הלכך לאו הנאה היא:"],[1,"שמא דעבודת כוכבים","למה גנבת את אלהי (בראשית ל״א:ל׳):"],[3,"נעל מ\"מ","חלוץ הנעל:"],[4,"פרט לסנדל המסוליים","הנפחת שאין לו עקב שול\"א. לישנא אחרינא על שם מקומו נקרא מסוליים לשון מור\"י:"],[5,"הב ליה סנדלך","ליבם ותחלוץ בו:"],[5,"יהיב ליה דשמאלא","במתכוין עבד דלא סבירא ליה לאביי דסנדל שאין שלו מותר לכתחלה:"],[5,"אמר ליה","רב יוסף אימר דאמור רבנן במתניתין בשל שמאל בימין חליצתה כשרה דיעבד לכתחלה מי אמור:"],[6,"הב ליה ואקני ליה","שיהא שלו במתנה:"],[7,"סנדל של עץ","דקתני מתני' חליצתה כשרה מני:"],[7,"רבי מאיר היא","דאמר קב הקיטע נעל הוא לצאת בו בשבת:"],[8,"סנדל המוסגר","שפרחה בו הצרעת לא תחלוץ בו בימי הסגרו דלא ליתי למיעבד במוחלט:"],[8,"ואם חלצה חליצתה כשרה","דלאו בר שריפה הוא ושיעוריה קאי:"],[8,"מוחלט חליצתה פסולה","דלשריפה קאי ואנן שיעורא בעינן חופה את רוב רגלו והאי כתותי מיכתת שיעוריה:"],[10,"מטמא מתוכו","במגע ואע\"ג דלא נכנס גופו לתוכו דלהוי טמא משום בא אל הבית אם נגע בכותל מטמא:"],[10,"והמוחלט","מטמא אף מאחוריו:"],[10,"מטמאין בביאה","אם נכנס דרך ביאה כיון שנכנס רובו לתוכו טמא משום והבא אל הבית. ומקראי נפקא לן בתורת כהנים דמוסגר מטמא מתוכו ולא מן אחוריו ובמוחלט כתיב טמא הוא הוסיף לו טומאה אחרת לומר לך שמטמא מאחוריו:"],[13,"מטלית","בגד המנוגע:"],[13,"שלש על שלש","הוי בגד דחזי לעניים:"],[13,"שאין בה כזית","שחוטה דק:"],[13,"כיון שנכנס רובה לבית טהור טמאתהו","טימאה את כל כלי הבית דמצורע מטמא בביאה וכן בגד ואבן המנוגעת כולן מטמאים באהל והא כיון דעל רובה ככולה דמיא:"],[13,"מאי לאו מוחלטת","ואפילו הכי אמרת שדי מיעוטא בתר רובא והוה ליה כמאן דעיילא כולה ואי כמאן דמכתתא דמיא זיל בתר מה דעייל ואין בבית ג' על ג':"],[14,"היו בה כמה זיתים","ואין בה אלא ג' על ג' אלא שחוטה עבה כיון שנכנס הימנה כזית לבית טימאתו ואע\"פ שאין כאן בגד דהא לא על רובה:"],[15,"אי אמרת בשלמא מוחלטת","היינו דמטמא בכזית אפילו אין כאן בגד שלש על שלש משום דמוחלט איתקש למת ומת מטמא בכזית והיכא איתקש דכתיב אל נא תהי כמת שמרים מוסגרת הואי וקאמר ליה אהרן למשה אל נא תחלט שלא תהא כמת:"],[16,"הכי גרסי' אלא שאני התם כו'","ולעולם במוחלט ומשום הכי שדינן מיעוטא בתר רובא לענין טומאה ולא אמרי' כמאן דמכתת דמי דכתיב ושרף:"],[17,"וליגמר מיניה","לענין חליצה להיות חשוב שלם:"],[17,"איסורא מטומאה לא גמרינן","שהלכות טומאה חדוש הוא:"],[18,"של עבודת כוכבים","שנועלים אותו לצלם ברגליו כשמסיעין אותו ממקום למקום:"],[18,"חליצתה כשרה","מוחלט כדאמרן שאפילו בשעת שריפה קרוי בגד ולאו מילף הוא אלא גילוי מילתא בעלמא הוא ושל עבודת כוכבים נמי הואיל להילוכא עביד ומשמשי עבודת כוכבים לאו לשריפה קיימי דאית להו תקנתא בביטול ואי משום איסור הנאה חליצה לאו הנאה היא דמצות לאו ליהנות ניתנו:"],[18,"של תקרובת עבודת כוכבים","שהקריבו ומסרוהו לפניו לשם דורון וקי\"ל (ע\"ז דף נ.) תקרובת עבודת כוכבים אין לה ביטול עולמית דאיתקש למת דכתיב ויאכלו זבחי מתים הלכך לית ליה תקנתא וכתותי מיכתת שיעורא:"]],[[3,"ת\"ל נעל מ\"מ","אע\"ג דדרשינן ליה לעיל דלא נימא תחש אין מידי אחרינא לא שקולים הם ויבואו שניהם וא\"ת והיכי דרשינן הנך דרשות מנעל הא איצטריך לגופיה שצריך לקרוא חלוץ הנעל ויש לומר דדרשינן שפיר ממה שצריך לקרות דה\"נ דרשינן במתניתין (לקמן יבמות דף קד:) מככה עיכובא אע\"ג שהוא עיקר קריאה:"],[4,"שאין חופה את רוב הרגל","אבל הכא לא סגי בשמיטת רוב עקב דאין קרוי מנעל אלא כשחופה רוב הרגל אבל לענין חליצה סגי בשמיטת רוב העקב כדאמר לעיל (יבמות דף קב.) דחשיב שפיר גילוי כרעיה בהכי:"],[4,"המסוליים","שם סנדל אחד כן דאמר בירושלמי ר' יהושע בן לוי נפק בסולייא בלילי צומא רבה ואמרינן נמי (מדרש רבה ש\"ה) מה שעשתה חכמה עטרה לראשה עשתה ענוה עקב לסולייתא דכתיב ראשית חכמה יראת ה' וכתיב עקב ענוה יראת ה' וגו' והא דאמר במדרש (שם) ג' דברים שקולים זה כזה חכמה יראה ענוה אר\"י דשקולים היינו דהא בלא הא לא סגי אבל ענוה גדולה מכולן:"],[10,"מטמא מאחוריו","פי' אם נגע בנגע מאחוריו של בית ומיהו מספקא לר\"י בבית מוסגר אם נגע בנגע שמתוכו בלא ביאה אי חשיב כאחוריו דמוחלט דמטמא בנגיעה או שמא גרע ומתוכו דמוסגר היינו שנכנס כולו לבית כדפירש בקונטרס ובת\"כ דריש כנגע נראה לי בבית מתוכו מטמא ואין מטמא מאחוריו והאי קרא במוסגר כתיב משמע שדורש דנגע הנולד בתוך הבית מטמא ולא הנולד מאחוריו:"],[13,"כיון שנכנס רובו לבית טהור טמאתו","אמר ר\"י אע\"פ שלא ישב שם אלא שהכניסה והוציאה טמא ואע\"ג דתנן ומייתינן לה בפרק קמא דקידושין (דף לג:) טמא עובר תחת האילן וטהור יושב טהור היינו דוקא גבי אילן שאין שם מחיצות בעינן שיהא יושב כדכתיב בדד ישב אבל בבית דאיכא מחיצות כאילו יושב תחתיו הטמא ומטמא הבית ואם תאמר דהכא משמע דמצורע מטמא באוהל ובריש מסכת כלים (פ\"א מ\"ד) אמר למעלה מהן מת שמטמא באהל מה שאין כולן מטמאין והתם לעיל חשיב מצורע בהדייהו ואמר רבינו יהודה דמ\"מ מת חמור דאפילו עובר תחת האילן מטמא באהל כל מה שתחת האילן ועוד דמת חמור שמטמא אפי' מה שבבית אחר אם יש בו חלון פותח טפח מה שאין כן במצורע דאין מטמא אלא בבית שנכנס בו דכתיב והבא אל הבית:"],[18,"סנדל של עבודת כוכבים לא תחלוץ","פי' בקונט' דמיירי בעבודת כוכבים של עובד כוכבים וקודם ביטול דכיון דראוי לבטל לא מכתת שיעוריה אף על פי שלא נתבטל עדיין וכן פי' בפ' ראוהו ב\"ד (ר\"ה כח.) גבי שופר של עבודת כוכבים לא יתקע ואם תקע יצא ותימה דאמרי' בסוף פרק כסוי הדם (חולין פט. ושם) שופר של עבודת כוכבים לא יתקע בו ואם תקע לא יצא ומפרש התם משום דעבודת כוכבים כתותי מכתת שיעוריה וי\"ל דהתם בעבודת כוכבים של ישראל דלא סגי לה בבטול דכי האי גוונא משני בפרק לולב הגזול (סוכה לא: ושם) אהא דאמר רבא לולב של עבודת כוכבים לא יטול ואם נטל יצא ופריך ממתני' דלולב של אשרה פסול ומשני באשרה של משה וא\"ת אי בעבודת כוכבים של ישראל מאי קאמר דמכתת שיעוריה והא טעונה גניזה דמפיק לה בפ' רבי ישמעאל (ע\"ז דף נב:) מושם בסתר וי\"ל כיון דטעונה גניזה אין כתותי שיעור גדול מזה א\"נ בעבודת כוכבים של עובד כוכבים שעבדה לדעת ישראל שטעונה שריפה וא\"ת ובעבודת כוכבים דעובד כוכבים מכי אגבה הויא דישראל כדאמר בפרק כל הצלמים (עבודה זרה דף מב.) גזירה דלמא מגבה לה והדר מבטל לה וי\"ל כגון שהגביה השופר והסנדל על מנת שלא לקנותו דהא תנן (לעיל יבמות דף קא.) במנעל שאינו שלו חליצתה כשירה ולולב איירי ביו\"ט שני ובסוכה הוה מצי לשנויי דאיירי ביו\"ט ראשון ולא הוה צריך לאוקומי באשרה דמשה אלא משום דקתני אשרה דומיא דעיר הנדחת דאפילו ביו\"ט שני והא דנקט בסנדל של תקרובת עבודת כוכבים חליצתה פסולה הוה מצי למנקט סנדל עבודת כוכבים של ישראל אלא ניחא ליה למנקט כוליה מילתא בעבודת כוכבים של עובד כוכבים ור\"ת מפרש דכולהו בעבודת כוכבים דעובד כוכבים והכא לאחר ביטול והתם קודם ביטול ולאחר ביטול נמי לכתחלה לא יתקע ולא יחלוץ דמאיס לענין מצוה לפי שהיה עליו שם עבודת כוכבים אפילו אם תמצא לומר דשרי לכסות בעפר של עבודת כוכבים לכתחילה כמו בשל עיר הנדחת לא דמיא כסוי לחליצה דלענין כסוי לא חיישי' למיאוס והא דמשני בסוכה מתני' באשרה דמשה ולא משני בדעובד כוכבים וקודם בטול משום דאפילו נקצץ לולב מן הדקל נתבטל והא דקתני בסוף פ' כסוי הדם (חולין דף פט. ושם) דלולב של עבודת כוכבים אם נטל לא יצא איירי שהלולב בעצמו (של) עבודת כוכבים אבל לולב של אשרה משמע שנלקט מן האשרה והכי הוי מצי למנקט בסמוך דאם חלצה קודם בטול פסול וליפלוגי בשל עבודת כוכבים עצמה אלא אגב אורחיה אתא לאשמועינן דתקרובת עבודת כוכבים אינה בטילה עולמית ואם תאמר כיון דבבטלה איירי רבא מאי קמבעיא ליה לר\"ל בפרק כל הצלמים (ע\"ז מז.) דקל של עבודת כוכבים שבטלו לולבו מהו למצוה תפשוט מדרבא דסוכה לכתחלה לא יטול ואם נטל יצא וי\"ל דלרבא פשיטא ליה ולריש לקיש מיבעיא ליה אע\"ג דפשיטא ליה התם מר' יוחנן רביה מכל מקום מדרבא לא בעי למפשט:"]]],[["ושל עיר הנדחת ושל זקן העשוי לכבודו לא תחלוץ ואם חלצה חליצתה פסולה","א\"ל רבינא לרב אשי מאי שנא זקן העשוי לכבודו דלאו להילוכא עביד דבי דינא נמי לאו להילוכא עביד","א\"ל אילו מסגי ביה שלוחא דבי דינא מי קפיד עליה דיינא:","\u0001מתני׳\u0002 חלצה בלילה חליצתה כשרה ורבי אלעזר פוסל בשמאל חליצתה פסולה ור' אלעזר מכשיר:","\u0001גמ׳\u0002 לימא בהא קמיפלגי דמר סבר מקשינן ריבים לנגעים ומר סבר לא מקשינן ריבים לנגעים","לא דכ\"ע לא מקשינן ריבים לנגעים דאי מקשינן אפילו גמר דין בלילה נמי לא והכא בהא קמיפלגי מר סבר חליצה כתחלת דין דמיא ומר סבר חליצה כגמר דין דמיא","רבה בר חייא קטוספאה עבד עובדא במוק וביחידי ובלילה אמר שמואל כמה רב גובריה דעביד כיחידאה","מאי קשיא אי מוק סתמא תניא אי לילה סתמא תניא","אלא יחידי קא קשיא ליה היכי עביד ביחידי דיחידאה קתני לה דתנן חלצה בשנים או בשלשה ונמצא אחד מהן קרוב או פסול חליצתה פסולה ור\"ש ורבי יוחנן הסנדלר מכשירים ומעשה באחד שחלץ בינו לבינה בבית האסורים ובא מעשה לפני ר\"ע והכשיר","ואמר רב יוסף בר מניומי אמר רב נחמן אין הלכה כאותו הזוג ואב\"א כולהו נמי יחידאה קתני להו דתניא א\"ר ישמעאל בר' יוסי אני ראיתי את רבי ישמעאל בן אלישע שחלץ במוק ביחידי ובלילה:","בשמאל חליצתה כו': מ\"ט דרבנן אמר עולא ילפינן רגל (ויקרא יד, יד) רגל ממצורע מה להלן דימין אף כאן דימין","ורבי אלעזר לא יליף רגל רגל ממצורע והתניא ר\"א אומר מנין לרציעה שהיא באזן הימנית נאמר כאן אזן ונאמר להלן אזן מה להלן ימין אף כאן ימין","אמר רב יצחק בר יוסף אמר ר' יוחנן מוחלפת השיטה","רבא אמר לעולם לא תיפוך אזן אזן מופני רגל רגל לא מופני","וכי לא מופני מאי פירכא איכא איכא למיפרך מה למצורע שכן טעון עץ ארז ואזוב ושני תולעת:","\u0001מתני׳\u0002 חלצה ורקקה אבל לא קראה חליצתה כשרה קראה ורקקה אבל לא חלצה חליצתה פסולה חלצה וקראה אבל לא רקקה רבי אלעזר אומר חליצתה פסולה ר\"ע אומר חליצתה כשרה"],[[0,"ושל עיר הנדחת","נמי לשריפה קיימא:"],[0,"ושל זקן העשוי לכבודו","לתכריכי מיתה הואיל ולאו להילוכא עביד לאו נעל הוא:"],[1,"דבי דינא נמי","סנדל שהיה לב\"ד ומיוחד לחליצה:"],[4,"לנגעים","כל ריב וכל נגע (דברים כ״א:ה׳) מה נגעים ראייתם ביום דכתיב (ויקרא י״ג:י״ד) וביום הראות בו אף ריבים ביום וחליצה דין הוא דגובה כתובתה:"],[5,"אפי' גמר דין נמי לא","ואנן תנן דיני ממונות דנין ביום וגומרים בלילה (סנהדרין ד' לב.):"],[5,"כתחלת דין דמיא","דנפקא לן בסנהדרין באחד דיני ממונות (סנהדרין דף לד:) דתחלת דין ביום:"],[6,"במוק","אע\"פ שאינו של עור:"],[6,"כמה רב גובריה","בלשון גנאי אמרה:"],[7,"אי מוק סתמא תניא","בברייתא דלעיל (יבמות דף קב:) בקב הקיטע במוק בסמיכת הרגלים:"],[7,"לילה סתמא תנינא","במתניתין חליצתה כשרה:"],[8,"ביחידי יחידאה תני לה","במתני' דתנן ובא מעשה לפני רבי עקיבא והכשיר:"],[11,"רגל רגל ממצורע","דכתיב על בהן רגלו הימנית (ויקרא י״ד:י״ד):"],[11,"ונאמר להלן אזן","במצורע:"],[13,"אזן אזן מופנה","משני צדדין בין במצורע בין בנרצע דקרא דמצורע עני מיותר לגמרי כדאמרן במנחות בפ\"ק (דף י:) יד יד לקמיצה רגל רגל לחליצה אזן אזן לרציעה וגבי רציעה תרי אזנו כתיבי ורצע אדניו את אזנו (שמות כ״א:ו׳) ונתת באזנו ובדלת (דברים ט״ו:י״ז):"],[13,"לא מופני","משני צדדין אלא מצד אחד דמצורע מיותר אבל בחליצה לא וליכא אלא חד וקסבר ר' אלעזר מופנה מצד אחד למדים אם אין תשובה ואם יש להשיב משיבין:"],[14,"וכי לא מופני מאי פירכא איכא","מופנה מצד אחד למדין ומשיבין והכא מאי פירכא איכא. ומהכא נפקא לן בכל דוכתא לר' אלעזר מופנה מצד אחד למדין ומשיבין (שבת דף קלא.):"],[15,"מתני' חליצתה כשרה","דקריאה לא מעכבא דכתיב ככה יעשה כל דבר שהוא מעשה מעכב דכי כתיב ככה דמשמע עיכובא אמעשה כתיב וקרייה דבורא בעלמא הוא:"]],[[5,"מר סבר חליצה כתחלת דין דמיא","לכך פסולה ובירושלמי בפרק אחד דיני ממונות גרסינן מנין שדנין ביום וגומרים בלילה שנאמר ושפטו את העם בכל עת ופריך אית קרא לשעבר אלא מנין שאם טעו ודנו בלילה שדינם דין ת\"ל ושפטו את העם בכל עת וגו' דומה שהוא טעות ועוד דלא פריך שפיר אגומרין בלילה ואית קרא לשעבר אלא גרסינן איפכא מנין שטעו ודנו בלילה שדינן דין שנאמר ושפטו את העם בכל עת ואית קרא לשעבר אלא מנין שגומרין בלילה וכו' וגמרא שלנו (סנהדרין דף לד:) מוקי נמי האי קרא לגומרין בלילה והרבה דברים יש בירושלמי שצריך להפכם:"],[7,"אי מוק סתמא תניא","הוה מצי למיפרך אימור דאמרי רבנן בדיעבד לכתחלה מי אמור אלא פריך אדשמואל שלא הקפיד אלא על מה שעשה כיחידאה ומסיק כרבי ישמעאל בן אלישע והוא עשה כן לכתחלה:"],[8,"אמר רבי ישמעאל בן רבי יוסי אני ראיתי את רבי ישמעאל בן אלישע","כך כתוב בספרים וקשיא לר\"י איך יתכן שראה רבי ישמעאל בן רבי יוסי את רבי ישמעאל בן אלישע שנהרג קודם רבי עקיבא ורבי ישמעאל כפוף ויושב לפני רבי ויום שמת ר\"ע נולד רבי ומיהו אין למחוק הספרים בשביל כך כי מה בכך שרבי ישמעאל ברבי יוסי היה כפוף ויושב לפני רבי כי גם רבי יוסי אביו אילו היה קיים היה כפוף ויושב לפני רבי ולמאי דפירש ר\"י דתרי רבי ישמעאל בן אלישע הוו אתי שפיר דאותו שנהרג היה זקנו של אותו רבי ישמעאל בן אלישע שראוהו רבי ישמעאל בן רבי יוסי דאפשר שחיה הרבה אחר רבי עקיבא:"]]],[["אמר ליה רבי אלעזר (דברים כה, ט) ככה יעשה כל דבר שהוא מעשה מעכב א\"ל רבי עקיבא משם ראיה ככה יעשה לאיש כל דבר שהוא מעשה באיש","החרש שנחלץ והחרשת שחלצה וחולצת לקטן חליצתה פסולה קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה חלצה בשנים או בשלשה ונמצא אחד מהן קרוב או פסול חליצתה פסולה רבי שמעון ורבי יוחנן הסנדלר מכשירין ומעשה באחד שחלץ בינו לבינה בבית האסורים ובא מעשה לפני רבי עקיבא והכשיר:","\u0001גמ׳\u0002 אמר רבא השתא דאמרת קריאה לא מיעכבא לפיכך אלם ואלמת שחלצו חליצתן כשירה","תנן חרש שנחלץ והחרשת שחלצה והחולצת מן הקטן חליצתה פסולה מ\"ט לאו משום דלא בני קרייה נינהו לא משום דלאו בני דעה נינהו","אי הכי אלם ואלמת נמי אמר רבא אלם ואלמת בני דעה נינהו ופומייהו הוא דכאיב להו","והא אמרי דבי רבי ינאי לפי שאינו באמר ואמרה אלא כי אתמר דרבא אסיפא אתמר חרש שנחלץ והחרשת שחלצה והחולצת מן הקטן חליצתה פסולה","אמר רבא השתא דאמרת קרייה מעכבא לפיכך אלם ואלמת שחלצו חליצתן פסולה ומתניתין כר' זירא","דאמר ר' זירא כל הראוי לבילה אין בילה מעכבת בו וכל שאין ראוי לבילה בילה מעכבת","שלחו ליה לאבוה דשמואל יבמה שרקקה תחלוץ מכלל דאיפסלא לה מאחין","מני אילימא ר' עקיבא השתא ומה במקום מצוה דאיכא למימר מידי דהוה אאימורים דכי ליתנהו לא מעכבי","וכי איתנהו מעכבי","אמר ר\"ע לא מעכבא מאחין איפסלא","ואלא לר' אלעזר","והא שני דברים המתירין נינהו ושני דברים המתירין אין מעלין זה בלא זה","אלא כרבי דתניא כבשי עצרת אין מקדשין הלחם אלא בשחיטה","כיצד שחטן לשמן וזרק דמן לשמן קדש הלחם שחט שלא לשמן וזרק לשמן לא קדש הלחם שחטן לשמן וזרק דמן שלא לשמן קדוש ואינו קדוש דברי רבי","ר' אלעזר בר\"ש אומר לעולם אינו קדוש עד שישחוט לשמן ויזרוק דמן לשמן","ומי אמר ר' עקיבא רקיקה לא פסלה והתניא חלצה ולא"],[[0,"כל דבר שמעשה","ורקיקה מעשה היא:"],[0,"מעשה באיש","חליצה שהאשה עושה מעשה בגופו של איש לאפוקי רקיקה דלאו מעשה באיש הוא:"],[1,"החרש שחלץ חליצתו פסולה","לפוטרה במקום אח כשר:"],[1,"וחרשת שחלצה חליצתה פסולה","היא עצמה אינה נפטרת בחליצתה כדאמרי' לקמן בפ' ב\"ש (יבמות דף קי.) ואין לה תקנה אלא בייבום ואם רצה להוציא יוציא בגט:"],[1,"חלצה בשנים","כשרים או בג' ונמצא אחד מהן קרוב דהדר הוו להו שנים חליצתו פסולה:"],[1,"ורבי שמעון ור' יוחנן הסנדלר מכשירים","ול\"ג בשנים דהא בשנים עסיק נמי ת\"ק:"],[2,"גמ' אלם ואלמת","שחלצו חליצתן כשרה:"],[5,"והאמרי דבי רבי ינאי","ומפרש טעמא דמתני' דחרש וחרשת מפני שאינן בואמר ואמרה דתנן (תרומות פ\"א מ\"ב) חרש שדברו חכמים בכל מקום שאינו לא שומע ולא מדבר:"],[5,"","ועמד ואמר וענתה ואמרה:"],[5,"חליצתה פסולה","ומתני' דקתני לא קראה חליצתה כשירה כר' זירא דא\"ר זירא בפרק המנחות והנסכים (מנחות קג:) כל הראוי לבילה כו' דקתני האומר הרי עלי ס\"א עשרונים מביא ס' בכלי אחד ואחד בכלי אחר ומפרש טעמא משום דקים להו לרבנן דששים נבללות בכלי אחד אבל ס\"א אינן נבללות יפה ומותבינן וכי אין נבללין מאי הוי והתנן (שם יח.) אם לא בלל כשר ומשני רבי זירא הראוי לבילה אין בילה מעכבת בו דאפילו לא בלל כשר ושאין ראוי לבילה בילה מעכבת בו דראוי לבילה בעינן דאפשר להתקיים בה מצות מנחה והכא נמי אע\"ג דקרייה לא מעכבא בראוי לקרייה אבל בשאין ראוי מעכבת:"],[8,"יבמה שרקקה","לפני ב\"ד:"],[8,"תחלוץ","דנפסלת עליהן מייבום:"],[9,"במקום מצוה","בשעת חליצה שהרקיקה מצוה:"],[9,"אאימורים דכי איתנהו מעכבי","בשר מאכילה בפ' תמיד נשחט (פסחים נט:) וכי ליתנהו לא מעכבי כגון שנטמאו או שאבדו והכא נמי נימא אע\"ג דלאו מעשה חשוב באיש הוא הואיל ואפשר לרוק ליעכב וקאמר רבי עקיבא לא מעכבא:"],[12,"אלא לר' אלעזר","דאמר במתני' מעכבא אלמא מעשה הוא:"],[13,"","ה\"ג והא שני דברים המתירין אין מעלין זה בלא זה:"],[14,"אין מקדשין שתי הלחם","להיות קדוש קדושת הגוף ליפסל ביוצא ולינה אלא בשחיטה ואע\"פ שהן טעונין תנופה חיין עם הלחם אין תנופתן מקדשן אלא שחיטתן דגמר מאיל נזיר דכתיב (במדבר ו׳:י״ז) ואת האיל יעשה זבח שלמים לה' על סל המצות תלה הכתוב עשיית סל המצות בזביחת האיל בפ' התכלת:"],[15,"","כיצד ל\"ג:"],[15,"","לחם קדוש ליפסל ביוצא ואין קדוש להיות ניתר באכילה:"]],[[0,"ככה יעשה דבר שהוא מעשה מעכב","וא\"ת ולמ\"ד (סנהדרין דף סה:) דעקימת פיו הוי מעשה היכי ממעטינן קריאה וי\"ל דמ\"מ מעשה גרוע הוא יותר מרקיקה אי נמי לא דמי למנהיג בקול שהוא מעשה גדול:"],[5,"והא אמרי דבי רבי ינאי לפי שאינו באמר ואמרה","וא\"ת מנא ליה לרבי ינאי האי טעמא דלמא משום דלאו בני דעה נינהו ותניא (לקמן יבמות דף קו.) דבעינן שיתכוונו שניהם ואמאי נמי אמרינן לקמן (יבמות דף קה:) דקטנה חולצת בפעוטות וקטן נמי הוה חליץ אי לאו דאיש כתיב בפרשה כיון דלאו בני דעה נינהו וי\"ל שב\"ד עומדים על גבם ומורים להם לעשות חליצה כתיקנה דהכי נמי אמרינן בפרק ב' דגיטין (דף כב: ושם) דחש\"ו שכתבו גט וגדול עומד על גבם דכשר ומיהו לענין חליצה שוטה לא חליץ אע\"ג דב\"ד עומדים ע\"ג כדאמר בתוספתא לפי שיש בחליצה רבויי דברים ואין בו דעת כלל לעשות לדעת ב\"ד אבל גבי גט שנוח לעשות כי גדול עומד ע\"ג כשר ומחשבתו ניכרת מתוך מעשיו שכותב הגט לשמה שכותב שם האיש והאשה והזמן ושם עירו ושם עירה והא דאמר בפ\"ק דחולין (דף יב: ושם) גבי וכולן ששחטו ואחרים רואין אותן שחיטתן כשירה ומוקי לה כר' נתן דלא בעי כוונה לשחיטה משמע דלרבנן דבעו כוונה לשחיטה לא מהני גדול עומד ע\"ג דהתם אחרים אין מלמדים אותו אך שראוהו שלא קלקל וגם אין מחשבתו ניכרת מתוך מעשיו כמו חליצה דאין מתכוין אלא לחיתוך בשר בעלמא כדאמר בפ\"ק דחולין (דף יג.) דבעינן מחשבתו ניכרת מתוך מעשיו:"],[7,"דאמר רבי זירא כל הראוי לבילה כו'","מילתיה דר' זירא בפ' המנחות והנסכים (מנחות קג: ושם) גבי ששים ואחד אין נבללים ופריך וכי לא בלל מאי הוי והתנן (שם דף יח.) אם לא בלל כשר וא\"ת מאי קשה והא לכתחלה בעינן בילה ואומר ר\"י דשאני התם כיון דאמר הרי עלי מנחה ס\"א עשרון לקרבן גדול קמכוין ולכך היה לו לעשות הכל בכלי אחד אם בדיעבד כשר בלא בלילה ודוקא כי אמר הרי עלי מנחה אמרינן דלקרבן גדול קמיכוין אבל סתם בלא מנחה לא משמע קביעות בחד מנא כדתנן התם (דף קב:) הרי עלי שני עשרונים להביא בכלי אחד והביא בשני כלים פסול משמע דאם אמר סתם ולא אמר בכלי אחד יכול להביא בשני כלים וא\"ת מנא ליה דאם לא בלל דכשר אימא לא בלל כהן אלא זר אבל לא בלל כלל פסולה דהכי נמי אמרינן בהקומץ רבה (מנחות דף יח. ושם) לא יצק כשר ומפרש דהיינו לא יצק כהן אלא זר וי\"ל דקבלה היה לו דאפילו לא בלל כלל דליכא עיכובא וא\"ת ואמאי לא מעכבת והלא בכמה מקומות כתיב (ויקרא ב׳:ד׳) בלולה במנחת מאפה תנור ושל מחבת ובמנחת נסכים (במדבר טו) כתיב טובא בלולה וכן בקרבן נשיאים תריסר זימני וי\"ל דלא משמע ליה עיכובא כיון דלא כתיב ויבלול לשון צווי וצ\"ע אם יש עיכובא בעלמא בכה\"ג א\"נ כולהו צריכי לשום דרשה וא\"ת מנא ליה דמעכבא בשאין ראוי לבילה וי\"ל דסברא הוא דכתיב בלולה ואמר רחמנא דלא מעכבא מסתמא להכי אהני הא דכתביה דבעינן ראוי לבילה והא דמספקא בפ' נערה בנדרים (דף עג.) אי חרש מיפר אי לא מיפר משום דלאו בר שמיעה הוא וכדרבי זירא היינו משום דשמא לא כתיב קרא ושמע אלא אורחא דמילתא דהכי הוי דכי שמע מיפר וקשה לר\"י ערל וטמא אמאי משלחין קרבנותיהן נהי דסמיכה לא מעכבא נימא כל שאין ראוי לבילה בילה מעכבת בו וי\"ל מדדרשינן בת\"כ מזובו ולא מנגעו ש\"מ דטמא משלח קרבנות דבהבאת קרבנות איירי ועוד מדמעטינן בפ\"ק דחגיגה (דף ד: ושם) טמא מובאת שמה והבאתם שמה כל שישנו בביאה ישנו בהבאה ש\"מ דשאר קרבנות משלחין ולא חיישינן שיהא ראוי לסמיכה וה\"ר שמעון הקשה מדאמר בפ' נגמר הדין (סנהדרין דף מה:) דאיכא מ\"ד נקטעה יד העדים חייב דלא בעי קרא כדכתיב ואמאי לא אמרי' כיון דכתיב יד העדים דבעינן ראוי ליד העדים ושמא יש שום ייתור דמחייב אע\"פ שנקטעה ידם אי נמי אין סברא לומר שיפטר משום שאין לעדים יד:"]]],[["רקקה ולא קראה חליצתה כשירה רקקה ולא חלצה ולא קראה חליצתה פסולה קראה ולא רקקה ולא חלצה אין כאן בית מיחוש","מני אילימא רבי אליעזר חלצה ולא רקקה ולא קראה חליצתה כשירה והא אמר רבי אליעזר (דברים כה, ט) ככה יעשה דבר שהוא מעשה מעכב אלא פשיטא רבי עקיבא וקתני רקקה ולא חלצה ולא קראה חליצתה פסולה למאן","אילימא לעלמא פשיטא מי הויא חליצה דאישתריא לעלמא אלא לאו לאחין שמע מינה","ולר\"ע מאי שנא רקיקה ומאי שנא קרייה","קרייה דאיתא בין בתחלה בין בסוף לא מיחלפא ליה רקיקה דבתחלה ליתא ולבסוף איתא מיחלפא ליה ואתו למישרי חלוצה לאחין","ואיכא דאמרי הכי שלחו ליה יבמה שרקקה תחלוץ ואינה צריכה לרוק פעם אחרת כי ההיא דאתיא לקמיה דרבי אמי הוה יתיב רבי אבא בר ממל קמיה רקקה מקמי דתחלוץ אמר ליה רבי אמי חלוץ לה ושרי לה תיגרא","אמר ליה ר' אבא והא בעינן מירק הא רקקה לה ותירוק ומה בכך נפיק מיניה חורבא דאי אמרת תיהדר ותירוק אמרי רקיקה קמייתא לית בה מששא ואתי למישרי חלוצה לאחין","והא בעינן כסדרן כסדרן לא מעכבא הוא סבר דחויי קא מדחי ליה נפק דק ואשכח דתניא בין שהקדים חליצה לרקיקה בין שהקדים רקיקה לחליצה מה שעשה עשוי","לוי נפק לקרייתא בעו מינה גידמת מהו שתחלוץ יבמה שרקקה דם מהו (דניאל י, כא) אבל אגיד לך את הרשום בכתב אמת מכלל דאיכא כתב שאינו אמת","לא הוה בידיה אתא שאיל בי מדרשא אמרו ליה מי כתיב וחלצה ביד ומי כתיב וירקה רוק","אבל אגיד לך הרשום בכתב אמת וכי יש כתב שאינו אמת","לא קשיא כאן בגזר דין שיש עמו שבועה כאן בגזר דין שאין עמו שבועה","כדרב שמואל בר אמי דאמר רב שמואל בר אמי אמר רבי יונתן מנין לגזר דין שיש עמו שבועה שאינו מתקרע שנא' (שמואל א ג, יד) לכן נשבעתי לבית עלי אם יתכפר עון בית עלי בזבח ובמנחה עד עולם","אמר רבה בזבח ובמנחה אינו מתכפר אבל מתכפר הוא בדברי תורה אביי אמר בזבח ובמנחה אינו מתכפר אבל מתכפר בגמילות חסדים רבה ואביי מדבית עלי קאתו רבה דעסק בתורה חיה ארבעין שנין אביי דעסק בתורה ובגמילות חסדים חיה שיתין שנין","ת\"ר משפחה אחת היתה בירושלים שהיו מתים כבן שמנה עשרה שנה באו והודיעו את רבן יוחנן בן זכאי אמר להם שמא ממשפחת עלי אתם שנא' (שמואל א ב, לג) וכל מרבית ביתך ימותו אנשים לכו ועסקו בתורה ותחיו הלכו ועסקו בתורה וחיו והיו קורין אותן משפחת יוחנן על שמו","אמר רב שמואל בר אוניא אמר רב מנין לגזר דין של צבור שאינו נחתם אינו נחתם והא כתיב (ירמיהו ב, כב) כי אם תכבסי בנתר ותרבי לך בורית נכתם עונך לפני","אלא מנין שאפי' נחתם מתקרע שנאמר (דברים ד, ז) מי כה' אלהינו בכל קראנו אליו והכתיב (ישעיהו נה, ו) דרשו ה' בהמצאו לא קשיא הא ביחיד הא בציבור יחיד","אימת אמר רב נחמן אמר רבה בר אבוה אלו עשרה ימים שבין ר\"ה ליוה\"כ","שלחו ליה לאבוה דשמואל יבמה שרקקה דם תחלוץ לפי שאי אפשר לדם בלא צחצוח רוק","מיתיבי יכול יהא דם היוצא מפיו ומפי האמה טמא ת\"ל (ויקרא טו, ב) זובו טמא ואין דם היוצא מפיו ומפי האמה טמא אלא טהור","ל\"ק כאן במוצצת כאן בשותת:","חרש שנחלץ וכו':"],[[0,"רקקה ולא חלצה ולא קראה חליצתה פסולה","ופוסלתה על האחין כדמפרש ואזיל:"],[0,"אין כאן בית מיחוש","ואפי' מייבום לא פסלה:"],[1,"למאן","כלומר למאי הלכתא תני פסולה:"],[2,"אילימא","דלא משתריא בה לעלמא פשיטא:"],[2,"אלא לאו לאשמועינן דאיפסלה מאחין","דקי\"ל במסכת גיטין (דף כד:) כל מקום ששנינו חליצה פסולה פסולה ופוסלת על האחין גט פסול פסול ופוסל מן הכהונה:"],[3,"מאי שנא רקיקה","דפסלה:"],[3,"ומאי שנא קריאה","דלא פסלה דקתני אין כאן בית מיחוש הואיל ותרוייהו לדידיה לא קא מעכבי:"],[4,"קרייה","בין קודם חליצה מאן יבמי בין לאחר חליצה ככה יעשה אי נמי אמרינן תתייבם לא מיחלפא לאינשי בחלוצה דליתי למימר הך בתר חליצה אתייבם דאמרי הך קרייה דמקמי חליצה הואי אבל רקיקה דליתא אלא בתר חליצה מיחלפא לאינשי ויאמרו הך מדרקקה ודאי חלצה לה ברישא ואפילו הכי הדרה ומתייבמת ואתי למישרי חלוצה לאחין:"],[5,"ושרי לה תיגרא","כלומר פטור ושלחנה מבית דין:"],[6,"אמרי רקיקה קמייתא לית בה מששא","ולא פסלה מאחין ומאן דחזי דמתייבמה סבר רקיקה בתר חליצה הואי כי אורחיה ושרינן חלוצה לאחין:"],[8,"מהו שתחלוץ","בשיניה:"],[8,"יבמה שרקקה דם מהו","מי הואי חליצה מעלייתא:"],[8,"אבל אגיד לך כו'","מקרא הוא בדניאל שהמלאך אמר לו אגיד לך את כל הנגזר בשמים ורשום בכתב והוא אמת מכלל דאיכא בשמים כתב דאינו אמת בתמיה:"],[9,"מי כתיב וירקה רוק","דליהוי משמע דלא יהא שם אלא רוק וירקה סתמא כתיב ואפילו רוק וד\"א והכא נמי אי אפשר בלא צחצוחי רוק:"],[10,"בכתב אמת","שהקב\"ה מאמתו ומקיימו ואינו חוזר ומבטלו:"],[13,"אמר רבא","גרסינן. ול\"ג ואמר רבא:"],[16,"בהמצאו","משמע שאין מצוי בכל עת:"],[18,"תחלוץ","ולא תתייבם עוד דאיפסלה עלייהו:"],[19,"יכול יהא דם היוצא מפיו","טמא כרוק ודם היוצא מפי אמתו טמא כזובו וקריו ומימי רגליו שהן מעיינותיו של זב וטמאין טומאה חמורה:"],[20,"מוצצת","אי אפשר בלא צחצוחי רוק:"]],[[2,"לאחין פסולה","משמע שפוסלה לאחין מדקתני פסולה ואפי' למ\"ד בכל הגט (גיטין דף כד:) כל מקום ששנו חכמים חליצה פסולה אינה פוסלת על האחין הכא דייק מדלא קתני אין כאן בית מיחוש ודלא כפי' הקונטרס דפירש דאתיא כמ\"ד כל מקום ששנו חכמים חליצה פסולה פוסלת דא\"כ בלא שום דיוק הוה מצי לאוקומי כוותיה:"],[9,"מי כתיב וחלצה ביד","והא דקאמר בירושלמי שחולצתו בימין למצוה בעלמא אבל עיכובא ליכא:"],[13,"רבא ואביי מדבית עלי קאתו","רבה גרס דרבא לא הוה כהן כדאמר בפ' הזרוע (חולין קלג. ושם) דאמר ליה לשמעיה זכי לי מתנתא אבל רבה היה כהן דאמר בפרק עד כמה (בכורות כז.) רבה בטיל לה ברוב ואמרינן במס' מועד קטן (דף כח. ושם) אמר רבא חיי בני ומזוני לאו בזכותא תליא מילתא כו' עד רבה חיה ארבעין שנין ורב חסדא תשעים שנין כדאמר נמי הכא רבה חיה ארבעין שנין הקשה הר\"ר אלחנן דבגמילות חסדים נמי עסיק דאמר בחלק (סנהדרין דף צח:) אמר רבה ייתי ולא אחמיניה אמר ליה אביי מאי טעמא אמר מר הכי כו' מר תורה איכא גמילות חסדים איכא ואמר ר\"י דלא עסיק כל כך בגמילות חסדים שינצל מגזירת בית עלי אבל כדי שינצל מחבלו של משיח היה בידו שגם שאר זכיות עומדות לו וא\"ת ומאי הא דקאמר במס' מועד קטן (דף כח.) דלא בזכותא תליא מילתא אלא במזלא מדרבה לא חיה אלא ארבעין שנין ודלמא היינו טעם לפי שהיה מבני עלי וי\"ל דסבירא ליה לרבא דבתורה בלבד הוא מתכפר כמו לרבה ועוד שגם רבה עסק בגמילות חסדים כדאמר בחלק (סנהדרין דף צח:):"],[18,"יבמה שרקקה דם תחלוץ","מעיקרא שלחו ליה ההוא דלעיל היבמה שרקקה ואח\"כ שלחו ליה דאפילו רקקה דם תחלוץ:"]]],[["אמר רב יהודה אמר רב זו דברי ר' מאיר אבל חכמים אומרים אין חליצת קטן כלום:","קטנה שחלצה וכו': אמר רב יהודה אמר רב זו דברי ר\"מ דאמר איש כתוב בפרשה ומקשינן אשה לאיש","אבל חכמים אומרים איש כתיב בפרשה אשה בין גדולה בין קטנה","מאן חכמים רבי יוסי היא דר' חייא ור' שמעון בר רבי הוו יתבי פתח חד מינייהו ואמר המתפלל צריך שיתן עיניו למטה שנאמר (מלכים א ט, ג) והיו עיני ולבי שם כל הימים","וחד אמר עיניו למעלה שנאמר (איכה ג, מא) נשא לבבנו אל כפים אדהכי אתא ר' ישמעאל בר' יוסי לגבייהו אמר להו במאי עסקיתו אמרו ליה בתפלה אמר להו כך אמר אבא המתפלל צריך שיתן עיניו למטה ולבו למעלה כדי שיתקיימו שני מקראות הללו","אדהכי אתא רבי למתיבתא אינהו דהוו קלילי יתיבו בדוכתייהו רבי ישמעאל ברבי יוסי אגב יוקריה הוה מפסע ואזיל","אמר ליה אבדן מי הוא זה שמפסע על ראשי עם קדוש אמר ליה אני ישמעאל בר' יוסי שבאתי ללמוד תורה מרבי אמר ליה וכי אתה הגון ללמוד תורה מרבי","אמר ליה וכי משה היה הגון ללמוד תורה מפי הגבורה אמר ליה וכי משה אתה אמר ליה וכי רבך אלהים הוא אמר רב יוסף שקליה רבי למטרפסיה דקאמר ליה רבך ולא רבי","אדהכי אתיא יבמה לקמיה דרבי אמר ליה רבי לאבדן פוק בדקה לבתר דנפק אמר ליה ר' ישמעאל כך אמר אבא איש כתוב בפרשה אבל אשה בין גדולה בין קטנה","אמר ליה תא לא צריכת כבר הורה זקן קמפסע אבדן ואתי אמר ליה רבי ישמעאל בר' יוסי מי שצריך לו עם קדוש יפסע על ראשי עם קדוש מי שאין צריך לו עם קדוש היאך יפסע על ראשי עם קדוש","אמר ליה רבי לאבדן קום בדוכתיך תאנא באותה שעה נצטרע אבדן וטבעו שני בניו ומאנו שתי כלותיו אמר רב נחמן בר יצחק בריך רחמנא דכספיה לאבדן בהאי עלמא","אמר ר' אמי מדבריו של ברבי נלמוד קטנה חולצת בפעוטות רבא אמר עד שתגיע לעונת נדרים והלכתא עד שתביא שתי שערות:","חלצה בשנים וכו': אמר רב יוסף בר מניומי אמר רב נחמן אין הלכה כאותו הזוג והא אמר ר\"נ חדא זימנא דאמר רב יוסף בר מניומי אמר רב נחמן חליצה בשלשה","צריכי דאי איתמר הך קמייתא הוה אמינא ה\"מ לכתחילה אבל דיעבד אפי' תרי קמ\"ל אין הלכה כאותו הזוג ואי אשמועינן אין הלכה כאותו הזוג אלא כתנא קמא ה\"א דיעבד אבל לכתחילה ליבעי חמשה צריכא:","מעשה שחלצו כו': בינו לבינה מי ידענא אמר רב יהודה אמר שמואל ועדים רואין אותו מבחוץ","איבעיא להו מעשה שחלצו בינו לבינה אבראי ובא מעשה לפני ר\"ע בבית האסורין או דלמא מעשה שחלצו בינו לבינה בבית האסורין אמר רב יהודה אמר רב בבית האסורין היה מעשה ולבית האסורין בא מעשה"],[[0,"זו דברי ר' מאיר","דאמר בהאשה רבה (לעיל יבמות צו.) עשו חליצת בן תשע כגט בגדול:"],[0,"אבל חכמים אומרים","דפליגי עליה התם ואמרי עשו ביאת בן ט' כמאמר בגדול אבל בחליצה לא ס\"ל כותיה:"],[0,"אין חליצת קטן כלום","אפי' לפוסלה עליו:"],[1,"זו דברי ר' מאיר","דשמעינן ליה דאמר קטן וקטנה לא חולצין ולא מייבמין:"],[1,"אשה ואיש","דכתיב (דברים כה) ואם לא יחפוץ האיש ולא קטן ואשה נמי אע\"ג דלא כתיב מיעוטא בעינן גדולה כאיש דאיתקש לה דכתיב בההוא קרא ועלתה יבמתו השערה:"],[3,"עיניו למטה","כלפי ארץ ישראל משום דשכינה התם קיימא כדכתיב והיו עיני ולבי שם:"],[5,"אתא רבי למתיבתא","למדרש ואיבעי כל חד למיתב אדוכתיה: ר' ישמעאל בר' יוסי בעל בשר הוה כדאמרי' בהשוכר את הפועלים (ב\"מ פד.):"],[5,"מפסע ואזיל","הולך לאט:"],[6,"אבדן","תלמידו של רבי היה:"],[7,"שקליה רבי למטרפסיה","לגמולו על ששמע ולא מיחה:"],[8,"פוק בדקה","אם הביאה שתי שערות:"],[9,"לא צריכת","למיבדקה:"],[9,"כבר הורה זקן","רבי יוסי:"],[10,"נצטרע אבדן","עונשו של לשון הרע נגעים:"],[11,"מדבריו של ברבי","ר' יוסי. כל ברבי לשון אדם גדול:"],[11,"קטנה חולצת","משהיא כפעוטות כבר שית כבר שבע דתנן במס' גיטין (דף נט.) הפעוטות מקחן מקח וממכרן ממכר במטלטלין הלכך לענין חליצה הואיל ולא כתיב מיעוט כשירה משהיא בפרק הזה שיודעת מעט להבחין:"],[11,"לעונת נדרים","שנה אחת קודם לזמן שתי שערות כדתנן בפרק יוצא דופן (נדה מה:) בת אחת עשרה שנה ויום אחד נדריה נבדקים אם יודעת לשם מי נדרה והקדישה דבריה קיימין:"],[12,"אין הלכה כאותו הזוג","אלא כתנא קמא דבעי ג':"],[12,"והאמר רב נחמן כו'","בריש פירקא (דף קא:):"],[13,"קמ\"ל אין הלכה כאותו הזוג","דאע\"ג דאי עבד הוא כדקתני חלצה בשנים וקתני מכשירין:"],[13,"הני מילי דסגי בתלתא דיעבד","כדקתני חלצה בשלשה ונמצא אחד מהן קרוב או פסול פסולה הא כולם כשרים חליצה כשירה אבל לכתחלה ליבעי חמשה כרבי יהודה קמ\"ל גבי פלוגתא דרבי יהודה הלכתא כת\"ק:"]],[[1,"קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצה פסולה","וא\"ת אמאי לא עריב ותני להו קטנה בהדי חרש וחרשת וקטן וי\"ל (כדמוכח) משום דבקטנה פליג רבי יוסי בגמ' ואם תאמר מ\"מ כיון דתנא פסולה אמאי תני שתחלוץ משתגדיל ועוד דלא תני ליה גבי קטן וי\"ל דאי לא הוה תני גבי קטנה ה\"א דחליצתה פסולה מדרבנן דהא דמקשינן אשה לאיש אינו מן התורה להכי תני תחלוץ משתגדיל יתור לשון לאשמועינן דחליצת קטנה אינה כלום כמו חליצת קטן ומיהו בירושלמי גרסי' בסדר המשנה תחלוץ משתגדיל ואם לא חלצה חליצתה כשירה משמע שסובר דהא דמקיש רבי מאיר אשה לאיש היינו מדרבנן אבל לרבי יוסי חולצת לכתחלה כדאשכחן בעובדא דלקמן ובירושלמי נמי מוקי לה כר\"מ:"],[6,"","אבא יודן בירושלמי ואבדן לישנא קלילא:"],[9,"מי שצריך לו עם קדוש יפסע על ראשי עם קדוש","והא דאמר בפ' קמא דסנהדרין (דף ז:) אזהרה לדיין שלא יפסע על ראשי עם קדוש היינו היכא שלא יצא לצורך עם קדוש אי נמי אפילו יצא לצורך יש לו לקצר דרכו כל מה שיכול כדאמרינן (קידושין דף לב:) אזהרה לזקן שלא יטריח מויראת ובהוריות (דף יג:) תניא בני חכמים ות\"ח בזמן שהצבור צריכין להם מפסיעין על ראשי העם כו' יצא לצורך נכנס ויושב במקומו פירוש לצורך העם ובתוספתא גרסינן בהדיא יצא לצורך העם:"],[11,"רבא אמר משתגיע לעונת נדרים","ואם תאמר דבפרק יוצא דופן (נדה מו. ושם) קאמר רבא קטנה שהגיעה לכלל שנותיה אינה צריכה בדיקה חזקה הביאה סימנין ומסיק כי קאמר רבא למיאון אבל לחליצה בעיא בדיקה אלמא קטנה לא חלצה ואר\"ת דרבא איירי הכא אליבא דרבי יוסי אבל איהו גופיה סבר עד שתביא שתי שערות והא דמסיק הכא והלכתא עד שתביא שתי שערות סיומא דמילתא הוא ובפרק התקבל (גיטין סה. ושם) דקאמר רבא גבי שלש מדות בקטן הגיע לעונת נדרים נדרו נדר והקדשו הקדש וכנגדן בקטנה חולצת מדה זו עושה אליבא דרבי יוסי ועוד דר\"י הוכיח שם מכח ההיא דמי שמת (ב\"ב קנה.) דרבה גרס ולא רבא:"],[12,"רבי שמעון ורבי יוחנן הסנדלר מכשירים בשנים","ולאו דוקא שנים אלא לשון עדות בעלמא נקט שנים ובקונטרס ל\"ג שנים:"],[13,"לכתחלה בעי חמשה","מכאן יש ללמוד דאין צריך חמשה אפי' לכתחלה ומיהו לפרסומי מילתא עבדינן בחמשה:"],[15,"ובא מעשה לפני ר' עקיבא בבית האסורין","וא\"ת והא במתני' משמע בהדיא שחלצה בבית האסורין דקתני מעשה שחלצה בינו לבינה בבית האסורין ובא מעשה לפני רבי עקיבא ויש לומר דבהרבה ספרים גרסי' בא מעשה לפני ר' עקיבא בלא וי\"ו וקאי נמי בבית האסורין ארבי עקיבא ואם תאמר והיכי פשיט שהמעשה בא לפני רבי עקיבא בבית האסורין ולא בא אבראי ויש לומר דיודע הגמרא שבא לפניו בבית האסורין כדאמר בירושלמי רבי יוחנן הסנדלר עבר קומי חבושין דרבי עקיבא היה מכריז ואמר מאן בעי מחטין ומאן בעי צנורין חלצה בינו לבינה מהו אדיק ליה רישיה מן כוותיה אמר ליה אית לך כושין אית לך כשר:"]]],[["תנו רבנן חליצה מוטעת כשרה אי זו היא חליצה מוטעת אמר ר\"ל כל שאומרים לו חלוץ ובכך אתה כונסה","אמר ליה רבי יוחנן אני שונה בין שנתכוון הוא ולא נתכוונה היא בין שנתכוונה היא ולא נתכוון הוא חליצתה פסולה עד שיתכוונו שניהם כאחד ואת אמרת חליצתה כשירה","אלא כל שאומרים לו חלוץ לה ע\"מ שתתן לך מאתים זוז תניא נמי הכי חליצה מוטעת כשירה אי זו היא חליצה מוטעת כל שאומרים חלוץ לה על מנת שתתן לך מאתים זוז","ומעשה באשה אחת שנפלה לפני יבם שאין הגון לה ואמרו לו חלוץ לה על מנת שתתן לך מאתים זוז ובא מעשה לפני רבי חייא והכשירה","ההוא דאתא לקמיה דרבי חייא בר אבא אמר לה בתי עמודי אמרה ליה אימא ישיבתה זו היא עמידתה אמר לה ידעת ליה אמרה ליה אין ממונא הוא דחזא לה וקבעי למיכליה מינה","אמר לה לא ניחא לך אמרה ליה לא אמר ליה חלוץ לה ובכך אתה כונסה לבתר דחלץ לה אמר ליה השתא מינך אפסלא לה חלוץ לה חליצה מעלייתא כי היכי דתישתרי לעלמא","בת חמוה דרב פפא נפלה לפני יבם שאין הגון לה אתא לקמיה דאביי אמר ליה חלוץ לה ובכך אתה כונסה אמר ליה רב פפא לא סבר לה מר להא דאמר רבי יוחנן ואלא היכי אימא ליה","אמר ליה חלוץ לה ע\"מ שתתן לך מאתים זוז לבתר דחלץ לה אמר לה זיל הב ליה אמר ליה משטה אני בך עבדה ליה","מי לא תניא הרי שהיה בורח מבית האסורין והיתה מעברא לפניו ואמר ליה טול דינר והעבירני אין לו אלא שכרו","אלמא אמר ליה משטה אני בך הכא נמי משטה אני בך","אמר ליה אבוך היכא א\"ל במתא אימך היכא א\"ל במתא יהיב בהו עיניה ושכיבן:","ת\"ר חליצה מוטעת כשרה גט מוטעה פסול חליצה מעושית פסולה גט מעושה כשר היכי דמי אי דאמר רוצה אני אפי' חליצה נמי ואי לא אמר רוצה אני גט נמי לא","הכי קאמר חליצה מוטעת לעולם כשר וגט מוטעה לעולם פסול חליצה מעושית וגט מעושה זימנין כשר וזימנין פסול הא דאמר רוצה אני הא דלא אמר רוצה אני","דתניא (ויקרא כב, יח) יקריב אותו מלמד שכופין אותו יכול בעל כרחו ת\"ל לרצונו הא כיצד כופין אותו עד שיאמר רוצה אני וכן אתה מוצא בגיטי נשים כופין אותו עד שיאמר רוצה אני","אמר רבא אמר רב סחורה אמר רב הונא חולצין אע\"פ שאין מכירין ממאנין אע\"פ שאין מכירין","לפיכך אין כותבין גט חליצה אלא אם כן מכירין ואין כותבין גט מיאון אלא אם כן מכירין דחיישינן לבית דין טועין","ורבא דידיה אומר אין חולצין אלא אם כן מכירין ואין ממאנין אא\"כ מכירין לפיכך כותבין גט חליצה אף על פי שאין מכירין וכותבין גט מיאון אף על פי שאין מכירין ולא חיישינן לבית דין טועין:"],[[2,"על מנת שתתן לך מאתים זוז","ואע\"ג דלא יהבא ליה חליצתה כשירה כדמפורש בכתובות בהמדיר (כתובות דף עד.) דכל תנאי מבני גד ובני ראובן גמרינן תנאה שאפשר להתנות על ידי שליח שעשה משה את יהושע שליח לתת להם את ארץ הגלעד הוי תנאיה תנאה וכל תנאי דלא אפשר לעשות על ידי שליח כגון חליצה אין תנאי מועיל בה וזהו טעמו של דבר:"],[4,"בתי עמודי","עמודי והתייבמי לו:"],[4,"ישיבתה","מהתייבם לו:"],[4,"זו היא עמידתה","זו היא תקנתה:"],[4,"לישנא אחרינא בתי עמודי","עמודי על רגליך דכתיב (דברים י״ט:י״ז) ועמדו שני האנשים בעמידה:"],[4,"ישיבתה זו היא עמידתה","קיטעת היא או חולה. אמר לה ידע לה מכיר הוא בה שרוצה לייבמה אמרה ליה אין וממונא חזא בה:"],[4,"ידעת ליה","מכרת היא בו שום דבר גנאי:"],[4,"אמרה ליה אין ממונא חזא לה","דבר זה היא יודעת בו שאין בא לייבמה אלא כדי לאכול ולכלות ממונה ולגרשה:"],[6,"להא דר' יוחנן","דאמר לעיל עד שיתכוונו שניהם:"],[7,"הב ליה","דהא קבילת עלה ואע\"ג דחליצה בהכי לא מיפסלא מיהא איחייבא לקיומי תנאה מדינא כשאר שכירות דעלמא:"],[7,"אמר ליה","כיון דחליצה כשירה היא משום דינא נמי לית ליה דכיון דעליה רמיא למיעבד ולא בעי משטה אני בך עבדה ליה:"],[8,"מעברא","מעבר ים בספינה:"],[10,"אמר ליה אביי","לרב פפא:"],[10,"אבוך היכא","כלומר כמדומה אני שיש לך אב ואם סמוכין לך לספק צרכיך לפיכך קא מחדדן שמעתיך:"],[10,"ושכבו","אבוה ואימיה:"],[11,"גט מוטעה פסול","אם אינה מקיימת תנאה דאיפשר לגט ע\"י שליח שהאומר לשנים כתבו ותנו גט לאשתי הרי אלו יכתבו ויתנו הילכך דמי לתנאי בני גד ומהני ביה תנאה:"],[13,"וכן בגיטי נשים","כופין אותו עד שיאמר רוצה אני:"],[14,"חולצין אע\"פ שאין מכירין","יבם ויבמה שבאו לפנינו לחלוץ ואין אנו מכירין בו שהוא יבמה נזקקין להן ב\"ד וחולצין:"],[14,"וממאנין","ב\"ד נזקקין למיאון אע\"פ שאין מכירין:"],[15,"לפיכך","הואיל ונזקקין להם אע\"פ שאין מכירין אותם:"],[15,"אין כותבין גט חליצה","עדים הרואים בחליצה ובמיאון אין כותבין ונותנין לה להיות בידה לזכות אא\"כ מכירין שהן יבם ויבמה. והשתא דאין כותבין אא\"כ מכירין אי נמי לאו יבמה הוא לא נפיק חורבה מיניה דכל כמה דלית לה גט חליצה לא נסבי לה:"],[15,"חיישינן לב\"ד טועין","אם כתבו לה עדים ראינו שחלצה בפנינו מפלוני ואפילו לא כתבו בו ואישתמודעינהו חיישינן שמא תראה גט זה לב\"ד אחר ויסמוכו עליו ולא יבדקו אם פלוני זה הכתוב בגט זה יבמה הוא אם לאו וישיאו אותה ויהיו טועין בהלכה שאין יודעין שחולצין וממאנין ואע\"פ שאין מכירין:"],[16,"לפיכך","הואיל ואין חולצין אא\"כ מכירין:"],[16,"כותבין גט חליצה","עדים שראו שחלצה יכולין לכתוב לה ואע\"פ שאין מכירין ולא חיישינן שמא טעו ב\"ד בהלכה זו לומר חולצין אף על פי שאין מכירין וחלצו לה ממי שאינו יבמה:"]],[[4,"בתי עמודי","ללשון שפי' בקונטרס עמודי וחלצי לו משמע שצריך עמידה לחלוץ ושמא לכתחלה בעי ולא מיפסלא בהכי כדפרישי' לעיל (יבמות דף קג.) גבי בין עומד בין יושב בין מוטה:"],[8,"אין לו אלא שכרו","היינו דוקא כגון הכא ששואל דבר גדול במקום שאין לוקחין אלא דבר מועט וכן ההיא דהגוזל בתרא (ב\"ק קטז: ושם) גבי הלך להביא כרוב ודורמסקין לחולה דאין לו אלא שכרו אבל היכא שלוקחין דבר גדול התם אין יכול לומר לו משטה אני בך ואע\"פ שלא הוציא כלום מאותו דבר שתובע עליו שכר:"],[14,"רבא אמר רב סחורה","והא דאמר באלו מציאות (ב\"מ דף לג. ושם) אמר רבא כגון רב סחורה דאסברן זוהמא ליסטרון פירוש שהאיר עיני באותה משנה אחת רבה גרס התם אבל רבא היה תלמידו מובהק כדמשמע הכא ובכמה דוכתין ואית דגרסי התם רבא וי\"ל דה\"ק אפילו לא אסברן אלא זוהמא ליסטרון בלבד אני חייב לקרוע עליו:"],[15,"לפיכך אין כותבין גט חליצה אא\"כ מכירין כו'","פירש בקונטרס דחיישינן שמא יטעו בית דין האחרון וישיאוה בלא הכרת יבם ויסמכו על בית דין הראשון וא\"ת ואמאי חולצין בית דין הראשון אע\"פ שאין מכירין וניחוש דלמא מייתי סהדי שחלצה בב\"ד ויסמכו בית דין האחרון עלייהו וישיאוה לשוק בלא הכרה וי\"ל דעדים אינם מעידין לחצאין וישאלו להם אם הכירום בית דין הראשון דכולי האי ודאי לא חיישינן:"],[16,"ורבא דידיה אמר כו' ולא חיישינן לבית דין טועין","פירוש שמא טעו ב\"ד הראשון ועשו בלא הכרה כך פירש הקונטרס וקשה דאין פירוש בית דין טועין שוה דחיישינן לבית דין טועין דרב סחורה היינו בית דין אחרון ולא חיישינן לבית דין טועין דרבא היינו בית דין הראשון ועוד קשה לר\"י דאמר פ' יש נוחלין (ב\"ב דף קלח: ושם) אמר רב דימי הילכתא לא חיישינן לב\"ד טועין ופריך מ\"ש מדרבא דאמר רבא אין חולצין אא\"כ מכירין דחיישי' לבית דין טועין כו' אלמא בדרבא גרסי' חוששין לבית דין טועין ונראה לר\"י כגירסת ספרים ישנים דגרסי בדרב סחורה לא חיישינן ובדרבא חיישינן וה\"פ לא חיישינן לבית דין טועין שמא יטעו בית דין אחרון להשיאה ע\"י חליצה שיעידו בחליצה ולא בהיכירא דכולי האי לא חיישינן אלא יחזרו עליהם אם הכירו ב\"ד הראשון ורבא סבר דאין חולצין אא\"כ מכירין שמא יטעו בית דין האחרון להשיאה על ידי עדים ויאמרו שלא עשו כ\"א בהכרה והקשה הר\"ר יהודה מדתניא בתוספתא (פי\"ב) חולצין לאשה אע\"פ שאין מכירין אותה תיקשה לרבא משמיה דנפשיה ותירץ דתוספתא מיירי דאורייתא ואמוראי דהכא איירי דרבנן:"]]],[["\u0001מתני׳\u0002 מצות חליצה בא הוא ויבמתו לבית דין והן משיאין לו עצה ההוגנת לו שנאמר (דברים כה, ח) וקראו לו זקני עירו ודברו אליו","והיא אומרת מאן יבמי להקים לאחיו שם בישראל לא אבה יבמי והוא אומר לא חפצתי לקחתה ובלשון הקדש היו אומרים ונגשה יבמתו אליו לעיני הזקנים וחלצה נעלו מעל רגלו וירקה בפניו רוק הנראה לדיינים וענתה ואמרה ככה יעשה לאיש אשר לא יבנה את בית אחיו עד כאן היו מקרין","וכשהקרא רבי הורקנוס תחת האלה בכפר עיטם וגמר את כל הפרשה הוחזקו להיות גומרין כל הפרשה ונקרא שמו בישראל בית חלוץ הנעל מצוה בדיינין ולא מצוה בתלמידים רבי יהודה אומר מצוה על כל העומדים שם לומר חלוץ הנעל:","\u0001גמ׳\u0002 אמר רב יהודה מצות חליצה קוראה וקורא וחולצת ורוקקה וקוראה מאי קמשמע לן מתני' היא הא קמשמע לן מצוה הכי ואי אפיך לית לן בה","תניא נמי הכי בין שהקדים חליצה לרקיקה ובין שהקדים רקיקה לחליצה מה שעשה עשוי","אמר אביי האי מאן דמקרי גט חליצה לא ליקרי לדידה לא לחודיה ואבה יבמי לחודיה דמשמע אבה יבמי אלא לא אבה יבמי","ולא ליקרי לדידיה לא לחודיה חפצתי לחודיה דמשמע חפצתי לקחתה אלא לא חפצתי לקחתה רבא אמר אפסוקי מילתא היא ואפסוקי מילתא לית לן בה","רב אשי אשכחיה לרב כהנא דקמצטער ומקרי לה לא אבה יבמי אמר ליה לא סבר ליה מר להא דרבא","אמר ליה מודה רבא בלא אבה יבמי אמר אביי האי מאן דכתב גיטא דחליצתא ליכתוב הכי אקרינוה לדידה מן מאן יבמי עד אבה יבמי ואקרינוהו לדידיה מן לא עד לקחתה ואקרינוה לדידה מן ככה ועד חלוץ הנעל","מר זוטרא משרטט וכתיב לכולא פרשה מתקיף לה מר בר אידי והא לא ניתן ליכתב והלכתא כוותיה דמר זוטרא","אמר אביי רקקה וקלטתו הרוח לא עשתה ולא כלום מאי טעמא וירקה בפניו בעינן הלכך הוא ארוך והיא גוצה קלטתהו הרוח איכא בפניו היא ארוכה והוא גוץ בעינן עד דמטי להדי אפיה והדר אזיל","אמר רבא אכלה תומא ורקתה אכלה גרגישתא ורקתה לא עשתה ולא כלום מאי טעמא וירקה מעצמה בעינן וליכא ואמר רבא צריכי דייני למיחזי רוקא כי נפיק מפומא דיבמה דכתיב לעיני הזקנים וירקה:","ונקרא שמו בישראל בית חלוץ הנעל מצוה בדיינין ולא בתלמידים: תניא א\"ר יהודה פעם אחת היינו יושבים לפני רבי טרפון ובאתה יבמה לחלוץ ואמר לנו ענו כולכם חלוץ הנעל חלוץ הנעל חלוץ הנעל:","\u0001הדרן עלך מצות חליצה\u0002"],[[0,"מתני' עצה ההוגנת לו","כלך אצל שכמותך ואל תכניס קטטה לתוך ביתך:"],[1,"בלשון הקדש היו אומרים","במסכת סוטה (דף לב.) נפקא לן מקראי בפ' אלו נאמרין:"],[2,"בכפר עיטם","בתלמידים היושבים שם לפני רבן בשעת החליצה:"],[3,"גמ' קוראה","מאן יבמי (דברים כה):"],[3,"וקורא","לא חפצתי לקחתה (שם):"],[3,"חולצת ורוקקה וקוראה","ככה יעשה לאיש (שם):"],[5,"דמקרי גט חליצה","המקרא את האשה בשעת חליצתה:"],[8,"מודה רבא בלא אבה יבמי","דבעינן שלא יפסיק דאי מפסיק משמע דהאי לא ארישא קאי דאמרה מאן יבמי להקים לאחיו שם בישראל לא כלומר לא מאן אלא אבה יבמי אבל בלא חפצתי לקחתה שהיא פתיחת קריאתו ליכא למימר הכי לא לעיל קאי ואי מפסיק לית לן בה:"],[8,"ממאן עד יבמי","ומפני שהגט אינו משורטט לא בעי למיכתב כוליה פסוק דקי\"ל (גיטין דף ו:) אין כותבין ד' תיבות בלא שרטוט:"],[9,"משרטט","גט חליצה וכתב לכולא פרשתא אקרינוה לדידה מאן יבמי וגו' וכן כולם וקיימא לן שלש תיבות של מקרא כותבין בלא שרטוט ד' אין כותבין בפ' קמא דגיטין (דף ו:):"],[9,"והא לא נתנו ליכתב","פרשה בפני עצמה במסכת גיטין בפרק הניזקין (גיטין דף ס.) דקתני אין כותבין מגילה לתינוק להתלמד בה:"],[9,"והלכתא כמר זוטרא","דכותבין דלא דמי לכותב מגילה לתינוק להתלמד בה דהתם אדעתה דפרשתא כתיב ליה דתיהוי כמגילה קטנה וקים לן (שם) תורה חתומה ניתנה אבל האי ספירת דברים הוא ולאו בקדושתיה הוא הלכך הלכתא כמר זוטרא דבמקום מצוה שרי:"],[10,"וקלטתו הרוח","לרוק והעבירו שלא בא לפני היבם:"],[10,"איכא בפניו","כיון שיצא מפיה היה בפניו:"],[10,"להדי אפיה","לנגד פניו שיראהו למול פניו קודם שיקלטהו הרוח:"],[11,"תומא","שומים:"],[11,"גרגישתא","ארזיל\"א. במעבה האדמה (מלכים א ז׳:מ״ו) מתרגמינן בגרגישתא דארעא:"]],[[6,"רבא אמר אפסוקי מילתא לית לן בה","וא\"ת דאמר רבא בפרק לולב הגזול (סוכה לח: ושם) לא לימא איניש ברוך הבא והדר בשם ה' רב ספרא אמר אפסוקי מילתא היא ולית לן בה ויש לומר דקבלה מרב ספרא או שמא יש לחלק:"],[8,"מודה רבא בלא אבה יבמי","לא אבה כתיב בספרים מדויקים וכן מוכח במסורה לא אבה ג' דסמיכי לא אבה ה' השחיתך (דברים י׳:י׳) לא אבה יבמי (שם כה) ישראל לא אבה לי (תהלים פא) ויש שנים ריש פסוק במשנה תורה ולא אבה סיחון (דברים ב׳:ל׳) ולא אבה ה' לשמוע אל בלעם (שם כג) ויש עוד פסוקים דלא שייכי לאותו מסורת ולא אבה נושא כליו דשאול (שמואל א ל״א:ד׳) וגם אל מלך מואב שלח ולא אבה דיפתח (שופטים י״א:י״ז):"],[10,"עד דמטי להדי אפיה והדר אזיל","והא דאמר בהחולץ (לעיל יבמות לט: ושם) ורקת קדמנא רוקא בבי דינא דמיתחזי על ארעא ובכל ספרים איתיה וכן בסנהדרין בירושלמי שמא למצוה מן המובחר הוא דבעינן הכי. [ועי' לעיל (יבמות לט:) תוס' ד\"ה דמתחזיא]:"]]],[["מתני׳ \u0001בית שמאי\u0002 אומרים אין ממאנין אלא ארוסות ובית הלל אומרים ארוסות ונשואות","ב\"ש אומרים בבעל ולא ביבם וב\"ה אומרים בבעל וביבם","ב\"ש אומרים בפניו ובית הלל אומרים בפניו ושלא בפניו ב\"ש אומרים בב\"ד וב\"ה אומרים בב\"ד ושלא בב\"ד","אמרו להם ב\"ה לבית שמאי ממאנת והיא קטנה אפילו ד' וה' פעמים אמרו להם ב\"ש אין בנות ישראל הפקר אלא ממאנת וממתנת עד שתגדיל ותמאן ותנשא:","\u0001גמ׳\u0002 אמר רב יהודה אמר שמואל מאי טעמא דבית שמאי לפי שאין תנאי בנשואין ואי נשואה תמאן אתי למימר יש תנאי בנשואין","נכנסה לחופה ולא נבעלה מאי איכא למימר לפי שאין תנאי בחופה","מסר האב לשלוחי הבעל מאי איכא למימר לא פלוג רבנן","ובית הלל מידע ידעי דנישואי קטנה דרבנן נינהו רבה ורב יוסף דאמרי תרוייהו טעמא דבית שמאי לפי שאין אדם עושה בעילתו בעילת זנות","נכנסה לחופה ולא נבעלה מאי איכא למימר לא ניחא ליה דתיהוי חופה דאיסורא מסר האב לשלוחי הבעל מאי איכא למימר לא פלוג רבנן ובית הלל כיון דאיכא קדושין וכתובה לא אתו למימר דבעילתו בעילת זנות","רב פפא אמר טעמא דב\"ש משום פירי טעמא דב\"ה משום פירי טעמא דב\"ש משום פירי דאי אמרת נשואה תמאן שמיט ואכיל להו מינה דסוף סוף למיפק קיימא ובית הלל אדרבה כיון דאמרת תמאן אשבוחי משבח להו סבר דאי לא עייצי לה קרוביה ומפקי לה מיניה","רבא אמר היינו טעמא דב\"ש שאין אדם טורח בסעודה ומפסידה וב\"ה תרוייהו ניחא להו כדי דליפוק עלייהו קלא דאישות:","ב\"ש אומרים בבעל וכו': אמר רבי אושעיא ממאנת למאמרו ואינה ממאנת לזיקתו אמר רב חסדא מאי טעמא דרבי אושעיא מאמר דמדעתה מציא עקרא זיקה דבעל כרחה לא מציא עקרא","והרי ביאה דבעל כרחה"],[[0,"מתני' אין ממאנין","יתומה שהשיאוה אמה ואחיה אלא מן האירוסין:"],[1,"בבעל","אבל אם מת ולא מיאנה בו ונפלה לפני יבם אינה יוצאת במיאון אלא תמתין עד שתגדיל ותחלוץ:"],[3,"אין בנות ישראל הפקר","ואפי' מן האירוסין לא תמאן ותיארס לאחר ותחזור ותמאן אלא ממאנת בזה ותמתין מלארוס לאחר עד שתגדיל ויהיו קדושין גמורים ולא תצא עוד משני במיאון:"],[3,"ותמאן","בראשון ותנשא. ובגמרא פריך הא מיאנה בו כבר חדא זימנא:"],[4,"גמ' מ\"ט דב\"ש","דאמרי נשואה לא ממאנה הא קטנה היא:"],[4,"לפי שאין תנאי","מועיל בנישואין של גדולה ואפי' הוה ליה תנאה בשעת קדושין אחולי אחליה בשעת ביאה וחופה וחיילא להו קדושין קמאי ואי אמרת נשואה קטנה תמאן לא ידעי אינשי דמשום קטנות הוא אלא אמרי תנאה ה\"ל בנישואין ואתו למימר יש תנאי בנישואי גדולה:"],[5,"נכנסה לחופה כו' מאי איכא למימר","לב\"ש אמאי לא ממאנת דקאמרי אין ממאנין אלא ארוסות ומשמע לאפוקי נכנסה לחופה או שנמסרה לשלוחי הבעל דנפקא לה מכלל ארוסה:"],[5,"לפי שאין תנאי","מועיל בחופה ואי אמרת קטנה שנכנסה לחופה ולא נבעלה תמאן אמרי תנאה הוה להו ואתי למימר יש תנאי בחופה:"],[6,"מסר האב","מסרה האב לשלוחי הבעל מאי איכא למימר א\"נ אתי למימר תנאי מועיל במסירה שפיר קאמרי שהרי אין כאן חיבה דנימא אחליה לתנאיה דקדושין. האי מסר האב לאו דוקא דאילו משקיבל אביה קידושיה לא נפקא במיאון דהאב זכאי בקידושי בתו ואין מיאון אלא ביתומה שקדשוה אמה ואחיה וה\"ק מסר האב לשלוחי הבעל דקי\"ל בכתובות (דף מח:) דנישואין נינהו ודכוותה הכא מסרוה אחין לשלוחין הוו נישואין ולב\"ש לא ממאנת מאי איכא למימר:"],[6,"לא פלוג רבנן","בין נישואין לנישואין:"],[7,"לפי שאין אדם כו'","ורבנן תקינו נישואין לקטנה כדי שלא ינהגו בה מנהג הפקר כדאמר לקמן (יבמות דף קיב:) בחרש שנשא ואי אמרת ממאנה מימנעי ולא נסבי לה דאין אדם רוצה לעשות בעילתו בעילת זנות ומיעקרא תקנתא דרבנן:"],[8,"דאיסורא","דבעילת זנות:"],[8,"מסר האב כו'","דקי\"ל דנישואין נינהו ודכוותה בנישואין דרבנן הויא מסירת אחין נישואין ולב\"ש לא ממאנה דהא מילתא פסיקא קאמרי דאין ממאנין אלא ארוסות מאי איכא למימר לאו בעילת זנות היא ולא מימנעי:"],[9,"משום פירי","שלא יפסיד פירות נכסי מלוג אבל ארוס לית ליה פירי:"],[9,"סבר דאי לא","דאם איני משביחן עייצי לה קרוביה כו':"],[10,"בסעודה","סעודת נישואין. הילכך אי אמרת תמאן מימנעי ולא נסבי:"],[10,"ניחא להו כו'","הילכך לא מימנעי:"],[11,"אמר ר' אושעיא ממאנת למאמרו","לב\"ה דאמרי ממאנת ביבם למאמרו ממאנת שאם עשה בה מאמר ממאנת ועוקרתו שלא תהא צריכה גט למאמרו אבל חליצה שהיא בשביל זיקה לא עקרא:"],[11,"דבעל כרחה","מקידושי ראשון ומכח נישואין רמיא עליה ובראשון לא מיאנה:"],[12,"והרי ביאת","יבם בעל כרחה היא כדאמר בהבא על יבמתו (לעיל יבמות נד.) יבמה יבא עליה בע\"כ:"]],[[4,"בית שמאי: אמר רב יהודה אמר שמואל מ\"ט דב\"ש לפי שאין תנאי בנישואין","תימה דבפ' המדיר (כתובות עג. ושם) גבי קדשה על תנאי וכנסה סתם קאמר שמואל דאין צריכה גט ומוקי אביי פלוגתייהו בבעל דמפרש טעמא דרב שאין אדם בועל בעילתו בעילת זנות אלמא אפילו בבעל לשמואל יש תנאי בנישואין וב\"ה נמי לא פליגי אלא משום דסברי דליכא למיגזר דמידע ידעי דנישואי קטנה דרבנן נינהו אבל הא מודו דאין תנאי בנישואין וריב\"ן הגיה כאן אמר רב יהודה אמר רב ואר\"י מ\"מ תיקשה לרבא דאמר התם (דף עג:) בטעות אשה גרידתא מודה רב דיש תנאי בנישואין ועוד דאפי' נכנסה לחופה ולא נבעלה קאמר הכא דאין תנאי בחופה ונראה לר\"י דאביי לא היה מפרש טעמא דב\"ה משום דמידע ידעי כו' אלא משום דיש תנאי בנישואין וסוגיא דהכא כעולא אמר ר' אלעזר דאמר התם המקדש על תנאי ובעל ד\"ה צריכה הימנו גט דאין תנאי בנישואין וגרס הכא אמר רב יהודה אמר רב דלשמואל בנכנסה לחופה ולא נבעלה יש תנאי והא דאמר אביי לעיל בס\"פ האשה רבה (יבמות דף צה:) גבי פלוגתא דרב ושמואל דיבמה הרי היא כאשת איש דאמר אביי לחד לישנא דשמואל אדר' יצחק נפחא קאי דמפרש מילתיה דרבי יוסי משום דאין תנאי בנישואין לאו משום דלא מהני תנאה קאמר אלא משום דאין רגילות שיהו נשואין מתבטלין מחמת תנאי שהיה בקדושין דרגילות הוא או שיודע וימנע מלישא או גמרי ומחלי אהדדי בשעת נישואין וכן צריך לפרש ע\"כ הא דקאמר שמואל אינה כא\"א דבקדושין איירי ובקדושין כ\"ע מודו דיש תנאי והר' חיים היה מפרש הא דהכא נמי בענין זה וה\"פ לפי שאין תנאי בנישואין פירוש אין רגילות שיתבטלו נישואין מחמת שום תנאי ואי אמרת נשואה תמאן אתי למימר יש תנאי בנישואין בתמיה וכי יעלה על לב לומר שמחמת תנאי נתבטלו הא אין רגילות מחמת קדושי קטנה נמי לא ידעי אלא יאמרו דאשת איש יוצאה בלא גט:"],[7,"טעמא דב\"ש לפי שאין אדם עושה בעילתו בעילת זנות","וקשה לר\"י דבפ' הזורק (גיטין דף פא. ושם) גבי המגרש את אשתו ולנה עמו בפונדקי דאמרי ב\"ש אינה צריכה הימנו גט ומפרש בגמרא טעמא דסברי אדם עושה בעילתו בעילת זנות ואין לנו לחוש שקדשה בביאה אלא בא עליה בלא קדושין ותירץ דשאני התם דכיון דגירשה ונתייחד עמה גלי אדעתיה שבעילתו בעילת זנות אבל הכא שהיה מתחלה דרך נישואין או בעלמא שאין הוכחה אין לנו לומר שיעשה בעילתו בעילת זנות:"],[9,"דאי אמרת תמאן שמיט ואכיל להו","וא\"ת והאמר בפ' המפקיד (ב\"מ לט.) המוציא הוצאות על נכסי אשתו קטנה כמוציא על נכסי אחר דמי וישלמו לו מה שהוציא וא\"כ לא יפסיד כלום במיאונה ואר\"י דמ\"מ שמיט ואכיל אפי' הזמורות וגוף הקרקע אם כילה דא\"צ לשלם אע\"פ שאכל שלא כדין כדמוכח בכתובות בס\"פ אלמנה (דף קא. ושם) דאמר שמואל אמתניתין ולא בלאות לא שנו אלא נכסי מלוג אבל נכסי צאן ברזל יש לה הוי בה רב פפא אהייא אילימא אממאנת אי דאיתנהו אידי ואידי שקלה ואי דליתנהו אידי ואידי לית לה ואיירי בהנך שכילה שלא כדין שכילה גם את הקרן דאי בהני שכילה כדין א\"כ היכי מסיק גבי איילונית אי דליתנהו איפכא מיבעי ליה דישלם פירות נכסי מלוג ולמה ישלם הפירות כיון שאכלם כדין אלא ודאי מיירי בפירות שאכלם שלא כדין כיון דליתנהו בעין לא ישלם ולכך קאמר שפיר דשמיט ואכיל פרי כיון שלא ישלם כלום:"],[10,"תרוייהו ניחא להו כו'","ה\"ג בפר\"ח תרוייהו ניחא להו דליפוק עלייהו קלא דאישות ולא גרסינן ניחא ליה דלדידה נמי ניחא לה כדאמרי' (גיטין דף מט:) יותר משהאיש רוצה לישא אשה רוצה להנשא ואמרי' נמי (קדושין מא.) טב למיתב טן דו:"]]],[["ומציא עקרא אלא ביאה ומאמר דהוא קעביד מציא עקרא זיקה דרחמנא רמא עלה לא מציא עקרא עולא אמר ממאנת אף לזיקתו מאי טעמא נישואי קמאי קא עקרא","איתיביה רבא לעולא כל שיכולה למאן ולא מיאנה צרתה חולצת ולא מתייבמת ואמאי תמאן השתא ותעקרינהו לנישואי קמאי ותתייבם צרתה צרת ערוה שאני דתני רמי בר יחזקאל מיאנה בבעל מותרת לאביו ביבם אסורה לאביו","אלמא בשעת נפילה נראית ככלתו הכא נמי בשעת נפילה נראית כצרת בתו","אמר רב מיאנה בזה אסורה לזה מידי דהוה אבעלת הגט בעלת הגט לאו כיון דאיתסרא לה לחד איתסרא להו לכולהו הכא נמי לא שנא","ושמואל אמר מיאנה בזה מותרת לזה ולא דמיא לבעלת הגט בעלת הגט הוא דקא עביד בה הכא היא קעבדא ביה דאמרה לא רעינא בך ולא צבינא בך בך הוא דלא רעינא הא בחברך רעינא","רב אסי אמר מיאנה בזה מותרת אפילו לו לימא כרבי אושעיא סבירא ליה דאמר אינה ממאנת לזיקתו בחד יבם הכי נמי דמציא עקרא הכא בשני יבמין עסקינן דאין מיאון לחצי זיקה","כי אתא רבין אמר רבי יוחנן מיאנה בזה מותרת לאחין ולא הודו לו מאן לא הודו לו אמר אביי רב רבא אמר רבי אושעיא ואמרי לה רב אסי:","בית שמאי אומרים בפניו וכו': תניא אמרו להן בית הלל לבית שמאי והלא פישון הגמל מיאנה אשתו שלא בפניו אמרו להן ב\"ש לבית הלל פישון הגמל במדה כפושה מדד לפיכך מדדו לו במדה כפושה","מדקא אכיל פירי פשיטא נשואה היא והאמרי ב\"ש נשואה לא ממאנה תרי קיטרי עבדו ביה:","בית שמאי אומרים בפני בית דין וכו': תנן התם החליצה והמיאונין בשלשה מאן תנא אמר רבה בית שמאי היא אביי אמר אפי' תימא בית הלל עד כאן לא קאמרי בית הלל אלא דלא בעינן מומחין אבל שלשה בעינן","כדתניא בית שמאי אומרים בפני בית דין וב\"ה אומרים בפני בית דין ושלא בפני בית דין ואלו ואלו מודים שצריך שלשה רבי יוסי בר יהודה ורבי אלעזר ברבי שמעון מכשירין בשנים אמר רב יוסף בר מניומי אמר רב נחמן הלכה כאותו הזוג:","בית שמאי אומרים תמאן וכו': והא מיאנה חדא זימנא אמר שמואל עד שתגדיל ותאמר רוצה אני במיאונים הראשונים","עולא אמר תרתי קתני או שתמאן ותגדיל ותיארס או שתמאן ותנשא לאלתר","בשלמא עולא היינו דקתני עד שתגדיל ותנשא אלא לשמואל עד שתגדיל ותאמר מיבעי ליה קשיא:","\u0001מתני׳\u0002 אי זו היא קטנה שצריכה למאן כל שהשיאוה אמה ואחיה לדעתה השיאוה שלא לדעתה אינה צריכה למאן רבי חנינא בן אנטיגנוס אומר כל תינוקת שאינה יכולה לשמור קידושיה אינה צריכה למאן","ר' אלעזר אומר אין מעשה קטנה כלום אלא כמפותה בת ישראל לכהן לא תאכל בתרומה בת כהן לישראל תאכל בתרומה","רבי אליעזר בן יעקב אומר כל עכבה שהיא מן האיש כאילו היא אשתו כל עכבה שאינה מן האיש כאילו אינה אשתו:","\u0001גמ׳\u0002 אמר רב יהודה ואמרי לה במתניתא תנא בראשונה היו כותבין גט מיאון לא רעינא ביה ולא צבינא ביה ולית אנא בעיא להתנסבא ליה כיון דחזו דנפיש דיבורא אמרי"],[[0,"ומציא עקרא","שלא תהא צריכה גט לביאתו דהא אמרי ב\"ה ממאנת ביבם דומיא דבעל:"],[0,"נישואין קמאי עקרא","ושוב אין כאן זיקה:"],[1,"כל שיכולה למאן","בפרק קמא (לעיל יבמות ב:) בתו קטנה הנשואה לאחיו ולא קיבל אביה קידושין כגון שהשיאה אביה תחלה לאחר ונתגרשה והיא יתומה בחיי האב ויכולה למאן ולא מיאנה בו ומת צרתה חולצת שאינה צרת הבת להפטר משום צרת ערוה הואיל והבת יכולה למאן אינן נישואין גמורין ולא מתייבמת הואיל ולא מיאנה הבת הויא לה הך צרת ערוה במקצת:"],[1,"צרת ערוה שאני","דאע\"ג דמהני מיאון לקטנה יבמה בעלמא למיפק בלא חליצה לא מהני לגבי ערוה אם מיאנה באביה שהוא יבמה למיהוי צרתה מותרת ליבם:"],[1,"דתני רמי בר יחזקאל","קטנה שמיאנה בבעל מותרת לינשא לאביו דעקרתינהי לנשואין והויא כאנוסה ומפותה אבל מת בעלה ולא מיאנה בו ומיאנה ביבם אע\"ג דנפקא בלא חליצה אלמא נישואי קמאי עקרא אפ\"ה אסורה לאביו מפני מראית העין דמשעת נפילה דאהני נישואי קמאי למיפל קמי יבם ולהצריכה מיאון לגבי יבם נראית כלתו של חמיה:"],[2,"ה\"נ","אע\"ג דעקרא לנישואי קמאי נראית צרתה כצרת בתו הואיל ואהנו נישואי אחיו בבתו למרמי קמיה:"],[3,"מיאנה","יבמה באחד מן האחין יבמין אסורה לכולן:"],[3,"אבעלת הגט","אם נתן לה האחד גט פסלה על כולן:"],[6,"אמר אביי רב","לא הודה לו דאיהו אמר לעיל מיאנה בזה אסורה לזה:"],[6,"רבי אושעיא לא הודה לו","מדקאמר ר' יוחנן מותרת לאחין אע\"ג דאיהו גופיה נמי במשמע ומיהו אי איכא אחין אין דהוה ליה מיאון לחצי זיקה כרב אסי אבל בחד יבם דמיאנה בזיקה שלימה אסורה ולרבי אושעיא אפי' בחד יבם נמי שריא דאין מיאון לזיקה:"],[6,"ואמרי לה רב אסי","נמי לא הודה לו וכל שכן רבי אושעיא דרבי יוחנן דוקא לאחין אמר ולא לו:"],[7,"במדה כפושה מדד","במדה כפויה מדד לשון אונאה כמודד בשולי המדה וחברו מצאתי בתוספתא דאהלות קדירה שהיא נתונה כו' היתה כפושה לשון הכפישני באפר (איכה ג׳:ט״ז) שהיה מפסיד נכסי מלוג שלה:"],[8,"תרי קיטרי עבדו ביה","שני קשרים עשו עליו לרעתו:"],[11,"והרי מיאנה חדא זימנא","בבעלה ואמאי קתני ותמאן ותנשא:"],[11,"רוצה אני","שמא חזרה:"],[12,"תרתי קתני","לאו למיהדר למאן זימנא אחריתי אלא תרתי מילי נינהו ממאנת וממתנת מליארס לאחר עד שתגדיל כדי שלא תחזור ותמאן בשני או אם רצתה להנשא ממאנת בבעל ותנשא לאלתר דתו לא ממאנת לבית שמאי דנשואה היא:"],[15,"מתני' אין מעשה קטנה אלא כמפותה","כדקתני בת ישראל לכהן לא תאכל כו' דכמי שלא נשאת דמי:"],[16,"כל עכבה כו'","כל מה שהיא מעוכבת אצלו בשבילו כאילו היא אשתו ובגמרא מפרש מה היא:"]],[[3,"מידי דהוה אבעלת הגט","הקשה רבינו יהודה א\"כ מיאנה בבעל אמאי מותרת לאביו ניחוש מידי דהוה אבעלת הגט שאסורה לאביו ואומר דשמא הכא שייך למיחש טפי כיון שאינה אשתו ואינה אסורה במיאון ה\"ה דגט לא אסר לה כיון שאינה אשתו:"],[6,"מאן לא הודו לו אמר אביי רב","משמע אבל ר' אושעיא הודה לו ומיאנה בזה מותרת לאחין דקאמר היינו לכל האחין ה\"ל כרבי אושעיא דאמר אינה ממאנת לזיקתו מאן לא הודה לו רבי אושעיא דיש לו דאין מיאון לכולה זיקה אבל רב אסי הודה לו דאית ליה אין מיאון לחצי זיקה הא לכולה זיקה יש מיאון והא דקאמר מותרת לאחין היינו אף לו כיון דאין מיאון לחצי זיקה איכא דאמרי אמרו רב אסי וכל שכן ר' אושעיא וכן פירש בקונטרס:"],[8,"תרי קיטרי עבדו ביה","בירושלמי פריך אילו העושה דבר שלא כשורה מתירין ערוה שלו ומשני רב חסדא (היא) הדא אמרה עברה ומיאנה מן הנשואין ושלא בפניו על דעתייהו דבית שמאי מיאונה מיאון ואין זו קושיא כ\"כ דאיכא למימר דקידושי קטנה דרבנן נינהו ואפקעינהו רבנן לקידושין מינייהו:"],[10,"מכשירין בשנים","הוא הדין בחד אלא שצריך לעדות שמיאנה:"],[10,"הלכה כאותו הזוג","פר\"ח דוקא בדיעבד אבל לכתחילה לא דמכשירים דיעבד משמע:"]]],[["אתי לאיחלופי בגיטא תקינו הכי ביום פלוני מיאנה פלונית בת פלוני באנפנא","תנו רבנן אי זהו מיאון אמרה אי אפשי בפלוני בעלי אי אפשי בקידושין שקידשוני אמי ואחי יתר על כן אמר ר' יהודה אפילו יושבת באפריון והולכת מבית אביה לבית בעלה ואמרה אי אפשי בפלוני בעלי זהו מיאון","יתר על כן אמר רבי יהודה אפי' היו אורחין מסובין בבית בעלה והיא עומדת ומשקה עליהם ואמרה להם אי אפשי בפלוני בעלי הרי הוא מיאון יתר על כן אמר רבי יוסי בר יהודה אפילו שיגרה בעלה אצל חנוני להביא לו חפץ משלו ואמרה אי אפשי בפלוני בעלי אין לך מיאון גדול מזה:","רבי חנינא בן אנטיגנוס אומר כל תינוקת וכו': אמר רב יהודה אמר שמואל הלכה כרבי חנינא בן אנטיגנוס תנא קטנה שלא מיאנה ועמדה ונשאת משום רבי יהודה בן בתירה אמרו נישואיה הן הן מיאוניה","איבעיא להו נתקדשה מהו תא שמע קטנה שלא מיאנה ועמדה ונתקדשה משום ר' יהודה בן בתירה אמרו קידושיה הן הן מיאוניה","איבעיא להו פליגי רבנן עליה דרבי יהודה בן בתירה או לא אם תימצי לומר פליגי בקידושין או אפי' בנישואין ואם תימצי לומר פליגי אפילו בנישואין הלכה כמותו או אין הלכה כמותו ואם תימצי לומר הלכה כמותו בנישואין או אפילו בקידושין","תא שמע אמר רב יהודה אמר שמואל הלכה כר' יהודה בן בתירה הלכה מכלל דפליגי","ואכתי תיבעי לך דהוה נסיבא מעיקרא או דלמא מיקדשא ת\"ש דכלתיה דאבדן אימרוד שדר רבי זוגי דרבנן למיבדקינהו אמרי להו נשי חזו גברייכו דקאתו אמרי להו ניהוו גברייכו דידכו","אמר רבי אין לך מיאון גדול מזה מאי לאו דהוה נסיבא לא דהוה מיקדשא קדושי והלכה כרבי יהודה בן בתירה ואפי' בנישואין דקמא:","רבי אלעזר אומר וכו': אמר רב יהודה אמר שמואל חוזרני על כל צדדי חכמים ולא מצאתי אדם שהשוה מדותיו בקטנה כרבי אלעזר שעשאה רבי אלעזר כמטיילת עמו בחצר ועומדת מחיקו וטובלת ואוכלת בתרומה לערב","תניא רבי אליעזר אומר אין מעשה קטנה כלום ואין בעלה זכאי לא במציאתה ולא במעשה ידיה ולא בהפרת נדריה ואינו יורשה ואין מיטמא לה כללו של דבר אינה כאשתו לכל דבר אלא שצריכה מיאון","רבי יהושע אומר בעלה זכאי במציאתה ובמעשה ידיה ובהפרת נדריה ויורשה ומיטמא לה כללו של דבר הרי היא כאשתו לכל דבר אלא שיוצאה במיאון","אמר רבי נראין דברי רבי אליעזר מדברי רבי יהושע שרבי אליעזר השוה מדותיו בקטנה ורבי יהושע חלק מאי חלק אי אשתו היא תיבעי גט","לרבי אליעזר נמי אי לאו אשתו היא מיאון נמי לא תיבעי אלא בכדי תיפוק:","ר\"א בן יעקב אומר וכו': ה\"ד עכבה שהיא מן האיש ועכבה שאינה מן האיש א\"ר יהודה אמר שמואל תבעוה לינשא ואמרה מחמת פלוני בעלי זו היא עכבה שהיא מן האיש מחמת בני אדם שאינם מהוגנין לי זו היא עכבה שאינה מן האיש","אביי בר אבין ורב חנינא בר אבין דאמרי תרוייהו נתן לה גט זו היא עכבה שהיא מן האיש והוא אסור בקרובותיה והיא אסורה בקרוביו ופסלה מן הכהונה מיאנה בו זו היא עכבה שאינה מן האיש והוא מותר בקרובותיה והיא מותרת בקרוביו ולא פסלה מן הכהונה","הא קתני לקמן הממאנת באיש הוא מותר בקרובותיה והיא מותרת בקרוביו ולא פסלה מן הכהונה נתן לה גט הוא אסור בקרובותיה והיא אסורה בקרוביו ופסלה מן הכהונה פרושי קמפרש:","\u0001מתני׳\u0002 הממאנת באיש הוא מותר בקרובותיה והיא מותרת בקרוביו ולא פסלה מן הכהונה נתן לה גט הוא אסור בקרובותיה והיא אסורה בקרוביו ופסלה מן הכהונה","נתן לה גט והחזירה מיאנה בו ונשאת לאחר ונתארמלה או נתגרשה מותרת לחזור לו מיאנה בו והחזירה נתן לה גט ונשאת לאחר ונתארמלה או נתגרשה אסורה לחזור לו"],[[0,"גמ' אתי לאיחלופי בגיטא","שיכתבנו סופר בור בגט גירושין לגרש בו אשה:"],[1,"אפי' כשהיא יושבת באפריון","ונושאין אותה מבית אביה לבית בעלה לחופה ואמרה אי אפשי בו דאיכא למימר אי לא בעיא ליה תיחות ותזיל אפי' הכי הוי מיאון:"],[2,"אפי' אורחים","דליכא בית דין ותו דהני מישתק שתקי ולא קא מודעי:"],[2,"אצל חנוני","דליכא אלא חנוני ואיכא למימר משום דאטרחה הוא להביא לו חפץ משלו: ל\"ג והגדילה:"],[4,"נתקדשה","לאחר בלא מיאון:"],[5,"בקידושין","שנתקדשה לאחר פליגי דלא הוי מיאון אבל בנישואין מודו או דלמא אפי' בנישואין שנישאת לאחר בלא מיאון פליגי:"],[6,"הלכה כר' יהודה","אתרוייהו איתמר:"],[7,"דהוה נסיבא מעיקרא","לראשון ואפילו הכי נפקא במיאון קל:"],[7,"למיבדקינהו","אי הוו מיהדרין ממרדייהו:"],[9,"ועומדת מחיקו","אם בת כהן לישראל היא:"],[9,"וטובלת","מפני תשמיש ששמשה ואוכלת לערב בתרומה:"],[11,"ר' יהושע אומר זכאי במציאתה","דרבנן אפקרוה גביה והפקר בית דין היה הפקר:"],[11,"ומיטמא לה","אם כהן הוא ואע\"ג דנישואין דידה דרבנן הא אוקימנא בהאשה כיון דירית לה הויא לה כמת מצוה:"],[14,"תבעוה לינשא","בעודה תחתיו ונתעכבה מלינשא בשבילו כאילו היא אשתו וצריכה מיאון:"],[15,"נתן לה גט זו היא עכבה מן האיש","דכיון שלא מיאנה בו גליא דעתה דבשבילו היתה מעכבת אצלו ואשתו היא ליאסר בקרובותיה ופסלה בגיטו מן הכהונה:"],[15,"עכבה שאינה מן האיש","לא נתעכבה אצלו בשביל אישות:"],[17,"מתני' נתן לה גט","ואפי' היא קטנה הרי היא כשאר גרושות ואסורה בקרוביו:"],[18,"מותרת לחזור לו","אף על גב דאם לא החזירה ונישאת לאחר מתוך הגירושין ונתארמלה אסורה לראשון אפי' הכי כי החזירה ומיאנה בו אתי מיאון וגלי עלה דקטנה היא ובטלוה לגיטה ולא הוי בחזרה שניה כמחזיר גרושתו משניסת לאחר:"]],[[0,"אתי לאיחלופי בגיטא","פירוש שיכתבנו סופר בור בגט ומשמע מכאן לשבש מה שכתב בתיקוני גט מיאון לא רעינא ביה כו' אלא כתבינן ליה כדמשמע הכא:"],[3,"קטנה שלא מיאנה ועמדה ונתקדשה קידושיה הן הן מיאוניה","והא דתניא לעיל ונישאת הוא הדין נתקדשה אלא לא חש לדקדק כיון שאין יודע חילוק בין קידושין בין נשואין:"],[6,"תא שמע דאמר רב יהודה אמר שמואל הלכה כרבי יהודה בן בתירה","ואכולהו קאי בין אקדושין בין אנישואין מכלל דרבנן פליגי עליה אפילו בנישואין:"],[10,"כללו של דבר אינה כאשתו לכל דבר","לאתויי בת ישראל לכהן לא תאכל בתרומה ובת כהן לישראל תאכל ולר' יהושע איפכא:"],[14,"מחמת בני אדם שאינם מהוגנים לי זו היא עכבה שאין מן האיש","פירוש והוי מיאון ותימה דאם כן תיפשוט הא דבעי לעיל אי הלכה כר' יהודה בן בתירה בנישואין דהכא משמע בשאינה רוצה להנשא מחמת שאינן מהוגנין לה דהויא מיאון כ\"ש אם נשאת לו ומשנת רבי אלעזר בן יעקב קב ונקי וי\"ל דהכא לא איירי במיאון אלא בקטנה שנישאת שלא לדעתה קאי וקאמר עלה ר\"א בן יעקב דאי אמרה מחמת בני אדם שאינן מהוגנים הוי שלא לדעתה מחמת פלוני בעלי הוי לדעתה וצריכה מיאון והשתא לא שייך מידי לההיא דלעיל:"]]],[["זה הכלל גט אחר מיאון אסורה לחזור לו מיאון אחר גט מותרת לחזור לו","הממאנת באיש ונשאת לאחר וגירשה לאחר ומיאנה בו לאחר וגירשה זה הכלל כל שיוצאה הימנו בגט אסורה לחזור לו במיאון מותרת לחזור לו:","\u0001גמ׳\u0002 אלמא אתי מיאון ומבטל גט ורמינהי","הממאנת באיש ונשאת לאחר וגירשה לאחר ומיאנה בו לאחר וגירשה זה הכלל כל שיצתה הימנו בגט אסורה לחזור לו במיאון מותרת לחזור לו אלמא לא אתי מיאון דחבריה ובטיל גיטא דידיה","אמר רב יהודה אמר שמואל תברא מי ששנה זו לא שנה זו","אמר רבא ומאי קושיא ודלמא מיאון דידיה מבטל גט דידיה מיאון דחבריה לא מבטל גיטא דידיה ומאי שנא מיאון דחבריה דלא מבטל גיטא דידיה איידי דמכרת ברמיזותיו וקריצותיו אזל משבש ומייתי לה מיאון דידיה נמי לא ליבטל גיטא דידיה דאיידי דמכרת ברמיזותיו וקריצותיו אזיל משבש ומייתי לה","הא כבר שבשא ולא אישבשא","אלא אי קשיא דחבריה אדחבריה קשיא מיאנה בו והחזירה נתן לה גט ונשאת לאחר ונתארמלה או נתגרשה אסורה לחזור לו טעמא דנתארמלה או נתגרשה הא מיאנה מותרת לחזור לו אלמא אתי מיאון דחבריה ומבטל גיטא דידיה","ורמינהי הממאנת באיש ונשאת לאחר וגירשה לאחר ומיאנה בו זה הכלל כל שיצתה ממנו בגט אסורה לחזור לו במיאון מותרת לחזור לו אלמא לא אתי מיאון דחבריה ומבטל גיטא דידיה","אמר רבי אלעזר תברא מי ששנה זו לא שנה זו עולא אמר כגון ששלשה בגיטין דמיחזיא כגדולה","מאן תנא אמר רב יהודה אמר רב מאי דכתיב (איכה ה, ד) מימינו בכסף שתינו עצינו במחיר יבאו בשעת הסכנה נתבקשה הלכה זו הרי שיצאה מראשון בגט ומשני במיאון מהו שתחזור לראשון","שכרו אדם אחד בארבע מאות זוז ושאלו את ר' עקיבא בבית האסורין ואסר את רבי יהודה בן בתירה בנציבין ואסר","אמר רבי ישמעאל בר' יוסי לזו לא הוצרכנו לאיסור כרת התרת לאיסור לאו לא כל שכן","ברם כך שאלו הרי היתה אשת אחי אמו שהיא שנייה לו ונשאה אחיו מאביו ומת מהו שתמאן השתא ותעקרינהו לנישואין קמאי ותתייבם צרתה יש מיאון לאחר מיתה במקום מצוה או לא","שכרו שני בני אדם בארבע מאות זוז ובאו ושאלו את רבי עקיבא בבית האסורין ואסר את רבי יהודה בן בתירה בנציבין ואסר","אמר רב יצחק בר אשיאן ומודה רב שמותרת לאחיו של זה שנאסרה עליו","פשיטא הוא ניהו דמכרת ברמיזותיו וקריצותיו אבל אחיו לא מהו דתימא ליגזר האי אטו האי קמ\"ל","ואיכא דאמרי אמר רב יצחק בר אשיאן כשם שאסורה לו כך אסורה לאחין והא אינה מכרת בקריצותיהם ורמיזותיהם גזירה אחיו אטו הוא:","\u0001מתני׳\u0002 המגרש את האשה והחזירה מותרת ליבם"],[[0,"זה הכלל","כלומר אפילו פעמים הרבה גירשה והחזירה ומיאנה אם נשאת לאחר מתוך גט אסורה לחזור לו מתוך המיאון מותרת לחזור לו:"],[1,"לאחר ומיאנה בו","כלומר חזרה ונשאת לשלישי ומיאנה בו:"],[1,"כל שיוצאה ממנו בגט אסורה לחזור לו","אף על פי שיצתה משל אחרון במיאון לא בטליה לגיטא דידיה. ובגמרא פרכינן רישא לסיפא:"],[4,"גמ' תברא","קשיין אהדדי:"],[5,"ומאי שנא מיאון דחבריה דלא מבטל גיטא","דקמא לאישתרויי לה לקמא:"],[5,"דאיידי דמכרת ברמיזותיו ובקריצותיו","דקמא:"],[5,"אזיל ומשבש לה","עד דממאנת בבתרא ומהדר לה:"],[6,"הא שבשא ולא אשתבשא","שהרי לאחר גירושין החזירה ולא יכול לפייסה שתעמוד עמו ומיאנה בו הילכך ליכא למיחש לה לשיבושא וכן כל היוצאת במיאון לא חיישינן לשיבושא דמסתמא פייסה כי הואי גביה שלא תמאן ולא איפייסה אבל כי נישאת לאחר מתוך הגט הולך ומפייסה ואמר מתחרט אני בגירושין והיא אוהבתו שהרי על כרחה יצתה ממנו הילכך הדרה וממאנת בשני:"],[7,"הא מיאנה מותרת לחזור","לראשון:"],[7,"אלמא אתי מיאון דחבריה","ומגלה על קטנות ומבטל גיטא מקמא:"],[9,"ששלשה בגיטין","שהוציאה שלש פעמים בגט דמיחזיא כגדולה תו לא הדרא לחד מינייהו דלא אתי מיאון דאחר לבטולי אבל קודם שתשלש אתי מיאון דחבריה ומבטל גיטא ואי בעיא לאהדורה מהדר לה:"],[10,"מאן תנא","דאמרן לעיל מי ששנה זו לא שנה זו:"],[10,"בשעת הסכנה","שנגזר שלא יעסקו בתורה:"],[10,"בכסף שתינו","על ידי שכירות למדנו:"],[12,"את רבי ישמעאל בר' יוסי והתיר ל\"ג","אלא אדרב פליג ואמר לא את זו אסרו רבי עקיבא ורבי יהודה בן בתירא ותנאי דקאמר היינו רב ורבי ישמעאל דרב נמי תנא הוא:"],[12,"לאיסור כרת","איסור אשת איש הפקעת ממנה בלא גט. אלמא אין מעשה שלה כלום:"],[12,"לאיסור לאו","דמחזיר גרושתו לא כ\"ש דגלי דקטנה היא ולא הוה גיטה כלום:"],[13,"אשת אחי האם","שנייה מדברי סופרים גזירה משום אשת אחי האב שהיא ערוה:"],[13,"מהו שתמאן","בנישואין הראשונים שלא תהא שנייה לו ותתייבם. אבל באישות דערוה כגון אשת אחיו מאמו קטנה ומת ונשאה אחיו מאביו פשיטא לן דלא אתי מיאון דלאחר מיתה למישרי ערוה לייבומה:"],[15,"ומודה רב","אע\"ג דלא אתי מיאון דחבריה ומבטל גיטא דידיה נהי דלדידיה לא הדרה אבל לגבי אחיו נתבטל דלא תיהוי גרושת אחיו. והא דקתני מתני' נתן לה גט אסורה בקרוביו היכא דתו לא נפיק מאחרים במיאון דלא איבטל גיטא דקמא:"],[16,"פשיטא","דהא תנן במתני' אתי מיאון ומבטל גיטא ואפי' דידיה לא אסרנא אלא איידי דמכרת ברמיזותיו אזיל ומשבש לה אבל אחיו ליכא למימר הכי:"],[16,"מהו דתימא ניגזור אחיו אטו הוא","דאי שריא ליה לאחיו אמרי הא חזינן דבטל גיטא ואתי איהו למינסב:"],[18,"מתני' מותרת ליבם","ולא אמרינן נישואין הראשונים מפילים יבמה לפני יבם והרי נאסרו עליו אותן נישואין בשעת שגירשה אחיו והויא ליה גרושת אחיו:"]],[[2,"אלמא אתי מיאון ומבטל גיטא ורמינהי הממאנת באיש כו'","מגופה דסיפא הוה מצי לאקשויי דמאי טעמא אמרינן כל שיוצאה ממנו בגט אסורה ואמאי לא אמרינן אתי מיאונה ומפקע קידושי שני והוי כמו שזינתה אחר גירושין דמותרת לחזור לו כדתנן בפ\"ב דסוטה (דף יח: ושם) אלא ניחא ליה לאקשויי רישא אסיפא:"],[5,"אזיל ומשבש ומייתי לה","אבל לא ניחא ליה למימר דאפי' ליכא גט לא יחזיר דלמא אזיל ומשבש לה (תחתיו) דהא כיון דליכא למיחש למידי לא גזרינן:"],[9,"אמר ר' אלעזר תברא כו'","רבא הוא דמסיק הכי אע\"ג דרב יהודה הוה בשינוייא קמא יודע היה רבא שכך היתה הקושיא ומשמיה דרבי אלעזר [נאמרה] וכה\"ג בפרק כירה (שבת מד. ושם) דאמר רב הונא מטה שיחדה למעות כו' ומותיב רב נחמן בר יצחק כו' אלא אי איתמר הכי איתמר אמר רב יהודה כו' ולא קאמר משמיה דרב הונא כדמעיקרא לפי שהיה יודע האמת שרב יהודה אמרה:"],[9,"כגון ששלשה בגיטין דמיחזיא כגדולה","וא\"ת לר' אלעזר למה איצטריך למיתני מיאנה לאחר וגירשה תרי זימני וי\"ל דקמ\"ל אע\"ג דגירשה תרי זימני לא חיישינן למיחזי כגדולה:"],[12,"לאיסור כרת התרת לאיסור לאו לא כ\"ש","פירש בקונט' איסור כרת דא\"א שהמיאון מפקיע הקידושין והקשה ריב\"ן דלא דמי איסור אשת איש למחזיר גרושתו דמיאון מפקיע הקידושין שאומרת אי אפשי בקידושין שקדשוני אמי ואחי אבל גט לא מפקיע ולאו קושיא היא דמהאי טעמא שמפקיע המיאון איסור דאשת איש א\"כ הויא כזונה אצלו ומותרת לחזור לו לאחר שגירשה כדתנן פרק שני דסוטה (דף יח: ושם) וריב\"ן פירש איסור כרת התרת שמותרת בקרוביו והוא בקרובותיה אפי' למי שיצאה ממנו בגט דהיינו אשת אחיו ואחות אשתו ואין נראה דא\"כ תיקשה למ\"ד בסמוך כשם שאסורה לו כך אסורה לאחיו אלמא לאיסור כרת לא התרת:"],[13,"יש מיאון אחר מיתה באחיו או לא","דוקא הכא הוא דמיבעיא ליה באיסור שנייה דרבנן היא אבל באיסור ערוה דאורייתא תנן כל שיכולה למאן ולא מיאנה צרתה חולצת ולא מתייבמת:"]]],[["ורבי אלעזר אוסר וכן המגרש את היתומה והחזירה מותרת ליבם ורבי אלעזר אוסר קטנה שהשיאה אביה ונתגרשה כיתומה בחיי האב והחזירה דברי הכל אסורה ליבם:","\u0001גמ׳\u0002 אמר עיפה מאי טעמא דרבי אלעזר הואיל ועמדה עליו שעה אחת באיסורא אמרו ליה רבנן לעיפה אי הכי חליצה נמי לא תיבעי","וכי תימא הכי נמי והתניא משום רבי אלעזר אמרו חולצת אלא אמר עיפה ר' אלעזר לא ידענא מאי טעמא","אמר אביי היינו טעמא דרבי אלעזר מספקא ליה אי מיתה מפלת אי נשואין הראשונים מפילים אי מיתה מפלת הא רמיא קמיה לייבום אי נשואין הראשונים מפילים הא עמדה עליו שעה אחת באיסור","רבא אמר לעולם פשיטא לרבי אלעזר דמיתה מפלת ומיהו הכל בקיאין בגירושין ואין הכל בקיאין בחזרה","אדרבה חזרה כיון דיתבא תותיה אית ליה קלא מי לא עסקינן דאהדרה באורתא ושכיב בצפרא","רב אשי אמר היינו טעמא דרבי אלעזר דגזר הני משום יתומה בחיי האב והחזירה הכי נמי מסתברא מדקתני סיפא קטנה שהשיאה אביה ונתגרשה כיתומה בחיי האב והחזירה דברי הכל שאסורה ליבם","האי מאי למימרא פשיטא אלא לאו הא קמ\"ל טעמא דר' אלעזר דגזר הנך משום האי שמע מינה","תניא כוותיה דרב אשי מודים חכמים לר' אלעזר בקטנה שהשיאה אביה ונתגרשה הרי היא כיתומה בחיי האב והחזירה שאסורה ליבם מפני שגירושיה גירושין גמורין ואין חזרתה חזרה גמורה","בד\"א שגירשה כשהיא קטנה והחזירה כשהיא קטנה אבל גירשה כשהיא קטנה והחזירה כשהיא גדולה אי נמי החזירה כשהיא קטנה וגדלה אצלו ומת או חולצת או מתייבמת משום רבי אלעזר אמרו חולצת ולא מתייבמת","בעא מיניה רבא מרב נחמן צרתה מהו אמר ליה היא גופה גזירה ואנן ניקום וניגזור גזירה לגזירה","והא תניא משום רבי אלעזר אמרו היא וצרתה חולצת היא וצרתה סלקא דעתך אלא לאו או היא או צרתה חולצת לאו תרוצי קמתרצת תריץ הכי היא חולצת צרתה או חולצת או מתייבמת:","\u0001מתני׳\u0002 שני אחין נשואין לשתי אחיות קטנות ומת בעלה של אחת מהן הלזו תצא משום אחות אשה וכן שתי חרשות גדולה וקטנה מת בעלה של קטנה תצא הקטנה משום אחות אשה","מת בעלה של גדולה רבי אליעזר אומר מלמדין את הקטנה שתמאן בו","רבן גמליאל אומר אם מיאנה מיאנה ואם לאו תמתין עד שתגדיל ותצא הלזו משום אחות אשה","רבי יהושע אומר אי לו על אשתו אי לו על אשת אחיו מוציא את אשתו בגט ואשת אחיו בחליצה:","\u0001גמ׳\u0002 ומי שרי והתני בר קפרא לעולם ידבק אדם בשלשה דברים ויתרחק משלשה דברים ידבק בשלשה דברים בחליצה ובהבאת שלום ובהפרת נדרים ויתרחק משלשה דברים מן המיאון ומן הפקדונות ומן הערבונות מיאון דמצוה שאני:","גופא תני בר קפרא לעולם ידבק אדם בשלשה דברים בחליצה כאבא שאול דתניא אבא שאול אומר הכונס את יבמתו לשם נוי לשם אישות לשם דבר אחר כאילו פוגע בערוה וקרוב בעיני להיות הולד ממזר","בהבאת שלום דכתיב (תהלים לד, טו) בקש שלום ורדפהו"],[[0,"ורבי אלעזר אוסר","מפרש טעמא בגמ':"],[0,"וכן המגרש היתומה","קטנה שהשיאוה אמה ואחיה והחזירה בין בקטנותה בין בגדלותה מותרת ליבם כדאמר דמיתה מפלת ובשעת מיתה היתה אשתו:"],[0,"קטנה שהשיאה אביה ונתגרשה","בקטנותה וקבל אביה גיטה כדאמר בפרק נערה שנתפתתה (כתובות מו:) ומקבל את גיטה הרי היא כיתומה בחיי האב אע\"פ שאביה חי הוא היא כיתומה לענין קידושין דשוב אין לו כח לקבל קידושיה כדאמר התם אם משהשיאה אין לאביה רשות בה:"],[0,"והחזירה בקטנותה אסורה ליבם","אם מת בקטנותה ואפי' לרבנן דגירושיה גירושין גמורין ואין חזרתה חזרה גמורה דקידושי קטנה אינן כלום הואיל ופקע זכות אב והיא אין לה יד והויא לה כגרושה ועומדת:"],[1,"גמ' עיפה","שם חכם:"],[1,"שעה אחת","באיסור גרושת אחיו שהיא בכרת:"],[3,"אי מיתת בעל מפלת","לייבום או כח נישואין הראשונים:"],[4,"בקיאים בגירושין","הכל רואין שגרשה דגירושין קלא אית להו אבל חזרה לית ליה קלא דזימנין דקא מהדר לה באורתא ושכיב בצפרא דלא חזו אינשי בחזרתה ואמרי זה מייבם גרושת אחיו:"],[5,"מי לא עסקינן","מי ליכא לאוקומי נמי מתני' בהכי דזימנין דהוי הכי:"],[7,"פשיטא","דהואיל ואין לאביה רשות בה והיא קטנה אין חזרתה חזרה והרי היא כגרושה אלא להכי תנייה במתני' לאשמועינן דטעמא דקמייתא משום הא:"],[7,"דגזר הנך","כל מוחזרת גזר משום יתומה בחיי האב דאמרי' במתני' דלאחר חזרתה הרי היא כגרושה:"],[9,"בד\"א","דחכמים מודים כשגירשה כשהיא קטנה וקבל אביה גיטה והחזירה כשהיא קטנה דאין כח לא לאביה ולא לה לקדשה ומת כשהיא קטנה דלא בעלה משגדלה דתהוי ביאה משגדלה קידושין:"],[9,"וגדלה אצלו","אמרי' סתם ביאה ראשונה משגדלה קידושין הן:"],[9,"משום ר' אלעזר אמרו כו'","ומדקתני לעיל ומודים חכמים לרבי אלעזר ביתומה בחיי האב אלמא איירי בה רבי אלעזר דטעמא דבאחרנייתא משום הא:"],[10,"צרתה","דמוחזרת גדולה לר\"א מהו:"],[10,"היא גופא גזירה","משום יתומה בחיי האב:"],[10,"גזירה לגזירה","צרתה אטו היא:"],[11,"היא חולצת","אם בא יבם להזקק לה חולצת ופוטרת צרתה ולא מתייבמת אבל אם נזקק לצרתה או חולצת או מתייבמת והיא נפטרת:"],[12,"מתני' תצא משום אחות אשה","ופטורה מחליצה ומייבום:"],[13,"מת בעלה של גדולה","ונפלה לפני בעל הקטנה זיקתה של גדולה שהיא מן התורה אוסרת הקטנה עליו דנישואיה מדרבנן ולא אלימא לאפקועי זיקה דאורייתא והויא לה אחות זקוקתו ומה יעשו:"],[13,"רבי אליעזר אומר מלמדין הקטנה שתמאן בו","ותעקור נישואיה ויהא מייבם את הגדולה:"],[14,"ר\"ג אומר","אין זיקתה אוסרת את זו דר\"ג סובר אין זיקה כלומר לא אלימא זיקה כדפי' בפ' ר\"ג (לעיל יבמות נא.) הלכך אם מיאנה מיאנה ותתייבם גדולה ואם לאו תמתין קטנה אצלו עד שתגדיל ויהיו נישואיה גמורין ותצא הלזו משום אחות אשה אבל מיחלץ לגדולה לא דפסל את הקטנה עליו משום אחות חלוצה:"],[15,"אי לו","אוי לו:"],[15,"מוציא את אשתו בגט","ואין מלמדין אותה למאן כדאמר בגמ' יתרחק אדם מן המיאונין ומיתב נמי לא יתבה תותיה דקסבר יש זיקה אלא תצא בגט וזו לא תתייבם משום אחות גרושה אלא תצא בחליצה:"],[16,"גמ' ומי שרי","ללמד קטנה שתמאן:"],[16,"ידבק אדם כו'","מפרש טעמא דכולהו לקמן:"],[16,"מן ערבון","שלא יהא ערב:"],[17,"כאבא שאול","פרק החולץ הכונס יבמתו לשם נוי וכו':"]],[[10,"היא גופה גזירה ואנן ניקום ונגזור גזירה לגזירה","פי' בקונטרס היא גופה גזירה משום יתומה בחיי האב ואין נראה לר\"י דהא רב אשי הוא דאמר להאי טעמא ולא רבא אלא יש לפרש היא גופה גזירה שמא יאמרו העולם ייבם גרושת אחיו לפי שהכל בקיאין בגירושין ואין הכל בקיאין בחזרה כדאמר רבא לעיל ולאו דוקא קאמר גזירה לגזירה דלא שייך הכא אלא כלומר אינה אלא איסורא דרבנן:"],[16,"ויתרחק מן המיאונים","פר\"ח בריש פירקין (לעיל יבמות קז:) בשם גאון דאין לקדש יתומה עד שיביאו ראיה שהיא בוגרת כדי להתרחק מן המיאונים והא דתקינו לה רבנן נישואין כדאמר לקמן (יבמות דף קיב:) צריך לומר לדברי הגאון דהיינו דוקא היכא שיש לחוש שלא ינהגו בה מנהג הפקר ומיהו מהכא אין לו ראיה אלא שלא ילמדוה למאן:"]]],[["ואמר רבי אבהו אתיא רדיפה רדיפה כתיב הכא (תהלים לד, טו) בקש שלום ורדפהו וכתיב התם (משלי כא, כא) רודף צדקה וחסד ימצא חיים צדקה וכבוד: בהפרת נדרים כרבי נתן דתניא רבי נתן אומר הנודר כאילו בנה במה והמקיימו כאילו הקריב עליה קרבן","ויתרחק משלשה דברים מן המיאונין דלמא גדלה ומיחרטא בה מן הפקדונות בבר מתא דבייתיה כי בייתיה דמי מן הערבון בערבי שלציון","דא\"ר יצחק מאי דכתיב (משלי יא, טו) רע ירוע כי ערב זר רעה אחר רעה תבא למקבלי גרים ולערבי שלציון ולתוקע עצמו לדבר הלכה מקבלי גרים כר' חלבו דאמר ר' חלבו קשים גרים לישראל כספחת בעור","ערבי שלציון דעבדי שלוף דוץ תוקע עצמו לדבר הלכה דתניא רבי יוסי אומר כל האומר אין לו תורה אין לו תורה פשיטא אלא כל האומר אין לו אלא תורה אין לו אלא תורה","הא נמי פשיטא אלא דאפילו תורה אין לו מאי טעמא אמר רב פפא אמר קרא (דברים ה, א) ולמדתם ועשיתם כל שישנו בעשיה ישנו בלמידה כל שאינו בעשיה אינו בלמידה","ואיבעית אימא לעולם כדאמריתו מעיקרא כל האומר אין לו אלא תורה אין לו אלא תורה לא צריכא דקא מגמר לאחריני ואזלי ועבדי מהו דתימא אית ליה אגרא לדידיה קמ\"ל","ואיבעית אימא תוקע עצמו לדבר הלכה בדיינא דאתי דינא לקמיה וגמר הלכה ומדמי מילתא למילתא ואית ליה רבה ולא אזיל משאיל","דאמר רבי שמואל בר נחמני אמר רבי יונתן לעולם יראה דיין עצמו כאילו חרב מונחת לו בין יריכותיו וגיהנם פתוחה לו מתחתיו שנאמר (שיר השירים ג, ז) הנה מטתו שלשלמה ששים גבורים סביב לה מגבורי ישראל וגו' מפחד בלילות מפחד של גיהנם שדומה ללילה:","ר\"ג אומר אם מיאנה וכו': בעא מיניה רבי אלעזר מרב מאי טעמא דר\"ג משום דקסבר קידושי קטנה מיתלא תלו וכי גדלה גדלי בהדה אע\"ג דלא בעל","או דלמא משום דקסבר המקדש אחות יבמה נפטרה יבמה והלכה לה אי בעל אין אי לא בעל לא","אמר ליה היינו טעמא דר\"ג משום דקסבר המקדש אחות יבמה נפטרה יבמה והלכה לה אי בעל אין אי לא בעל לא","אמר רב ששת אמינא כי ניים ושכיב רב אמר להא שמעתא דתניא המקדש את הקטנה קידושיה תלויין מאי תלויין לאו כי גדלה גדלי בהדה ואע\"ג דלא בעל","אמר ליה רבין בריה דרב נחמן הא מילתא דקטנה מיתלא תליא וקיימא אי בעל אין אי לא בעל לא דאמרה הוא עדיף מינאי ואנא עדיפנא מיניה","וסבר רב אי בעל אין אי לא בעל לא והא איתמר קטנה שלא מיאנה והגדילה ועמדה ונשאת רב אמר אינה צריכה גט משני ושמואל אמר צריכה גט משני"],[[0,"וא\"ר אבהו","במסכת קידושין:"],[0,"אתיא רדיפה רדיפה","תשלום שכר גדול להבאת שלום שאוכל פירותיהן בעולם הזה והקרן קיימת לו לעולם הבא כגמילות חסדים דכתיב בהו ימצא חיים צדקה בעולם הבא וכבוד בעולם הזה:"],[0,"כאילו בנה במה","בשעת איסור הבמות דחוטא הוא דכתיב (דברים כ״ג:כ״ג) וכי תחדל לנדור וגו' הא לא תחדל יהיה בך חטא:"],[0,"כאילו הקריב קרבן","שעבר עליו שתי עבירות אלא ילך אצל חכם ויתירנו כדי שלא יהא רגיל בכך:"],[1,"בבר מתא","לא יקבל פקדון מבן עירו:"],[1,"דבייתיה כי בייתיה דמי","שרגיל אצלו ויטול את שלו ויחזור ויתבענו:"],[1,"שלציון","שם מקום שמניחין הלוה ותופסין הערב לישנא אחרינא שלציון קוראין שם הערבון על שם נוטריקון שלוף דוץ שולף עצמו מן הלוה ותוקע עצמו על הערב:"],[2,"רע ירוע","רעה אחר רעה:"],[2,"כי ערב זר","המערב זרים גרים בישראל והנכנס בערבון נמי משמע:"],[2,"ולתוקע עצמו","סיפא דקרא ושונא תוקעים בוטח וכולה מפרש לה:"],[2,"תוקע עצמו לדבר הלכה","שאומר הריני שונה ואיני מקיים ואקבל שכר למוד:"],[2,"קשים גרים","שאין בקיאין בדקדוקי מצות ולמדין ישראל ממעשיהן:"],[2,"כספחת","לישנא דקרא נקט ונלוה הגר עליהם ונספחו על בית יעקב (ישעיהו י״ד:א׳):"],[3,"דוץ","לשון תיקוע כדאמר דצה שלפה (שבת דף נ:):"],[3,"אין לו תורה","אינו עוסק בתורה:"],[3,"אין לו תורה","אין מקבל שכר למוד:"],[3,"אלא תורה","ואין מקיים:"],[4,"אפילו תורה","אפי' שכר לימוד אין לו:"],[5,"ואיבעית אימא","כדמעיקרא אין לו אלא תורה ודקאמרת האי נמי פשיטא לא צריכא כו':"],[5,"אית ליה אגרא","דעשיה:"],[6,"וגמר הלכה","יודע הלכה שאין דומה לדין הבא לפניו כל כך ומדמי מילתא למילתא ולא משאיל לרביה. והיינו תוקע שסומך ונשען על ההלכה שהוא יודע:"],[7,"גיבורים","דיינים:"],[7,"שלשלמה","שהשלום שלו:"],[7,"מטתו","בית המקדש ששם לשכת הגזית:"],[8,"מאי טעמא דר' גמליאל","דאמר כשתגדיל זו תצא זו בולא כלום:"],[8,"גדלי בהדה ואע\"ג דלא בעל","דניקדשה השתא מ\"מ משגדלה תפסי קידושי מעיקרא ואיגלי מילתא למפרע דזיקה דהך לא כלום הוא:"],[9,"או דלמא","קידושין קמאי לא כלום נינהו ומשום קידושין דבעילה דמשגדלה נפקא הך יבמה. ואע\"ג דזיקה קודמת לקידושין קסבר המקדש אחות יבמה נפטרה יבמה דאתי קידושי ומבטלי לזיקה:"],[12,"מיתלא תלי","כל ימי קטנות ספק יבעול משתגדיל ותהיה אשתו ספק לא יבעול ולא סמכה דעתה:"],[12,"דאמרה איהו עדיף מינאי","ויוציאני בגט בעל כרחי:"],[12,"ואנא עדיפנא מיניה","וכל זמן שארצה אצא במיאון על כרחו:"]],[[0,"אתיא רדיפה רדיפה","אבל מדכתיב לעיל מי האיש החפץ חיים וגו' לא מצי דייק דדלמא קאי אכולא פרשתא נצור לשונך מרע סור מרע ועשה טוב וגו' דהיינו כל התורה כולה אי נמי הכא כתיב צדקה חיים וכבוד דלא הוה נפקא לן מההוא קרא בפ\"ק דקידושין (דף מ.) דאדם אוכל מפירותיהן בעולם הזה והקרן קיימת לו לעולם הבא:"],[0,"הנודר כאילו בנה במה","י\"מ דנפקא לן חדלה חדלה כתיב הכא וכי תחדל לגדור וכתיב התם חדלו לכם מן האדם אשר נשמה באפו כי במה נחשב ואמר בפ\"ק דברכות (דף יד. ושם) אל תקרי במה אלא במה וג\"ש דחדלה דריש בפרק ד' נדרים (נדרים דף כב.) אמר שמואל הנודר אע\"פ שמקיימו נקרא רשע אמר ר' אבהו מאי קראה כתיב הכא וכי תחדל לנדור וכתיב התם שם רשעים חדלו רוגז:"],[2,"רעה אחר רעה תבא למקבלי גרים","אמר ר\"י דהיינו היכא שמשיאין אותן להתגייר או שמקבלין אותן מיד אבל אם הן מתאמצין להתגייר יש לנו לקבלם שהרי מצינו שנענשו אברהם יצחק ויעקב שלא קבלו לתמנע שבאתה להתגייר והלכה והיתה פלגש לאליפז בן עשו ונפק מינה עמלק דצערינהו לישראל כדאמרינן בהגדת חלק (סנהדרין צט:) וגם יהושע קבל רחב הזונה ונעמה ורות המואביה ובריש פרק במה מדליקין (שבת לא.) שגייר הלל אותו שאמר גיירני על מנת שתשימני כ\"ג ואותו דעל מנת שתלמדני כל התורה כולה ואע\"פ שלא היו מתאמצין להתגייר יודע היה הלל בהן שסופם להיות גרים גמורים כמו שעשה לבסוף:"],[5,"מהו דתימא אית ליה אגרא","תימה דאמרי' בפרק בתרא דיומא (דף פז.) כל המזכה את הרבים אין חטא בא על ידו ומפרש טעמא התם שלא יאמרו הרב בגיהנם ותלמידו בגן עדן ועוד קשה לר\"י הרי אחר דר\"מ למד לפניו ואפ\"ה יצא לתרבות רעה ושמא היכא שהוא רע מתחלה קודם שמלמד אחרים התם לא שייך האי טעמא אבל היכא שהיה טוב מתחלה אז ודאי אין חטא בא על ידו ואחר מתחלתו היה רע כדאמר בחגיגה (דף טו:) שכלי זמר לא פסק מתוך ביתו וגם ספרי צדוקים היו נושרים מחיקו:"],[7,"ששים גבורים סביב לה","פירש בקונטרס [הכא] ובסנהדרין (דף ז.) דאלשכת הגזית קאי וקשה דה\"ל למימר ע' או ע\"א אלא י\"ל דאששים ריבוא ישראל קאי:"],[7,"אחוזי חרב","משמע ליה מזויינין בדין כדדרשינן בסנהדרין (דף לו.) מויחגור דוד חרבו שדנו לנבל בסנהדרין ואע\"ג דבתורה כתיב חגור חרבך על ירך גבור (תהילים מ״ה:ד׳):"],[8,"וכי גדלה גדלי בהדה ואע\"ג דלא בעל","ואפי' סבירא לן מקדש אחות יבמה לא נפטרה יבמה מ\"מ היכא שהקידושין היו באים ממילא נפטרה יבמה מעצמה:"],[12,"הוא עדיף מינאי","פירוש שיכול להוציאני בגט בעל כרחי ואנא עדיפא מיניה שאוכל למאן בו כל זמן שלא בעל והיינו דוקא מן התורה יכולה למאן אבל מדרבנן אין יכולה משהביאה ב' שערות דתנן בפ' בא סימן (נדה נב.) עד מתי הבת ממאנת עד שתביא ב' שערות והיינו אפילו לא בעל דבבעל לא הוה פליג רבי יהודה עד שירבה השחור על הלבן כדאמר התם בגמרא דמודי רבי יהודה בבעל:"]]],[["מאי לאו דלא בעל לא דבעל אי דבעל מאי טעמא דשמואל קסבר כל הבועל על דעת קדושין הראשונים הוא בועל","והא פליגי בה חדא זימנא דאיתמר קדשה על תנאי וכנסה סתם רב אמר צריכה הימנו גט ושמואל אמר אינה צריכה הימנו גט","רב אמר צריכה הימנו גט כיון דנסבה אחולי אחליה לתנאיה ושמואל אמר אינה צריכה הימנו גט כל הבועל על דעת קדושין הראשונים הוא בועל","צריכא דאי איתמר ההיא בההיא קאמר רב משום דאיכא תנאה וכיון דבעל אחליה לתנאיה אבל בהא אימא מודה ליה לשמואל ואי איתמר בהא בהך קאמר שמואל אבל בהך אימא מודה ליה לרב צריכא","ומי אמר רב כי בעל אין אי לא בעל לא והא ההיא עובדא דהוה בנרש ואיקדישה כשהיא קטנה וגדלה ואותביה אבי כורסייא ואתא אחרינא וחטפה מיניה ורב ברונא ורב חננאל תלמידי דרב הוו התם ולא הצריכוה גיטא מבתרא","אמר רב פפא בנרש מינסב נסיבי והדר מותבי אבי כורסייא רב אשי אמר הוא עשה שלא כהוגן לפיכך עשו בו שלא כהוגן ואפקעינהו רבנן לקידושי מיניה","אמר ליה רבינא לרב אשי תינח דקדיש בכספא קדיש בביאה מאי שויוה רבנן לבעילתו בעילת זנות אמר רב יהודה אמר שמואל הלכה כרבי אליעזר וכן אמר רבי אלעזר הלכה כרבי אליעזר:","\u0001מתני׳\u0002 מי שהיה נשוי לשתי יתומות קטנות ומת ביאתה או חליצתה של אחת מהם פוטרת צרתה וכן שתי חרשות קטנה וחרשת אין ביאת אחת מהן פוטרת צרתה","פקחת וחרשת ביאת הפקחת פוטרת החרשת ואין ביאת החרשת פוטרת את הפקחת גדולה וקטנה ביאת הגדולה פוטרת הקטנה ואין ביאת הקטנה פוטרת הגדולה:","\u0001גמ׳\u0002 וחרשת בת חליצה היא והתנן חרש שנחלץ וחרשת שחלצה וחולצת מן הקטן חליצתה פסולה","אמר רב גידל אמר רב אביאה רבא אמר אפילו תימא אחליצה כאן בחרשת מעיקרא כאן בפקחת ואח\"כ נתחרשה","חרשת מעיקרא כי היכי דעל הכי נפק פקחת ואחר כך נתחרשה לא דמעכבא בה קרייה","איתיביה אביי וחרשת מעיקרא בת חליצה היא והתנן שני אחין אחד פקח ואחד חרש נשואין לשתי נכריות אחת פקחת ואחת חרשת מת חרש בעל חרשת מה יעשה פקח בעל פקחת כונס ואם רצה להוציא יוציא","מת פקח בעל פקחת מה יעשה חרש בעל חרשת כונס ואינו מוציא לעולם מאי לאו בחרשת מעיקרא וקתני כונס אין"],[[0,"מאי לאו דלא בעל","ראשון משגדלה וקאמר רב אינה צריכה גט משני דחלו קידושין הראשונים כשגדלה:"],[0,"כשבעל","לפיכך אינה צריכה גט משני דבעילה שבעל הראשון משגדלה סתמא לשם קדושין נתכוון דיודע היה שאין קידושי קטנה כלום:"],[1,"על תנאי","שאין עליה נדרים או מומין:"],[1,"וכנסה סתם","ואח\"כ נמצאו עליה נדרים צריכה גט דביאה לשם קידושין הואי דיודע היה שאין קידושין הראשונים כלום:"],[3,"ה\"ג צריכא דאי איתמר בהא בהא קאמר רב משום דליכא תנאי","והכי איתא בכתובות פ' המדיר (כתובות דף עג.):"],[3,"דאי איתמר בהא","גבי קטנה שלא מיאנה בהא קאמר רב דאסיק אדעתי' לבעול לשם קידושין משגדלה משום דליכא תנאה אין פסול קידושין הראשונים משום תנאי אלא משום קטנות ואדם יודע שאין קידושין הראשונים כלום וחזר ובעל לשם קידושין:"],[3,"אבל בההיא","דאיכא תנאי אימא מודה לשמואל ואדעתא דתנאי בעיל כסבור שאין עליה נדרים וקיימא תנאי שביניהן:"],[4,"אבי כורסייא","באפריון וקס\"ד כשאר חופות שעדיין לא בעלה ואפ\"ה לא הצריכוה גיטא מבתרא. אלמא חלו קדושי קמאי:"],[5,"מינסב נסבי","ונתקדשה בבעילה משגדלה:"],[5,"וקא אפקעינהו לקידושין מיניה","דכל דמקדש תולה בדעת חכמים הוא דהא כדת משה וישראל קאמרינן ורבנן אמרי דחוטף אשה מבעלה לא ניהוי קידושין:"],[6,"תינח דקדיש בכספא","איכא למימר דאפקעינהו לקידושין ושוו מעות מתנה דהפקר ב\"ד היה הפקר:"],[6,"קדיש בביאה","מאי הפקר ב\"ד איכא למימר:"],[6,"שויוה לבעילתו בעילת זנות","והוא בדעתם תלה:"],[6,"כר' אליעזר","דמלמדין הקטנה למאן:"],[7,"מתני' שתי יתומות","נכריות:"],[7,"או חליצתה","לאחר שתגדיל:"],[7,"קטנה וחרשת","לא ידעינן בהי ניחא ליה והי חשיבה אשתו טפי:"],[9,"גמ' וחרשת בת חליצה היא","דקתני מתניתין וכן שתי חרשות:"],[11,"כי היכי דעל","לבעל הראשון שכנסה ברמיזה הכי נמי נפיק מיבם ברמיזה:"],[12,"נשואין שתי נכריות","פקחת לפקח וחרשת לחרש:"],[12,"כונס","שאינה בת חליצה משום קרייה אלא כונסה ואם רצה להוציאה אח\"כ מוציאה בגט שכשם שנכנסה ברמיזה כך תצא ברמיזה ולא צריכה חליצה:"],[13,"כונס ואין מוציאה לעולם","שאין גיטו מפקיע קידושי אחיו פקח שהזקיקוה לו ליבום:"]],[[0,"קסבר שמואל כל הבועל על דעת קידושין הראשונים הוא בועל","וא\"ת לשמואל דלית ליה דקדושין גדלי בהדה מ\"ט דר\"ג ולעיל בריש פ\"ב (יבמות דף יח.) משמע דשמואל אית ליה מילתא דר\"ג דפריך אמילתיה ואי אין זיקה תיבטל דהא אמר ר\"ג כו' וי\"ל דלשמואל צ\"ל דמיירי כדמפרש בהדיא שבועל לשם קידושין ועוד אור\"י דהתם כיון דיבמתו ואשתו שתיהן לפניו אפילו בסתמא בועל לשם קידושין כדי לדחות יבמתו ממנו דבאשתו ניחא ליה מיבמתו ומיהו קשה דתיקשה לשמואל מדרבנן דרבי אליעזר כשהחזירה כשהיא קטנה וגדלה אצלו דמסתמא בועל לשם קידושין דליכא למימר דאיירי כשפירש שבועל לשם קידושין דא\"כ היכי פריך מיניה בהמדיר (כתובות דף עג: ושם) לרב אלא ע\"כ כשבועל סתם ולא מצי לאוקומי כשפירש דא\"כ היינו החזירה כשהיא גדולה ואר\"י דשמואל סבירא לי' כר\"ש בן יהודה (משום ר' ישמעאל) דאמר בהמדיר (ג\"ז שם) אם בעלו לא קנו אי נמי כר' ישמעאל דאמ' שמואל משום רבי ישמעאל והיא לא נתפשה כו':"],[1,"והא אפליגו בה חדא זימנא","תימה לר\"י והא תרוייהו צריכי דאי אתמר ההיא דאמר רב צריכה הימנו גט ה\"א צריכה מספק דלא ידעינן אי בעל לשם קידושין אם לאו קמ\"ל דאין צריכה גט משני דודאי ראשון בעל לשם קידושין ואי אתמר ההיא דקאמר שמואל צריכה גט משני ה\"א היינו מספק ומראשון נמי צריכה גט מדאורייתא דשמא לשם קידושין בעל ואר\"י דהכי פריך והא איפליגו בה חדא זמנא ואמאי פליגי בשני מקומות דבחד מהנך הוה מצי לאשמועי' ולימא הכי קדשה על תנאי ובעל רב אמר צריכה גט מראשון ולא משני ושמואל אמר אין צריכה גט מראשון אלא משני אי נמי ליתני באידך קטנה שהגדילה ועמדה ונשאת רב אמר אינה צריכה גט משני אלא מראשון ושמואל אמר צריכה גט משני ולא מראשון מה\"ת אבל מדרבנן צריכה:"],[3,"בההיא קאמר רב משום דאיכא תנאי אחולי אחליה לתנאיה","פי' משום דאין אדם עושה בעילתו בעילת זנות אית לן למימר דאחליה לתנאיה והיה בדעתו שיחולו קידושי כסף מדלא הזכיר התנאי אבל בהא דליכא בעילת זנות שהרי יש שם קדושין דרבנן ועוד דליכא קדושין הראשונים דנימא שיחולו אימא מודי ליה לשמואל ובקונטרס הגיה הכא צריכותא דכתובות ואין למחוק גירסא זו דהא למ\"ד בהמדיר (כתובות דף עד.) קידשה ע\"ת ובעל ד\"ה צריכה הימנו גט ואפ\"ה פליגי (שם דף עג. ושם) בקטנה שלא מיאנה והגדילה ועמדה ונשאת א\"כ פשיטא ליה טפי במקדש ע\"ת דצריכה גט מבקטנה שלא מיאנה דכוותיה מיתוקמא הך צריכותא דהכא וצריכותא דכתובות (ג\"ז שם) אליבא דאביי:"],[5,"לפיכך עשו לו שלא כהוגן ואפקעינהו לקידושי מיניה","מספקא לר\"י אי טעמא דאפקעינהו משום דכל דמקדש אדעתא דרבנן מקדש או משום דיש כח ביד חכמים לעקור דבר מן התורה מדלא הזכיר כאן כמו שהזכיר בכל מקום כל דמקדש אדעתא דרבנן מקדש:"],[9,"וחרשת בת חליצה היא והתנן כו'","וא\"ת תיקשי נמי מקטנה דתנן במתניתין דחליצת אחת מהן פוטרת צרתה ואילו בפרק מצות חליצה (לעיל יבמות דף קד:) תנן קטנה שחלצה תחלוץ משתגדיל ואם לא חלצה חליצתה פסולה ומיהו בקונט' פי' דחליצתה לכשתגדיל פוטרת צרתה ועוד דאיכא לאוקמא מתני' דהכא כר' יוסי דאמר אשה בין גדולה בין קטנה ולפי הירושל' דגרסי' לעיל ואם לא חלצה חליצתה כשרה אתי שפיר טפי:"]]],[["חולץ לא לא בפקחת ואחר כך נתחרשה","תא שמע שני אחין פקחין נשואין שתי נכריות אחת פקחת ואחת חרשת מת פקח בעל החרשת מה יעשה פקח בעל פקחת כונס ואם רוצה להוציא יוציא מת פקח בעל פקחת מה יעשה פקח בעל חרשת או חולץ או מייבם","מאי לאו מדהוא פקח מעיקרא היא נמי חרשת מעיקרא וקתני כונס אין חולץ לא מידי איריא הא כדאיתא והא כדאיתא","איתיביה שני אחין אחד פקח ואחד חרש נשואין שתי אחיות אחת פקחת ואחת חרשת מת חרש בעל חרשת מה יעשה פקח בעל פקחת תצא משום אחות אשה","מת פקח בעל פקחת מה יעשה חרש בעל חרשת מוציא את אשתו בגט ואשת אחיו אסורה לעולם","וכי תימא ה\"נ בפקח ואחר כך נתחרש מי מצי מפיק והתנן נתחרשה יוציא נשתטית לא יוציא נתחרש הוא או נשתטה לא יוציא עולמית","אלא לאו בחרש מעיקרא ומדהוא חרש מעיקרא היא נמי חרשת מעיקרא ומדאחיות חרשות מעיקרא נכריות נמי חרשות מעיקרא ותנן גבי נכריות כונס אין חולץ לא אישתיק","כי אתא לקמיה דרב יוסף א\"ל מ\"ט תותביה מהא דיכול לשנויי לך אחיות חרשות מעיקרא נכריות פקחות ואח\"כ נתחרשו","אלא איבעי לך לאותביה מהא שני אחין חרשין נשואין שתי אחיות פקחות או שתי אחיות חרשות או שתי אחיות אחת פקחת ואחת חרשת וכן שתי אחיות חרשות נשואות לשני אחין פקחין או לשני אחין חרשין או לשני אחין אחד פקח ואחד חרש הרי אלו פטורות מן החליצה ומן הייבום ואם היו נכריות יכנוסו ואם רצו להוציא יוציאו","היכי דמי אילימא בפקחים ולבסוף נתחרשו מי מצי מפקי והתנן נשתטית לא יוציא נתחרש הוא או נשתטה לא יוציא עולמית","אלא לאו אחרשין מעיקרא ומדהן חרשין מעיקרא אינהו נמי חרשות מעיקרא וקתני אם היו נכריות יכנוסו יכנוסו אין יחלצו לא תיובתא דרבה תיובתא:","קטנה וחרשת וכו': אמר רב נחמן אשכחתיה לרב אדא בר אהבה ולרב חנא חתניה דיתבי וקמקוו אקוותא בשוקא דפומבדיתא ואמרי הא דתנן קטנה וחרשת אין ביאת אחת מהן פוטרת צרתה הני מילי דנפלה ליה מאחיו פקח דלא ידעינן אי בקטנה ניחא ליה אי בחרשת ניחא ליה","אי בקטנה ניחא ליה דאתיא לכלל דיעה אי בחרשת ניחא דגדולה היא ובת ביאה היא אבל נפלה מאחיו חרש ודאי בחרשת ניחא ליה דבת ביאה היא ובת מיניה היא","ואמינא להו אנא אפילו נפלה ליה מאחיו חרש נמי מספקא ליה","כיצד תקנתן אמר רב חסדא אמר רב כונס החרשת ומוציאה בגט וקטנה תמתין עד שתגדיל ותחלוץ","אמר רב חסדא ש\"מ קסבר רב חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה דאי ס\"ד חרשת קנויה ואינה קנויה קטנה קנויה ומשויירת חרשת אמאי כונס ומוציאה בגט"],[[0,"חולץ לא","משום קרייה:"],[4,"מוציא אשתו בגט","דזיקת אחותה פקחת אוסרתה שנישואיה גמורין וזו ספק ואין כח בקידושיה לפטור את אחותה משום אחות אשה:"],[4,"ואשת אחיו אסורה לעולם","דחרש לא מצי חליץ ומיכנס נמי לא מצי כניס לה דאחות גרושתו היא דאחותה חרשת היתה קנויה במקצת לאחיו החרש הילכך לא אפשר (שהרי אחות גרושתו היא). ומהך מתניתין לא מותיב ליה לרבא דהכא מדינא לא חליץ האי חרש לפקחת שהרי אשת פקח היתה וזיקתו גמורה וליכא למימר כי היכי דעל הכי נפיק אלא להכי מייתי לה לגלויי אהנך תרתי תיובתי קמייתא דבחרשת וחרש מעיקרא קמיירי דהא כולהו תניא להו גבי הדדי במתני' לקמן בחרש שנשא פקחת (יבמות דף קיב:):"],[5,"מי מצי מפיק","דקתני מוציא את אשתו בגט ומדקתני בגט משמע שתהא מותרת לאחרים:"],[5,"נשתטית לא תצא","פקחת שנשתטית לא תצא מבעלה אע\"פ שהאשה יוצאת לרצון ושלא לרצון רבנן תקון שלא תצא כדי שלא ינהגו בה מנהג הפקר לפי שאינה יודעת לשמור עצמה אבל נתחרשה יוצאת דלא בעינן דעת אשה בגט שהרי אפי' פקחת בעל כרחה מוציא והכא לא תקון רבנן מידי דהא יודעת לשמור עצמה:"],[5,"נתחרש הוא כו'","דקידושיו היו גמורין וגירושין בלא דעת:"],[6,"נכריות נמי","הנך תרתי דלעיל חרשות מעיקרא קאמר דהא גבי הדדי תניין. והמגמגם לומר למה לי כל הנך דיוקי דקאמר מדהוא חרש מעיקרא איהי נמי חרשת מעיקרא כו' ומדאחיות חרשות מעיקרא כו' לותיב מחד ומדהוא חרש מעיקרא הנך נמי דלעיל חרשות מעיקרא וקתני בהו כונס אין חולץ לא לאו מילתא היא דכל הנך חרשין דלעיל נפלה לפניהם פקחת מכח קידושי פקח וליכא למימר כי היכי דעל הכי נפק אבל בחרשת דלעיל איכא למימר הכי ואפילו הכי קתני כונס פקח ולא חולץ:"],[8,"שני אחין חרשין","נישואיהן שוין בין שהן פקחות בין שהן חרשות בין אחת פקחת ואחת חרשת שהרי כניסתן לבעליהן ברמיזה וכן שתי חרשות כניסתן ברמיזה ואע\"פ שהן פקחין או אחד פקח ואחד חרש נישואיהן שוין הילכך יוצאת היבמה משום אחות אשה:"],[8,"ואם היו נכריות","ומת אחד מהן יכנוס השני דלאו בר חליצה הוא או היא אינה בת חליצה:"],[10,"ומדהן חרשין מעיקרא כו' ל\"ג","דבלאו הכי מצי מותיב מינייהו:"],[11,"ומקוו אקוותא","מקהילים תלמידים סביבם שהיו באים לשמוע דבריהם. ל\"א דמקהו אקהתא משיבין קושיות זל\"ז:"],[14,"כיצד תקנתן","דקטנה וחרשת הואיל ואין האחת פוטרת צרתה וחרשת לאו בת חליצה היא דניפוק תרוייהו בחליצה ואי מייבם לה וחליץ לקטנה כשתגדיל מיפסלא קמייתא עליה דקם ליה בלא יבנה דהא ביאה דחרשת לא דחיא זיקה דנימא אין אחריה כלום:"],[14,"כונס את החרשת ומוציאה בגט","דחליצת קטנה תפסל לה עליה:"],[15,"חרשת קנוייה במקצת ומשויירת","קטנה ספק קנוייה כולה ספק אינה קנוייה כלל. דבשתיהן קנויות ומשויירות ליכא למימר דממתני' שמעינן לה דא\"כ תיפטר חדא בביאת חברתה ושתיהן ספק נמי ליכא למימר מדקתני סיפא דמתני' בא יבם על הקטנה וחזר ובא על החרשת פסל את הקטנה בא יבם על החרשת וחזר ובא על הקטנה פסל את החרשת ואי שתיהן ספק קמייתא תיתיב גביה ממה נפשך דהא אחרונה לא פסלה לה עליה דאם שתיהן קנויות אין האחרונה פוסלת הראשונה דאין אחר ביאה כלום ואם זו (קנויה) וזו אינה קנויה אינן צרות זו לזו אלא חדא קנויה ומשויירת וחדא ספק. ומדרב שמעינן דחרשת היא הקנויה והמשויירת וקטנה ספק משום הכי תצא החרשת בגט דלמא קטנה קנויה היא לגמרי ועדיפא מחרשת ופסלה לה חליצתה עליה:"]],[[2,"מאי לאו מדהוא פקח מעיקרא","דהכי משמע שפקח נשא חרשת משמע שבשעת נישואין היה זה פקח וזו חרשת אבל בבבא קמייתא דחרש בעל חרשת לא מצי לאוקומי בחרשת מעיקרא דומיא דפקח בעל פקחת דהא לא שייכי מידי אהדדי:"],[5,"וכי תימא הכא נמי בפקח ואח\"כ נתחרש ומי מצי מפיק לה","הוה מצי לאקשויי טפי דכיון דפקח הוה דנשואין דאורייתא הוי אמאי צריך לגרש את אשתו דקתני ומוציא את אשתו בגט והלא תצא אחותה משום אחות אשה אלא לרבות' נקטיה דאפי' היה צריך גט מי מצי לאפוקי:"],[5,"או נשתטה לא יוציא עולמית","וא\"ת מאי קושיא והא רשב\"ג פליג עליה בפ' מי שאחזו (גיטין דף עא. ושם) ואית ליה בפקח ואח\"כ נתחרש הוא היה כותב ואחרים חותמים ונוקי הך משנה כרשב\"ג וי\"ל דלא בעי לאוקומי כרשב\"ג כיון דרישא לא מיתוקמא כוותיה ההיא דנקט חרש או נשתטה ועוד דבלאו הכי הוה פריך ליה ומי מצי לגרש את אשתו כדמפרש:"],[6,"ותנן גבי נכרית כונס אין חולץ לא אישתיק","הכא לא בעי לשנויי הא כדאיתא והא כדאיתא כדמשני לעיל גבי פקח וחרשת שהם שני מינין אבל הכא שניהם חרשים ובמין אחד לא שייך למימר הא כדאיתא והא כדאיתא:"],[7,"מאי טעמא לא תותביה מהא","תימה לר\"י דמה היה בדעתו של אביי שלא הקשה לו מזאת הבבא שהיא ראשונה וקושיא טובה ולא היה צריך לכל אלו הבבות:"],[11,"וקמקוו אקוותא","פי' בקונטרס מקשין קושיות זה לזה וכן פי' ר\"ח והביא ראיה מר' יהושע קיהה וטהר (נגעים פ\"ד מי\"א) דקדק בדבר הרבה וטיהר:"],[15,"קסבר רב חרשת קנויה ומשויירת קטנה קנויה כו'","וא\"ת והיכי שמעינן דקסבר רב הכי דלמא לעולם מספקא ליה אי חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה או איפכא להכי קאמר כונס את החרשת ומוציאה בגט וקטנה תמתין עד שתגדיל דמספיקא אזיל לחומרא וי\"ל דקים ליה לרב חסדא דחדא קנויה ומשויירת וחדא קנויה ואינה קנויה אלא דהוא לא הוה ידע הי מינייהו והשתא פשיטא דחרשת משויירת וקטנה קנויה ואינה קנויה ומברייתא נמי מצי למפשט דקטנה קנויה ואינה קנויה אבל כל כמה דלא ידע ברייתא פשיט ממילתיה דרב:"]]],[["תיתיב גביה ממה נפשך אי קנויה היא הא קנויה היא ואי לאו קנויה היא הא נכרית בעלמא היא","וכי תימא קטנה אמאי תמתין עד שתגדיל ותחלוץ תיתיב גביה אי קנויה היא הא קנויה היא אי לאו קנויה היא נוכריתא בעלמא היא אם כן חרשת במה תיפוק","אמר רב ששת הכי נמי מיסתברא כדקא מתרץ רב חסדא אליבא דרב","דתניא שני אחין נשואין שתי אחיות יתומות קטנה וחרשת מת בעלה של קטנה חרשת יוצאה בגט וקטנה תמתין עד שתגדיל ותחלוץ","מת בעלה של חרשת קטנה יוצאה בגט וחרשת אסורה לעולם ואם בא על החרשת נותן לה גט והותרה","אי אמרת בשלמא חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה משום הכי דכי בא על החרשת נותן לה גט והותרה דאמרת ממה נפשך אי קטנה קנויה היא הא נפקא משום אחות אשה אי לאו קנויה שפיר מיבם","אלא אי אמרת חרשת קנויה ואינה קנויה קטנה קנויה ומשויירת כי בא על חרשת אמאי נותן גט והותרה הויא ליה ביאה פסולה וביאה פסולה לא פטרה","הא מני רבי נחמיה היא דאמר ביאה פסולה פוטרת מחליצה","אי רבי נחמיה אימא סיפא מי שהיה נשוי שתי יתומות קטנה וחרשת ומת בא יבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת נאסרו שתיהן עליו כיצד תקנתן חרשת יוצאת בגט וקטנה תמתין עד שתגדיל ותחלוץ","אי אמרת בשלמא חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה ורבנן היא משום הכי תמתין עד שתגדיל ותחלוץ דדלמא קדים ובעיל חרשת ברישא והויא ליה ביאה דקטנה ביאה פסולה","אלא אי אמרת רבי נחמיה הא אמר ביאה פסולה פטרה","אלא שמע מינה רבנן היא ש\"מ","אמר רב אשי מרישא נמי שמע מינה דרבנן היא דקתני אם בא על החרשת נותן לה גט והותרה ולא קתני אם בא על הקטנה נותן לה גט והותרה","אי משום הא לא איריא חרשת דלית לה תקנתא דהיתירא קתני תקנתא דאיסורא קטנה דאית לה תקנתא דהיתירא לא תני תקנתא דאיסורא:","\u0001מתני׳\u0002 מי שהיה נשוי לשתי יתומו' קטנות ומת ובא יבם על הראשונה וחזר ובא על השניה או שבא אחיו על השניה"],[[0,"הא קנויה היא","ותו ליכא זיקה אבתרייתא:"],[0,"נכרית בעלמא היא","ולא פסלה לה חליצת קטנה:"],[1,"(וליטעמיך) קטנה אמאי תמתין ותחלוץ","ישאנה מתחלה ותשב אצלו ממה נפשך:"],[1,"חרשת במאי תיפוק","הא לאו בת חליצה היא ורב תקנתא לתרוייהו קתני. ואי קשיא מתניתין דקתני בא על הקטנה וחזר ובא על החרשת פסל את הקטנה אמאי פסלה הואיל ונסבה ברישא תיפוק חרשת בגט וקטנה תיתיב גביה ממה נפשך כדאמרן ואיכא תקנתא לתרוייהו תריץ מתניתין משום גזירה דלמא אתי למיבעל חרשת ברישא והכי נמי מתרץ לה בברייתא לקמן:"],[2,"כדקא מתרץ כו'","חרשת קנויה ומשויירת קטנה קנויה ואינה קנויה:"],[3,"מת בעלה של קטנה חרשת יוצאה בגט","דזיקת קטנה אוסרתה עליו דחרשת קנויה ומשויירת וקטנה שמא קנויה לגמרי והויא לה חרשת אחות זקוקתו:"],[4,"קטנה תצא בגט","דזיקת חרשת אחותה אוסרתה שמא קטנה אינה קנויה כלל והויא כמפותה וחרשת קנויה ומשויירת והויא לה אשתו אחות זקוקתו:"],[4,"וחרשת אסורה לעולם","לכונסה אי אפשר שמא קטנה קנויה היא וזו אחות גרושתו ואין זקוקה לו ואפילו מתה קטנה אחר כך ופקע איסור אחות אשה אסורה משום אשת אח הואיל ובשעת נפילה נפטרה ממנו ובחליצה אי אפשר דלאו בת חליצה היא:"],[5,"ואם עבר ובא על החרשת","אחר שגירש הקטנה נותן לה גט והותרה לשוק ממה נפשך אי קטנה קנויה הואי נפקא לה הך מרישא משום אחות אשה והך כניסה זנות בעלמא היא ואי קטנה לאו קנויה היא שפיר ייבם:"],[6,"אמאי נותן לה גט והותרה","הא איכא למימר דלמא חרשת קנויה היא לגמרי לאחיו וזקוקה לו וקטנה לא דחיא לה דקנויה ומשויירת היא וביאתה ביאה פסולה שהרי אחות אשה במקצת היא וביאה פסולה לא פטרה מייבום וצריכה גט לביאתו וחליצה לזיקתו וחרשת לאו בת חליצה היא:"],[7,"ר' נחמיה","בפרק ר\"ג (לעיל יבמות דף נ:):"],[8,"יתומות","משום קטנה נקט:"],[8,"נאסרו שתיהן עליו","אע\"ג דקטנה מדינא לא מיפסלא עליה משום ביאה דחרשת ממה נפשך אי קטנה קנויה ליכא מידי בתר ביאתה ואי לאו קנויה היא נכרית בעלמא היא אפ\"ה אסורה כדמפרש לקמן משום גזירה דלמא אתי למיעבד איפכא ובעיל חרשת ברישא וביאת קטנה פסלה לה דשמא קנויה היא כולה ואתי למימר נמי תיתיב חרשת גביה:"],[8,"חרשת יוציא בגט","ושריא ממה נפשך אי קטנה קנויה היא מיפטרא חרשת בביאתה דקטנה ואי לאו קנויה היא פטורה בביאה דידה:"],[8,"קטנה תמתין כו'","כדמפרש טעמא:"],[9,"אי אמרת בשלמא","רישא גבי אחיות דקתני אם בא על החרשת נותן לה גט והותרה משום דחרשת קנויה ומשויירת וקטנה קנויה ואינה קנויה וממה נפשך חרשת בתר גיטא מיפטרא אי משום אחות אשה אי משום יבומה שהיה בהיתר שאחותה לא היתה קנויה אבל אי הוה אמרינן איפכא קטנה קנויה היא ומשויירת וחרשת ספק תו לא מיפטרא חרשת בגט דלמא קנויה היא ולא נפקא משום אחות אשה שקנין אחותה הקטנה משויירת ובביאתה נמי לא מיפטרא דביאה פסולה היא שהרי אחות אשתו היא ומתני' רבנן היא. ומש\"ה קתני סיפא גבי נכרית קטנה בעיא חליצה ואע\"ג דממה נפשך ביאתה בהיתר הואי וגיטה גט גמור משום גזירה דלמא קדים ובעיל חרשת ברישא ואתי למימר נמי תרוייהו ליפקו בגט וקטנה שהיא אחרונה לא סגי לה בגיטא דלמא קנויה היא ורמיא קמיה דלא איפטרא בביאת חרשת המשויירת ובביאה דידה נמי לא מיפטרא דביאה פסולה היא דקם עליה באיסור שני בתים:"],[10,"אלא אי אמרת קטנה קנויה ומשויירת","וחרשת ספק ומרישא דקתני באחיות אם בא על החרשת נותן לה גט והותרה שמעינן דביאה פסולה פוטרת סיפא בנכרית אמאי קטנה בעיא חליצה בשלמא אפוקי מפקינן לה מיניה דלמא חרשת אחרונה קנויה כולה ופסלה לה עילויה אלא בגיטא תיסגי לה דביאת עצמה פוטרתה דביאה כשרה היא ואי נמי חשיב לה פסולה משום דקיימא זיקת חרשת דאיכא למימר קנויה לגמרי הא א\"ר נחמיה ביאה פסולה פטרה:"],[12,"מרישא נמי","גבי אחיות:"],[12,"ש\"מ דרבנן היא","דקתני גבי מת בעלה של חרשת אם בא על החרשת נותן לה גט וגבי מת בעלה של קטנה דקתני קטנה תמתין ולא קתני אם בא על הקטנה נותן לה גט והותרה אלמא רבנן היא ומש\"ה לא נפקא בגט דביאתה פסולה דחרשת קנויה במקצת וזו אסורה משום אחות אשה ומייבום לא מדחיא דלמא קטנה קנויה כולה וקנין משויירת דאחותה לא דחי לה:"],[13,"דלית לה תקנתא דהיתירא","דקתני בה וחרשת אסורה לעולם:"]],[[0,"תיתיב גביה ממה נפשך","פירש בקונטרס ואי קשיא מתני' הבא על הקטנה ואחר כך בא על החרשת פסל את הקטנה ואמאי לא אמר תיתיב גביה הקטנה ממה נפשך אי קנויה היא קנויה היא ואי לא נכרית בעלמא היא ותירץ דגזרינן דלמא בעיל חרשת ברישא כדלקמן בבריית' וקשה דקתני בברייתא ואם בא על החרשת נותן לה גט והותרה ואמאי לא גזרינן בא על החרשת אטו מת בעלה של קטנה ובא עליה דלא משתריא בגט אלא בחליצה דביאה פסולה לא פטרה כי היכי דגזרינן במתני' ושמא כיון שלא היה תקנתא לחרשת לא רצו לאוסרה איסור עולם:"],[6,"הויא לה ביאה פסולה ולא פטרה","וא\"ת התינח לעיל פרק ר\"ג (יבמות דף נ:) דביאה פסולה לא פטרה דגזרינן ביאה אחר הגט אטו ביאה אחר חליצה אבל הכא מאי חששא איכא וי\"ל דהכא נמי אי פטרה אמרי דביאת חרשת ביאה כשירה היא ואע\"פ שהיא אחר ביאת הקטנה ואתי לאיחלופי בגדולה שאחר שבא על הגדולה יחזור ויבא על אחותה:"]]],[["לא פסל את הראשונה וכן ב' חרשות","קטנה וחרשת בא יבם על הקטנה וחזר ובא על החרשת או שבא אחיו על החרשת פסל את הקטנה","בא יבם על החרשת וחזר ובא על הקטנה או שבא אחיו על הקטנה פסל את החרשת","פקחת וחרשת בא יבם על הפקחת וחזר ובא על החרשת או שבא אחיו על החרשת לא פסל את הפקחת","בא יבם על החרשת וחזר ובא על הפקחת או שבא אחיו על הפקחת פסל את החרשת","גדולה וקטנה בא יבם על הגדולה וחזר ובא על הקטנה או שבא אחיו על הקטנה לא פסל את הגדולה בא יבם על הקטנה וחזר ובא על הגדולה או שבא אחיו על הגדולה פסל את הקטנה ר' אלעזר אומר מלמדין הקטנה שתמאן בו:","\u0001גמ׳\u0002 אמר רב יהודה אמר שמואל הלכה כרבי אלעזר וכן אמר רבי אלעזר הלכה כרבי אלעזר","וצריכא דאי איתמר בהא קמייתא בהך קאמר שמואל הלכה כרבי אליעזר משום דלא קיים מצות ייבום אבל בהא דאיקיים מצות ייבום אימא תרוייהו לפקו בגט","ואי אשמעינן בהא משום דגדולה רמיא קמיה אבל אידך לא צריכא:","\u0001מתני׳\u0002 יבם קטן שבא על יבמה קטנה יגדלו זה עם זה בא על יבמה גדולה תגדלנו","היבמה שאמרה בתוך שלשים יום לא נבעלתי כופין אותו שיחלוץ לה לאחר שלשים יום מבקשין הימנו שיחלוץ לה ובזמן שהוא מודה אפילו לאחר שנים עשר חדש כופין אותו שיחלוץ לה","הנודרת הנאה מיבמה בחיי בעלה כופין אותו שיחלוץ לה לאחר מיתת בעלה מבקשין הימנו שיחלוץ לה ואם נתכוונה לכך אפי' בחיי בעלה מבקשין הימנו שיחלוץ לה:","\u0001גמ׳\u0002 לימא מתניתין דלא כרבי מאיר דתניא קטן וקטנה לא חולצין ולא מתייבמין דברי רבי מאיר","אפילו תימא רבי מאיר כי אמר ר' מאיר גדולה לקטן וקטנה לגדול דחד מינייהו ביאה דאיסורא הוא אבל קטן הבא על הקטנה דתרוייהו כי הדדי נינהו לא אמר","והא קתני בא על יבמה גדולה תגדלנו אמר רבי חנינא חוזאה בא שאני והא תגדלנו קאמר דכל ביאה וביאה דאיסורא הוא אלא מחוורתא מתניתין דלא כרבי מאיר","קרי כאן (דברים כה, ז) להקים לאחיו שם והאי לאו בר הכי הוא אמר אביי אמר קרא יבמה יבא עליה כל דהו","רבא אמר בלאו הכי נמי לא מצית אמרת מי איכא מידי דהשתא אסירא ליה ולבתר שעתא שריא והא אמר רב יהודה אמר רב כל יבמה שאין אני קורא בשעת נפילה יבמה יבא עליה הרי היא כאשת אח שיש לו בנים ואסורה","ואימא הכי נמי אמר קרא (דברים כה, ה) כי ישבו אחים יחדו אפילו בן יום אחד:","יבמה שאמרה בתוך שלשים יום וכו': מאן תנא דעד תלתין יומין מוקים איניש אנפשיה","אמר רבי יוחנן רבי מאיר היא דתניא טענת בתולים כל שלשים יום דברי רבי מאיר","רבי יוסי אומר נסתרה לאלתר לא נסתרה אף לאחר כמה שנים","רבה אמר אפי' תימא ר' יוסי עד כאן לא קאמר ר' יוסי התם אלא בארוסתו דגיס בה אבל אשת אחיו"],[[0,"מתני' לא פסל את הראשונה","שהרי ביאתן שוה ואי ראשונה קנויה היא הרי היא אשתו ואחרונה ביאת זנות ואי לאו קנויה היא הרי שתיהן נכריות אצלו שלא היתה קנויה לאחיו ומקיים את הראשונה שלא נפסלה עליו אבל אחרונה לא דלמא קנויות הוו ומשבא על הראשונה קמה הך עליה באיסור שני בתים:"],[1,"פסל את הקטנה","משום גזירה דלמא קדים ובעיל חרשת ברישא וכדאמר בגמרא ואע\"ג דממה נפשך היא שריא ליה הואיל וראשונה היא אי קנויה היא הא קנויה היא אי לאו קנויה היא נכרית בעלמא היא:"],[2,"פסל את החרשת","שמא קטנה קנויה כולה וקנין החרשת משויירת:"],[5,"רבי אלעזר","ה\"ג במתני'. ובקמייתא רבי אליעזר גרס והכי אמרן בפ\"ק דנדה (דף ח.):"],[5,"מלמדין את הקטנה שתמאן בו","ותעקור נישואיה ויקיים את הגדולה:"],[6,"גמ' וכן א\"ר אלעזר","בן פדת דאמורא הוא הלכה כר\"א דמתניתין והוא ר\"א בן שמוע:"],[7,"וצריכא","לשמואל ור' אלעזר בן פדת למימר בקמייתא הלכה כר' אליעזר ובהא נמי הלכה כרבי אלעזר דבתרוייהו מלמדין את הקטנה למאן:"],[7,"דאי איתמר בקמייתא","גבי אחיות (לעיל יבמות דף קט.) משום דאכתי לא איקיים מצות ייבום הילכך מלמדין את הקטנה אשתו למאן ותתייבם יבמתו:"],[7,"אבל בהא דאיקיים מצות ייבום","בשתיהן אימא לא אמר שמואל הלכה כרבי אלעזר אלא יוציא שתיהן בגט:"],[8,"ואי אשמעינן בהא משום דגדולה רמיא קמיה","לייבומי משום הכי מהדרינן אמיאון דקטנה כדי שתתייבם גדולה:"],[8,"אבל אידך","בההיא דאחיות דגדולה אחות אשתו היא נימא לא רמיא קמיה ולא ילמדו קטנה למאן בשביל ייבומיה של גדולה צריכא:"],[9,"מתני' יגדלו זה עם זה","ואם בא לגרשה אינו יכול עד שיגדיל דגט קטן אינו גט:"],[10,"היבמה שאמרה בתוך שלשים יום","שכנסה היבם:"],[10,"לא נבעלתי לו","ליבם וגט יבמין יוצא מתחת ידה כדמפרש בגמ' והוא אומר בעלתיך ודייך בגט כופין אותו לחלוץ דהיא נאמנת דעד תלתין יומין מוקי איניש אנפשיה מלבעול:"],[10,"לאחר ל' יום","הוא נאמן דלא מוקים איניש אנפשיה מלבעול ומיהו איהי לא משתריא דשויתה לנפשה חתיכה דאיסורא ובעיא חליצה ומבקשין הימנו אבל כופין לא דהא בעל:"],[11,"בחיי בעלה","ולא נתכוונה לפטור עצמה הימנו לאחר מיתת בעלה אלא שהיה להם כעס זה עם זה:"],[12,"גמ' לא חולצין ולא מייבמין","קטן שמא ימצא סריס קטנה שמא תמצא איילונית ואינם בני ייבום נמצאו פוגעין בערוה:"],[13,"ביאה דאיסורא","קטן בגדולה דגדולה בת עונשין היא ושמא הקטן ימצא סריס והרי נבעלה לאסור לה שלא במקום מצוה וכן גדול בקטנה אם תמצא איילונית נמצא שפגע גדול בערוה אבל קטן וקטנה אפילו אינן בני ייבום כגון הוא סריס והיא אילונית אין כאן איסור דקטן אוכל נבלות אין ב\"ד מצווין להפרישו וה\"נ שניהן לאו בני עונשין:"],[16,"ולבתר שעתא","כשיגדלו:"],[17,"ואימא הכי נמי","לעולם אסורה לו:"],[17,"אפי' בן יום אחד","ישבו יחדו קאמר קרא יבמה יבא עליה ואפי' לא הוי משמע כל דהו מסברא שריא ליה בקטנות כדאמר:"],[19,"טענת בתולים","להפסיד כתובתה:"],[19,"כל שלשים יום","דיכול לטעון לא בעלתי עד עתה:"],[20,"נסתרה לאלתר","הוא טוען ואם טוען לאחר זמן אינו נאמן דודאי מרישא בעל ומצאה בתולה ושתק והשתא הוא דרתח עלה:"]],[[10,"לאחר שלשים יום מבקשים ממנו שיחלוץ לה","ואם תאמר מה הוא מפסיד אם חולץ לה ולמה אין כופין כדי להתירה ויש לומר שהוא מתבייש בבית דין לחלוץ לה שתרוק בפניו:"],[11,"לאחר מיתת בעלה מבקשים ממנו שיחלוץ לה","ולא אמרינן כופין שנתן אצבע בין שיניה שלא היפר לה שהרי אין יכול להפר עד שיבעול ואי סבירא ליה דמצי מיפר דפלוגתא היא בנדרים בפ' נערה (נדרים דף עד.) ומייתי לה בפ' ארבעה אחין (לעיל יבמות ד' כט:) סבירא ליה כמ\"ד בכתובות (דף נט:) היא נתנה אצבע בין שיניה ולהכי מבקשים ולא כופין:"],[15,"קרי כאן להקים לאחיו שם בישראל והאי לאו בר הכי הוא","ואע\"פ שיבא לכלל הקמת שם לא מהניא כיון שלא היה לו שעת הכושר כי היכי דפסלינן בהערל (לעיל יבמות דף עט:) סריס חמה שלא היה לו שעת הכושר אע\"פ (לעיל יבמות פ.) שבמינו מתרפאים באלכסנדריא של מצרים ומשני אמר קרא כו' ולא דמי לסריס חמה שאין רפואתו ברורה לבוא כמו קטן שיגיע לכלל גדלות:"],[15,"יבמה יבא עליה כל דהו","מדלא כתיב אחי המת יבא עליה:"],[17,"אמר קרא כי ישבו אחים יחדו","וממעטינן מיניה לעיל בפ\"ב (יבמות דף יז: ושם) אשת אחיו שלא היה בעולמו מכלל שאם היה בעולמו אפילו יום אחד מייבם אבל ליכא למימר דמיחדו דריש דאם כן אפי' סריס נמי לייבם מהאי טעמא דהא יחדו איתנהו:"],[19,"טענת בתולים כל שלשים יום","אפי' ראינו שנסתרה כבר רבי יוסי אומר נסתרה לאלתר לאלתר לאו דוקא דאי אפשר לטעון עד שימצא בית דין:"],[20,"לא נסתרה אפי' אחר כמה שנים","כלומר שאין אנו יודעין שנסתרה אע\"פ שנכנסה לחופה ור\"מ סבירא ליה דלא מוקי איניש אנפשיה שלא יסתר ויבעול בעילת מצוה אי נמי לא נסתרה שאנו יודעין בודאי שלא נסתרה ובהא לא פליג רבי מאיר:"]]],[["מיבזז בזיז מינה","עד שכופין אותו לחלוץ ניכפנו לייבם אמר רב בשגיטה יוצא מתחת ידה","מיתיבי יבמה שאמרה בתוך שלשים יום לא נבעלתי בין שהוא אומר בעלתי בין שהוא אומר לא בעלתי כופין אותו שיחלוץ לה לאחר שלשים יום מבקשין הימנו שיחלוץ לה","היא אומרת נבעלתי והוא אומר לא בעלתי הרי זה יוציא בגט הוא אומר בעלתי והיא אומרת לא נבעלתי אע\"פ שחזר ואמר לא בעלתי צריך גט וחליצה","אמר רבי אמי צריכה חליצה עם גיטה רב אשי אמר התם גט לזיקתו הכא גט לביאתו","הנהו שניהם מודים דאתו לקמיה דרבא אמר להו רבא חלוצו לה ושרו לה תיגרא אמר ליה רב שרביא לרבא והתניא צריכה גט וחליצה אמר ליה אי תניא תניא","בעא מיניה הון בריה דרב נחמן מדרב נחמן צרתה מהו","אמר ליה וכי מפני שאנו כופין ומבקשין תיאסר צרה:","הנודרת הנאה וכו': תנן התם בראשונה היו אומרים שלש נשים יוצאות ונוטלות כתובה","האומרת טמאה אני לך השמים ביני לבינך נטולה אני מן היהודים","חזרו לומר שלא תהא אשה נותנת עיניה באחר ומקלקלת על בעלה אלא האומרת טמאה אני לך תביא ראיה לדבריה השמים ביני לבינך יעשו דרך בקשה","נטולה אני מן היהודים יפר חלקו ומשמשתו ותהא נטולה מן היהודים","איבעיא להו נטולה אני מן היהודים ליבם מהו מי מסקה אדעתה דמיית בעלה ונפלה קמי יבם או לא","רב אמר יבם אינו כבעל ושמואל אמר יבם הרי הוא כבעל אמר אביי כוותיה דרב מסתברא דתנן הנודרת הנאה מיבמה בחיי בעלה כופין אותו שיחלוץ ואם איתא דמסקה אדעתה"],[[0,"מיבזז בזיז","בוש הימנה:"],[1,"בשגיטה יוצא","שנתן לה גט וקס\"ד גט גמור לביאתו הוא:"],[3,"היא אומרת נבעלתי","לאחר שלשים קאי:"],[3,"יוציא בגט","אם בא להוציאה דיה בגט דהיא נאמנת דכולי האי לא מוקים:"],[3,"צריכה גט","לביאתו משום דאמר בעלתי ולאחר שלשים יום איהו מהימן:"],[3,"וחליצה","משום דהיא שויתה לנפשה חתיכה דאיסורא. ומדקאמר צריכה גט מכלל דבאין לה גט עסקינן ואמאי קתני רישא כופין לחלוץ ניכפינהו לייבם:"],[4,"אמר רבי אמי","לעולם בשגיטה בידה והכי קאמר צריכה חליצה עם גיטה ואע\"פ דקתני אמבקשים קאי וה\"ק אע\"פ שחזר ואמר לא בעלתי דאיכא למימר כופין הואיל ומודה אפ\"ה אין כופין אלא צריכה חליצה ואי לא בעי למיחלץ לא כייפינן דסמכינן אדיבוריה קמא הואיל ולאחר שלשים יום הוא:"],[4,"רב אשי אמר","לעולם צריכה גט אחר לבד גט הראשון דהתם גט לזיקתו ונפסלה עליו לפיכך לא נכפינן לייבם וכיון דאמר בעלתי צריכה גט לביאתו דיש ביאה אחר הגט והשתא מסתברא אע\"פ דקתני וה\"ק אע\"פ שחזר ואמר לא בעלתי ואיכא למימר לא תיבעי גט אלא חליצה אפ\"ה בעיא גט:"],[5,"שניהם מודים","שלא נבעלה ומעיקרא אמר בעלתי:"],[6,"הון","כך שמו:"],[6,"צרתה מהו","יבמה שכנסה היבם ונפטרה צרתה ואמרה יבמה לאחר זמן לא נבעלתי מהו ליאסר צרתה מפני דיבורה של זו:"],[7,"מפני שאנו כופין ומבקשים","לצרכה דאיהי שויתה לנפשה חתיכה דאיסורא נאסרה צרתה ודאי לא מיתסרא דחזקה הכונס את האשה בועל לאלתר:"],[9,"האומרת טמאה אני לך","אשת כהן שאמרה לבעלה נאנסתי דאיתסרא עליה וכתובתה לא מיפסדה ובאשת כהן מוקמינן לה בפרק בתרא דנדרים:"],[9,"השמים ביני לבינך","גלוי וידוע לפניו שאינך נזקק לי כדרך בני אדם ואין איש עד להוכיח בין שנינו:"],[9,"נטולה אני מן היהודים","נדרה היא שלא תיבעל ליהודים. ומדאסרה נפשה אכולי עלמא ש\"מ תשמיש קשה לה ואנוסה היא לפיכך נוטלת כתובתה:"],[10,"נותנת עיניה באחר","ותלך למקום שאין מכירין בה ובנדרה ותנשא לו:"],[10,"תביא ראיה לדבריה","ואם לאו לא כל כמינה דאסרה נפשה עליה:"],[10,"יעשו דרך בקשה","לבעל להתנהג בה מנהג יפה:"],[12,"ליבם מהו","מי אסירא ליבם מפני נדר זה שנדרה בחיי בעלה או לא:"],[12,"מי מסקה אדעתה דמיית בעלה","בלא בנים ונפלה קמי יבם ונדרה נמי אדעתא דידיה ובעל לא הפר אלא לחלקו ויבם נמי לא מצי מיפר שאפי' בעל אין מיפר בקודמים ואסורה לו:"],[12,"או לא","אסקה אדעתה ולא נדרה זו אלא לאסור עצמה על כל מי שמותרת לו ע\"י גירושי בעלה ולהפיס דעתו של בעל שלא יחשדנה בנותנת עיניה באחר כדי שיתרצה לגרשה אבל איבם שאסורה לו ועומדת אפי' אחר גירושין לא נתכוונה ומותרת לו אם מת בעלה ולא גירשה:"],[13,"אינו כבעל","שיהיה צריך להפר כבעל דאדעתא דבעל נדרה וצריך הוא להפר אבל ליבם מותרת בלא הפרה:"]],[[3,"היא אומרת נבעלתי והוא אומר לא בעלתי יוציא בגט","פי' בקונט' דאאחר שלשים יום קאי וכן נראה דומיא דסיפא דהוא אומר בעלתי והיא אומרת לא נבעלתי אעפ\"כ צריכה גט וחליצה והיינו דוקא אחר שלשים דבתוך שלשים משמע ברישא דאינה צריכה גט דקתני כופין אותו שיחלוץ ולא קתני וצריכה גט וה\"ה דהך בבא נמי דהיא אומרת נבעלתי אלאחר שלשים יום קאי אבל בתוך שלשים יום צריכה חליצה דאי אתוך שלשים נמי קאי ליתנייה נמי לעיל גבי תוך שלשים שלא נטעה להעמידה דוקא אלאחר ל' כמו סיפא ולפי זה לא יתכן הא דאמר בסמוך וכי מפני שאנו כופין ומבקשים נאסור צרתה ופירש בקונט' וכן ר\"ח וכי מפני שאנו כופין בתוך שלשים ומבקשים אחר שלשים נאסרה צרתה ואמאי שריא צרתה בתוך שלשים הא איהי גופה כי אמרה נבעלתי בתוך ל' בעיא חליצה וכ\"ש צרתה דלא קים לה בבעילה כמותה שיש לנו לאוסרה בלא חליצה אלא נראה דצרתה לא שריא בסמוך אלא אחר ל' דוקא וכופין היינו כי אמר בעלתי וחזר ואמר לא בעלתי דומיא דסיפא דברייתא אבל כשלא אמר מתחלה בעלתי אלא שניהם מודים מתחלה ועד סוף שלא בעל אפילו אחר ל' לא שריא צרה דהא משמע בסיפא דוקא כשאמר מתחלה בעלתי צריכה גט אבל אם אמר מתחלה לא בעלתי אינה צריכה גט ולא יתכן שתהא מותרת הצרה כששניהם מודים שלא בעל ולהחזיקה כודאי בעולה כיון דאיהי לא בעיא גט ומיהו י\"ל דאיהי נמי בעיא גט אפי' שניהם מודים שלא בעל והא דנקט והוא אומר בעלתי וחזר ואמר כו' ה\"ה אפי' אמר לא בעלתי בעיא גט אלא לא נקט אמר בתחלה בעלתי אלא לאשמועינן דאפי' הכי כופין אותו לחלוץ ולא כמו שפירש בקונטרס ור\"ח דאין כופין ועוד יש לפרש דבסמוך שריא צרתה אפי' תוך שלשים כמו שפירש בקונטרס ור\"ח והוא אומר לא בעלתי קאי נמי אתוך שלשים וכן סיפא דהוא אומר בעלתי קיימא נמי אתוך ל' ואפי' שניהם מודים שלא בעל צריכה גט בהדי חליצה אפי' תוך שלשים ולאו דוקא נקט הוא אומר בעלתי כדפי' ורישא דקתני כופין אותו לחלוץ ה\"ה דגט נמי בעיא כדקתני בסיפא אלא אכתי לא אתא לאשמועינן תקנתא דגט בהדי חליצה אלא דין כפייה ובקשה דחליצה ומחמת שתי הלשונות שפר\"י נראה לאסור הצרה עד לאחר שלשים יום אם לא יודו שניהם שבעל ולהצריך גט לכנוסה אפי' תוך שלשים אפי' שניהם מודים שלא בעל:"],[4,"אמר ר' אמי","לא בעי לאוקומי הך משנה כמשנה אחרונה (לעיל יבמות דף לט:) דמצות חליצה קודמת ולכך כופין לחלוץ דאמתני' קאי ומתניתין דאיירי בדיני ייבום לפי משנה ראשונה קיימא:"],[4,"אמר רבי אמי צריכה חליצה עם הגט","פי' גיטה שהיה כבר ואם תאמר וא\"כ מאי הא דקתני ואע\"פ שחזר ואמר לא בעלתי צריכה גט וחליצה אדרבה היא הנותנת דכיון דלא בעל צריכה חליצה ויש לומר דהכי קאמר אע\"פ שאמר לא בעלתי צריכה להיות בידה גיטה לראיה כי לא תוכל להנשא על פי חליצה בלבד. ר\"י:"],[9,"השמים ביני לבינך","פי' בקונטרס גלוי וידוע לשמים שאין נזקק עמי כשאר בני אדם ולא נהירא דבשלהי נדרים (דף צא.) מפרש בגמרא בהדיא דהיינו שאינו יורה כחץ:"],[10,"יעשו דרך בקשה","פר\"ת יתפללו למקום ויתן להם בנים ור\"ח פי' יעשה סעודה ויפייסה וכן בירושלמי:"],[12,"איבעיא להו נטולה אני מן היהודים מהו ליבם","פי' בקונטרס מי אסורה ליבם משום נדר זה דמסקה אדעתה דמית בעלה ונפלה קמיה ואסורה לו או לא מסקה אדעתה ולא אסרה נפשה איבם וקשה לר\"י על פירושו דפשיטא דאסרה נפשה אכל היהודים ועוד מאי אינו כבעל אינו כשאר אדם מיבעי ליה ועוד מאי קאמר ש\"מ כופין כרב והלא היא מותרת לו על כן נראה לו לפרש דמיבעיא ליה אי מסקה אדעתה לאסור נפשה על היבם ומבקשין לחלוץ או שמא לא עשתה כדי לאסור עצמה על יבמה כמו על בעלה וקאמר רב יבם אינו כבעל דלא מסקה אדעתה לאסור עצמה איבמה כמו על בעלה ולכך כופין שיחלוץ לה ושמואל אמר יבם הרי הוא כבעל ומבקשין שיחלוץ דמסקה אדעתה לאסור עצמה על יבמה. כן נראה לי עיקר לפי שטה זו:"]]],[["מבקשין מיבעי ליה הכא במאי עסקינן באשה שיש לה בנים דכולי האי לא מסקה אדעתה","אבל אין לה בנים מאי מבקשין אדתני אם נתכוונה לכך אפילו בחיי בעלה מבקשין ממנו שיחלוץ לה ליפלוג וליתני בדידה במה דברים אמורים בשיש לה בנים אבל אין לה בנים מבקשין","אלא שמע מינה לא שנא יש לה בנים ולא שנא אין לה בנים כופין אותו כרב שמע מינה:","\u0001הדרן עלך בית שמאי\u0002","מתני׳ \u0001חרש\u0002 שנשא פקחת ופקח שנשא חרשת אם רצה להוציא יוציא ואם רצה לקיים יקיים כשם שהוא כונס ברמיזה כך הוא מוציא ברמיזה","פקח שנשא פקחת ונתחרשה אם רצה יוציא ואם רצה יקיים נשתטית לא יוציא נתחרש הוא או נשתטה אינו מוציאה עולמית","אמר רבי יוחנן בן נורי מפני מה האשה שנתחרשה יוצאה והאיש שנתחרש אינו מוציא אמרו לו אינו דומה האיש המגרש לאשה המתגרשת שהאשה יוצאה לרצונה ושלא לרצונה והאיש אינו מוציא אלא לרצונו","העיד רבי יוחנן בן גודגדא על החרשת שהשיאה אביה שהיא יוצאה בגט אמרו לו אף זו כיוצא בה","ב' אחין חרשין נשואין לב' אחיות חרשות או לשתי אחיות פקחות או לשתי אחיות אחת חרשת ואחת פקחת או ב' אחיות חרשות נשואין לשני אחין פקחין או לשני אחין חרשין או לשני אחין אחד חרש ואחד פקח הרי אלו פטורין מן החליצה ומן הייבום ואם היו נכריות יכנוסו ואם רצו להוציא יוציאו","שני אחין אחד חרש ואחד פקח נשואין לשתי אחיות פקחות מת חרש בעל הפקחת מה יעשה פקח בעל הפקחת תצא משום אחות אשה","מת פקח בעל הפקחת מה יעשה חרש בעל פקחת מוציא אשתו בגט ואשת אחיו אסורה לעולם","שני אחין פקחין נשואין לשתי אחיות אחת חרשת ואחת פקחת מת פקח בעל חרשת מה יעשה פקח בעל פקחת תצא משום אחות אשה מת פקח בעל פקחת מה יעשה פקח בעל החרשת מוציא את אשתו בגט ואת אשת אחיו בחליצה","שני אחין אחד חרש ואחד פקח נשואין לשתי אחיות אחת חרשת ואחת פקחת מת חרש בעל חרשת מה יעשה פקח בעל פקחת תצא משום אחות אשה","מת פקח בעל פקחת מה יעשה חרש בעל חרשת מוציא את אשתו בגט ואשת אחיו אסורה לעולם","שני אחין אחד חרש ואחד פקח נשואין לשתי נכריות פקחות מת חרש בעל פקחת מה יעשה פקח בעל פקחת או חולץ או מייבם מת פקח בעל פקחת מה יעשה חרש בעל פקחת כונס ואינו מוציא לעולם","שני אחין פקחין נשואין לב' נכריות אחת פקחת ואחת חרשת מת פקח בעל חרשת מה יעשה פקח בעל פקחת כונס ואם רצה להוציא יוציא מת פקח בעל פקחת מה יעשה פקח בעל חרשת או חולץ או מייבם","שני אחין אחד חרש ואחד פקח נשואים לב' נכריות אחת חרשת ואחת פקחת מת חרש בעל חרשת מה יעשה פקח בעל פקחת כונס ואם רצה להוציא יוציא מת פקח בעל פקחת מה יעשה חרש בעל חרשת כונס ואינו מוציא לעולם:","\u0001גמ׳\u0002 אמר רמי בר חמא מאי שנא חרש וחרשת דתקינו להו רבנן נשואין ומ\"ש דשוטה ושוטה דלא תקינו להו רבנן נשואין דתניא שוטה וקטן שנשאו נשים ומתו נשותיהן פטורות מן החליצה ומן היבום","חרש וחרשת דקיימא תקנתא דרבנן תקינו להו רבנן נשואין שוטה ושוטה דלא קיימא תקנתא דרבנן דאין אדם דר עם נחש בכפיפה אחת לא תקינו רבנן נשואין","ומאי שנא קטן דלא תקינו רבנן נשואין וחרש תקינו ליה רבנן נשואין חרש דלא אתי לכלל נשואין תקינו רבנן נשואין קטן דאתי לכלל נשואין לא תקינו רבנן נשואין","והרי קטנה דאתיא לכלל נשואין ותקינו רבנן נשואין התם שלא ינהגו [בה] מנהג הפקר","ומ\"ש קטנה דממאנה ומ\"ש חרשת דלא ממאנה דא\"כ"],[[0,"מבקשין מיבעי ליה","דאיכא למימר להכי איכוונה:"],[4,"מתני' חרש. כשם שכונס ברמיזה","מה טעם קאמר כלומר כקידושין כך גירושין וכן פקח בחרשת ברמיזה כנס שרמז באצבע עד שנתרצית לו וברמיזה אם רצה להוציא יוציא:"],[5,"פקח שנשא פקחת ונתחרשה","אע\"פ שקידושיה גמורים אם רצה יוציא דבגט לא בעינן דעת האשה כדמפרש לקמן במתניתין:"],[5,"נשתטית לא יוציא","בגמרא מפרש שלא ינהגו בה מנהג הפקר ותקנתא דרבנן היא:"],[5,"נתחרש הוא","לאחר קידושין הואיל וקידושיה גמורים היו לא יוציא עולמית:"],[7,"שהשיאה אביה","בקטנותה וקיבל קידושיה והוו קידושין גמורים שיוצאה בגט ואפי' משגדלה ופקע כח אב מקבלת היא את גיטה:"],[7,"אף זו","פקחת שנתחרשה כיוצא בה:"],[8,"הרי אלו פטורות","דהואיל ושתיהן חרשות או שניהן חרשים כקידושי זו כך קידושי זו ואתו קידושין דאשתו ומפקעי זיקה:"],[8,"יכנוסו","שאין חליצה בחרשת וחרש שאינן באמר ואמרה ואח\"כ אם רצו יוציאו בגט דאתא גט ברמיזה ומפקיע נישואין דידיה וזיקת אחיו דהוא ברמיזה:"],[10,"מוציא אשתו בגט","דזיקת אחותה הבאה מכח קידושין גמורים אוסרתה עליו ואין כח בקידושין דידה לדחותה משום אחות אשה:"],[10,"ואשת אחיו אסורה לעולם","דחרש לא חליץ ולכנוס אי אפשר משום אחות אשה:"],[16,"כונס ואין מוציא לעולם","דלא אתי גט דידיה ומפקע זיקת יבומי אחיו הראשון:"],[17,"גמ' דתקינו להו רבנן נישואין","דקתני מתני' שצריכות חליצה אלמא יש נישואין וקידושין לחרש ואע\"ג דלאו בר דעה הוא ומדאורייתא אין קנינו קנין:"],[17,"","ה\"ג שוטה וקטן שנשאו נשים נשותיהן פטורות מן החליצה ומן הייבום:"],[18,"דקיימא תקנתא דרבנן","שדרכן להיות שלום ביניהם אפי' חרש עם חרשת וכ\"ש כשהאיש פקח אבל שוטה אפילו בפקחת לשוטה ושוטה לפקח אין שלום ביניהם וכ\"ש שוטה לשוטה:"],[18,"בכפיפה","בתוך קופה אחת:"],[19,"ומאי שנא קטן","דקתני לעיל שוטה וקטן שנשאו כו':"],[19,"חרש דלא אתי","לעולם לכלל נישואין דאורייתא:"],[19,"תקינו ליה רבנן נישואין","כדי שלא יבטל:"],[20,"שלא ינהגו בה מנהג הפקר","אי לא מוצאה דמנסבה אין לה מי ישמרנה וינהגו בה מנהג הפקר בזנות:"]],[[4,"מתני' ואם רצה לקיים יקיים","הא פשיטא אלא אגב דתנא יוציא תנא יקיים:"],[7,"העיד ר' יוחנן בן גודגדא","רבנן הביאוה לבית המדרש להביא ראיה לדבריהם מאמרו לו אף זו כיוצא בה ואם תאמר לר' יוחנן בן נורי למה אינה מתגרשת הלא אינה חוזרת כשמרמזים לה ויש לומר דמכל מקום בשעת נתינת הגט משלחה וחוזרת היא ואינה מבינה עד שמוציאין אותה על כרחה: יש גורסים במשנה ועל קטנה בת ישראל שאוכלת בתרומה כמו שהוא בגמרא בפרק הניזקין (גיטין דף נה. ושם) ואין צריך לגרוס זו כאן שהרי לא הביאו העדות אלא ראיה לדבריהם וקטנה למה יזכירו כאן:"],[18,"דאין אדם דר עם נחש בכפיפה אחת","מיהו היכא שנישאת לו כבר תקינו רבנן שאינה מתגרשת כיון שאינה יודעת לשמור עצמה כדלקמן (יבמות דף קיג:):"]]],[["מימנעי ולא נסבי לה","ומאי שנא קטנה דאכלה בתרומה ומאי שנא חרשת דלא אכלה בתרומה דתנן העיד רבי יוחנן בן גודגדא על החרשת שהשיאה אביה שיוצאה בגט ועל קטנה בת ישראל שנשאת לכהן שאוכלת בתרומה ואילו חרשת לא אכלה","גזירה שמא יאכיל חרש בחרשת וליכול קטן אוכל נבלות הוא","גזירה שמא יאכיל חרש בפקחת וחרש בפקחת נמי ליכול בתרומה דרבנן גזירה דלמא אתי לאוכלה בתרומה דאורייתא","ומאי שנא קטנה דאית לה כתובה ומאי שנא חרשת דלית לה כתובה דא\"כ מימנעי ולא נסבי לה","וקטנה מנלן דאית לה כתובה דתנן הממאנת והשנייה ואיילונית אין להן כתובה אבל יוצאה בגט וקטנה יש לה כתובה","וחרשת מנלן דלית לה כתובה דתניא חרש ושוטה שנשאו פקחות אע\"פ שנתפקח החרש ונשתפה השוטה אין להם עליהם כלום רצו לקיימן יש להם כתובה","ופקח שנשא חרשת או שוטה אפי' כתב לה מאה מנה כתובתה קיימת מפני שרצה לזוק בנכסיו טעמא דרצה הא לא רצה אין לה דא\"כ מימנעי ולא נסבי לה","אי הכי פקחת לחרש ליתקן לה כתובה דא\"כ מימנעי ולא מינסבי יותר משהאיש רוצה לישא אשה רוצה להנשא","ההוא חרש דהוה בשבבותיה דרב מלכיו אנסביה איתתא וכתב לה ארבע מאה זוזי מנכסיה אמר רבא מאן חכים כרב מלכיו דגברא רבה הוא קסבר אילו רצה שפחה לשמשו מי לא זבנינן ליה כ\"ש הכא דאיכא תרתי","אמר רב חייא בר אשי אמר שמואל אשת חרש אין חייבין עליה אשם תלוי","לימא מסייע ליה חמשה לא יתרומו ואם תרמו אין תרומתן תרומה ואלו הן חרש שוטה וקטן והתורם את שאינו שלו ועובד כוכבים שתרם של ישראל אפילו ברשות ישראל אין תרומתו תרומה","הוא דאמר כרבי אלעזר דתניא ר' יצחק אומר משום רבי אלעזר תרומת חרש לא תצא לחולין מפני שהוא ספק אי סבירא כרבי אלעזר אשם תלוי נמי ליחייב","בעינן חתיכה משתי חתיכות","ומי בעי רבי אלעזר חתיכה משתי חתיכות והתניא רבי אלעזר אומר כוי חייבין על חלבו אשם תלוי","שמואל סבר כר' אלעזר בחדא ופליג עליה בחדא","ואיכא דאמרי אמר רב חייא בר אשי אמר שמואל אשת חרש חייבין עליה אשם תלוי מיתיבי חמשה לא יתרומו סבר לה כרבי אלעזר","בעא רב אשי מ\"ט דר' אלעזר מיפשט פשיטא לי' דחרש דעתא קלישתא הוא ומיהו מספקא לי' אי דעתא צילותא"],[[0,"מימנעי ולא נסבי לה","הואיל ולעולם היא יכולה למאן מפני חרשותה אבל קטנה גבול יש לה וסבר מפייסנא לה כל שעתא עד שיעבור זמן מיאונה:"],[1,"מאי שנא דאכלה בתרומה","אם השיאתה אמה לכהן:"],[1,"ומאי שנא חרשת","שלא השיאה אביה בקטנותה שאין נישואיה גמורין דלא אכלה כדתנן כו' אלמא לא אכלה:"],[1,"על החרשת שהשיאה אביה","בקטנותה שיוצאה בגט ואפי' משתגדיל ואין אביה מקבל גיטה מקבלתו היא ויוצאה ואע\"ג דקידושיה גמורין הוו וגירושיה בלא דעת הוי גיטא לפי שהאשה יוצאת לרצונה ושלא לרצונה:"],[1,"ועל קטנה בת ישראל","יתומה הנישאת ע\"פ אמה שאוכלת בתרומה אע\"פ שאין נישואיה נישואין גמורים אכלה בתרומה דרבנן כך אוקימנא בהאשה רבה (לעיל יבמות דף צ.):"],[1,"ואילו חרשת לא אכלה","מדשבקה לחרשת דקעסיק בה ואתי ונקט קטנה ולא קתני ועל החרשת שנישאת מעצמה שאוכלת בתרומה:"],[2,"גזירה שמא יאכיל חרש בחרשת","והאי לאו שינויא מעליא הוא מה לי פקח בחרשת מה לי חרש בחרשת שניהן אינן נשואין ואם זו מותרת אף זו מותרת שהרי צד היתר שלהן אינו אלא משום דלאו בני עונשין נינהו והוו כקטן אוכל נבלות אלא כולה משום גזירה שמא יאכיל חרש בפקחת הוא דאיכא עליה חיוב מיתה כדאמרי' במסקנא דמילתא ולהכי נקט ברישא שמא יאכיל חרש בחרשת ולא נקט שמא יאכיל חרש בפקחת משום דחרש בפקחת לא מיחלף בפקח בחרשת אבל חרשת אשת חרש מיחלפא בחרשת אשת פקח והדר מיחלף חרש בעל פקחת בחרש בעל חרשת אבל קטנה לגדול ליכא למיגזר משום גדולה לקטן דאין לקטן נישואין:"],[2,"וליכול","אפי' חרש בפקחת בתרומה דרבנן הא אית לה נשואין מדרבנן:"],[4,"ומ\"ש כו'","לקמן בעי תרוייהו מנא לן דהא אית לה והא לית לה:"],[4,"מימנעי ולא נסבי לה","אבל בקטנה לא מימנעי דאתיא לכלל דיעה:"],[5,"ממאנת","לית לה כתובה דהא בעל כרחו נפקא:"],[5,"שנייה","מד\"ס:"],[5,"אין לה כתובה","דרבנן קנסוה כדאמר ביש מותרות (לעיל יבמות דף פה:):"],[5,"איילונית","משום דמקח טעות הוא:"],[5,"אבל יוצאה בגט כו'","מדיוקא דמתני' דקתני ממאנת שמעינן מינה טעמא משום דבעל כרחו נפקא הא הוציאה אית לה אלמא יש כתובה לקטנה:"],[6,"אין להן עליהם כלום","דאין להם דעת ואין תנאו הראשון תנאי ואע\"ג דתקון רבנן נשואין לחרש לא תקינו לה רבנן כתובה מיניה כדמפרש לקמן יותר ממה שהאיש רוצה לישא אשה רוצה להנשא:"],[7,"שרוצה לזוק בנכסיו","ואע\"פ שלא (נשא) תקנו לה חכמים כתובה הרי הוא כתב לה הואיל ורוצה להפסיד ולהיות נזוק מנכסיו תנאו קיים:"],[7,"הא לא רצה","דלא כתב לה אין לה מתקנת חכמים:"],[7,"א\"כ","דבעי למיתב לה כתובה מימנעי ולא נסבי לה:"],[10,"אין חייבין עליה אשם תלוי","דנימא ספק אשת איש היא ספק היה בו דעת ספק אין בו והבא עליה באשם תלוי דודאי אין לו שום קנין מן התורה:"],[11,"התורם את שאינו שלו","ולא צוהו בעל הבית דשליחות נפקא לן (קדושין דף מא:) מאתם גם אתם לרבות שלוחכם הלכך מה אתם לדעתכם אף שלוחכם לדעתכם:"],[11,"ועובד כוכבים שתרם את של ישראל אפי' ברשות בעלים אינה תרומה","דבעינן מה אתם בני ברית אף שלוחכם בני ברית. וקתני מיהא חרש אין תרומתו תרומה ומותרת לזר ואי ספק הוא תרומה ויחזור ויתרום מיבעי ליה:"],[12,"הוא דאמר כר' אלעזר","כלומר מהא לא תסייעיה דגבי תרומה ס\"ל לשמואל כר' אלעזר דספק הוא וגבי אשתו אע\"ג דספק הוא אינה באשם תלוי דגבי אשם תלוי כתיב אחת מכל מצות ה' (ויקרא ה׳:י״ז) וקרינן מצוות דמשמע חדא מתרתי שיש היתר ואיסור לפניו כגון אשתו וא\"א עמו בבית וסבור אין שם אלא אשתו ובא על האחת ולבקר נמצאו שתיהן ולא ידע על אי זו בא וכן חלב ושומן לפניו וסבר שתיהן שומן ואכל אחת מהן ולסוף נודע לו שהאחת חלב ולא ידע אי זו אכל דאי ידע מייתי חטאת נקבה וכל דהו אפי' בת דנקא והשתא דלא ידע מביא אשם זכר בכסף שקלים אבל הכא שהספק תלוי בחתיכה אחת ספק איסור ספק היתר לא מייתי אשם תלוי:"],[14,"כוי חייבין על חלבו אשם תלוי","והא הכא כל הספק תלוי בה:"],[17,"מ\"ט דר\"א","באשת חרש:"],[17,"קלישתא","דקה. כלומר דעתו מועטת שאין מחודד להבין כשאר בני אדם ומיהו מספקא ליה אי דעתא צילותא היא אותה קצת הדעת שיש לו אם צלולה היא ובמה שהוא נותן דעתו ועושה דבר ודאי כוונתו כוונה אי לאו דעתו צלולה היא ולעולם כל ימיו של חרש פשיטא ליה לרבי אלעזר דחדא דעתא אית ליה לחרש דאינו עתים חלים עתים שוטה:"]],[[1,"ואילו חרשת לא אכלה","וא\"ת מנלן אי משום דנקט קטנה דלמא כ\"ש חרשת שלא תבא לכלל גדלות ואי הוה נקיט חרשת אכלה ה\"א דקטנה לא אכלה כיון שבאה לכלל נישואין וי\"ל דדייק מדלא תנא חרשת בהדי קטנה:"],[3,"שמא יאכיל חרש בפקחת","אבל משום שמא יאכיל קטן בגדולה לא גזרינן שלא תאכל קטנה בתרומה דמשום זמן מועט לא גזרינן שהרי כשיגדיל ויבעול יהיו קידושין דאורייתא ובירושלמי מפרש בקטנה לא גזרינן משום חינא שיהיו הכל קופצין עליה לישאנה ושמא בחרשת לא שייך האי טעמא משום דחרשותה גרמה לה ובקונ' פי' בהניזקין (גיטין ד' נה. ד\"ה בפקחת) דלא גזרינן אטו קטן שישא גדולה משום דלית ליה נשואין כדאמר הכא ומילתא דלא שכיחא היא ואין נראה דהא משיאן סמוך לפירקן מעליותא היא כדפי' לעיל (יבמות דף סב: ד\"ה סמוך):"],[3,"דלמא אתי לאוכלה בתרומה דאורייתא","אבל בקטנה דלא אכלה אלא בתרומה דרבנן כדאמר בהאשה רבה (לעיל יבמות דף צ. ושם) לא גזרו אטו דאורייתא כיון שתגיע לכלל גדלות:"],[4,"דאם כן מימנעי ולא נסבי לה","ואי משום שלא תהא קלה בעיניו להוציאה לא חשו חכמים לכך:"],[9,"מאן חכים למיעבד הכי","דוקא במטלטלי תנן בהניזקין (גיטין דף נט.) חרש רומז ונרמז אבל במקרקעי לא ומה ששיעבד בכתובה מקרקעי משום שהיה לו אפוטרופוס וגם זכין לאדם שלא בפניו. ר\"י:"]]],[["אי לאו דעתא צילותא ולעולם חדא דעתא הוא או דלמא פשיטא ליה דדעתיה קלישתא ולאו דעתא צילותא הוא והכא היינו טעמא כיון דעתים חלים ועתים שוטה","למאי נפקא מינה להוציא אשתו בגט אי אמרת חדא דעתא הוא כקדושין כך גירושין","ואי אמרת עתים חלים ועתים שוטה קדושי מצי מקדש גרושי לא מצי מגרש מאי תיקו:","נשתטית וכו': א\"ר יצחק דבר תורה שוטה מתגרשת מידי דהוה אפקחת בעל כרחה ומה טעם אמרו אינה מגורשת שלא ינהגו בה מנהג הפקר","היכי דמי אילימא דיודעת לשמור גיטה ויודעת לשמור עצמה מי נהגי בה מנהג הפקר אלא דאין יודעת לשמור לא גיטה ולא עצמה","דבר תורה שוטה מתגרשת והא אמר דבי רבי ינאי (דברים כד, א) ונתן בידה מי שיש לה יד לגרש עצמה יצתה זו שאין לה יד לגרש עצמה","ותנא דבי רבי ישמעאל (דברים כד, א) ושלחה מביתו מי שמשלחה ואינה חוזרת יצתה זו שמשלחה וחוזרת","לא צריכא דיודעת לשמור גיטה ואינה יודעת לשמור עצמה דבר תורה שוטה מתגרשת דהא יודעת לשמור גיטה ואמור רבנן לא ליפקא שלא ינהגו בה מנהג הפקר","אמר אביי דיקא נמי דקתני גבי דידה נשתטית לא יוציא וגבי דידיה לא יוציא עולמית מאי שנא הכא דקתני עולמית ומאי שנא התם דלא קתני עולמית אלא שמע מינה הא דאורייתא הא דרבנן:","א\"ר יוחנן בן נורי וכו': איבעיא להו רבי יוחנן בן נורי איש פשיטא ליה ואשה קמיבעיא ליה או דלמא אשה פשיטא ליה ואיש קמיבעיא ליה","ת\"ש מדקאמרו ליה אינו דומה האיש המגרש לאשה המתגרשת שהאשה יוצאת לרצונה ושלא לרצונה והאיש אינו מוציא אלא לרצונו ש\"מ איש קמיבעיא ליה אדרבה מדקא\"ל אף זו כיוצא בה ש\"מ אשה קמיבעיא ליה","אלא ' ר' יוחנן בן נורי לדבריהם קאמר להו לדידי כי היכי דאיש לא מצי מגרש אשה נמי לא מיגרשא אלא לדידכו מאי שנא אשה ומאי שנא איש אמרו ליה אינו דומה האיש המגרש לאשה המתגרשת:","העיד רבי יוחנן וכו': אמר רבא מעדותו של רבי יוחנן בן גודגדא אמר לעדים ראו גט זה שאני נותן ואמר לה כנסי שטר חוב זה הרי זו מגורשת","מי לא אמר רבי יוחנן בן גודגדא לא בעינן דעתה הכא נמי לא בעינן דעתה פשיטא","מהו דתימא מדא\"ל כנסי שטר חוב זה בטולי בטליה קמ\"ל אי איתא דבטליה לעדים הוה קאמר להו ומדלא אמר לעדים לא בטליה ולא מידי והאי דקאמר הכי מחמת כיסופא הוא דקאמר להו","רב יצחק בר ביסנא אירכסו ליה מפתחי דבי מדרשא ברשות הרבים בשבתא אתא לקמיה דרבי פדת אמר ליה זיל"],[[0,"או דלמא פשיטא ליה","דלאו דעתא צילותא היא אלא היינו טעמא דמספקא ליה דעתים שהוא חלים לגמרי ודעתו צלולה וחיישינן שמא בשעת קידושין חלים היה:"],[1,"להוציא את אשתו בגט","חרש מעיקרו לר' אלעזר אם יכול לגרש או לא דבשלמא לרבנן פשיטא לן דמוציא כדאמרינן במתני' (לעיל יבמות קיב:) כשם שכונס ברמיזה כך מוציא ברמיזה אלא לר' אלעזר דמשוי ליה ספק מאי:"],[6,"שמשלחה מביתו וחוזרת","שכן מנהג השוטים שאין בושין:"],[10,"ש\"מ איש מיבעיא ליה","ואשה פשיטא ליה דאי אשה מיבעיא ליה ואיש פשיטא ליה הכי איבעי להו לאהדורי אינו דומה אשה המתגרשת לאיש המגרש:"],[11,"אשה נמי לא מיגרשא","ועלה קמייתו לה רבנן ראיה לדבריהם אף זו כיוצא בה ואינו דומה דקמהדרי ליה אאיש משום דאיהו ה\"ק לדידכו דאמריתו אשה מיגרשא מ\"ש איש ומ\"ש אשה:"],[12,"מעדותו של ר' יוחנן","דאמר דאפי' במקום קידושין גמורים לא בעינן דעתא דאשה בגירושין:"],[12,"אמר לעדים ראו גט זה שאני נותן לה","והיא לא שמעה וחזר ואמר לה לאשתו פקחת כנסי שטר חוב זה ולא הודיעה שהוא גיטה ה\"ז מגורשת:"],[13,"לאו אמר ר' יוחנן לא בעינן דעתה","דאשה בגירושין דקתני חרשת יוצאת בגט:"],[13,"פשיטא","דלר' יוחנן ודאי הכי הוא:"]],[[5,"יצתה זו שאין לה יד לגרש עצמה","אר\"ת דהיינו דוקא באין לה אב ובפ' התקבל (גיטין דף סד: ושם) וכן בפ\"ב דקידושין (דף מג:) גבי כל קטנה שאין יכולה לשמור את גיטה אינה יכולה להתגרש פי' בקונט' אפי' ע\"י אביה ואין נראה לר\"ת דהא ר' ינאי מפיק לה הכא מונתן בידה מי שיש לה יד לגרש את עצמה יצתה זו שאין לה יד וכיון שיש לה אב הרי יש לה יד דאפי' נערה בין היא בין אביה מקבל גיטה ולרבי יהודה אביה ולא היא ור' ישמעאל נמי דדריש מושלחה משמע דלא פליג ארבי ינאי אלא דדריש מקרא אחרינא וטעמא דיש לה אב משלחה ואינה חוזרת היא שאביה משמרה מלחזור ועוד הביא ר\"ת ראייה מירושלמי דפירקין דקאמר התם נשתטית לא יוציא דבי ר' ינאי אמרי מפני גרירה ה\"פ שנגררת אחר כל אחד ונוהגין בה מנהג הפקר ר' זירא ור' מנא תרוייהו אמרי שאין יכולה לשמור את גיטה רבי נחמיה בשם ר' יהודה אמר תלתא מילי איכא בינייהו עבר וגירש מ\"ד מפני גרירה מותר כיון דליכא אלא איסור דרבנן שלא ינהגו בה הפקר אם עבר וגירש ה\"ז גט למ\"ד לפי שאינה יכולה לשמור את גיטה אסור פי' מדאורייתא אין הגט גט ועוד איכא בינייהו יש לה אב ופעמים שוטה ופעמים חלומה מ\"ד מפני גרירה אסור שאין האב יכול לשומרה מן ההפקר וכן בעתים שהיא שוטה אין נזהרת מן ההפקר אבל למ\"ד שאינה יכולה לשמור את גיטה יש לה אב יכול לשמור את גיטה וכן פעמים חלומה יש לה עתים יכולה לשמור את גיטה וה\"מ למימר דאיכא בינייהו יודעת לשמור את גיטה ולא את עצמה דלמ\"ד מפני גרירה אסור כדאמר הכא ולמ\"ד שאינה יודעת לשמור את גיטה זו יודעת לשמור גיטה אלא ניחא ליה למימר איכא בינייהו אפי' באין יודעת לשמור את גיטה ולא עצמה ואע\"ג דהכא משמע דליכא מאן דפליג שלא ינהגו בה מנהג הפקר ורבי ינאי הוא דדריש הכא שאין יכולה לשמור גיטה מונתן בידה ובירושלמי קאמר ר' ינאי משום גרירה ופליג אטעמא דאמר דאינה יכולה לשמור גיטה אין זה תימה כ\"כ כי יש סוגיות ומימרות הפוכות מהש\"ס שלנו וי\"מ דגרירה דקאמר בירושלמי היינו משלחה וחוזרת ויכולה לשמור גיטה היינו שיש לה יד לשמור גיטה והיינו פלוגתא דאמוראי דהכא ולפ\"ז מאן דמפיק מושלחה אפי' יש לה אב אינה מתגרשת דקאמר יש לה אב למאן דאמר מפני גרירה אסור ומיהו אין נראה פירוש זה דעבר וגירש אמאי מותר למ\"ד מפני גרירה כיון דהוי דאורייתא ועוד עתים שוטה ועתים חלומה אמאי קאמר דלמ\"ד מפני גרירה אסור כיון דקבלה גט כשהיא חלומה הרי באותה שעה משלחה ואינה חוזרת היא והורה כן ר\"ת הלכה למעשה ובפ\"ב דקידושין האריך בתוס' יותר והכא דפריך ואלא דאין יודעת לשמור לא גיטה ולא עצמה דבר תורה שוטה מתגרשת והאמר דבי ר' ינאי כו' הוה מצי לשנויי ביש לה אב אלא שזהו בכלל שינויא דמשני ביודעת לשמור את גיטה ולא את עצמה:"],[8,"אמר אביי דיקא נמי דקתני גבי דידה כו'","וא\"ת דהכא קאמר אביי גופיה עולמית לכדרבי יצחק ובפרק מי שאחזו (גיטין ד' עא: ושם) קאמר אביי מתני' נמי דיקא דחלוקין עליו חבריו על רשב\"ג דאמר בפקח שנתחרש שיכול לדבר מתוך הכתב דאין יכול לגרש מדקתני עולמית ודחי ליה רב פפא דלמא עולמית לכדר' יצחק והכא קאמר ליה אביי גופיה ואר\"י דעולמית קאי אנתחרש' ואנשתטה והתם דייק דחולקין עליו חבריו ממאי דקאמר עולמית אנתחרש ורב פפא סבר דלמא לא אתיא כלל אלא לכדר' יצחק:"],[12,"אמר רבא מעדותו של ר' יוחנן כו'","הוה מצי למימר מדרבנן דאמרי חרשת יוצאה בגט אלא ניחא ליה למינקט ר' יוחנן שחכמים מביאין ראיה מדבריו ועוד משום דכל עדות הלכה היא:"],[14,"מהו דתימא כי אמר לה כנסי שט\"ח כו'","והקשה ר\"י דהא היכא דאמר לה כנסי שטר זה לא שמעי' מדרבי יוחנן בן גודגדא אלא מסברא דאם איתא דבטליה כו' ולא שמעי' מדבריו אלא דלא בעינן דעתה ואכתי תיקשה פשיטא וי\"ל דאמילתיה דרבא פריך פשיטא ולמה ליה לרבא למימר כלל ומשני דרבא השמיענו בכנסי שטר חוב:"]]],[["דבר טלי וטליא וליטיילו התם דאי משכחי להו מייתי להו אלמא קסבר קטן אוכל נבלות אין ב\"ד מצווין להפרישו לימא מסייע ליה לא יאמר אדם לתינוק הבא לי מפתח הבא לי חותם אלא מניחו תולש מניחו זורק","אמר אביי תולש בעציץ שאינו נקוב זורק בכרמלית דרבנן:","ת\"ש עובד כוכבים שבא לכבות אין אומרים לו כבה ואל תכבה מפני שאין שביתתו עליהם קטן הבא לכבות אומרים לו אל תכבה ששביתתו עליהם","א\"ר יוחנן בעושה על דעת אביו דכוותיה גבי עובד כוכבים דעושה על דעת ישראל מי שרי עובד כוכבים אדעתא דנפשיה עביד","ת\"ש בן חבר שרגיל לילך אצל אבי אמו עם הארץ אין חוששין שמא יאכילנו דברים שאינם מתוקנים מצא בידו פירות אין זקוק לו אמר רבי יוחנן בדמאי הקילו","אלא טעמא דדמאי הא ודאי בעא לעשורי והאמר ר' יוחנן בעושה על דעת אביו אלא רבי יוחנן ספוקי מספקא ליה קאי הכא מדחי קאי הכא מדחי","ת\"ש בן חבר כהן שרגיל לילך אצל אבי אמו כהן עם הארץ אין חוששין שמא יאכילנו תרומה טמאה מצא בידו פירות אין זקוק לו בתרומה דרבנן","תא שמע יונק תינוק והולך מעובדת כוכבים ומבהמה טמאה ואין חוששין ביונק שקץ ולא יאכילנו נבלות וטרפות שקצים ורמשים ומכולן יונק מהם ואפילו בשבת ובגדול אסור אבא שאול אומר נוהגין היינו שיונקים מבהמה טהורה ביום טוב","קתני מיהא אין חוששין ביונק שקץ התם משום סכנה אי הכי גדול נמי","גדול בעי אומדנא קטן נמי ליבעי אומדנא אמר רב הונא בריה דרב יהושע סתם תינוק מסוכן אצל חלב:","אבא שאול אומר נוהגין היינו שיונקים מבהמה טהורה ביום טוב: היכי דמי אי דאיכא סכנה אפילו בשבת נמי ואי דליכא סכנה אפילו ביום טוב אסור לא צריכא דאיכא צערא","וקסבר מפרק כלאחר יד הוא שבת דאיסור סקילה גזרו רבנן יו\"ט דאיסור לאו לא גזרו ביה רבנן","ת\"ש (ויקרא יא, מב) לא תאכלום כי שקץ הם לא תאכילום להזהיר הגדולים על הקטנים מאי לאו דאמר להו לא תאכלו לא דלא ליספו ליה בידים","תא שמע (ויקרא יז, יב) כל נפש מכם לא תאכל דם להזהיר הגדולים על הקטנים מאי לאו דאמרי להו לא תאכלו לא דלא ליספו להו בידים","ת\"ש (ויקרא כא, א) אמור ואמרת להזהיר גדולים על הקטנים מאי לאו דאמר להו לא תיטמו לא דלא ליטמו להו בידים","וצריכי דאי אשמעינן שקצים"],[[0,"דבר טלי וטליא","הנהג תינוקות זכרים ונקבות:"],[0,"ליטיילו התם","ישחקו שם. שבת היתה:"],[0,"הבא לי מפתח","דרך רה\"ר בשבת:"],[2,"לכבות","הדליקה:"],[3,"בעושה על דעת אביו","שהתינוק צופה באביו ורואה שנוח לו בכך ואביו עומד עליו דהוה כאילו הוא מצוהו לעשות אבל הנך מפתחות דרב יצחק לא הודיען שנאבדו שם ולא הכירו בדעתו שנוח לו:"],[3,"עובד כוכבים אדעתא דנפשיה עביד","אפילו בלא ידיעת ישראל העובד כוכבים מתכוין להנאתו שיודע שיטול שכר:"],[4,"שאינן מתוקנין","שאינן מעושרין:"],[4,"אין זקוק לו","ליטלו הימנו:"],[5,"והא\"ר יוחנן","לעיל בעושה על דעת אביו אבל להפרישו אינו מצווה היכא דתינוק עביד אדעתא דנפשיה:"],[6,"תרומה טמאה","והא הכא דאיסורא דאורייתא הוא כדאמר בהערל (לעיל יבמות עג:) בשעריך תאכלנו לזה אתה אוכל בטומאת עצמו כדכתיב הטמא והטהור ולא לאחר למעוטי תרומה דאסורה בטומאת עצמה:"],[7,"ואין חוששין","לומר שהוא יונק שקץ כלומר דבר המשוקץ ונאסר:"],[7,"ולא יאכילנו","בידים דברים האסורים. חלב בהמה טמאה אסור בגדול מדאורייתא דנפקא לן מגמל גמל ב' פעמים בפ\"ק דבכורות (ד' ו:):"],[8,"סכנה","שאם לא יינק ימות בצמא:"],[9,"אומדנא","אם יכול להמתין עד מוצאי שבת ויעשה בהיתר:"],[11,"","חולב בידיו חייב משום מפרק דבר מגידולו והיונק הוי מפרק ע\"י שינוי והיינו כלאחר יד:"],[11,"שבת דאיסור סקילה","יש במפרק בידיו גזרו רבנן ביונק ואע\"ג דמשנה הוא ואינה מלאכה מן התורה אבל י\"ט דכי עביד בידים ליכא אלא איסור לאו לא גזור רבנן ביונק:"],[12,"(לא תאכלום) לא תאכלום כי שקץ הם","קרא יתירא הוא דהא כתיבי אזהרות הרבה בשרצים:"],[13,"לא תאכל דם","קרא יתירא הוא דהא כתיבי אזהרות הרבה גבי דם:"],[14,"אמור אל הכהנים בני אהרן ואמרת","שתי אמירות הללו למה להזהיר גדולים על הקטנים שלא יטמאו:"]],[[4,"אמר רבי יוחנן בדמאי הקילו","ה\"מ למימר דאפילו לא הקילו בדמאי כיון דאינו אלא מדרבנן שאני כדקאמר לעיל אלא משום דהאי שינויא משני בכמה דוכתי א\"נ כיון שיש לחוש לספק טבל דהוי דאורייתא החמירו אי לאו טעמא דבדמאי הקילו:"],[5,"אלא רבי יוחנן ספוקי מספקא ליה","והא דקאמר הש\"ס בס\"פ יוצא דופן (נדה דף מו: ושם) אליבא דר' יוחנן דאמר מופלא סמוך לאיש דאורייתא וקטן האוכל נבלות אין ב\"ד מצווין להפרישו על ברייתא דמותיב ליה התם הוה מצי למימר וליטעמיך והא ר' יוחנן ספוקי מספקא ליה הכא אלא דבלאו הכי שפיר קאמר התם ה\"ר אלחנן:"],[11,"וקסבר דהוי מפרק כלאחר יד","וא\"ת ואפילו לא הוי כלאחר יד נמי דהא אין דישה אלא בגידולי קרקע כדאמר בפרק כלל גדול (שבת דף עה. ושם) גבי פוצע חלזון וכ\"ת אע\"ג דחלזון לא חשיב גידולי קרקע בהמה חשיבא גידולי קרקע כדאמרי' בריש פ' בכל מערבין (עירובין ד' כז:) דממעט דגים מדכתי' בקר וצאן מה הפרט מפורש גידולי קרקע כו' זה אין לומר דנהי דחשיב בהמה גידולי קרקע מ\"מ כיון דגמרי' מסממנין בעינן ממש שיהא גדל מן הקרקע כמו סממנין דלגבי גדולי קרקע ממש לא חשיב בהמה גדולי קרקע כדמוכח בהשוכר את הפועלים (ב\"מ דף פט. ושם) דתניא דיש מה דיש מיוחד כו' יצא החולב והמגבן והמחבץ שאינם גידולי קרקע ואין פועל אוכל בו אלמא גבי דבר הגדל ממש מן הארץ לא חשיבא בהמה גידולי קרקע וכן משמע בפ\"ק דקידושין (דף יז.) גבי גורן ויקב וי\"ל דאיצטריך טעמא דהכא דמפרק כלאחר יד הוא משום ר' יהודה דסבר יש דישה שלא בגידולי קרקע דמחייב בפוצע חלזון נמי משום דש ור\"ת מפרש דמפרק חייב משום ממחק שמחליק העור ומאבות מלאכות הוא וקשה לר\"י מדאמר בפ' חבית (שבת דף קמד. ושם) חולב אדם עז לתוך הקדירה אבל לא לתוך הקערה ולפי' הקונטרס ניחא דטעמא משום דכשחולב לתוך הקדירה הוי משקה הבא לאוכל ואוכל הוא ואין זה בורר אבל לא לתוך הקערה דבורר משקה מאוכל ודומה לדש שבורר אוכל מתוך פסולת אבל לפירוש ר\"ת בין כך ובין כך ליחייב משום ממחק:"],[11,"שבת דאיסור סקילה גזור רבנן כו'","קשה דאמרי' בפרק אע\"פ (כתובות ד' ס.) גונח יונק חלב בשבת קסבר מפרק כלאחר יד הוא ומשום צערא לא גזור רבנן והכא אסר ליה בשבת וליכא למימר דהתם במסוכן דאם כן אפילו מלאכה גמורה ואינו כלאחר יד שרי ואמר ר\"ת דהתם מחמת חולי והכא מחמת רעב קרי שפיר צער כדאמר בפרק שלישי דשבועות (ד' כו: ושם) נשבע על הככר ומסתכן עליה מהו מסתכן לישרי ליה מר אלא מצטער עליה מהו וקשה לר\"י דאם כן מאי קאמר הכא אי דאיכא סכנה אפילו בשבת מותר והא אפילו בחולים בעלמא מותר כיון שאין בהן מלאכה גמורה ולרבי נראה דאין זו קושיא דהא אכתי לא פירש הש\"ס דמפרק כלאחר יד הוא וקאמר דאפילו מלאכה גמורה מן התורה יש לו לדחות להיות מותר כיון דאיכא סכנה ור\"י תירץ דהך דהכא פליגא וכן משמע התם (כתובות דף ס.) דאמר הלכה כר' מרינוס מכלל דאיכא דפליגי עליה ואיכא דמפרש דהכא בצער של בהמה איירי שמתקשה לה רוב חלב בדדיה וקשה לר\"י דלמה היו יונקים והלא היו יכולין לחלוב לתוך הקדירה ומיהו לפירוש ר\"ת לא קשה דמסתמא כיון שהיו רעבים לא היה להם שום מאכל בקדירה:"]]],[["משום דאיסורן במשהו אבל דם דעד דאיכא רביעית אימא לא ואי אשמעינן דם משום דאיכא כרת אבל שרצים אימא לא","ואי אשמעינן הני תרתי משום דאיסורן שוה בכל אבל טומאה אימא לא ואי אשמעינן טומאה כהנים שאני משום דריבה בהן מצות יתרות אבל הני אימא לא צריכא","תא שמע שני אחין אחד פקח ואחד חרש נשואין שתי אחיות פקחות מת חרש בעל פקחת מה יעשה פקח בעל פקחת תצא משום אחות אשה","מת פקח בעל פקחת מה יעשה חרש בעל פקחת מוציא את אשתו בגט ואשת אחיו אסורה לעולם","אמאי מוציא את אשתו בגט תיתיב גביה קטן אוכל נבלות הוא משום איסורא דידה","תא שמע שני אחין פקחין נשואין שתי אחיות אחת פקחת ואחת חרשת מת פקח בעל חרשת מה יעשה פקח בעל פקחת תצא משום אחות אשה מת פקח בעל פקחת מה יעשה פקח בעל חרשת מוציא את אשתו בגט ואשת אחיו בחליצה","ואמאי מוציא את אשתו בגט תיתיב גביה קטן אוכל נבלות הוא משום איסורא דידיה","אמר רבא תא שמע שני אחין אחד חרש ואחד פקח נשואין לשתי אחיות אחת פקחת ואחת חרשת מת חרש בעל חרשת מה יעשה פקח בעל פקחת תצא משום אחות אשתו מת פקח בעל פקחת מה יעשה חרש בעל חרשת מוציא את אשתו בגט ואשת אחיו אסורה לעולם","והא הכא דלאו איסורא דידה איכא ולאו איסורא דידיה איכא וקתני מוציא את אשתו בגט אמר רב שמעיה גזירה משום התרת יבמה לשוק:","\u0001הדרן עלך חרש\u0002","מתני׳ \u0001האשה\u0002 שהלכה היא ובעלה למדינת הים שלום בינו לבינה ושלום בעולם ובאה ואמרה מת בעלי תנשא מת בעלי תתייבם","שלום בינו לבינה ומלחמה בעולם קטטה בינו לבינה ושלום בעולם ובאתה ואמרה מת בעלי אינה נאמנת רבי יהודה אומר לעולם אינה נאמנת אלא אם כן באתה בוכה ובגדיה קרועין אמרו לו אחת זו ואחת זו תנשא:","\u0001גמ׳\u0002 תנא שלום בינו לבינה משום דקבעי למיתני קטטה בינו לבינה תנא שלום בעולם משום דקבעי למיתני מלחמה בעולם","אמר רבא מאי טעמא דמלחמה משום דאמרה בדדמי סלקא דעתא בכל הני דאיקטול הוא פליט אם תימצא לומר כיון דשלום בינו לבינה נטרא עד דחזיא זימנין דמחו ליה בגירא או ברומחא וסברא ודאי מת ואיכא דעבד סמתרי וחיה","סבר רבא למימר רעבון אינו כמלחמה דלא אמרה בדדמי הדר אמר רבא רעבון הרי הוא כמלחמה דההיא דאתת לקמיה דרבא אמרה ליה בעלי מת ברעב אמר לה שפיר עבדת דשיזבת נפשיך ס\"ד דבההוא פורתא דנפפיתא דשבקת ליה הוה חיי אמרה ליה מר נמי ידע דכי האי גוונא לא חיי","הדר אמר רבא רעבון גריעה ממלחמה דאילו מלחמה כי אמרה מת בעלי במלחמה הוא דלא מהימנא הא מת על מטתו מהימנא ואילו גבי רעבון עד דאמרה מת וקברתיו","מפולת הרי הוא כמלחמה דאמרה בדדמי שילוח נחשים ועקרבים הרי הן כמלחמה דאמרה בדדמי","דבר אמרי לה הרי הוא כמלחמה ואמרי לה אינו כמלחמה אמרי לה הרי הוא כמלחמה דאמרי בדדמי ואמרי לה אינו כמלחמה דסמכי אדאמרי אינשי שב שנין הוה מותנא ואינש בלא שני לא אזיל","איבעיא להו החזיקה היא מלחמה בעולם מהו מי אמרינן מה לה לשקר"],[[0,"במשהו","בכעדשה כטומאתן:"],[4,"משום דידה","שהיא פקחת ובת עונשין. ובמציעא גרס משום דידיה:"],[8,"משום גזירת התרת יבמה לשוק","דאי אמרי' תיתיב חרשת גבי חרש לא ידעי אינשי דטעמא משום קטן אוכל נבלות הוא וסברי דקדושין דידה דחו לה לזיקה דפקחת אחותה ואין בועל אחות זקוקתו הילכך אתי למישרייה לאחותה לשוק כשאר אחות אשה שפטורה מן החליצה:"],[10,"מתני' האשה ושלום בעולם","שאין שעת חירום דתימא בדדמי מאומד לבה אם פירש הימנה חדש או חדשים ודאי הואיל ולא חזר הרגוהו ליסטים דהואיל ולאו שעת חירום אי לא חזיתיה דמית חיישא לקלקולא שמא יבא לאחר שניסת ותהא מקולקלת כדאמר בהאשה רבה (לעיל יבמות דף פז:) ולא אמרה בדדמי:"],[11,"קטטה בינו לבינה","י\"ל מתוך ששונאתו היא רוצה לאסור עצמה עליו:"],[13,"גמ' בדדמי","מאומד לבה ואע\"ג דלא חזיתיה דמית כדפרישית דסברה סלקא דעתא בכל הני דאיקטול הוא פליט בתמיה:"],[13,"סמתרי","תחבושת:"],[14,"שפיר עבדת","לנסותה ולתופשה מתוך דבריה נתכוון:"],[14,"דשיזבת נפשך","שהנחת אותו אפי' חי וברחת לך משום דכי תעלה בדעתיך דבההוא פורתא דנפפיתא קמח מנופה בנפה חיי בתמיה:"],[14,"מר נמי ידע כו'","אלמא אמרה בדדמי ומשום האי מעשה הדר ביה רבא:"],[15,"מת וקברתיו","דאילו במלחמה סברה שמא ברח וניצל אבל ברעב היא סבורה איך יחיה:"],[16,"מפולת","שנפל הבית עליו או בא רוח סערה והיה מפיל כל בתי העיר:"],[18,"החזיקה היא מלחמה בעולם","שלא היינו יודעים שיש מלחמות באותן מדינות אלא מפיה:"]],[[0,"משום דאיסורן במשהו","פי' בקונט' איסורן בכעדשה ולא דק דבהדיא אמר במעילה בפרק קדשי מזבח (מעילה דף טז: ושם) דשרצים לוקין עליהם בכזית דאכילה כתיב בהו ואמרי' נמי בפ' בתרא דמכות (דף טז: ושם) ריסק ט' נמלים ואחד חי והשלים לכזית וכן משמע בכמה דוכתי אלא יש לפרש דאיסורן במשהו דלוקה על נמלה משום דהוי בריה וכן נראה לר\"י:"],[11,"מתני' האשה שלום. אמרו לו אחת זו ואחת זו תנשא","אין להקשות דהיינו ת\"ק דהא מעיקרא לא פי' אי מיירי אפי' בלא בוכה והכא מפרש ליה:"],[12,"תנא שלום בינו לבינה ושלום בעולם","דלא צריך למיתני דהא סתמא דמילתא הכי הוא דשלום בינו לבינה ושלום בעולם אלא תניא משום סיפא:"],[13,"זימנין דמחו ליה בגירא או ברומחא","והיא יראה לעמוד עד שימות לפי שזורקין חצים ואבני בלסטראות במלחמה ואינם מתכוונים על מי שיפול אבל לקמן גבי נפלו עלינו לסטים נאמנת לומר נהרג שעומדת שם עד שימות ולא אמרה בדדמי:"],[18,"מי אמרי' (כו') מה לי לשקר ומרע ליה לחזקיה","תימה לר\"י דע\"כ לא שייך מיגו כיון דאמרה בדדמי דאי שייך מיגו א\"כ במלחמה בעולם אמאי לא מהימנא במיגו דאי בעיא אמרה מת על מטתו אלא ש\"מ דלא שייך מיגו כיון דאינה חשודה לשקר ואר\"י כיון דדייקא כולי האי שהחזיקה מלחמה בעולם ואומרת כי מלחמה היא אם כן ודאי לא אמרה בדדמי ומטעמא דמיגו דאי בעיא אמרה שלום הוא בעולם יש לה להאמינה כיון דדייקא כולי האי אבל כי לא החזיקה אינה נאמנת לומר מת בעלה במלחמה מתוך שיכולה לומר מת על מטתו דאין זה מיגו כיון שידוע לעולם שהיא מלחמה יראה לומר מת על מטתו וידוע שהיא משקרת אבל בהחזיקה ודאי דייקא טפי ומיהו קשה לר\"י דאמר פ' כל הנשבעין (שבועות דף מה: ושם) גבי שכיר נשבע ונוטל לא שנו אלא ששכרו בעדים אבל שכרו שלא בעדים מתוך שיכול לומר לא שכרתיך מעולם יכול לומר שכרתי ונתתי לך שכרך ומה מגו הוא זה והלא אינו חשוד לשקר [אלא] דבעל הבית טרוד בפועליו הוא כדאמר התם ואמר בדדמי ומהאי טעמא מיבעי ליה הכא דלמא לא אתי מה לי לשקר ומרע לחזקה משום דאמרה בדדמי וי\"ל דשאני התם דנהי דטרוד בפועליו הוא מכל מקום נחשב קצת שקרן במה שטוען דרך ודאי שפרעו ולכך יש להאמינו במיגו דלא שכרתיך כיון שטוען שברור לו שפרעו ואינו תולה בשכחה וגם יש לו מיגו:"]]],[["דאי בעיא אמרה שלום בעולם או דלמא כיון דאיחזקה אמרה בדדמי ולא אתי מה לי לשקר ומרע חזקתיה","ת\"ש עישינו עלינו בית עישינו עלינו מערה הוא מת ואני נצלתי אינה נאמנת שאני התם דאמר לה כי היכי דלדידך איתרחיש ניסא לדידיה נמי איתרחיש ניסא","ת\"ש נפלו עלינו עובדי כוכבים נפלו עלינו ליסטים הוא מת ונצלתי נאמנת התם כדרב אידי דא\"ר אידי אשה כלי זיינה עליה","ההוא גברא דבשילהי הלוליה איתלי נורא בי גנני אמרה להו דביתהו חזו גבראי חזו גבראי אתו חזו גברא חרוכא דשדי ופסתא דידא דשדיא","סבר רב חייא בר אבין למימר היינו עישינו עלינו בית עישינו עלינו מערה אמר רבא מי דמי התם לא קאמרה חזו גבראי חזו גבראי ועוד גברא חרוכא דשדי ופסתא דידא דשדיא","ורב חייא בר אבין גברא חרוכא דשדיא אימא איניש אחרינא אתא לאצולי ואכילתיה נורא ופסתא דידא דשדיא נורא איתליא ואתיליד ביה מומא ומחמת כיסופא אזל וערק לעלמא","איבעיא להו עד אחד במלחמה מהו טעמא דעד אחד מהימן משום דמילתא דעבידא לאיגלויי הוא לא משקר ה\"נ לא משקר או דלמא טעמא דעד אחד משום דהיא גופא דייקא ומינסבא והכא [כיון דזימנין דסניא ליה] לא דייקא ומינסבא","אמר רמי בר חמא ת\"ש אמר רבי עקיבא כשירדתי לנהרדעא לעבר השנה מצאתי נחמיה איש בית דלי ואמר לי שמעתי שאין משיאין את האשה בארץ ישראל על פי עד אחד אלא רבי יהודה בן בבא ונמתי לו כן הדברים אמר לי אמור להם משמי אתם יודעים המדינה הזו משובשת בגייסות כך מקובלני מר\"ג הזקן שמשיאין האשה על פי עד אחד","מאי מדינה משובשת בגייסות לאו אע\"ג דמדינה זו משובשת כך מקובלני שמשיאין על פי עד אחד אלמא עד אחד מהימן","אמר רבא אי הכי מאי שנא מדינה זו כל מקום שיש גייסות מיבעי ליה אלא אמר רבא ה\"ק אתם יודעים שמדינה זו משובשת בגייסות ולא אפשר לי למשבק אינשי ביתי ומייתי קמי רבנן כך מקובלני מרבן גמליאל שמשיאין האשה ע\"פ עד אחד","ת\"ש מעשה בשני תלמידי חכמים שהיו באין עם אבא יוסי בן סימאי בספינה וטבעה והשיא רבי נשותיהן ע\"פ נשים והא מים כמלחמה דמו ונשים אפי' מאה כעד א' דמו וקתני השיא","ותסברא מים שאין להם סוף נינהו ומים שאין להם סוף אשתו אסורה אלא ה\"ד דאמרי אסקינהו קמן"],[[0,"דאי בעיא אמרה שלום בעולם","ומהימנא השתא נמי מהימנא או דלמא הכא ליכא למימר מה לה לשקר דאיהי גופא לא מכוונה לשקורי אלא כיון דאתחזק מלחמה אמרה בדדמי וסבורה היא שמת. ואי קשיא תיפשוט ליה ממתניתין דקתני שלום בעולם נאמנת דהא ודאי מת בעלי במלחמה קאמרה דאי על מטתו מאי אריא שלום בעולם אפי' מלחמה בעולם אמרן לעיל כי אמרה מת על מטתו מהימנא אלא ודאי מת במלחמה איצטריך לאשמועי' היינו החזיקה היא מלחמה בעולם תריץ מתניתין דאמרה מת סתמא ואשמועינן מתניתין דהואיל ושלום בעולם אע\"ג דלא אמרה על מטתו בהדיא מסתמא מת על מטתו קאמרה ובזמן שיש מלחמה בעולם מסתמא מת במלחמה קאמרה עד דאמרה מת על מטתו וכי קמיבעיא ליה לרבא כגון דיש שלום בעולם ואמרה איהי מת במלחמה:"],[1,"עישינו עלינו בית","הציתוהו באש ונתמלא עשן ואני ברחתי והוא נשאר שם ומת:"],[1,"אינה נאמנת","והא הכא דהחזיקה היא מלחמה זו וקתני אינה נאמנת ולא אמרי' מה לה לשקר דאי בעיא אמרה מת סתמא:"],[1,"שאני התם","דהכי קאמרה דכשנתמלא עשן ברחה ולא המתינה עד שתראהו מת ואי משום עשן כי היכי דלדידך איתרחיש ניסא כו' אבל לגבי מלחמה איכא למימר לא אמרה אי לא חזיתיה דהא אי בעיא לשקורי לא הוי מחזקה מלחמה בעולם:"],[2,"נפלו עלינו עובדי כוכבים כו'","והא הכא היא החזיקה וקתני נאמנת אלמא אמרינן מה לה לשקר:"],[2,"התם כדרב אידי בר אבין","כלומר הכא כיון דמלחמה קטנה היא דאיהי הוה בהדיה לא אמרה בדדמי אלא נטרה וחזיא ליה דמית דאשה לא מסתפיא מלסטים:"],[2,"כדר' אידי","במסכת ע\"ז בפ' אין מעמידין (עבודה זרה דף כה:):"],[3,"חזו גבראי","שהאש אוכלתו:"],[4,"היינו עישינו","דאמרן כי היכי דלדידך איתרחיש כו':"],[4,"פסתא דידא","מאיש אחר [הבא להצילו]:"],[5,"ואתיליד מומא","בבעלה:"],[6,"עד אחד במלחמה","מלחמה בעולם ובא עד אחד ואמר מת בעליך מי מהימן או לא:"],[6,"והכא לא דייקא","ותרוייהו אמרי בדדמי:"],[7,"כן הדברים","כאשר אתה אומר:"],[10,"מים כמלחמה","דאיכא למימר בדדמי:"],[11,"מים שאין להם סוף","מפרש בפ' בתרא (לקמן יבמות קכא.) כל שעומד ואין רואה מארבע רוחותיו:"],[11,"אשתו אסורה","ואע\"פ שיש עדים כשרים שטבע שמא צף מתחת המים ויצא:"]],[[0,"דאי בעיא אמרה שלום בעולם","וא\"ת אמאי לא קאמר מיגו שיכולה לומר מת על מטתו ונראה דהיכא שנהרג במלחמה אמרינן מתוך שיכולה לומר נהרג ולא במלחמה אבל נהרג אטו מת לא:"],[0,"או דלמא לא אתי מה לי לשקר ומרע לחזקה","אר\"י דלא דמי להא דמיבעיא בפ\"ק דבבא בתרא (דף ה: ושם) פרעתיך בתוך זמני אי מהימן במיגו דאי בעי למימר פרעתיך אחר זמני אי אתי מה לי לשקר ומרע לה לחזקה או לא דהתם מרע לה הכא לא מרע לה כיון דאמרה בדדמי ואי לא מרע התם לפי שאין הווה כלל שיהיה פורע בתוך זמנו אבל הכא מרע דיכול להיות אמת דמת במלחמה וכן הא דקאמר בפ' האומר בקידושין (דף סד.) אמר בשעת קידושין יש לי בנים ואין לי אחים ובשעת מיתה אמר אין לי בנים ויש לי אחים נאמן להתיר פירוש אי הוי איפכא ואין נאמן לאסור דברי רבי ור' נתן אומר כו' ומפרש התם טעמא דרבי משום דאתי מה לי לשקר ומרע לה לחזקה מיגו דאי בעי פטר לה בגיטא אבל הכא אמרה בדדמי ולכך לא מרע ולרבי נתן דאמר התם לא מרע התם דבשעת מיתה יש לו להיות נאמן יותר:"],[6,"טעמא דעד אחד נאמן משום דמילתא דעבידא לאיגלויי לא משקר הכא נמי לא משקר","ולא יאמר בדדמי כיון שהדבר יהיה גלוי או דלמא טעמא דנאמן משום דדייקא ומינסבא והכא לא דייקא כלומר לעולם לא יאמר עד אחד בדדמי כמו האשה עצמה ומכל מקום אין להאמינו דנהי דלא אמר בדדמי האשה לא דייקא כאן וסומכת עליו יותר ממה כשאומר מת על מטתו כיון דיש רגלים לדבר אבל אין לפרש או דלמא טעמא דעד אחד משום דדייקא ואפי' אמר בדדמי נאמן דהא אפילו דדייקא האשה למה לו להיות נאמן כיון דאמר בדדמי:"],[7,"אמר רבי עקיבא כשירדתי לנהרדעא לעבר שנה","בסוף מסכת ברכות (דף סג.) אמרי' דרבי עקיבא לא הניח כמותו בארץ ישראל ולכך היה יכול לעבר שנים בחוצה לארץ וכן צריך לומר בפ' שני דמגילה (דף יח:) גבי ר\"מ שהלך לעבר שנה בעסיא שלא הניח כמותו בארץ דעסיא חוצה לארץ היא כדאמרינן בחזקת הבתים (ב\"ב דף נו.) קיני קניזי וקדמוני עסיא ערדיסקיס אספמיא ומה שלא עיברו בארץ ישראל י\"ל דשום אונס היה וכן יש בירושלמי ירמיה עיבר בחוצה לארץ וכן יחזקאל וברוך בן נריה ומיהו קשיא לר\"י דבפ' זה בורר (סנהדרין דף כו. ושם) ר' חייא בן זרנוקי ור' שמעון בן יהוצדק כו' ושם היה רבי יוחנן גדול מהם מדריש לקיש היה קורא אותם רועי בקר וי\"ל דלעבר דקאמר התם לאו דוקא אלא חישוב בעלמא עשו אם השנה צריכה להתעבר דהא שנת שביעית היתה כדמוכח התם דקאמר כהן וחריש ובפ' קמא דסנהדרין (דף יב. ושם) אמר דאין מעברין שנה שביעית ושום אונס היה שלא חישבו בארץ ישראל כדפרישי' לעיל:"],[10,"והא מים דכמלחמה דמו","השתא סלקא דעתך שראו הנשים שטבעו אבל לא ראו שהעלום המים ולכך אמרו בדדמי:"]]],[["וחזינהו לאלתר וקאמרי סימנין דלאו עלייהו סמכינן אלא אסימנים","ההוא גברא דאפקיד שומשמי גבי חבריה אמר ליה הב לי שומשמי אמר ליה שקילתינהו והא כן וכן הויין ובחביתא רמיין א\"ל דידך שקלתינהו והני אחריני נינהו","סבר רב חסדא למימר היינו שני תלמידי חכמים ולא אמרינן הנך אזלו לעלמא והני אחריני נינהו","אמר ליה רבא מי דמי התם קאמרי סימנים הכא שומשמי מאי סימנא אית להו ודקאמר כן וכן הויין אימר חושבנא איתרמי","א\"ל מר קשישא בר רב חסדא לרב אשי ומי חיישינן שמא פינן והתנן מצא כלי וכתוב עליו קו\"ף קרבן מ\"ם מעשר דל\"ת דמוע טי\"ת טבל תי\"ו תרומה שבשעת הסכנה היו כותבין תי\"ו תחת תרומה","א\"ל רבינא לרב אשי ולא חיישינן שמא פינן אימא סיפא ר' יוסי אומר אפילו מצא חבית וכתוב עליה תרומה הרי אלו חולין שאני אומר אשתקד הוה מלא תרומה ופינה","אלא דכולי עלמא חיישינן שמא פינן והכא בהא קמיפלגי מר סבר אם איתא דפינהו מיכפר הוה כפר ואידך אימר אישתלויי אישתלי אי נמי לפנחיא שבקיה:","יצחק ריש גלותא בר אחתיה דרב ביבי הוה קאזיל מקורטבא לאספמיא ושכיב שלחו מהתם יצחק ריש גלותא בר אחתיה דרב ביבי הוה קאזיל מקורטבא לאספמיא ושכיב מי חיישינן לתרי יצחק או לא אביי אמר חיישינן רבא אמר לא חיישינן","אמר אביי מנא אמינא לה דההוא גיטא דאשתכח בנהרדעא וכתיב בצד קלוניא מתא אנא אנדרולינאי נהרדעא פטרית ותרכית ית פלונית אנתתי ושלחה אבוה דשמואל לקמיה דרבי יהודה נשיאה ושלח ליה תיבדק נהרדעא כולה","ורבא אמר אם איתא יבדק כל העולם מיבעי ליה אלא משום כבודו דאבוה דשמואל הוא דשלח הכי","אמר רבא מנא אמינא לה דהנהו תרי שטרי דנפקי במחוזא וכתיב בהו חבי בר ננאי וננאי בר חבי ואגבי בהו רבא בר אבוה זוזי והא חבי בר ננאי וננאי בר חבי במחוזא שכיחי טובא ואביי"],[[0,"וקאמרי סימנים","דאי לאו סימנים חיישינן דלמא אחרים נינהו לפי שהמים משנים צורת הפנים ואין ניכר כל כך:"],[1,"שקלתינהו","כבר החזרתים לך:"],[1,"אמר ליה","מפקיד:"],[1,"והא כן וכן הויין","כך וכך סאין היו:"],[1,"ובחביתא רמיין","ועדיין הן אצלך בחבית צא ובדוק בה תמצא כחשבוני:"],[1,"אמר ליה דידך שקלתינהו והני אחריני נינהו","ושלי הם:"],[2,"היינו שני ת\"ח","דתניא לעיל והשיא רבי את נשותיהן על פי נשים ותרצינן דאמרי סימני ולא אמרינן אחריני נינהו וסימנים הכי איתרמו:"],[3,"חושבנא","איכא למימר דמתרמי:"],[4,"ומי חיישינן שמא פינן","היכא דסימנא קמא איתא קמן:"],[4,"קרבן","הקדש:"],[4,"דימוע","חולין ותרומה שנתערבו ואין נאכל אלא לכהן:"],[4,"הסכנה","שגזרו שלא לקיים מצות אלמא לא אמרינן שמא פינו אותה תבואה שנתן בה בכתיבת אות זה ואלו אחרים:"],[5,"הרי אלו חולין","דאזלינן בתר רובא:"],[6,"מיכפר הוה כפר ליה","מקנח וגורר היה את האות:"],[6,"לפנחיא שבקה","להצלת פירות שבתוכה הניח בה אות זה ולא גיררה כדי שיבדלו בני אדם מהן:"],[6,"פנחיא","לשון שימור כאדם שתולה ממונו באדם חשוב כדי שלא יגזלוהו הימנו ודומה לו בהגוזל עצים (ב\"ק דף קג.) הלוקח שדה בשם ריש גלותא כו' ופנחיא בעלמא קבעינן:"],[7,"מי חיישינן לתרי יצחק","היכא דלא הוחזקו שני יוסף בן שמעון בעיר אחת:"],[7,"רבא אמר לא חיישינן","הואיל ולא הוחזקו אבל היכא דהוחזקו מודה כדאמר לקמן (יבמות דף קטז.):"],[8,"ההוא גיטא דאישתכח בנהרדעא כו'","האשה עומדת ותובעתו לפנינו:"],[8,"בצד קלוניא","שם עיר:"],[8,"תיבדק כל נהרדעא","אם יש שם אנדרולינאי אחר חוץ מבעל אשה זו:"],[9,"ואם איתא דחיישינן יבדק כל העולם מיבעי ליה","שמא אנדרולינאי אחר היה בנהרדעא והלך לו:"],[9,"משום כבודו","שלא להחזיקו כטועה ושואל דבר שאין צריך:"],[10,"שכיחי טובא","ואפ\"ה מגבינן כשמוציא שט\"ח על אחרים ולא חיישינן שמא אחר היה וכיון דלענין ממונא אף על גב דהוחזקו לא חיישינן לענין איסורא כי לא הוחזקו מיהא לא חיישינן:"]],[[0,"וחזינהו לאלתר","פי' לאלתר שהעלום מן המים אבל אם שהו במים הרבה אין לחוש דמיא מצמת צמתי כי ליתא למכה כדאמר בפ' בתרא (לקמן יבמות קכא.) אבל כששוהה אחר העלאה מיתפח תפח:"],[0,"וקאמרי סימנים","אבל על ידי טביעת עין אין להאמינם דאמרי בדדמי ובדבר מועט יאמרו שאלו בעליהן של אלו אבל מה שפי' בקונט' דמים משנים צורת הפנים אין נראה דהא אמרי' לקמן בפרק בתרא (שם) דמיא מצמת צמתי היכא דליכא מכה ואי סימנים לאו דאורייתא איירי הכא בסימנים מובהקים דהוו דאורייתא כדאמרינן באלו מציאות (ב\"מ דף כז: ושם) אי נמי מהני ע\"פ טביעות עינא. ר\"י:"],[0,"וקאמרי סימנים","פי' רבינו חננאל ש\"מ דאשה ועד אחד בספינה שטבעה ואמרו מת לא מהני וכל שכן עובד כוכבים אפי' מסיח לפי תומו ותימה היאך משיאין נשי בני אדם שטבעו על ידי טביעת עין בלא שום הכרת סימנים ושמא איירי כשנשחתה קצת צורת פניהם דאכלום כוורי ולא נשאר אלא מה ששנו במשנה בפ' בתרא (לקמן יבמות קכ.) וכן מפרש רבינו תם לקמן גבי אין מעידין אלא עד ג' ימים שכשנשחתה צורת פניו מיירי כמו שמפרש במשנה אבל אם צורת פניו שלימה שריא אפי' אחר כמה ימים:"],[1,"וכן הויין ובחביתא רמיין","אר\"י דאיירי בהפקיד אצלו בעדים ולכך היה נוטל בסימן מובהק דאי ליכא עדים מה מועיל הסימן יכול לומר לקוחין הן בידי וכן הא דאמר פרק איזהו נשך (ב\"מ דף ע. ושם) הני זוזי דיתמי היכי עבדינן להו חזינא איניש דאית ליה דהבא פריכא כו' ודוקא דהבא פריכא אבל כלים לא דלמא אפקדינהו גביה ויהיב סימנא ושקיל להו ומיהו קשה דאמר בהכותב (כתובות דף פה: ושם) גבי כסא דכספא דאפקידו בי חסא שכיב חסא ולא פקיד כו' עד ולא אמרן אלא דלא רגיל דעייל לביתיה אבל רגיל דעייל לביתיה אימר איניש אחרינא אפקיד ומיחזא חזא ומשמע דאיירי שלא הפקיד זה בעדים ואפ\"ה קאמר חדא דידענא ביה בחסא דלא אמיד ועוד הא קיהיב סימנא ומה מועיל הסימן כיון שלא הפקיד אצלו בעדים וי\"ל ששני הטעמים מצריך דלא אמיד וקא יהיב סימנא ואם תאמר אם כן בספ\"ק דכתובות (דף יג:) גבי ארוס וארוסתו דקאמר רב יוסף חדא דהא קא מודי ועוד האמר רב יהודה אמר שמואל הלכה כרבן גמליאל ואמר ליה אביי ובהא כי לא מודי מי מכשר רבן גמליאל ומאי קושיא דלמא רב יוסף מצריך שני הטעמים וי\"ל דאי טעמא דהא קא מודי לא מהני לחודיה לא מהני נמי מאי דהלכה כרבן גמליאל כיון דלא מכשר רבן גמליאל אלא ברוב כשרים אצלה והכא כולן פסולין לבד מארוס ולהכי פריך כי לא מודי פירוש כי לא מהני טעמא דמודי לחודיה מי מהני בהדיה טעמא דהלכה כר\"ג כו':"],[3,"אתרמויי אתרמי ליה","הכא משמע דמנין ומדה לא הוי סימן והא דאמר באלו מציאות (ב\"מ דף כג:) מדמשקל הוי סימן מדה ומנין נמי הוי סימן התם מיירי בענין שאין דרך בני אדם להצניע אבל הכא דרך בני אדם להצניע במדה זו:"],[4,"ומי חיישינן שמא פינן","תימה מאי קשיא היא מהאי דהא בממונא יש לחוש לעולם שמא פינן ולא נפיק ממונא מחזקתיה וי\"ל דנראה לו לדמות כיון דרגילות לפנותם ואפי' הכי לא חיישינן שמא פינן לענין ממונא נמי מפקינן ליה מחזקה כיון דלא חיישינן אע\"ג דרגילות הוא:"],[6,"אימור אישתלויי אישתלי","פי' רבינו חננאל בירושלמי דמעשר שני בפרק ב' רבי יונה ורבי יוסי הוו שותפי בגרבי דחמרא כד דמך רבי יונה אמר רבי מני בריה דרבי יונה לרבי יוסי כל גרבי דכתיב ביה רבי יונה דידיה הוא א\"ל אשתקד הוה דידיה והשתא דידי:"],[7,"יצחק ריש גלותא בר אחתיה כו'","איירי דלא הוחזקו תרי יצחק ובשכיחי שיירתא דאי לא שכיחי שיירתא ולא הוחזקו התנן בפ\"ק דבבא מציעא (דף כ. ושם) דכל מעשה בית דין הרי זה יחזיר ואי שכיחי שיירתא והוחזקו תרי יצחק א\"כ אמאי לא חייש רבא דהא לקמן גבי ענן בר חייא מחגרא חייש רבא דלמא בגמלא פרחא אזיל כיון שהוחזקו שהיה שם ענן אחר אלמא בלא הוחזקו איירי:"],[10,"אמר רבא מנא אמינא לה דהנהו תרי שטרי כו'","וא\"ת ואמאי לא מייתי רבא מרבה רביה דאמר בפ\"ק דב\"מ (דף יח: ושם) ובפרק כל הגט (גיטין דף כז.) גבי גיטא דאשתכח בבי דינא דרב הונא ואמר דיחזיר משום דלא הוחזקו אפי' בשיירות מצויות וי\"ל דאין הכי נמי אלא דניחא ליה לאיתויי ראיה מאמוראי קמאי:"],[10,"והא חבי בר ננאי כו'","וא\"ת היכי פשיט רבא איסורא מממונא דהכי פרכי' על רבה בפ\"ק דב\"מ (דף כ: ושם) גבי גיטא דאשתכח בי דינא דרב הונא ועוד הא בהוחזקו תרי יצחק מודה רבא כדפי' לעיל והכא בהוחזקו שני חבי בר ננאי וי\"ל דמדמה רבא ממונא היכא דהוחזקו לאיסורא דלא הוחזקו:"]]],[["למאי ניחוש לה אי לנפילה מזהר זהיר ביה אי לפקדון כיון דשמיה כשמיה לא מפקיד גביה","מאי אמרת דלמא מסר ליה אותיות נקנות במסירה","ההוא גיטא דאשתכח בסורא וכתיב ביה הכי בסורא מתא אנא ענן בר חייא נהרדעא פטרית ותרכית פלונית אנתתי ובדקו רבנן מסורא ועד נהרדעא ולא הוה ענן בר חייא אחרינא לבר מענן בר חייא מחגרא דהוה בנהרדעא ואתו סהדי ואמור דההוא יומא כי איכתב ההוא גיטא ענן בר חייא מחגרא גבן הוה","אמר אביי אף לדידי דאמינא חיישינן הכא לא חיישינן דהא קאמרי סהדי דבנהרדעא הוה מאי בעא בסורא","אמר רבא אף לדידי דלא חיישינן הכא חיישינן דלמא בגמלא פרחא אזל אי נמי בקפיצה אי נמי מילי מסר","כדאמר להו רב לספרי וכן אמר להו רב הונא לספרי כי איתנכו בשילי כתובו בשילי אע\"ג דמימסרן מילי בהיני וכי איתנכו בהיני כתובו בהיני אע\"ג דמימסרן מילי בשילי","מאי הוה עלייהו דשומשמי רב יימר אמר לא חיישינן רבינא אמר חיישינן והלכתא חיישינן:","קטטה בינו לבינה וכו': היכי דמי קטטה בינו לבינה אמר רב יהודה אמר שמואל באומרת לבעלה גרשיני כולהו נמי אמרו הכי אלא באומרת לבעלה גירשתני","וליהמנה מדרב המנונא דאמר רב המנונא אשה שאמרה לבעלה גירשתני נאמנת חזקה אין אשה מעיזה פניה בפני בעלה","באומרת גירשתני בפני פלוני ופלוני ושאילנא ואמרו לא היו דברים מעולם","מ\"ט דקטטה רב חנינא אמר משום דמשקרא רב שימי בר אשי אמר משום דאמרה בדדמי מאי בינייהו"],[[1,"דלמא מסר ליה","נתנו לו ולא קנו מידו בקנין ושמא יחזור בו ליכא למיחש להכי דאותיות כגון שטר נקנות במסירה בלא קנין ואין יכול לחזור בו:"],[2,"גבן הוה","אצלנו היה בנהרדעא וגיטא כתיב בסורא:"],[3,"הכא לא חיישינן","דהא איבדקא כל נהרדעא ולהאי ענן ליכא למיחש דהא אמרי סהדי כו' ואביי לא חייש לדלמא אזיל ליה לעלמא ובדיקה הוא דקמצריך באותו מקום:"],[4,"הכא חיישינן","הואיל והוחזק איש אחר בעירו כשמו:"],[4,"גמלא פרחא","הולך מהר כעוף פורח:"],[4,"בקפיצה","על ידי שם:"],[4,"מילי מסר","ואע\"פ שלא היה עמהם שמא מתחלה אמר להם בעירו כתבו גט לאשתי ואח\"כ הלכו העדים לסורא:"],[5,"שילי והיני","מקומות הן:"],[6,"ה\"ג מאי הוי עלייהו דשומשמי","מי חיישינן שמא פינן:"],[7,"אמרו הכי","בשעת כעסן:"],[10,"מ\"ט דקטטה","דתנן במתניתין כי אמרה מת בעלי לא מהימנא:"],[10,"דמשקרא","מרוב שנאה מתכוונת לאסור עצמה עליו:"],[10,"דאמרה בדדמי","כל מקום סכנה שראתה אינה נותנת דעתה לומר שמא לא מת ולא אנשא דהואיל וסניא ליה לא דייקא כולי האי:"]],[[0,"למאי ניחוש לה אי לנפילה כו'","והא דאמרי' בפ' גט פשוט (ב\"ב קעג.) אותיות נקנות במסירה אביי אמר צריך להביא ראיה פירוש דחיישינן לנפילה ופקדון וי\"ל דהתם איירי בנפילה דרבים אבל לנפילה דיחיד שיפול מיוסף בן שמעון וימצאנו יוסף בן שמעון אחר ודאי לא חיישינן והכי נמי מפליג בפ' גט פשוט (בבא בתרא דף קעב:) בין נפילה דיחיד לנפילה דרבים וא\"ת א\"כ היכי קאמר התם אהא דתנן במתני' (שם:) דשני יוסף בן שמעון מוציאים שטר חוב על אחרים ותנא דבריית' קאמר דאין מוציאין בפלוגתא דפליגי אביי ורבא בצריך להביא ראיה או אין צריך דמ\"ד אין מוציאין סבר לה כאביי דחייש לנפילה והא לנפילה דחד לא חייש אביי שיפול מיוסף בן שמעון זה וימצאנו אחר ויש לומר דלאו ממש בפלוגתא דאביי ורבא פליגי אלא כמו שאביי חשש לנפילה דרבים חושש אותו תנא אפי' לנפילה דיחיד וא\"ת והיכי מייתי התם ראיה אביי למילתיה דחיישינן להביא ראיה אלמא חיישינן לנפילה מההוא דאחד מן האחין שהיה שטר חוב יוצא מתחת ידו עליו להביא ראיה אלמא חיישינן לנפילה והא אחין הוי נפילה דחד ולא חייש אביי ויש לומר דמדמי אחים דשמטי מהדדי כדמפרש התם לנפילה דרבים ואי חיישינן לנפילה דרבים התם נמי יש לחוש:"],[1,"מאי אמרת דלמא מסר ליה אותיות נקנות במסירה","וא\"ת ורבא היכי מייתי מינה ראיה הא שפיר קאמר אביי וכי תימא דחייש לנפילה ופקדון האמרי' בפרק גט פשוט (בבא בתרא קעג:) אותיות נקנות במסירה אביי אמר צריך להביא ראיה רבא אמר אין צריך להביא ראיה אלמא אין צריך להביא ראיה אי חיישינן לנפילה ופקדון וי\"ל דרבא סבירא ליה דאין אותיות נקנות במסירה ולכן מייתי ראיה דאי חיישינן לתרי יצחק הכא נמי גבי חבי בר ננאי הוה לן למיחש דלמא מסר ליה והשתא חוזר בו והא דקאמר בפ' גט פשוט (ג\"ז שם) אותיות נקנות במסירה כו' ורבא אמר אין צריך לאו משום דרבא ס\"ל הכי אלא אליבא דר' מאיר דאית ליה הכי במתני' דהתם פליגי וא\"ת בריש כל הגט (גיטין כד:) אמר קטנה הוא דלא מצי מגרש הא גדולה מצי מגרש אמר רבא זאת אומרת שני יוסף בן שמעון הדרים בעיר אחת מוציאין שטר חוב על אחרים ומה ראיה הוא גט לשטר חוב בגט אין לחוש שמא תמסור לחברתה להתגרש בו שידוע שלא תוכל להתגרש ובשטר יש לחוש דלמא מסר ליה וי\"ל דהתם גרס רבה מדמהדר אביי בתריה והכא גרס רבא אי נמי אפי' גרס התם נמי רבא יש לפרש דהכי דייקינן התם דכי היכי דגדולה מצי מגרש ולא חיישינן שמא מסרה לצור על פי צלוחיתו ה\"נ לא חיישינן לשני יוסף בן שמעון שמא מסרם זה לזה לצור על פי צלוחיתו דלגבות החוב הם יודעין שאין המסירה מועלת דאין אותיות נקנות במסירה וה\"ר אלחנן תירץ דמדמי שטר לגט דכמו שהיה לנו לחוש בגט לנפילה כיון דלא מיזדהרא ביה הכי נמי היה לחוש בשטר דלמא מסר ליה ומדלא חיישינן בגט לנפילה הוא הדין דלא חיישי' דלמא מסר ליה:"],[1,"אותיות נקנות במסירה","הא אינן נקנות חיישינן דלמא מסר ליה ותימה מאי שנא בדברים שאין עשויין להשאיל ולהשכיר שהמוחזק בו נאמן לומר שהוא שלו כי אפילו ידוע שמאמינים זה לזה אין לחוש על פקדון אלא בדברים העשויים להשאיל ולהשכיר וגודרות שהדבר ידוע שלא לקחם א\"כ גבי אותיות נמי היה לנו להאמינו כשאומר שהם שלו וכי תימא כיון דאין אותיות נקנות במסירה דצריך שטר ואין לו שטר חיישינן דאינן שלו מ\"מ ליחוש שמא הקנה לו אגב קרקע דשטר נקנה אגב קרקע כדאמרינן בהמוכר את הספינה (ב\"ב דף עו: ושם) בשמעתא דאין אותיות נקנות ושמא קנין אגב קרקע לא שכיחא אי נמי לא מהני קנין אגב קרקע אלא בשטר של אותה קרקע כדאמרינן התם כיון שהחזיקו בקרקע נקנה השטר בכל מקום שהוא דשטר אפסרא דארעא הוא אבל שטר חוב בעלמא אין נקנה אגב קרקע דלא דמי למטלטלין אבל תימה לר\"י דלמה לא נימא שהם שלו ולא נתן לו חברו כלום ושמא כיון דשמיה כשמיה ואין מוכיח מתוך השטר שהוא שלו ולא עשה בו סימן יש לחוש שמא של חברו היה כי אי אפשר שלא יהא סימן לזה שאין בזה ושוב פר\"י דודאי הקלף יכול לעכב שלא יפסיד חזקתו אע\"פ שדרכו להפקיד גביה אבל החוב לא יוכל להוציא כל זמן שנוכל להסתפק דלמא הפקיד גביה והיינו נמי דאמר בגט פשוט (שם קעג.) גבי שאני הכא דאחין משמטי מהדדי ואין החוב למוחזק שלא יוכל לגבות החוב אבל הקלף נראה לר\"י שיוכל לעכב וכן חפץ אחר:"],[4,"הכא חיישינן דלמא בגמלא פרחא אזל","וא\"ת בפ\"ק דמכות (דף ה. ושם) אמר רבא (בר אבא) אתו בי תרי ואמרו בחד בשבא בצפרא הרג פלוני את הנפש בנהרדעא ואתו בי תרי ואמרו בפניא בחד בשבא עמנו הייתם בסורא חזינן אי מצפרא לפניא מצו אזלי אין נהרגין ואי לא מצו אזלי נהרגין פשיטא מהו דתימא ניחוש לגמלא פרחא קמ\"ל ואר\"ת דהכא כיון שמתכוין לקלקל אשת חברו אזל בגמלא פרחא אבל התם אם הלכו בגמלא פרחא היה מקלקלם יותר וה\"ר מנחם פי' דהתם אם איתא דאזלו בגמלא פרחא היה להן לטעון כן ומדלא אמרו הכי ש\"מ דשקר הם מעידים:"],[5,"אע\"ג דמימסרן לכו מילי בשילי","אר\"ת דשילי והיני שני מקומות הן וסמוכות זה לזה כדאמר במס' ביצה (דף כה:) רב הונא בשבתא דריגלא מכתפי ליה מהיני לשילי ולרבותא נקט הני מקומות שסמוכין זה לזה:"],[8,"וליהמנה מדרב המנונא","אמר ר\"י דהלכתא כרב המנונא מדפריך סתמא דגמרא מרב המנונא ובפ\"ב דכתובות (דף כב: ושם) גבי אמרה נשביתי דייק לאוקומי אמוראי דהתם כרב המנונא ובפ' התקבל (גיטין סד:) נמי פריך אדר\"י מדרב המנונא והא דבשילהי נדרים (דף צא. ושם) דחה רבה למילתיה דחויא בעלמא הוא ואפי' פליג הלכתא כרב המנונא כדפי' וא\"ת בסוף פרק הכותב (כתובות פט. ושם) גבי הוציאה גט דקאמר רב יוסף הב\"ע שאין שם עידי גירושין דמיגו דיכול לומר לא גרשתיה יכול לומר גרשתיה ונתתי לה כתובתה והיאך יכול לומר כן כיון שנאמנת לומר גירשתני ויש לומר דכשתובעת כתובה אינה נאמנת אלא דוקא לענין נישואין:"]]],[["איכא בינייהו דארגיל הוא קטטה","איבעיא להו עד אחד בקטטה מהו מ\"ט דעד אחד מהימן משום דמילתא דעבידא לאיגלויי לא משקר הכא נמי לא משקר או דלמא טעמא דעד אחד מהימן משום דהיא דייקא ומינסבא והכא כיון דאית ליה קטטה לא דייקא ומינסבא תיקו:","רבי יהודה אומר לעולם אינה וכו': תניא אמרו לו לרבי יהודה לדבריך פקחת תנשא שוטה לא תנשא אלא אחת זו ואחת זו תנשא","ההיא דאתיא לבי דינא דרבי יהודה אמרי לה ספדי בעלך קרעי מאניך סתרי מזייך אלפוה שיקרא אינהו כרבנן סבירא להו אמרי תעביד הכי כי היכי דלישריה:","\u0001מתני׳\u0002 בית הלל אומרים לא שמענו אלא בבאה מן הקציר ובאותה מדינה וכמעשה שהיה","אמרו להם בית שמאי אחת הבאה מן הקציר ואחת הבאה מן הזיתים ואחת הבאה מן הבציר ואחת הבאה ממדינה למדינה לא דברו חכמים בקציר אלא בהווה חזרו בית הלל להורות כבית שמאי:","\u0001גמ׳\u0002 תניא אמרו להם בית שמאי לבית הלל לדבריכם אין לי אלא קציר חטים קציר שעורים מנין ואין לי אלא קוצר בוצר מוסק גודר עודר מנין","אלא מעשה שהיה בקציר והוא הדין לכולהו הכא נמי מעשה שהיה באותה מדינה והוא הדין לכולהו","ובית הלל באותה מדינה דשכיחי אינשי מירתת ממדינה למדינה אחרת דלא שכיחי אינשי לא מירתת ובית שמאי הכא נמי שכיחי שיירתא","מאי מעשה שהיה דאמר רב יהודה אמר שמואל שילפי קציר חטין היו והלכו עשרה בני אדם לקצור חטין נשכו נחש לאחד מהן ומת ובאת אשתו והודיעה לבית דין ושלחו ומצאו כדבריה באותה שעה אמרו האשה שאמרה מת בעלי תנשא מת בעלי תתייבם","נימא רבי חנניא בן עקיבא ורבנן בפלוגתא דבית שמאי וב\"ה קמיפלגי דתניא לא ישא אדם מי חטאת ואפר חטאת ויעבירם בירדן ובספינה","ולא יעמוד בצד זה ויזרק לצד אחר ולא ישיטם על פני המים ולא ירכיבם לא על גבי בהמה ולא על גבי חברו אלא אם כן היו רגליו נוגעות בקרקע אבל מעבירם על הגשר אחד ירדן ואחד שאר נהרות רבי חנניא בן עקיבא אומר לא אמרו אלא ירדן ובספינה וכמעשה שהיה","לימא רבנן דאמרי כב\"ש ור' חנניא בן עקיבא דאמר כב\"ה","אמרי לך רבנן אנן דאמרינן אף כב\"ה עד כאן לא קאמר בית הלל התם אלא משום דמירתת במקום קרוב מירתת במקום רחוק לא מירתת הכא מה לי ירדן מה לי שאר נהרות","רבי חנניא בן עקיבא אמר לך אנא דאמרי אף לב\"ש עד כאן לא קאמרי ב\"ש התם אלא משום דאיהי דייקא ומינסבא מה לי מקום קרוב מה לי מקום רחוק הכא משום מעשה שהיה בירדן ובספינה דהוה מעשה גזור רבנן בשאר נהרות דלא הוה מעשה לא גזור רבנן","מאי מעשה שהיה דאמר רב יהודה אמר רב מעשה באדם שהיה מעביר מי חטאת ואפר חטאת בירדן ובספינה ונמצא כזית מן המת תחוב בקרקעית של ספינה באותה שעה אמרו לא ישא אדם מי חטאת ואפר חטאת ויעבירם בירדן ובספינה:","\u0001מתני׳\u0002 בית שמאי אומרים תנשא ותטול כתובתה בית הלל אומרים תנשא ולא תטול כתובתה אמרו להם בית שמאי התרתם ערוה חמורה ולא נתיר ממון הקל אמרו להם בית הלל מצינו"],[[1,"עד אחד בקטטה","קטטה בינו לבינה והלך למדינת הים ובא עד אחד ואמר מת מי מהימן אי לא:"],[3,"אלפוה שיקרא","בתמיה. אם כרבי יהודה סבירא להו דאינה נאמנת אא\"כ בוכה למה הורוה לבכות:"],[4,"מתני' אלא בבאה מן הקציר","שכך היה המעשה כדאמרי' לקמן ולא התירו חכמים אלא דוגמתו שיהא הדבר קרוב לנו ומירתתא ולא משקרא אבל ממדינת הים אינה נאמנת:"],[5,"אלא בהווה","מעשה שהיה כך היה והוא הדין לכל מקומות:"],[6,"גמ' לדבריכם","שאתם אומרים כעין המעשה שהיה בעינן:"],[6,"אין לי אלא קציר חטים","דמעשה שהיה בקציר חטים היה כדלקמן:"],[6,"גודר","תמרים:"],[6,"עודר","מלקט תאנים:"],[7,"הכא נמי","לענין מדינת הים:"],[9,"שילפי","סוף קציר חטים. שילפי לשון שלף איש (רות ד׳:ז׳) שכבר היה הקציר משתלף ועובר:"],[10,"ויעבירם בירדן ובספינה","משום מעשה שהיה בירדן ובספינה ונטמאו כדאמרינן לקמן:"],[11,"ויזרקם בצד זה","של נהר דהיינו נמי דומיא דספינה שפורחין באויר על פני המים:"],[11,"לא ירכיבם על גבי בהמה","בתוך המים דהיינו נמי דומיא דספינה שהאדם הנושאו יושב במקומו וספינתו נוטלתו ומוליכתו וספינה פעמים שהיא גוששת ונוגעת בקרקע:"],[11,"אלא אם כן רגליו","של עליון נוגעות במים בקרקע:"],[11,"על הגשר","דכארעא סמיכתא היא והאדם המעבירו הולך כל שעה ברגליו ואינו דומה לספינה:"],[15,"תחוב בקרקעיתה","והאהיל הכלי של מי חטאת עליהן ונטמאו:"],[16,"מתני' תנשא ותטול כתובתה","על פיה:"]],[[0,"איכא בינייהו דארגיל בה קטטה","פי' למ\"ד משום דמשקרא היתה יראה כ\"כ לשקר כיון דרחמא ליה ולמ\"ד דאמרה בדדמי כיון דיש קטטה בדבר מועט אמרה בדדמי ול\"ג דארגילא היא כי לעולם יש לחוש שתשקר כיון ששונאתו וא\"ת ואמאי לא תשקר והלא היא משקרת שאמרה גירשתני בפני פלוני ופלוני ושיילינן להו ואמרו להד\"מ וי\"ל דזה לא היתה עושה שתשקר לומר מת בעלי ואם יבא תצא מזה ומזה וכל הדרכים האלו בה:"],[5,"לא דברו בקציר אלא בהווה","ירושלמי למה קציר א\"ר מנא דאונסא דשכיח שאני החמה קודחת בראשו של אדם בשעת הקציר הדא הא דכתיב ויגדל הילד ויהי היום ויצא אל אביו אל הקוצרים ויאמר אל אביו ראשי ראשי ורבנן אמרי דריחשא שכיח:"],[9,"באותה שעה אמרו האשה שאמרה מת בעלי כו'","משום דחזו דאיכא עיגונא טפי אם לא היו מאמינים אותה וא\"ת ואמאי לא מהימנינן לה במגו שהיתה יכולה לומר גירשתני למאן דאמר בפ' שני דכתובות (דף כג. ושם) דאיתמר דרב המנונא אפי' שלא בפניו ויש לומר דאין זה מגו שאם תאמינה לומר מת היתה אומרת כמה פעמים בדדמי ולכך אין להאמינה אי לאו משום דחייש לעיגונא ועוד י\"ל דההוא אמורא דאמר שלא בפניו [נמי] אינה מעיזה היינו דוקא אמתני' דהתם שאומרת אשת איש הייתי וגרושה אני שיש להאמינה מטעם דהפה שאסר הוא הפה שהתיר ואע\"ג דאיכא איסור דאשת איש כיון דשלא בפניו אינה מעיזה אבל בעלמא לא היתה נאמנת:"]]],[["שאין האחין נכנסין לנחלה על פיה","אמרו להם בית שמאי והלא מספר כתובה נלמוד שהוא כותב לה שאם תנשאי לאחר תטלי מה שכתוב ליכי וחזרו בית הלל להורות כדברי ב\"ש:","\u0001גמ׳\u0002 אמר רב חסדא נתייבמה יבמה נכנס לנחלה על פיה הם דרשו מדרש כתובה אנו לא נדרוש מדרש תורה","(דברים כה, ו) יקום על שם אחיו אמר רחמנא והרי קם","אמר רב נחמן באת לבית דין ואמרה מת בעלי התירוני להנשא מתירין אותה להנשא ונותנין לה כתובתה תנו לי כתובתי אף להנשא אין מתירין אותה מאי טעמא אדעתא דכתובה אתאי","איבעיא להו התירוני להנשא ותנו לי כתובתי מהו כיון דאמרה כתובתה אדעתא דכתובה אתאי או דלמא כל מילי דאית ליה לאיניש אמר להו לבי דינא ואת\"ל כל מילי דאית ליה לאיניש אמר תנו לי כתובתי והתירוני להנשא מהו","הכא ודאי אדעתא דכתובה אתאי או דלמא הואיל דלא ידעה במאי משתריא תיקו:","\u0001מתני׳\u0002 הכל נאמנין להעידה חוץ מחמותה ובת חמותה וצרתה ויבמתה ובת בעלה","מה בין גט למיתה שהכתב מוכיח:","\u0001גמ׳\u0002 איבעיא להו בת חמיה מהו טעמא דבת חמותה משום דאיכא אימא דסניא לה היא נמי סניא לה והכא ליכא אימא דסניא לה","או דלמא טעמא דבת חמותה דאמרה קאכלה לגירסנא דאימא הכא נמי קאמרה אכלה לגירסנא דבי נשאי","תא שמע הכל נאמנין להעידה חוץ מחמש נשים ואם איתא שית הויין דלמא טעמא דבת חמותה דאמרה קאכלה לגירסנא דבי נשאי לא שנא בת חמותה ולא שנא בת חמיה","והאנן תנן חוץ משבע נשים ההיא ר' יהודה היא דתנן רבי יהודה מוסיף אף אשת אב והכלה","אמרו לו אשת אב הרי היא בכלל בת הבעל כלה הרי בכלל חמותה","ור' יהודה בשלמא חמותה סניא לה לכלה דאמרה קאכלה לגירסני אלא כלה מאי טעמא סניא לחמותה בשלמא בת הבעל דסניא לאשת האב דאמרה קאכלה לגירסני דאם אלא אשת האב מאי טעמא סניא לבת הבעל","אלא מאי מוסיף תרתי אלא כלה מ\"ט סניא לחמותה דמגלה לבנה כל דעבדה אשת אב נמי סניא לבת הבעל דמגלה לאביה כל דעבדה","ורבנן (משלי כז, יט) כמים הפנים לפנים כן לב האדם לאדם ורבי יהודה ההיא בדברי תורה כתיב","אמר רב אחא בר עויא בעי במערבא חמותה הבאה לאחר מיכן מהו מי מסקה אדעתה דמית בעל ונפלה קמי יבם וסניא לה או לא"],[[0,"שאין האחין נכנסין לנחלתו של בעלה על פיה","דרחמנא אמר ע\"פ שנים עדים (דברים יט) ולגבי נשואין דידה הוא דאקילו רבנן משום עיגונא:"],[1,"כשתנשאי לאחר","והרי נשאת:"],[2,"גמ' לנחלה","זכה בנחלת אחיו כדאמר בפרק החולץ (לעיל יבמות מ.) הכונס את יבמתו זכה בנכסי אחיו:"],[2,"ואנן לא נדרוש מדרש תורה","בתמיה:"],[4,"אדעתא דכתובה אתאי","ובאפוקי ממונא סהדי בעינן:"],[5,"כל מילי דאיניש כו'","ועיקר אדעתא דנשואין אתאי ושרינן לה וכיון דשרינן לה שקלה נמי כתובה דמספר כתובה נלמוד:"],[6,"דלא ידעה במאי משתריא","וכיון דהזכירה נשואין גליא דעתא דלמשרייה אתאי והא דאמרה ברישא תנו לי כתובתי שמא כסבורה היא שזו התרתה:"],[7,"מתני' ויבמתה","אשת יבמה. וטעמא דכולהו מפני ששונאות אותה ומתכוונות לקלקלה. חמותה שונאתה שאומרת בלבה זו תאכל כל יגיעי ועמלי. וכן בת חמותה אומרת זו תירש כל עמל אבי ואמי ואני אדחה. ויבמתה יראה שמא סופה להיות צרתה. ובת בעלה זו באה במקום אמי אוכלת כל עמלה:"],[8,"מה בין גט למיתה","דאמר בפ\"ב דגיטין (דף כג:) אף הנשים שאין נאמנות לומר מת בעלה נאמנות להביא גטה ממדינת הים ואע\"ג דעלייהו סמכינן דצריכות לומר בפני נכתב ובפני נחתם:"],[8,"שהכתב מוכיח","וסמכינן עיקר אכתבא:"],[9,"גמ' בת חמיה","שאין בת חמותה מהו:"],[10,"לגירסנא","יגיע אמי שהביאה לאבי מבית אביה:"],[10,"והכא נמי","אע\"ג דהיא לא אכלה לגירסנא דאמה שהרי אין בעלה של זו אחיה מן האם ובני אמה נוטלין מה שהביאה אמה דתנן (כתובות דף נב:) בנין דיכרין די יהווין ליכי מינאי אינון ירתון כסף כתובתיך יתר על חולקהון דעם אחוהון אפ\"ה הא קא אכלה לגירסנא דבי נשאי וסניא לה:"],[13,"אשת אב הרי היא בכלל בת הבעל","כיון דזו אינה מעידה לזו ממילא נפקא דאשת אב נמי אינה מעידה לבת בעלה הלכך אין זו תוספת ולא הוצרכו להזכירו:"],[14,"ור' יהודה","אמר לך ודאי הוצרכו דבשלמא חמותה סניא לכלה מפני שסופה לירשנה ואמרה קאכלה לגירסנאי כו' הלכך איצטריך למימנינהו:"],[15,"אלא מאי מוסיף כו'","כיון דאין לה על מה לשנאות חמותה אמאי קא מוסיף לה ר' יהודה לומר אינה נאמנת. ומשני טעמא דרבי יהודה כלה סניא לה לחמותה משום דמגלה לברה מילי עלה:"],[16,"ורבנן כמים הפנים לפנים","קרא כתיב כמים הפנים לפנים כמים הללו שאדם צופה בהן ורואה בהם פנים כפניו אם הוא שוחק הם שוחקות ואם הוא עוקם הם עקומות כן לב האדם לאדם האחר אם הוא אוהב את זה גם זה הוא אוהבו ואם הוא שונא את זה גם הוא שונאו הלכך לא בעי לאוספינהו דמטעמא קמא שמעינן דאין נאמנות דכיון דחמותה סניא לכלה משום דקאכלה לגירסנא כלה נמי סניא לחמותה דסניא לה וכיון דבת הבעל סניא לאשת אב אשת אב נמי סניא לה לדידה:"],[16,"בדברי תורה כתיב","לפי פנים ולב שאתה נותן לתורה לבך עומד לך להעמיד גירסא אם יגעת בה תמצא אם לא יגעת לא תמצא: ל\"א אם רבו מסביר לו פנים הוא מחכים ואם לאו אינו מחכים מרבו:"],[17,"חמותה הבאה לאחר מכאן מהו","אם יבמה היא ולא אם בעלה ושמא סופה להיות חמותה מי נאמנת לומר מת בעליך והתייבמי לבני או חלצי והנשאי לאחר:"],[17,"מי מסקה","הך אם יבם אדעתה דלמא מיית בעל ונפלה קמי יבם ברה וקאכלה לגירסנא ומתכוונת לקלקלה מעכשיו כדי שלא תתייבם עוד לבנה או לא. ואע\"ג דצרה הבאה לאחר מיכן פשיט לן כדאמר במתני' ויבמתה דהיינו משום צרות העתידות לבא התם הוא דצערא דגופה הוא ומסקא אדעתה טפי אבל שנאת חמותה לכלה מחמת ממון הוא ולא מסקא אדעתה כולי האי או לא:"]],[[0,"שאין האחין נכנסין לנחלה על פיה","והא דאמרינן בפרק המפקיד (ב\"מ לח: ושם) בשמעו בו שמת כולי עלמא לא פליגי דמורידין קרוב לנכסי שבוי מצי לאוקומי כששמעו בו בשני עדים דאי בעד אחד מיירי הא אשה דהכא כעד אחד דמיא אפ\"ה אין האחין נכנסין לנחלה על פיה וא\"ת מ\"מ תקשי אדמסיק התם כי פליגי בשלא שמעו בו שמת פירוש בשני עדים אלא בעד אחד דאי לא שמעו בו כלל פשיטא דאין מורידין וא\"כ היכי קאמר שמואל התם מורידין וי\"ל דהכא מיירי לירד ולמכור והתם מיירי לאכול כדמשמע התם ולפי זה יש לפרש ששמעו בו שמת היינו בעד אחד ולאכול דאי בשני עדים אפי' לירד ולמכור וא\"ת וא\"כ היכי פליגי בלא שמעו בו שמת דמורידין וי\"ל דלא שמעו בו שמת בעד אחד אלא ע\"י קול בעלמא כדאמרי' בשילהי דמס' גיטין (דף פט.) כששמע פלוני מפלוני ופלוני מפלוני והלכו להם למדינת הים ומיהו בפ' בתרא דכתובות (דף קז.) איכא טובא כששמעו בו שמת ואיירי בשני עדים ומצינו למימר נמי הכא שיצא לדעת והתם אין מורידין קרוב לנכסיו כדאמר בפרק המפקיד (ב\"מ דף לח: ושם):"],[1,"וחזרו ב\"ה להורות כב\"ש","והא דאמר בפ' האשה שנפלו (כתובות פא. ושם) גבי ולימא אח אני יורש אשתו איני קובר ואי משום כתובה לא ניתנה כתובה לגבות מחיים ודחי מאן שמעת ליה דאית ליה מדרש כתובה בית שמאי הא אית להו שטר העומד לגבות כגבוי דמי ומאי קושיא דלמא אפילו ב\"ה נינהו דהודו להו וי\"ל דב\"ה לא חזרו בהם מטעם מדרש כתובה אלא מטעם קל וחומר א\"נ התם דחויא בעלמא הוא דמוקי כבית שמאי ולמסקנא דהדר אתי שפיר כבית הלל וי\"מ דלא דרשי ב\"ה מדרש כתובה כל כך כמו ב\"ש ולא יתכן דאי מסתבר לדורשו בכתובות כמו הכא אמאי לא דרשי ליה ב\"ה ואי לא מסתבר מנא ליה דדרשי אפי' ב\"ש:"],[1,"בית הלל כו'","ותימה וכי נחלקו ב\"ה על הלל רבן שדורש מדרש כתובה בפ' המקבל (ב\"מ קד.) דקאמר התם הלל היה דורש לשון הדיוט אנשי אלכסנדריא היו מקדשים נשותיהם ובשעת כניסתן לחופה באו אחרים וחוטפין אותן כו' ומצא כתוב בהן לכשתנשאי לי תיהוי לי לאנתו ואומר ר\"י דלא דמי דהתם ודאי הדבר ידוע ומוכיח שהיו כותבין בשביל שחוטפין להן אבל הכא כשתנשאי לאחר היינו על ידי עדות ברורה ולא ע\"י דבר אחר וב\"ש סברי דמ\"מ תנשאי לאחר קרינא ביה:"],[7,"חוץ מחמותה כו' ויבמתה","פי' שרוצה לקלקלה לפי שיראה שימות בעלה או יבמה ויהיו צרות זו לזו ואפי' לשמואל דאמר לעיל בסוף האשה רבה (יבמות דף צו.) דאינה כאשת איש א\"כ כשיבא היבם תהא מותרת לחזור מ\"מ מתכוונת היא לביישה ועוד שמא יחלוץ לה בעלה ותנשא לאחר אז אסורה לזה ולזה ולא תפול עוד לפני בעלה לייבם וא\"ת והלא כשמעידה על יבמה שמת שמא ייבמנה בעלה ותהא צרתה לאלתר וי\"ל שאינה חוששת בכך כיון שיודעת שבעלה חי ויחזור ולבסוף יקלקלנה:"],[12,"והא תנן חוץ מז' נשים","אמתני' פריך דלא קתני אלא חמש:"]]],[["ת\"ש אמרה מת בעלי ואח\"כ מת חמי תנשא ותטול כתובה וחמותה אסורה מ\"ט חמותה אסורה לאו משום דאמרינן לא בעלה מיית ולא חמיה מיית והא דקאמרה הכי לקלקולא לחמותה הוא דקמיכוונא","סברה לבתר שעתא לא תיתי תצטערן","דלמא שאני התם דרגיש לה צערא:","\u0001מתני׳\u0002 עד אומר מת ונשאת ובא אחד ואמר לא מת הרי זו לא תצא עד אומר מת ושנים אומרים לא מת אע\"פ שנשאת תצא שנים אומרים מת ועד אומר לא מת אע\"פ שלא נשאת תנשא:","\u0001גמ׳\u0002 טעמא דנשאת הא לא נשאת לא תנשא והאמר עולא כ\"מ שהאמינה תורה עד אחד הרי כאן שנים ואין דבריו של אחד במקום שנים","הכי קאמר עד אחד אומר מת והתירוה להנשא ובא אחד ואמר לא מת לא תצא מהיתירה הראשון:","עד אומר מת: פשיטא דאין דבריו של אחד במקום שנים לא צריכא בפסולי עדות וכדר' נחמיה","דתניא רבי נחמיה אומר כל מקום שהאמינה תורה עד אחד הלך אחר רוב דעות ועשו שתי נשים באיש אחד כשני אנשים באיש אחד","ואיבעית אימא כל היכא דאתא עד אחד כשר מעיקרא אפי' מאה נשים כעד אחד דמיין אלא כגון דאתאי אשה מעיקרא","ותרצה לדרבי נחמיה הכי רבי נחמיה אומר כל מקום שהאמינה תורה עד אחד הלך אחר רוב דעות ועשו שתי נשים באשה אחת כשני אנשים באיש אחד אבל שתי נשים באיש אחד כפלגא ופלגא דמי:","שנים אומרים מת וכו': מאי קמשמע לן בפסולי עדות וכדר' נחמיה דאזיל בתר רוב דעות היינו הך","מהו דתימא כי אזלינן בתר רוב דעות לחומרא אבל לקולא לא קמ\"ל:","\u0001מתני׳\u0002 אחת אומרת מת ואחת אומרת לא מת זו שאומרת מת תנשא ותטול כתובתה וזו שאומרת לא מת לא תנשא ולא תטול כתובתה","אחת אומרת מת ואחת אומרת נהרג ר\"מ אומר הואיל ומכחישות זו את זו הרי אלו לא ינשאו ר' יהודה ור' שמעון אומרים הואיל וזו וזו מודות שאין קיים ינשאו עד אומר מת ועד אומר לא מת"],[[0,"אמרה מת בעלי ואח\"כ מת חמי","רבותא אשמועינן דאע\"ג דאמרה ברישא מת בעלי ונמצא שאין זו חמותה והרי היא לה כנכרית אפי' הכי לא מהימנא אדאמרה מת חמי וחמותה אסורה מ\"ט הא לאו חמותה היא אלא משום דאמרי הך לאו בעלה מיית ועדיין זו חמותה ולא חמיה מיית וזו כלתה מתכוונה לקלקלה ואע\"ג דהשתא הרי בנה של זו במדינת הים ואין אמו אצלו לדבר לו על כלתה דברים רעים אפ\"ה מסקא כלה אדעתה לקלקלה מעכשיו כי היכי דלבתר שעתא כשישוב בעלי ובעלה תדחה לחרפות ולא תיתי לטרדן וה\"ה לחמותה הבאה לאחר מיכן דהא נמי אחר מיכן הוא:"],[2,"דרגש לה צערא","כבר הרגישה כלה זו בצער שמצערתה חמותה ושנאה ישנה היא אבל בחמותה לאחר מיכן שמעולם לא היתה חמותה לא תפשוט:"],[4,"הרי כאן שנים","הרי הוא חשוב כשנים:"],[5,"לא תצא מהיתירה הראשון","ודוקא התירוה קודם שיבא עד שני המכחישו אבל בא קודם שיתירוה מודה עולא דלא סמכינן אקמא דאכתי לא אחשביניה כתרי:"],[6,"עד אומר מת","ובאו עדים ואמרו לא מת פשיטא דמודי עולא דלגבי תרי חשיב כחד ובטל ולא אמרינן תרי ותרי נינהו:"],[6,"בפסולי עדות","ואע\"ג דשנים שאמרו לא מת נשים היו הרי עד ראשון בטל אצלן ואיצטריך לאשמועינן כי האי גוונא:"],[7,"כל מקום שהאמינה תורה עד אחד","אין שם תורת עדות כי היכי דחד חשיב פסולי עדות נמי חשיבי הלכך הלך אחר רוב דעות ואין עליך לבדוק אם כשרים אם פסולים:"],[7,"ועשו שתי נשים באיש אחד","שתי נשים שהכחישו עד אחד ואמרו לא מת כשני אנשים באיש אחד שהראשון בטל ואפילו ניסת תצא:"],[8,"כל היכא דאתא ע\"א כשר מעיקרא","והתירוה על פיו אפילו מאה נשים כעד אחד דמיין וכי היכי דעד אחד בטל דאמרינן ראשון הרי הוא כשנים ואין דבריו של אחרון במקום שנים מאה נשים נמי בטלים לגביה ובכי האי גוונא לא אשמועינן מתני' דתצא אלא מתני' דקתני אף על פי שנשאת תצא כגון דאתאי אשה מעיקרא ונשאת על פיה ואשמועינן מתני' דתצא ע\"פ שתי נשים הבאות אחרי כן ולא מוקמינן קמייתא במקום עד כשר ואע\"ג דאחשבינה כתרי למישרייה על פומה:"],[9,"כפלגא ופלגא","בעד אחד אומר מת והתירוה לינשא ובא אחר ואמר לא מת דאמר במתני' לא תצא מהיתירה הראשון:"],[11,"לחומרא","כגון מציעתא דקתני תצא:"],[12,"מתני' אחת אומרת מת","שתי נשים צרות הבאות ממדינת הים אחת אומרת מת בעלי וצרתה אומרת לא מת:"],[13,"הואיל והן מכחישות כו'","ובגמ' פריך לפלוג נמי ר' מאיר ברישא דזו שאומרת מת לא תנשא:"],[13,"הואיל וזו וזו מודות כו'","הא אחת מודה והאחת אינה מודה לא ינשאו שתיהן אלא האחת:"]],[[0,"לאו משום דאמרינן לא בעלה מת ולא חמיה מת","ומ\"מ מתירים אותה לינשא כיון דחזיא דחמותה אסורה אף היא לא מקלקלה נפשה וא\"ת מה יש לחוש מכל מקום נתיר לחמותה כשנשאת הכלה דהשתא לא תיתי ותצטער שהרי לא תחזור להיות כלתה וי\"ל דמכל מקום יש לחוש פן תנשא חמותה קודם שתנשא הכלה והיא מתכוונת לכך ונמצאת שאסרה את חמותה ולכך לא רצו חכמים להתירה אפילו כשתנשא הכלה:"],[2,"דלמא שאני התם דרגש לה צערה","ה\"ה דה\"מ למימר שאני התם דלא מסקא אדעתה שמא ימות בעלה אבל כלה יכולה לידע שיבא בעלה וממללא לברה מילי עילויה אי נמי משוי אותם הגמרא לפי שאין דבר ברור כל כך שיחזור בעלה ממדינת הים:"],[3,"עד אחד אומר מת ושנים אומרים לא מת תצא","אבל אחד ואחד בזה אחר זה לא תצא אבל לא תנשא שנים אומרים מת ואחד אומר לא מת אע\"פ שלא נשאת תנשא אחד ואחד בבת אחת לא תנשא ובזה אחר זה מותרת להנשא מה\"ת אי לאו משום לזות שפתים:"],[4,"הא לא נשאת לא תנשא והא אמר כו'","קשה לר\"י דבפרק ב' דכתובות (דף כב: ושם) גבי מילתיה דרבי יוחנן דשנים אומרים מת כו' משמע דמילתיה דעולא איירי בדיעבד אבל לכתחלה מודה דלא תנשא משום דרב אסי הסר ממך עקשות פה וי\"ל דהכא דייק הכי טעמא דנשאת משום הכי לא תצא הא לא נשאת לא תנשא ואם נשאת תצא דהכי משמע דוקא נשאת לא תצא הא לא נשאת לא תנשא ואם נשאת תצא משום הכי פריך מדעולא וא\"ת והיכי משני התירוה לינשא ובא אחר ואמר לא מת לא תצא מהיתירה הראשון משמע ותנשא לכתחלה ויש לומר דודאי לכתחלה לא תנשא ולא תצא מהיתירה הראשון היינו לענין דאם נשאת לא תצא וסיפא דע\"א אומר מת ואחד אומר לא מת הרי זו לא תנשא איירי בבת אחת ואפי' נשאת תצא וא\"ת ור' יוחנן בפ\"ב דכתובות (ג\"ז שם) מאי קמ\"ל מתני' היא וי\"ל דר' יוחנן אתא לאשמועינן דלכתחלה לא תנשא משום דרב אסי ור\"י אומר דפריך משום דמשמע ליה הא לא נשאת לא תנשא מדאורייתא מדקאמר תצא ולא קתני הולד ממזר ועוד מדקתני סיפא עד אחד אומר מת ועד אחד אומר לא מת לא תנשא משמע דהיינו בבת אחת ואי מדרבנן אפילו בזה אחר זה נמי וא\"ת דהכא משמע דעולא לא איירי אלא בזה אחר זה דהיינו בהתירוה לינשא ובפ' מי שקינא (סוטה לא: ושם) משמע דאיירי עולא בכל ענין בין בבת אחת בין בזה אחר זה דתנן התם עד אחד אומר נטמאת ועד אחד אומר לא נטמאת היתה שותה כו' דדייק בגמ' טעמא דהאי מכחיש אבל לא מכחיש עד אחד נאמן מה\"מ כו' ופריך כיון דמדאורייתא עד אחד מהימן אידך היכי מצי להכחיש ליה והאמר עולא כל מקום שהאמינה תורה עד אחד הרי כאן שנים אלא אמר עולא תני לא היתה שותה ור' חייא אמר היתה שותה ולרבי חייא קשה מתני' לעולא לא קשיא כאן בבת אחת כאן בזה אחר זה משמע דעולא נמי איירי בבת אחת כמו בזה אחר זה ולכך צריך להגיה ולא משני כדמשני רבי חייא ומיהו י\"ל דעולא לא איירי אלא בזה אחר זה אלא שנראה לו דוחק להעמיד המשנה בבת אחת משום דמשמע ליה דאיירי נמי בזה אחר זה ועוד אמר ר\"י דאפילו איירי עולא בכל ענין ה\"מ התם דמדאורייתא עד אחד מהימן בסוטה כדנפקא ליה התם מועד אין בה אבל הכא גבי אשה דלא מהימן אלא מדרבנן לא חשיב כשנים אלא בזה אחר זה ואע\"ג דיש חלוק בין דאורייתא בין דרבנן מייתי מדעולא דנראה לו דחשיב כשנים בזה אחר זה בדרבנן כמו בדאורייתא בבת אחת:"],[6,"לא צריכא בפסולי עדות","והא דאמר בפרק מי שקינא (סוטה לא: ושם) תנן עד אחד אומר נטמאת ושנים אומרים לא נטמאת היתה שותה הא חד וחד אינה שותה תיובתא דרבי חייא וליטעמיך אימא סיפא שנים אומרים נטמאת ואחד אומר לא נטמאת כו' אלא בפסולי עדות כו' ואמאי לא מוקי רישא בפסולי עדות מטעם דפריך הכא פשיטא וי\"ל דניחא ליה לאקשויי מסיפא כיון דמשכח לה אי נמי דרישא דהתם כיון דעד אחד נאמן מן התורה הוי כתרי ותרי ואי מכחשי אהדדי לא היתה שותה אבל הכא תקנתא דרבנן היא:"],[13,"ומכחישות זו את זו הרי אלו לא ינשאו","דודאי אחת מהן שקרנית ואולי שתיהם אומרות שקר כי לא ידעו אמתת הדברים ואיכא מאן דאמר בגמ' דר\"מ פליג ברישא ואיכא נמי הכחשה ולא תנשא והא דלא נקט פלוגתייהו ברישא משום דהוה אמינא דבסיפא מודה:"],[13,"[הואיל] וזו וזו מודות שאין קיים","אבל המכחשת ואומרת קיים אותה לא תנשא דרישא מיתוקמא כוותייהו:"]]],[["אשה אומרת מת ואשה אומרת לא מת הרי זו לא תנשא:","\u0001גמ׳\u0002 טעמא דאמרה לא מת הא אישתיקא תנשא הא אין צרה מעידה לחברתה","לא מת איצטריכא ליה סד\"א הא מיית והא דקאמרה לא מת לקלקולה לצרה היא דקמיכוונא (שופטים טז, ל) ותמות נפשה עם פלשתים קאמרה קמשמע לן:","אחת אומרת מת כו': וליפלוג רבי מאיר ברישא אמר רבי אלעזר במחלוקת שנויה ורבי יהודה ורבי שמעון היא ורבי יוחנן אמר אפילו תימא רבי מאיר בהא אפילו רבי מאיר מודה דכל לא מת בעדות אשה לאו הכחשה היא","תנן עד אומר מת ועד אומר לא מת אשה אומרת מת ואשה אומרת לא מת הרי זו לא תנשא בשלמא לרבי אלעזר סתמא כר' מאיר אלא לרבי יוחנן קשיא קשיא:","\u0001מתני׳\u0002 האשה שהלכה היא ובעלה למדינת הים ובאה ואמרה מת בעלי תנשא ותטול כתובתה וצרתה אסורה היתה בת ישראל לכהן תאכל בתרומה דברי רבי טרפון","רבי עקיבא אומר אין זו דרך מוציאתו מידי עבירה עד שתהא אסורה לינשא ואסורה מלאכול בתרומה","אמרה מת לי בעלי ואחר כך מת חמי תנשא ותטול כתובתה וחמותה אסורה היתה בת ישראל לכהן תאכל בתרומה דברי רבי טרפון רבי עקיבא אומר אין זו דרך מוציאה מידי עבירה עד שתהא אסורה לינשא ואסורה מלאכול בתרומה:","\u0001גמ׳\u0002 וצריכא דאי איתמר הך קמייתא בהא קא\"ר טרפון משום דצערא דגופה אבל חמותה דצערא מילי דעלמא אימא מודי ליה לרבי עקיבא","ואי איתמר בהא בהא קאמר רבי עקיבא אבל בהך אימא מודה ליה לרבי טרפון צריכא","א\"ר יהודה אמר שמואל הלכה כרבי טרפון אמר אביי אף אנן נמי תנינא ניתן לי בן במדינת הים מת בני ואח\"כ בעלי נאמנת בעלי ואחר כך בני אינה נאמנת","וחוששין לדבריה וחולצת ולא מתייבמת לדבריה הוא דחוששין הא לדברי צרה אין חוששין ש\"מ:"],[[0,"אשה אמרה מת ואשה אמרה לא מת הרי זו לא תנשא","הואיל ובאת שניה קודם שיתירוה על פי ראשונה ואפי' שניה זו צרתה אוסרתה. ובגמ' מוקמינא לה להאי סתמא כר' מאיר דאמר צרתה נמי מכחשא לה:"],[2,"גמ' לא מת איצטריכא ליה","דאע\"ג דאי שתקא פשיטא לן דלא תנשא בעדות חברתה איצטריך לאשמועינן היכא דמכחשה לה נמי לא תנשא דמהו דתימא כיון דאתיא ומערערא גליא דעתא דלצעורי לצרה קאתיא ולעגנה שלא תנשא ותמות נפשה עם פלשתים קעבדא הלכך אפי' היא תשתרי קמשמע לן:"],[3,"במחלוקת שנויה","במחלוקת אחרונה אף ראשונה שנויה דלא תימא סתמא דברי הכל היא אלא ר' יהודה ור\"ש היא דאמרי צרה לא מכחשה:"],[3,"לא מת לאו הכחשה היא","דרבנן הימנוה לקמא:"],[4,"ואשה אומרת לא מת","אפי' צרתה במשמע:"],[5,"מתני' היתה","צרתה בת ישראל לכהן:"],[5,"תאכל בתרומה","בחזקת שבעלה קיים ואינה חוששת לעדות צרתה הואיל ואינה נאמנת להשיאה אינה נאמנת לפוסלה:"],[7,"וחמותה אסורה","שאין כלה מעידה לחמותה ואע\"ג דאמרה ברישא מת בעלי דפקע לה צד כלות והויא נכרית אפילו הכי לא מהימנא כדאמר לעיל (יבמות דף קיז:) הא לאו בעלה מיית ולא חמוה מיית כו':"],[7,"היתה","חמותה בת ישראל לכהן כו':"],[8,"גמ' צערא דגופה","תשמיש מונעת לה מבעלה הא ודאי משקרא כדי לקלקלה שתנשא ואפי' שהיא נשאת תמות נפשה עם פלשתים:"],[8,"מודי ליה לר\"ע","דלא מחזקינן לה בשקרנית כולי האי ונהי דלהשיאה לא מהימנא אבל לחומרא לענין תרומה תיחוש:"],[10,"ניתן לי בן","אשה שהלכה עם בעלה למדינת הים וכשיצתה מכאן לא היה לה בן ועומדת בחזקת ייבום ובאת ואמרה ניתן לי בן במדינת הים ומת בני ואח\"כ מת בעלי דלא מפקא נפשה מחזקה קמייתא שעדיין היא צריכה לייבם נאמנת ומותרת להתייבם:"],[10,"אינה נאמנת","להנשא לשוק בלא חליצה דכי הימנוה רבנן לאשה אבעלה הימנוה דדייקא ומנסבא אבל לאפוקי נפשה מיבם לא הימנוה דזימנין דסניא ליה:"],[11,"וחיישינן לדבריה","דאפקה נפשה מחזקה ואם בא יבם לייבמה לא שבקינן לה וחולצת:"],[11,"לדבריה","מיעוטא משמע:"]],[[1,"טעמא דאמרה לא מת הא אישתיקא כו'","וא\"ת מאי דייק והא לא מת איצטריך ליה לאשמועינן שאע\"פ שמכחשה צרתה תנשא וליכא למימר דהא פשיטא כיון שאין צרה מעידה לחברתה דהא איצטריך טובא דפליג ר\"מ עלה ולר' יוחנן נמי אשמעי' דר\"מ מודה בהא ואר\"י דדייק מדקאמר זאת שאומרת לא מת לא תנשא דלא הוי ליה למיתני אלא אחת אומרת מת ואחת אומרת לא מת תנשא ואנא ידענא דאאומרת מת קאי דההיא דלא מת שויתה לנפשה חתיכה דאיסורא:"],[2,"סד\"א הא מימת מיית","יש לנו לומר שמת יותר ממה שהיתה שותקת דאי שתקה ודאי בעיא לקלקולה אבל כשאומרת לא מת מחמת שנאה אומרת כן שהיא רוצה שתתעגן דאי לא ידעה דמית היתה שותקת לקלקלה וא\"ת מכל מקום היכי סלקא דעתא למישרייה כיון דשויתה לנפשה חתיכה דאיסורא וי\"ל דאפי' מודה ונתנה אמתלא לדבריה אינה נאמנת ולא דמיא (כתובות כב.) לאשה שאמרה אשת איש אני וחזרה ואמרה פנויה אני דנאמנת כשנתנה אמתלא לדבריה:"],[3,"דכל לא מת בעדות אשה לאו הכחשה היא","נראה לרבינו יואל דה\"ק דכל לא מת אפי' בבת אחת ובצרות דוקא לא הויא הכחשה דהימנוה רבנן וצרתה שאומרת שוב לא מת אין להאמינה אבל בעד ועד בבת אחת אמר במתני' בסיפא לא תנשא ואמרינן לעיל עד אומר מת והתירוה לינשא הא לא התירוה לינשא אלא באו שניהם בבת אחת לא תנשא ועל כן יש לפרש דבצרות דוקא איירי וטעמא דלא מת דלא הוי הכחשה שמכחשתה צרתה ואין לנו להאמינה ולכך תנשא האחרת אבל זו אומרת מת וזו אומרת נהרג הויא ודאי הכחשה כיון דשתיהן באות להתיר עצמן ואינן מכוונות דבריהן דאמרי בדדמי ואין יודעות אמתות הדברים והשתא דייק שפיר מסיפא דקתני אשה אומרת מת ואשה אומרת לא מת הרי זו לא תנשא ואפי' צרות משמע כדפי' בקונטרס דאי לאו הכי מה משמיענו היינו עד ועד דעלמא וקאמר בשלמא לר\"א סתמא כר\"מ ופליגא ארישא דאמר תנשא אפי' בבת אחת אלא לרבי יוחנן קשה כו' אבל אם היינו מפרשים דר' יוחנן איירי דכל לא מת היינו בזה אחר זה א\"כ מאי מקשה מסיפא לר' יוחנן וגם לכולי עלמא יש להעמידה לר\"א דאיירי בבת אחת אלא ש\"מ דכולה שמעתא איירי בבת אחת ודוקא בצרה דכל לא מת בעדות אשה לאו דוקא אלא בצרה כדפי':"],[4,"אשה אומרת מת ואשה אומרת לא מת","אי אמרי' דאשה אחת מכחשת את העד היכא שבאין יחד ואם אמת הוא כן הוה ליה למיתני הכי דהוי ליה רבותא טפי ובירושלמי מצא ר' יהודה דאין הכי נמי ומייתי ברייתא הכי:"],[4,"אלא לר' יוחנן קשיא","דאשה אומרת אפי' בצרתה משמע וא\"ת מנלן דלמא בנשים בעלמא איירי דהכי תנן בפ' מי שקינא (סוטה דף לא:) עד אחד אומר נטמאת ועד אחד אומר לא נטמאת אשה אומרת נטמאת כו' והתם לא קאי אצרות ואפ\"ה קתני אשה וי\"ל דהתם ליכא למיטעי דבצרות איירי:"],[5,"בת ישראל לכהן תאכל בתרומה","מספקא לר\"י אי דוקא בתרומה דרבנן אי נמי בתרומה דאורייתא דאוקמה אחזקה דדייקא ומינסבא ועל צרתה אין להאמינה ואוקמה אחזקת אשת איש מידי דהוה אשני שבילין מיהו איכא הכא חדא דעביד איסורא ממ\"נ ובכי האי גוונא לא ילפינן מסוטה כדמשמע בריש מסכת נדה (דף ב: ושם) ובמס' חולין (דף ט: ושם):"],[10,"אף אנן נמי תנינא","הא דלא מייתי רישא דהאשה שהלכה היא ובעלה שמא משום דסיפא מיירי בהתר יבמה לשוק כמילתיה דרבי טרפון דייק מיניה:"],[11,"לדבריה הוא דחוששין","תימה לר\"י דהיכי מייתי סייעתא לר\"ט מהך דקתני לדבריה חוששין ולא לדברי צרתה דלמא הכא ר\"ע מודה כיון שאם לא ניחוש לדברי צרה ליכא עבירה כלל אבל בדרבי עקיבא אילו לא ניחוש לדברי צרה ואכלה בתרומה איכא עבירה בודאי ואמר ר\"י דלא דייק אלא מייתור וחוששין לדבריה:"]]],[["\u0001מתני׳\u0002 קידש אחת מחמש נשים ואין יודע אי זו קידש כל אחת אומרת אותי קידש נותן גט לכל אחת ואחת ומניח כתובה ביניהן ומסתלק דברי רבי טרפון","רבי עקיבא אומר אין זו דרך מוציא מידי עבירה עד שיתן גט וכתובה לכל אחת ואחת גזל אחד מחמשה ואין יודע מאיזה גזל כל אחד אומר אותי גזל מניח גזילה ביניהן ומסתלק דברי רבי טרפון רבי עקיבא אומר אין זו דרך מוציא מידי עבירה עד שישלם לכל אחד ואחד:","\u0001גמ׳\u0002 קידש קתני בעל לא קתני גזל קתני לקח לא קתני מני מתני' לא תנא קמא ולא רבי שמעון בן אלעזר","דתניא רשב\"א אומר לא נחלקו רבי טרפון ורבי עקיבא על שקידש אחת מחמש נשים ואינו יודע איזו קידש שמניח כתובה ביניהן ומסתלק על מה נחלקו על שבעל רבי טרפון אומר מניח כתובה ביניהן ומסתלק רבי עקיבא אומר עד שישלם לכל אחת ואחת","לא נחלקו רבי טרפון ורבי עקיבא על שלקח מקח מחמשה בני אדם ואין יודע מאיזה מהן לקח שמניח דמי מקח ביניהן ומסתלק לא נחלקו אלא שגזל מחמשה שאמר ר' טרפון מניח גזילה ביניהם ומסתלק ורבי עקיבא אומר עד שישלם גזילה לכל אחד ואחד","מדקאמר רבי שמעון בן אלעזר בקידש ולקח לא פליגי מכלל דתנא קמא סבר פליגי מני","אי תנא קמא ליתני קידש ולקח אי רבי שמעון בן אלעזר ליתני בעל וגזל","לעולם רבי שמעון בן אלעזר ומאי קידש קידש בביאה תנא קידש להודיעך כחו דרבי עקיבא","דאע\"ג דאיסורא דרבנן עבד קניס תנא גזל להודיעך כחו דרבי טרפון דאע\"ג דאיסורא דאורייתא עבד לא קניס:","\u0001מתני׳\u0002 האשה שהלכה היא ובעלה למדינת הים ובנה עמהם ובאת ואמרה מת בעלי ואחר כך מת בני נאמנת מת בני ואחר כך מת בעלי אינה נאמנת וחוששין לדבריה וחולצת ולא מתייבמת","ניתן לי בן במדינת הים ואמרה מת בני ואחר כך מת בעלי נאמנת מת בעלי ואחר כך מת בני אינה נאמנת וחוששין לדבריה וחולצת ולא מתייבמת","ניתן לי יבם במדינת הים אמרה מת בעלי ואחר כך מת יבמי יבמי ואחר כך בעלי נאמנת","הלכה היא ובעלה ויבמה למדינת הים אמרה מת בעלי ואחר כך יבמי יבמי ואחר כך בעלי אינה נאמנת שאין האשה נאמנת לומר מת יבמי שתנשא ולא מתה אחותה שתכנס לביתו ואין האיש נאמן לומר מת אחי שייבם אשתו ולא מתה אשתו שישא אחותה:","\u0001גמ׳\u0002 בעא מיניה רבא מרב נחמן המזכה גט לאשתו במקום יבם מהו כיון דסניא ליה זכות הוא לה וזכין לאדם שלא בפניו או דלמא כיון דזימנין דרחמא ליה חוב הוא לה ואין חבין לאדם שלא בפניו","אמר ליה תנינא וחוששין לדבריה וחולצת ולא מתייבמת","אמר ליה רבינא לרבא המזכה גט לאשתו במקום קטטה מהו כיון דאית לה קטטה בהדיה זכות הוא לה או דלמא ניחא דגופא עדיף לה תא שמע דאמר ריש לקיש טב למיתב טן דו מלמיתב ארמלו","אביי אמר דשומשמנא גברא כורסיה בי חרתא רמו לה רב פפא אמר דנפצא גברא תיקרי בסיפי בבא ותיתיב","רב אשי אומר דקולסא גברא לא בעיא טלפחי לקידרא תנא וכולן מזנות ותולות בבעליהן:","\u0001הדרן עלך האשה שלום\u0002"],[[0,"מתני' נותן גט לכל אחת","אם אינו חפץ לישא את כולן:"],[2,"גמ' קידש קתני","דאיכא למימר התם הוא דקאמר ר' טרפון דמניחה ביניהם דלא עשה מעשה אבל בעל לא קתני דליפלוג ר' טרפון דכיון דעשה בה מעשה וגינה אותה בקדושי ביאה צריך להוציא עצמו מידי עבירה וליתן לכולן:"],[2,"גזל קתני","דהואיל ואיסורא עבד קניס ליה ר\"ע אבל לקח מקח מחמשה ואין יודע אי זהו לא קתני דלקנסיה ר\"ע:"],[5,"מכלל דת\"ק פליג עליה","ואמר בקידש ולקח פליגי דליכא איסור כולי האי אבל בבעל וגזל אפי' ר' טרפון מודה:"],[7,"ומאי קידש קידש בביאה","דגינה אותה ואפ\"ה פטר רבי טרפון ולא תימא ליתני גזל ולא איבעי קידש דתרוייהו איצטריך תנא קידש בביאה להודיעך כחו דר\"ע דאיסורא דרבנן הוא קעביד דרב מנגיד אמאן דמקדש בביא' ואין כאן איסורא דאוריי' אפ\"ה קניס:"],[9,"מתני' מת בעלי ואח\"כ מת בני","והריני מותרת לשוק נאמנת שהרי בחזקת לשוק יצאה והפה שאסר הוא הפה שהתיר:"],[9,"אינה נאמנת","להתייבם לו וחוששין לדבריה דאפקה נפשה מחזקה ולא מישתריא בלא חליצה דשויתה לנפשה חתיכה דאיסורא מעלמא:"],[10,"ניתן לי בן","והיא הלכה בלא בן ובחזקת עתידה לייבם:"],[11,"ניתן לי יבם","שהלכה חמותי במדינת הים והיא הלכה בחזקת שאין לה יבם:"],[12,"מת בעלי ואח\"כ מת יבמי כו'","דתרוייהו קשריא נפשה לשוק נאמנת ומותרת לשוק בחזקתה הראשונה דהפה שאסר הוא הפה שהתיר:"],[13,"גמ' המזכה גט לאשתו","שעשה שליח לקבלה וזיכה לה ע\"י שליח שתתגרש מעכשיו:"],[13,"במקום יבם","שיש לו אח ונתכוון לפוטרה הימנו דשלא במקום יבם והוא בא לגרשה פשיטא לן דלא מיגרשה עד שתגיע לידה דאין חבין לאדם שלא בפניו אלא הכא מי אמרי' זכות הוא לה כו':"],[14,"וחוששין לדבריה","מדקתני בתרוייהו חוששין ביצאה בחזקת [היתר] לשוק ובאה והחזיקה עצמה ליבם וקתני חוששין ולא אמרינן אוקמה אחזקה ותנשא דהא ודאי משקרא משום דרחמא ליה קאמרה אלמא לא מחזקינן לה באהבה ומדקתני נמי בחזקת יוצאה ליבם ובאה והחזיקה עצמה לשוק כגון ניתן לי בן ומת בעלי ואח\"כ בני וקתני חוששין ולא תתייבם ולא אמרי' ודאי משקרא ומשום דסניא ליה קאמרה אלמא זימנין דלא סניא ליה. אלמא מספקא לן וגבי מזכה גט נמי מספקא לן אי רחמא ליה וחוב הוא לה אי סניא ליה וזכות הוא לה ותחלוץ ולא תתייבם:"],[15,"טן דו","גופים שנים כל דהו בעל:"],[16,"דשומשמנא גברא","גוץ כנמלה:"],[16,"כורסיה בי חרתא רמיא","מחזקת עצמה כנשואה ונותנת כסאה אצל חשובות חורות הארץ:"],[16,"דנפצא","אומנתו מאוסה מנפץ צמר:"],[17,"דקולסא גברא","שמץ פסול משפחה:"],[17,"טלפחי","עדשים שהוא מאכל קל ואין חסרון כיס כל כך אינה שואלת ממנו אך יקרא שמו עליה:"]],[[14,"אמר ליה תנינא וחוששין לדבריה","וא\"ת האי דאינה מתייבמת משום דשויתה לנפשה חתיכה דאיסור' וי\"ל דדייק מדקתני חולצת דמשמע שכן הדין מדלא קאמר מבקשים לחלוץ אי נמי משמע דחולצת אפילו נתנה אמתלא לדבריה:"],[17,"דקולסא","מוכר קלסי כרוב:"]]],[["מתני׳ \u0001האשה\u0002 שהלך בעלה וצרתה למדינת הים ובאו ואמרו לה מת בעליך לא תנשא ולא תתייבם עד שתדע שמא מעוברת היא צרתה","היתה לה חמות אינה חוששת יצתה מליאה חוששת רבי יהושע אומר אינה חוששת:","\u0001גמ׳\u0002 מאי היא צרתה הא קמ\"ל להא צרה הוא דחיישינן אבל לצרה אחריתי לא חיישינן:","לא תנשא ולא תתייבם וכו': בשלמא יבומי לא דדלמא מיעברא וקפגעה באשת אח דאורייתא אלא לא תנשא אמאי הלך אחר רוב נשים ורוב נשים מתעברות ויולדות","לימא ר\"מ היא דחייש למיעוטא","אפילו תימא רבנן כי אזלי רבנן בתר רובא רובא דאיתיה קמן כגון תשע חנויות וסנהדרי אבל רובא דליתיה קמן לא אזלי רבנן בתר רובא","והרי קטן וקטנה דרובא דליתא קמן היא ואזלי רבנן בתר רובא דתניא קטן וקטנה לא חולצין ולא מייבמין דברי ר' מאיר אמרו לו לר' מאיר יפה אמרת שאין חולצין איש כתיב בפרשה ומקשינן אשה לאיש אלא מה טעם אין מייבמין","אמר להם קטן שמא ימצא סריס קטנה שמא תמצא אילונית ונמצאו פוגעים בערוה ורבנן סברי זיל בתר רובא דקטנים ורוב קטנים לאו סריסי נינהו זיל בתר רוב קטנות ורוב קטנות לאו אילונית נינהו אלא מחוורתא מתניתין רבי מאיר היא","במאי אוקימתא כר' מאיר אימא סיפא היתה לה חמות אינה חוששת אמאי הלך אחר רוב נשים ורוב נשים מתעברות ויולדות מיעוט מפילות וכל היולדות מחצה זכרים ומחצה נקבות סמוך מיעוטא דמפילות למחצה נקבות והוו ליה זכרים מיעוטא וליחוש","דלמא כיון דאיחזקה לשוק לא חייש רישא דאיחזק לייבום תייבם","אמר רב נחמן אמר רבה בר אבוה רישא דאיסור כרת חששו סיפא דאיסור לאו לא חששו","אמר רבא מכדי הא דאורייתא והא דאורייתא מה לי איסור כרת מה לי איסור לאו אלא אמר רבא"],[[0,"מתני' האשה שהלך בעלה כו' לא תנשא","הואיל ובלא בנים יצא בעלה:"],[0,"ולא תתייבם","שמא ילדה צרתה. ובגמ' פריך אמאי לא תנשא תחלוץ ותנשא ממה נפשך:"],[0,"היא צרתה","מפרש בגמ':"],[1,"היתה לה חמות","במדינת הים וכשיצאה לא היה לה בן ואין יבם לזו אינה חוששת שמא ניתן לה יבם. אע\"ג דחיישינן לעיל שמא ילדה צרה התם הוא דכל מה דילדה צרה בין זכר בין נקבה מפיק לה להא מיבם אבל חמות דאי נמי ילדה לא זקיק לה להך אא\"כ ילדה זכר וכולי האי לא חיישינן שמא ילדה וזכר היה:"],[1,"יצתה מליאה","יצתה חמותה מעוברת:"],[1,"חוששת","שמא זכר היה:"],[1,"אינה חוששת","דאיכא למימר שמא הפילה ואת\"ל לא הפילה שמא נקבה היתה:"],[2,"גמ' לצרה אחריתי","אם באו עדים שאין צרתה מעוברת אינה חוששת שמא אשה אחרת נשא ומותרת ליבם:"],[4,"רבי מאיר חייש למיעוטא","בפ' הכל שוחטין (חולין ו.) גבי כותים שגזר על כל כותים משום אותם שמצאו דמות יונה בהר גריזים והשתחוו לה:"],[5,"תשע חנויות","דתניא (שם דף צה.) ובנמצא הלך אחר הרוב דכיון דחנויות לפנינו הן ואנו רואין שרובן מוכרות בשר שחוטה:"],[5,"וסנהדרי","י\"ב מזכין וי\"א מחייבין דקי\"ל דזכאי (סנהדרין דף מ.) דהואיל ורוב מזכין וקמן נינהו:"],[6,"דליתא קמן","כגון הכא דניזיל בתר רוב נשים שבעולם:"],[8,"אימא סיפא היתה לה חמות אינה חוששת","אמאי נהי נמי דזכרים מיעוטא כדמפרש ואזיל מיהו הלך אחר רוב נשים וכיון דרוב נשים מתעברות ליכא למימר בזכרים מיעוטא דמיעוטא אלא חד מיעוטא דרוב נשים מתעברות ויולדות ומיעוט כו':"],[8,"","ה\"ג והוו להו זכרים מיעוטא וליחוש:"],[10,"דאיסור כרת חששו","שמא נתעברה צרתה:"],[10,"לא חששו","שמא נתעברה חמותה ואוקמה אחזקה:"],[11,"מה לי איסור לאו","מי לא בעינן למיחש לספק איסור לאו כי היכי דחיישינן לספק איסור כרת הא מידי דספיקא לאו הרחקה דרבנן היא בדבר המותר דנימא לכרת עביד הרחקה ללאו לא עביד הרחקה בדבר המותר דהכא שמא איסורא דאורייתא ממש קעביד:"]],[[0,"מתני' האשה. יצתה מליאה חוששת","אע\"ג דאיכא חזקה דמסייע לרובא דנקבות ומפילות חוששת דאיתרע ליה חזקה שיצתה מליאה:"],[2,"אבל לצרה אחריתי לא חיישינן","מהיתור לשון דהיא צרתה דייק דהיא צרתה משמע ליה שהצרה עצמה מעוברת ולא משמע צרה אחרת אם נשא:"],[3,"אמאי הלך אחר רוב נשים כו'","וא\"ת דתנן לעיל באידך פירקין (יבמות דף קיח:) ניתן לי בן במד\"ה מת בעלי ואח\"כ מת בני למה אינה נאמנת במגו שהיתה יכולה לומר עדיין בני קיים וסמכינן ארוב נשים שמתעברות ויולדות וי\"ל דמיירי כגון שיש שני עדים שאומרים ששניהם מתו דהשתא אינה יכולה לומר עדיין בני קיים:"],[4,"רבי מאיר היא","וא\"ת אמאי לא מוקי לה נמי כרבנן וכי אזלי רבנן בתר רובא היינו בדלא תלי במעשה אבל דתלי במעשה לא אזלי' בתר רובא דכה\"ג משני בפ\"ג דבכורות (דף כ. ושם) וי\"ל דהכא כרבה דלית ליה ההוא שינויא א\"נ אין חשוב תלי במעשה אלא ממילא הוא בא שאדם נזקק לאשתו:"],[5,"כגון ט' חנויות וסנהדרין כו'","תימה היכי פליג ר\"מ והכתיב אחרי רבים להטות ועוד היכא אשכחן דפליגי ר\"מ ורבנן בט' חנויות הא לא אשכחן דפליגי אלא בקטן וקטנה ושמא לאו דוקא נקט ט' חנויות וסנהדרין אלא כגון מיעוטא דפליגי בחולין (דף יא.) ובמס' ע\"ז (דף מ:). [עי' תוספות בכורות יט: ד\"ה ברובא]:"],[7,"מחוורתא מתני' ר\"מ היא","דחייש למיעוטא מיהו אנן לא קי\"ל כר\"מ אף על גב דאתי סתמא דמתני' כר\"מ בהא דחייש למיעוטא [אפ\"ה] לא קי\"ל כוותיה מדאמר בפ\"ק דחולין (דף יא: ושם) ור' מאיר היכי אכיל בישראל משמע דאנן שפיר אכלינן וקשה דבפרק הלוקח בהמה (בכורות כד. ושם) פסיק ר' יוחנן כרשב\"ג דאמר בלוקח בהמה מניקה מן העובד כוכבים דפטורה מן הבכורה כשבנה כרוך אחריה משום דלא מרחמא אא\"כ ילדה אבל מטעמא דחלב לא מיפטרא אע\"ג דרוב בהמות אין חולבות אא\"כ יולדות אלמא חיישינן למיעוט אע\"ג דליכא חזקה בהדי מיעוטא דאי אמרת אוקי בהמה בחזקת שלא ילדה אדרבה העמד הולד בחזקת שאין קדוש בבכורה שהיה חולין במעי אמו ויש לומר דר' יוחנן לא פסיק כוותיה אלא בהא דלא מרחמא אלא אם כן ילדה ונ\"מ להיכא שראינוה שהיה לה חלב קודם לידה דההיא לא מיפטרא מטעם חלב ואפשר דרשב\"ג סבר חלב פוטר והשתא אתי שפיר דמשכחת רבן שמעון בן גמליאל דלא חייש למיעוטא בריש פרק כל הצלמים (ע\"ז דף מ: ושם) דלא גזר שאר מקומות אטו אותו מקום כדגזר רבי מאיר התם וקאמר נמי רשב\"ג כל מצות שהחזיקו בם כותים כו' אלמא לא חייש למיעוט ורבי יוחנן נמי אכיל משחיטת כותים ומיהו מכותים אין להביא ראיה דמשום דאחד רשע אין להחזיק כולם רשעים אבל בפ' עשרה יוחסין (קדושין דף פ. ושם) גבי שני דברים אין בהן דעת לישאל ועשאום כו' משמע דסבר רבי יוחנן נמי כרבנן דרבי מאיר והא דאמר רבי יוחנן בס\"פ אין מעמידין (ע\"ז דף לט:) למעוטי מורייס וגבינות בית אונייקי וסתמא כרבי מאיר התם הוי סתם ואח\"כ מחלוקת בריש כל הצלמים (עבודה זרה דף מ:) והא דארשב\"ג כל ששהה ל' יום באדם אינו נפל הא לא שהה ספיקא הוי אפילו נפל מן הגג או אכלו ארי בפרק רבי אליעזר דמילה (שבת דף קלו. ושם) וקיימא לן התם כוותיה אע\"ג דרוב אינם נפלים וכן תוך ח' ימים בבהמה אסר התם ולא אזלינן בתר רובא התם משום שלא יבא להקל בערוה והצריכוה חליצה במת תוך שלשים ולא רצו לסמוך על הרוב להתירה לשוק בלא חליצה שלא יאמרו העולם שפיהק ומת ויבא לידי לעז וקלקול ולכך גם לענין אבילות פטור שלא יבא להקל בערוה ועוד דבלאו הכי יש להקל התם דקיימא לן הלכה כדברי המיקל באבל ואסרו כמו כן בבהמה דגזרו בהמה אטו אדם דאי לא הא לא קיימא הא אי נמי אסרו בבהמה בבריא שמא יבא להתיר בחולה שיהא קרוב לפיהק ומת וא\"ת ולר\"מ דחייש למיעוט היכי משכחת לה דמאי כיון דאיכא מיעוט עם הארץ שאין מעשרין ועוד דאיכא חזקה דטבל ומיהו אי לא חייש ר\"מ למיעוט מה\"ת אפילו היכא דאיכא חזקה בהדיה אלא מדרבנן הוה אתי שפיר ויש לומר דלא חיישינן כה\"ג למיעוט דאם הוא הוחזק כל ישראל מי הוחזקו אע\"ג דגבי כותים גזר ר\"מ על כולם משום מיעוט שנתקלקלו כדאמר בפ\"ק דחולין (דף ו.) שאני כותים דאומה אחת הן ואין נזהרין במצות כישראל:"],[9,"רישא דאיחזקה לייבום תתייבם","דסלקא דעתך השתא כמו דחזקה לשוק מהני בהדי רוב ה\"נ מהני חזקה לייבום בהדי מיעוט דמפילות ותתייבם:"]]],[["רישא חזקה לייבום ורובא לשוק וחזקה לא עדיף כי רובא ואייתי מיעוטא דמפילות סמוך לחזקה והוה ליה פלגא ופלגא לא תנשא ולא תתייבם","סיפא חזקה לשוק ורובא לשוק והוי ליה זכרים מיעוטא דמיעוטא ומיעוטא דמיעוטא לא חייש רבי מאיר:","לא תנשא ולא תתייבם וכו': ולעולם","אמר זעירי לעצמה שלשה חדשים לחברתה תשעה וחולצת ממה נפשך","רבי חנינא אמר לעצמה שלשה לחברתה לעולם ותחלוץ ממה נפשך","אביי בר אבין ורבי חנינא בר אבין אמרי תרוייהו גזירה שמא יהא ולד בן קיימא ונמצא אתה מצריכה כרוז לכהונה","וליצרכה דלמא איכא דהוי בחליצה ולא הוי בהכרזה ואמרי קשרו חלוצה לכהן","תנן ניתן לי בן במדינת הים ואמרה מת בני ואחר כך בעלי נאמנת מת בעלי ואחר כך בני אינה נאמנת וחוששין לדבריה וחולצת ולא מתייבמת","וליחוש דלמא אתו עדים ואמרי כדקאמרה ונמצא אתה מצריכה כרוז לכהונה אמר רב פפא בגרושה רב חייא בריה דרב הונא אמר באמרה אני והוא נחבאנו במערה:","\u0001מתני׳\u0002 שתי יבמות זו אומרת מת בעלי וזו אומרת מת בעלי זו אסורה מפני בעלה של זו וזו אסורה מפני בעלה של זו","לזו עדים ולזו אין עדים את שיש לה עדים אסורה ואת שאין לה עדים מותרת לזו בנים ולזו אין בנים את שיש לה בנים מותרת ואת שאין לה בנים אסורה","נתייבמו ומתו היבמין אסורות להנשא ר' אלעזר אומר הואיל והותרו ליבמין הותרו לכל אדם:","\u0001גמ׳\u0002 תנא לזו עדים ובנים ולזו לא עדים ולא בנים שתיהן מותרות","נתייבמו ומתו היבמין אסורין להנשא רבי אלעזר אומר הואיל והותרו ליבמין הותרו לכל אדם","בעי רבא מאי טעמא דרבי אלעזר משום דקסבר צרה מעידה לחברתה או דלמא משום דהיא לא מקלקלא נפשה","למאי נפקא מינה"],[[0,"רישא חזקה","מייתי לה לייבום ורובא מייתי לה להיתר שוק דרוב נשים מתעברות ויולדות והרי ילדה צרתה ונפטרה גם היא וחזקה לא עדיף כי רובא דניזיל אבתרה הלכך לא תתייבם ולשוק נמי לא כר' מאיר דחייש למיעוטא:"],[1,"סיפא חזקה לשוק","שהרי בלא יבם היתה תחלה כשיצתה ורובא לשוק דא\"נ נתעברה חמותה שמא נקבה היתה או נפל דרוב עוברים נפלים ונקבות כדאמרינן לעיל דמחצה דוולדי קיימי נקבות הוו ומיעוט עוברים נפלים הוו זכרים דקיימא מיעוטא לגבי וולדות והכא נמי איכא חזקה לרוב דמרע נמי לחששא דמיעוטא דזכרים הוו להו מיעוטא דמיעוטא:"],[2,"ולעולם","בתמיה'. תחלוץ ממה נפשך ותנשא לשוק:"],[3,"לעצמה שלשה","בשביל עצמה תמתין שלשה חדשים דכל הנשים צריכות להמתין ג' חדשים ואפי' בעלה מת במדינת הים דליכא למיחש שמא מעוברת היא דהא זקנה ואיילונית נמי צריכות להמתין שלשה חדשים כדאמרינן בהחולץ (לעיל יבמות מב:) הלכה כולן צריכות להמתין:"],[3,"לחברתה תשעה","בשביל חברתה שמא מעוברת היא צרתה צריכה להמתין ט' חדשים שאפי' חלצה לא תנשא בתוך ט' שמא חברתה מעוברת היא והולד של קיימא ואין חליצה פוטרת לזו אלא וולד פוטר והוולד אינו פוטר עד שיצא לאויר העולם:"],[4,"לחברתה לעולם","בשביל חבירתה צריכה להמתין לעולם עד שתדע אם יש לה וולד אם לאו:"],[4,"ותחלוץ","לאחר ט' ממה נפשך ותנשא אם ילדה צרתה הרי נפטרה בולד ואם לאו הרי חליצתה פוטרתה:"],[5,"מצריכה כרוז","להכריז שלא היתה חלוצה ומותרת לכהונה:"],[7,"מת בני ואח\"כ מת בעלי","והריני זקוקה ליבם כבתחלה:"],[7,"נאמנת","במה שאמרה מת בני ראשון ואח\"כ בעלי ולא חיישינן דלמא משום דרחמא ליבם קאמרה מאי טעמא הואיל ובחזקת ייבום היתה עומדת ופיה אסר עצמה על היבם כשאמרה ניתן לי בן והוא הפה יכול להתיר עצמה ליבם ולומר מת בני ראשון:"],[7,"אינה נאמנת","להנשא לשוק הואיל ובחזקת ייבום יצתה וחיישינן דלמא משום דסניא ליה קאמרה ניתן לי בן וחוששין לדבריה שמא אמת הן ואסורה לייבם וחולצת:"],[8,"כדקאמרת","דלא היתה זקוקה לו ואין חליצתה כלום ומותרת לכהונה:"],[8,"בגרושה","שהיתה גרושה כבר מאיש אחר שפסלה לכהונה עולמית:"],[8,"אני","ובני ובעלי נחבאנו במערה ואין איש עמנו לבא ולהעיד הלכך ליכא למיחש דלמא אתי סהדי:"],[9,"מתני' שתי יבמות","נשי שני אחים:"],[9,"זו אסורה","לשוק מפני בעלה של זו שהוא יבמה דשמא חי הוא וזקוקה לו ואע\"פ שאשתו אומרת מת אינה נאמנת איבמתה שתנשא על פיה שאין יבמה מעידה על חברתה שהיא אחת מחמש נשים שאין נאמנות להעידה:"],[10,"לזו עדים","שמת בעלה:"],[10,"זו שיש לה עדים אסורה","לינשא מפני יבמה דשמא חי הוא דעדים מאי אהנו לה הא היא נמי מהימנא לומר מת בעלי:"],[10,"וזו שאין לה עדים מותרת","לשוק דהא אמרה שהוא מת ובשביל יבמה נמי לא חיישינן שהרי יש עדים שמת:"],[10,"לזו בנים ולזו אין בנים","ואין עדים לא לזו ולא לזו את שיש לה בנים מותרת כו':"],[11,"נתייבמו","שהיה להם כאן שני יבמין ונתייבמו שהאשה שאמרה מת בעלי תתייבם דלענין ייבום לא הוצרכה זאת לעדותה של זו. וארישא קאי שאין להם לא עדים ולא בנים:"],[11,"ומתו היבמין אסורות להנשא","לשוק זו מפני בעלה הראשון של זו וזו מפני בעלה הראשון של זו שמא עדיין הם חיים ואע\"פ שנשאו שתיהן ליבמין בחזקת שמתו בעליהם אצל עצמן נאמנות אבל עכשיו כשינשאו לשוק נמצא עדותה של זו מועיל לזו ואין יבמות מעידות זו על זו צד היתר:"],[11,"הואיל והותרו ליבמין","בחזקת שמתו בעליהם תו לא מיתסרן דניחוש לשמא חיין הם:"],[12,"גמ' שתיהן מותרות","שאין כאן זיקת ייבום זו מפני בניה וזו בעדי חברתה:"],[14,"צרה מעידה לחברתה","דהא שתי יבמות צרות נינהו ומפני צד צרות לא נפסלו מלהעיד זו לזו:"]],[[0,"וחזקה לא עדיף מרובא","לא הוה צריך דלא עדיף דאפי' עדיף מרוב נשים מתעברות ויולדות מכל מקום יש לחוש דר\"מ חייש למיעוט אלא האמת אומר דלא עדיף מרובא:"],[0,"סמוך מיעוטא לחזקה והוה ליה פלגא ופלגא","וא\"ת דבפרק בתרא דקדושין (דף פ.) ובפרק כסוי הדם (חולין פו. ושם) גבי תינוק שנמצא בצד העיסה אמרינן סמוך מיעוטא דאין מטפחין לחזקת טהרה ואיתרע ליה רובא ומטהרין לעיסה והכא קאמר דהוי פלגא ופלגא ומחמרינן ואומר רבינו חיים דתינוק הוי דבר שאין בו דעת לישאל והוי ספיקו טהור ואפילו ברשות היחיד ולהכי איתרע ליה רובא:"],[1,"סיפא חזקה לשוק ורובא לשוק הוו להו זכרים מיעוט' דמיעוט' ולמיעוטא דמיעוטא לא חיישינן","הקשה ה\"ר אלחנן א\"כ היכי פריך מינה בפ\"ג דבכורות (דף כ: ושם) על רבי יהושע דחייש למיעוטא והכא לא חייש למיעוטא והא הכא איכא מיעוטא דמיעוטא ולהכי לא חייש ותירץ דיצתה מלאה איתרע ליה חזקה כיון שיש לה עובר במעיה ואפ\"ה לא חייש רבי יהושע וחשיב ליה כמו מיעוט כיון דת\"ק אסר ביציאתה מלאה ועוד הקשה דת\"ק דר' יהושע דאמר יצתה מלאה חוששת וחיישינן למיעוט אע\"ג דליכא חזקה בהדיה וברישא גבי האשה שהלך בעלה וצרתה למדינת הים בעי חזקה בהדי מיעוט ותירץ דודאי לא בעי חזקה בהדי מיעוט והא דנקט דבעינן ברישא חזקה בהדי מיעוטא לא בעינן הכי אלא שלא תהא חזקה מסייעתא לרוב דאז הוי המיעוט מיעוט דמיעוט וצ\"ע גבי גבינת בית אונייקי דאסר ליה ר\"מ משום דרוב עגלים נשחטים לעבודת כוכבים של אותה העיר ופריך מאי איריא רוב אפילו מיעוט נמי דר\"מ חייש למיעוט ומאי קושיא כיון דרוב עגלים אין נשחטים וחזקה דחלב בחזקת היתר אם כן איתרע ליה רובא כדאמר הכא:"],[10,"את שיש לה עדים אסורה וכו'","תימה לר\"י מאי קמ\"ל ושמא אשמעינן דלא אסרינן הא אטו הא:"],[14,"מאי טעמא דרבי אלעזר משום דקסבר צרה מעידה לחברתה כו'","תימה לר\"י אמאי לא פליג רבי אלעזר באידך פירקא (לעיל יבמות קיז.) גבי הכל נאמנים להעידה חוץ מחמותה כו' וקחשיב צרתה ויבמתה ואי ר' אלעזר איירי לבתר דאינסבא צרה מכל מקום ליפלגי גבי ההיא דמת בעלי ואח\"כ מת חמי תנשא וחמותה אסורה ור' אלעזר לא אסר כיון שנשאת הכלה ונראה לר\"י דלא דמי דלעיל ודאי שהצרה או היבמה באה להעיד על חברתה אין לה להיות נאמנת אפי' לר' אלעזר אבל הכא כל אחת אינה מתכוונה להעיד על חברתה אלא על עצמה וממילא נאמנת על צרתה כיון שאין מתכוונה להעיד על חברתה:"]]],[["לאנסובי לצרה מקמי דידה אי אמרת צרה מעידה לחברתה אף על גב דלא אינסיב מנסבינן לה לצרה אי אמרת משום דהיא לא מקלקלא נפשה אינסיב מנסבינן לה לצרה אי לא אינסיב לא מנסבינן לה","מאי תא שמע ר' אלעזר אומר הואיל והותרו ליבמין הותרו לכל אדם אי אמרת בשלמא דהיא לא מקלקלא נפשה היינו דכי אינסיב מנסבינן לה","אלא אי אמרת משום דצרה מעידה לחברתה אף על גב דלא אינסיב נמי אלא שמע מינה טעמא דרבי אלעזר משום דאינסיב הוא ולא מקלקלא נפשה","רבי אלעזר לדבריהם קאמר להו לדידי צרה מעידה לחברתה ואף על גב דלא אינסיב מנסבינן לה אלא לדידכו אודו לי מיהת דהיכא דאינסיב מנסבינן לה משום דהיא לא מקלקלא נפשה ורבנן (שופטים טז, ל) תמות נפשי עם פלשתים הוא דקעבדה","ת\"ש האשה שהלכה היא ובעלה למדינת הים ובאה ואמרה מת בעלי תנשא ותטול כתובתה וצרתה אסורה ר' אלעזר אומר הואיל והותרה היא הותרה נמי צרתה אימא הואיל והותרה ונשאת","וליחוש דלמא בגיטא אתאי והאי דקאמרה הכי לקלקלא לצרה היא מיכוונה","אי דאינסיב לישראל הכי נמי הכא במאי עסקי' דאינסיב לכהן:","\u0001מתני׳\u0002 אין מעידין אלא על פרצוף פנים עם החוטם אע\"פ שיש סימנין בגופו ובכליו אין מעידין אלא עד שתצא נפשו ואפי' ראוהו מגוייד וצלוב והחיה אוכלת בו אין מעידין אלא עד ג' ימים","ר' יהודה בן בבא אומר לא כל האדם ולא כל המקום ולא כל השעות שוין:","\u0001גמ׳\u0002 תנו רבנן פדחת ולא פרצוף פנים פרצוף פנים ולא פדחת אין מעידין עד שיהו שניהם עם החוטם אמר אביי ואיתימא רב כהנא מאי קרא (ישעיהו ג, ט) הכרת פניהם ענתה בם","אבא בר מרתא דהוא אבא בר מניומי הוה מסקי ביה דבי ריש גלותא זוזי אייתי קירא דבק בבלייתא דבק באפותיה חלף קמייהו ולא בשקרוה:","אע\"פ שיש סימנין וכו': למימרא דסימנין לאו דאורייתא","ורמינהי מצאו קשור בכיס ובארנקי ובטבעת או שנמצא בין כליו אפילו לזמן מרובה כשר","אמר אביי לא קשיא הא רבי אליעזר בן מהבאי הא רבנן דתניא אין מעידין על השומא ר' אליעזר בן מהבאי אומר מעידין מאי לאו בהא קמיפלגי דמר סבר סימנין דאורייתא ומר סבר סימנין דרבנן","אמר רבא דכולי עלמא סימנין דאורייתא הכא בשומא מצויה בבן גילו קמיפלגי מר סבר שומא מצויה בבן גילו ומר סבר אינה מצויה בבן גילו","ואיכא דאמרי הכא בשומא העשויה להשתנות לאחר מיתה קמיפלגי מר סבר עשויה להשתנות לאחר מיתה ומר סבר אינה עשויה להשתנות לאחר מיתה","ואיכא דאמרי אמר רבא דכולי עלמא סימנין דרבנן והכא בשומא"],[[0,"לאינסובי לצרה בעלמא מקמי דידה","האשה שהלכה למדינת הים עם בעלה ובאה ואמרה מת בעלי והיתה לה כאן צרה אם זו תנשא בעדותה של זו קודם שתנשא היא:"],[4,"הואיל והותרה היא","אלמא משעת היתר דידה שרינן לצרתה ואע\"ג דעדיין היא לא ניסת:"],[5,"ליחוש דלמא בגיטא אתאי","אי טעמא דר\"א לאו משום דצרה מעידה לחברתה הוא אלא משום דלא מקלקלא נפשה ניחוש דלמא הא בגיטא אתאי והחביאה גיטה ואמרה מת בעלי וכדי שתנשא גם צרתה ואיהי לא מקלקלא דבשלמא במתני' היכא דנתייבמו ליכא למימר הכי דאי נמי בגיטא אתאי איקלקלא שנשאת לאחי בעלה אבל לשוק ליחוש:"],[6,"דאינסיב לכהן","דאי אתי בעלה ומיבעי לה לאחוויי גיטא מיפסלא אכהן ונפקא:"],[7,"מתני' אין מעידים","על האיש שמת אא\"כ ראוהו מת בפרצוף פניו עם חוטמו שיכולין להכירו שזהו אבל לא ראוהו בפרצוף או שניטל חוטמו אין מעידין עליו להשיא את אשתו שמא אין הוא:"],[7,"ואפי' ראוהו מגוייד","לשון גודו אילנא (דניאל ד׳:י״א) מנותח ומלא פצעים וחבורות חרב:"],[7,"או צלוב","על הצליבה או חיה דורסתו ואוכלת בו:"],[7,"אין מעידין","עד שיראו שתצא נפשו:"],[7,"ואין מעידים אלא עד ג' ימים","אם ראוהו בתוך ג' ימים למיתתו מעידין עליו אבל אם לא ראוהו עד לאחר ג' ימים חיישינן שמא נשתנו מראית פניו ואין זה שהם סבורים:"],[8,"רבי יהודה בן בבא אומר לא כל האדם כו'","יש לך אדם שממהר להנפח משאר אדם כגון אדם שמן ויש לך מקום שחמה נוגעת בו יותר ואדם מת ממהר להסריח ולהשתנות ויש לך שעה שהעולם חם והמת ממהר להסריח. ובגמ' בעי לחומרא פליג או לקולא פליג:"],[9,"גמ' פדחת","מצח:"],[9,"הכרת פניהם ענתה בם","העידה בם. אלמא אין עדות בשאר הגוף אלא בהיכר פנים:"],[10,"קירא","שעוה:"],[10,"דבק בבלייתא","הדביקה במעט מטלית בלויה:"],[10,"בלייתא","בגד בלוי:"],[10,"באפותיה","במצחו:"],[12,"מצאו קשור","המביא גט לאשה ואבד הימנו:"],[12,"בין כליו","בין כלי ביתו ומכיר את הכיס ואת הטבעת שהן שלו כשר ולא חיישינן דלמא האי כיס והאי טבעת דאיניש אחרינא הוה והאי גט אחר הוא. אלמא סמכינן אסימנא דאית ליה בכיס ובארנקי ואפי' למישרי איסור אשת איש דאורייתא אלמא סימנין דאורייתא:"],[13,"שומא","ורוא\"ה:"],[13,"סימנין דאורייתא","אף השמלה בכלל היתה כו' בפ' ואלו מציאות (ב\"מ דף כז.):"],[14,"בן גילו","שנולד בפרק אחד ובמזל אחד ור\"א בן מהבאי סבר אין שומא מצויה בבן גילו:"],[15,"להשתנות","ממראה:"],[16,"סימנין דרבנן","ולא דריש אף השמלה לסימן אלא לתובעין דהתם פלוגתא היא:"]],[[7,"אין מעידין אלא על פרצוף פנים כו' ואין מעידין אלא עד ג' ימים","פי' משום דמשם ואילך משתנה כו' ואר\"ת דהיינו דוקא כשאין שם אלא הפרצוף אבל כל גופו שלם אפי' אין כאן פדחת וחוטם ניכר הוא היטב ע\"י סימני הגוף ועוד דשמא דוקא בסימנין הוא דקאמר הכי אבל ע\"י טביעות עין ניכר היטב ע\"י סימני הגוף כיון שיש כל גופו ואפי' לאחר כמה ימים והיכא שאינו נחבל בפנים ודאי נראה דבר פשוט שיוכלו להכירו אפי' אחר כמה ימים כי אינו משתנה כל כך ודבר ידוע הוא שהוא ניכר אפי' אחר כמה ימים אפי' הוא אמת דהיכא שנחבל בפרצוף אין מעידין עליו אלא בתוך ג' ימים כיון שנשאר גופו שלם וגם יכול להיות שהוא בתוך ג' ימים כגון היכא שאין ידוע מתי נהרג אין לתלותו אלא בתוך ג' ימים דוקא ותשובת ר\"ת כתובה בספר הישר:"],[9,"הכרת פניהם ענתה בם","פירוש שצריך פדחת של פניהם להכי מייתי האי קרא דכתיב הכרת פניהם ענתה בם דמשמע שצריך הכרה לבד מן הפנים ועל פי' הקונט' קשיא דבפ' יש בכור (בכורות מו: ושם) מייתי לה אברייתא דהכא ולא על המשנה דהתם והכא נמי משמע דאברייתא לחודה קאי דמייתי עובדא ודבק קירא באפותיה היינו על מצחו ובירושלמי דהכא משמע דאחוטם קאי:"],[12,"מצאו קשור בכיס ובארנקי כו'","וא\"ת מאי קושיא דלמא הכא שאני דמכירו לגט או לכיס בטביעות עין דאפי' עם הארץ אית ליה טביעות עין כדאמר בגט פשוט (ב\"ב קסח.) האי צורבא מרבנן דאזיל לקדושי איתתא לידבר עם הארץ בהדיה ויש לו להיות נאמן במגו שיכול לומר לא איבדתיו מעולם וי\"ל כגון דאיכא עדים שאיבדו דהשתא ליכא מגו א\"נ במצאו אחר ומחזירו ע\"י סימן זה שקשור בכיס ולהכי נקט כיס וארנקי:"],[12,"שנמצא בין כליו","ואע\"ג דרבים מצוים שם ואם נמצא בקרקע היה לחוש ליוסף בן שמעון אחר השתא שמצאו בין כליו אין לחוש שנתנו אחר שם אלא הוא:"],[16,"אמר רבא דכולי עלמא סימנין דרבנן","ואם תאמר ברייתא דמצאו קשור בכיס כמאן תוקמא וי\"ל דמעיקרא ס\"ד דאדם אחר מצאו כדפרישית ולכך בעי למיפשט מינה דסימנין דאורייתא אבל השתא סבר דמיירי שמצאו בעצמו ומכיר הכיס בטביעות עין ונאמן במגו שיוכל לומר לא אבדתיו אי נמי שיש עדים שהארנקי וכיס וטבעת שלו וידוע שם א\"נ דחשיבי כיס וטבעת סימן מובהק:"]]],[["סימן מובהק קא מיפלגי מר סבר סימן מובהק ומר סבר לאו סימן מובהק","ולהך לישנא דאמר רבא סימנין דאורייתא הא קתני אף על פי שיש סימנין בגופו ובכליו","גופו דארוך וגוץ כליו דחיישינן לשאלה ואי חיישינן לשאלה חמור בסימני אוכף היכי מהדרינן","לא שיילי אינשי אוכפא דמסקיב ליה לחמרא מצאו קשור בכיס ובארנקי ובטבעת היכי מהדרינן","טבעת חייש לזיופי כיס וארנקי מנחשי אינשי ולא מושלי ואיבעית אימא כליו בחיורי וסומקי:","ואפילו ראוהו מגוייד וכו': למימרא דמגוייד חיי ורמינהי אדם אינו מטמא עד שתצא נפשו אפילו מגוייד ואפי' גוסס טמויי לא מטמא הא מיחייא לא חיי","אמר אביי לא קשיא הא ר\"ש בן אלעזר הא רבנן דתניא מעידין על המגוייד ואין מעידין על הצלוב רבי שמעון בן אלעזר אומר אף על המגוייד אין מעידין מפני שיכול לכוות ולחיות","ומי מצית לאוקומי כר\"ש בן אלעזר והא קתני סיפא מעשה בעסיא באחד ששילשלוהו לים ולא עלתה בידם אלא רגלו ואמרו חכמים מן הארכובה ולמעלה תנשא מן הארכובה ולמטה לא תנשא","שאני מיא דמרזו מכה","והאמר רבה בר בר חנה לדידי חזי לי ההוא טייעא דשקיל ספסירא וגיידיה לגמליה ולא אפסיקתיה לנערותיה אמר אביי ההיא כחישא הויא","רבא אמר בסכין מלובנת ודברי הכל:","והחיה אוכלת וכו': אמר רב יהודה אמר שמואל לא שנו אלא ממקום שאין נפשו יוצאה אבל ממקום שנפשו יוצאה מעידין","וא\"ר יהודה אמר שמואל שחט בו שנים או רוב שנים וברח מעידין","איני והאמר רב יהודה אמר שמואל שחט בו שנים או רוב שנים ורמז ואמר כתבו גט לאשתי הרי אלו יכתבו ויתנו חי הוא וסופו למות","אלא מעתה יהא גולה על ידו אלמה תניא שחט שנים או רוב שנים הרי זה אינו גולה הא איתמר עלה אמר רב הושעיא חיישינן שמא הרוח בלבלתו אי נמי שמא איהו"],[[0,"מובהק הוא","ואע\"ג דסימנין דרבנן אסימן כי האי סמכינן אפילו אאיסור דאורייתא:"],[2,"דארוך וגוץ","לאו סימנין נינהו:"],[2,"כליו","בגדיו שמא לאחר השאילן ואותו אחר מת וראוהו אלו וסבורים שזהו בעל הבגדים:"],[2,"חמור בסימני אוכף","דקיימא לן באלו מציאות (ב\"מ דף כז.) דמהדרינן:"],[3,"לא שיילי אינשי","בעל החמור לא היה שואל אוכפו של זה לחברו:"],[3,"דמסקיב ליה","דאשי\"ר בלע\"ז:"],[3,"מצאו קשור בכיס כו'","מאי איכא למימר ליחוש אע\"פ שהוא מכיר את הכיס יש לחוש שמא השאילו לאחר וקשר בו גט זה והחזירו לזה ושכח בו את הגט:"],[4,"לזיופא","שמא יעשה חותם וצורה כנגד טבעתו וילך ויראהו לאשתו ויטול הימנה כל אשר ישאל:"],[4,"מנחשי אינשי","שלא יטול זה מזלו. ואי קשיא הא קתני או שנמצא בין כליו הא אמרן דחיישינן לשאלה לא קשיא כליו דמתניתין היינו בגדיו ודרך להשאיל מלבושים וכליו דגיטין היינו בין כלי תשמישי ביתו בתיבתו שאין דרך להשאילם:"],[4,"ואיבעית אימא כליו","דמתני' דקתני בגופו ובכליו דלא סמכינן אסימנייהו:"],[4,"בסומקי וחיורי","דלא אמרינן הוי סימן במלבושיו אי שחורין היו או לבנים היו דאין זה סימן שהרבה יש שחורין ולבנים ואדומים:"],[7,"והא קתני סיפא","דמתני' (לקמן יבמות דף קכא.):"],[7,"מן הארכובה ולמטה לא תנשא","דחיי ואי משום טביעה הואיל ומים שאין להם סוף חיישינן שמא יצא מן המים ועלה ברחוק פרסה או יותר ולא ראוהו קתני מן הארכובה ולמעלה תנשא אלמא מגוייד לא חיי:"],[8,"שאני מיא דמרזו מכה","מחזיקות ומגדלות כאב המכה. וחברו מיטרא רזיא לאילני במס' תענית (דף ג:):"],[9,"גיידיה לגמליה","לשון גודו אילנא (דניאל ד):"],[9,"ולא אפסקיה לנערותיה","ולא הפסיק לגמור את קול נערותו שהיה נוער עד שמת:"],[10,"מלובנת","באש שמתוך המכוה מתרפא:"],[12,"וברח","הנשחט:"],[13,"יכתבו ויתנו","אלמא כחי מחזקינן:"],[13,"ומשני חי הוא","לפיכך גיטו גט וסופו למות הלכך מעידין:"],[14,"אלא מעתה","הואיל וודאי ימות יהא גולה השוחטו אם נפל סכין מידו עליו ושחטו אלמה תניא אין גולה ואפילו מת שמא מחמת דבר אחר מת:"],[14,"על ידו","בשבילו:"],[14,"הרוח בלבלתו","ומחמת הרוח מת הלכך לגבי גלות פטור ומיהו לענין אשתו מעידין עליו דודאי ימות:"]],[[1,"כליו דחיישינן לשאלה","וכליו דמצא קשור דלא חיישינן לשאלה איכא למימר בכלים שאין דרכן להשאילם כמו שפירש ריב\"ן דלא חיישינן לשאלה:"],[1,"כליו דחיישינן לשאלה","ואם תאמר מצא פירות בכלי דבפ' אלו מציאות (ב\"מ דף כד:) משמע דהוי סימן ויחזיר ואמאי לא חיישינן לשאלה ויש לומר דלא חיישינן לשאלה אלא בדבר איסור אבל בממון לא חיישינן לשאלה וא\"ת א\"כ מאי פריך הכא והתם חמור בסימני אוכף היכי מהדרינן ניחוש לשאלה והא בממון לא חיישינן לשאלה וי\"ל דפשיטא ליה ודאי אפי' אי חיישינן לשאלה מן התורה אבל מדרבנן לא חיישינן לשאלה להחזיר אבדה אבל קשה היכי מפקינן מקרא דמהדרי חמור בסימני אוכף ניחוש לשאלה מן התורה מיהו למסקנא אתי שפיר דלא חיישינן לשאלה אפי' באיסור:"],[4,"איבעית אימא כליו בחיורי כו'","ולעולם לא חיישינן לשאלה וא\"ת בפרק כל הגט (גיטין כז. ושם) תנן מצאו בחפיסה או בדלוסקמא אם מכירו כשר פי' אם מכיר הגט ולמה לי שיכיר הגט אפילו אינו מכירו נמי כיון דמכיר חפיסה ודלוסקמא די בכך דהא לא חיישינן לשאלה ויש לומר דה\"פ אם מכירו לחפיסה ודלוסקמא שהם שלו כשר ואע\"ג דנקט לשון יחיד אין לחוש ואע\"ג דחפיסה הוי לשון נקבה דמפרש התם דחפיסה היא חמת קטנה מ\"מ נקט לשון זכר משום דלוסקמא דהוי לשון זכר כדתני בתוספתא עשרה דלוסקמות מלאים שטרות מסרתי לך וללישנא קמא דחיישינן לשאלה מיירי התם שידוע שכן איבדו בחפיסה ולהכי לא חיישינן לשאלה ושם אאריך בע\"ה:"],[5,"למיימרא דמגוייד חיי ורמינהו כו ' טמויי הוא דלא מטמי הא מחייא לא חיי","תימה דהא קתני בה גוסס אע\"ג דחיי דרוב גוססים למיתה ומיעוטן חיין ותנן נמי אין מעידין על הגוסס ויש לומר בגוסס שהוא מגוייד כיון שהוא גוסס על ידי אדם לא חיי ומ\"מ מוכיח שפיר דמגוייד לא חיי מדלא קתני ואפילו גוסס מגוייד ועוד אמר ר\"י לפרש דודאי פשיטא דמגוייד דמתני' מת לבסוף כיון שמגוייד במקום שעושים אותו טריפה כמו נחתך מן הארכובה ולמעלה כדמשמע בסמוך אבל אינו דבר ברור שימות קודם שיתירוה לינשא והשתא פריך ליה ממגוייד וגוסס ואותו גוסס שסופו למות הוא מת לאלתר והוא הדין נמי דמגוייד מיית לאלתר מדקתני מגוייד בהדי גוסס וא\"ת בלאו מילתיה דרשב\"א תקשי ליה רישא לסיפא וי\"ל דמעיקרא לא קשיא ליה רישא לסיפא דמצי לאוקמי רישא דאין מעידין היינו לאלתר וסיפא דתנשא היינו לאחר י\"ב חדש אבל אמילתיה דרשב\"א לא מצי לשנויי:"],[14,"אלא מעתה יהא גולה על ידו","לשמואל דחשיב ליה מת קפריך דכיון דמת הוא יש לו לגלות דס\"ד טעמא דחייב לגלות לפי שמת לאלתר אבל לא מת לאלתר לא יתחייב גלות כלל דלישנא דוימות דכתיב גבי גלות משמע ליה שמת לאלתר ולית ליה השתא הא דאמרינן בפרק אלו נערות (כתובות לג: ושם) ונקה המכה בשוגג מאי ונקה ונקה מגלות ואע\"פ שחייב מיתה במזיד אפילו לא מת זמן מרובה יש חילוק בין מיתה לגלות כי היכי דמפלגי בין דרך ירידה לדרך עלייה גבי גלות ולא גבי מיתה אבל אין לומר דמשום רוח בלבלתו או קירב מיתתו אין לנו לפוטרו כיון שמת לאלתר דהא אכתי לא ידעינן להני טעמי:"],[14,"חייישינן שמא הרוח בלבלתו","ודוקא בגלות ולא במיתה כדפרישית לעיל והא דאמר ונקה המכה מגלות הא לא הלך על משענתו אע\"פ ששהה הרבה חייב גלות איכא למימר כגון דליכא בלבול דרוח כגון בביתא דשישא ולא פירכס כלל:"]]],[["קירב מיתתו מאי בינייהו","דשחטיה בביתא דשישא ופרכיס אי נמי דשחטיה בברא ולא פרכיס:","רבי יהודה אומר לא כל וכו': איבעיא להו רבי יהודה בן בבא לקולא פליג או לחומרא פליג","תא שמע דההוא גברא דטבע בכרמי ואסקוהו אבי הדיא לבתר תלתא יומין ואנסבה רב דימי מנהרדעא לדביתהו ותו ההוא גברא דאטבע בדגלת ואסקוהו אגישרא דשביסתנא ואנסבה רבא לדביתהו אפומא דשושביני לבתר חמשה יומי","אי אמרת בשלמא לקולא פליג אינהו דעביד כרבי יהודה בן בבא אלא אי אמרת לחומרא פליג אינהו דעביד כמאן שאני מיא דצמתי","והאמרת מיא מרזו מכה ה\"מ היכא דאיכא מכה אבל היכא דליכא מכה מיצמת צמית והני מילי דכי אסקיה חזייה בשעתיה אבל אישתהי מיתפח תפח:","\u0001מתני׳\u0002 נפל למים בין שיש להן סוף בין שאין להן סוף אשתו אסורה אמר רבי מאיר מעשה באחד שנפל לבור הגדול ועלה לאחר שלשה ימים","אמר רבי יוסי מעשה בסומא שירד לטבול במערה וירד מושכו אחריו ושהו כדי שתצא נפשם והשיאו את נשותיהם ושוב מעשה בעסיא באחד ששלשלוהו לים ולא עלתה בידם אלא רגלו אמרו חכמים מן הארכובה ולמעלה תנשא מן הארכובה ולמטה לא תנשא:","\u0001גמ׳\u0002 תנו רבנן נפל למים בין שיש להם סוף בין שאין להם סוף אשתו אסורה דברי רבי מאיר וחכ\"א מים שיש להם סוף אשתו מותרת ושאין להם סוף אשתו אסורה","היכי דמי מים שיש להם סוף אמר אביי כל שעומד ורואה מארבע רוחותיו","ההוא גברא דטבע באגמא דסמקי אנסבה רב שילא לדביתהו אמר ליה רב לשמואל תא נשמתיה אמר ליה נשלח ליה ברישא","שלחו ליה מים שאין להם סוף אשתו אסורה או מותרת שלח להו אשתו אסורה ואגמא דסמקי מים שיש להם סוף או מים שאין להם סוף שלח להו מים שאין להם סוף הוא ומר מאי טעמא עבד הכי","מיטעא טעינא אנא סברי כיון דקוו וקיימי כמים שיש להם סוף דמי ולא היא כיון דאיכא גלי אימור גלי אשפלו","קרי שמואל עליה דרב (משלי יב, כא) לא יאונה לצדיק כל און קרי רב עליה דשמואל (משלי יא, יד) ותשועה ברוב יועץ","תניא אמר רבי מעשה בשני בני אדם מכמרין מכמורין בירדן ונכנס אחד מהם למחילה של דגים ושקעה חמה ולא ראה פתחה של מחילה ושהה חברו כדי שתצא נפשו ובא והודיע בתוך ביתו למחר זרחה חמה והכיר פתחה של מחילה ובא ומצא הספד גדול בתוך ביתו אמר רבי כמה גדולים דברי חכמים שאמרו מים שיש להם סוף אשתו מותרת שאין להם סוף אשתו אסורה","אי הכי מים שיש להם סוף נמי ליחוש למחילה של דגים במים שיש להם סוף מחילה של דגים לא שכיחא","אמר רב אשי הא דאמרו רבנן מים שאין להם סוף אשתו אסורה הני מילי באיניש דעלמא אבל צורבא מרבנן לא אי דסליק קלא אית ליה ולא היא לא שנא איניש דעלמא ולא שנא צורבא מרבנן דיעבד אין לכתחלה לא","תניא אר\"ג פעם אחת הייתי מהלך בספינה וראיתי ספינה אחת שנשברה והייתי מצטער על תלמיד חכם שבה ומנו רבי עקיבא וכשעליתי ביבשה בא וישב ודן לפני בהלכה אמרתי לו בני מי העלך אמר לי דף של ספינה נזדמן לי וכל גל וגל שבא עלי נענעתי לו ראשי","מכאן אמרו חכמים אם יבואו רשעים על אדם ינענע לו ראשו אמרתי באותה שעה כמה גדולים דברי חכמים שאמרו מים שיש להם סוף מותרת מים שאין להם סוף אסורה","תניא א\"ר עקיבא פעם אחת הייתי מהלך בספינה וראיתי ספינה אחת שמטרפת בים והייתי מצטער על תלמיד חכם שבה ומנו רבי מאיר כשעליתי למדינת קפוטקיא בא וישב ודן לפני בהלכה אמרתי לו בני מי העלך אמר לי גל טרדני לחברו וחברו לחברו עד שהקיאני ליבשה אמרתי באותה שעה כמה גדולים דברי חכמים שאמרו מים שיש להם סוף אשתו מותרת מים שאין להם סוף אשתו אסורה","תנו רבנן נפל לגוב אריות אין מעידין עליו לחפורה מלאה נחשים ועקרבים מעידין עליו רבי יהודה בן בתירא אומר אף לחפורה מלאה נחשים ועקרבים אין מעידין עליו חיישינן"],[[0,"קירב מיתתו","על ידי שפירכס יותר מדאי מת הלכך אין גולה אלא אם כן מת תחת ידו:"],[1,"בביתא דשישא","שאין שם רוח. ללישנא דרוח בלבלתו הכא גולה דאין כאן רוח ומחמתו מת וללישנא דהוא קירב את מיתתו אינו גולה:"],[1,"","הכי גרסינן אי נמי בדברא ולא פירכס:"],[2,"לקולא פליג","דקאמר תנא קמא אין מעידין אלא עד ג' ימים ואתא רבי יהודה למימר יש לך אדם או מקום או שעה שאינו מהיר לנפוח ולהשתנות ויכול להעיד אפי' לאחר ג' ימים:"],[2,"או לחומרא פליג","דקאמר תנא קמא עד שלשה ימים מעידים ואתא איהו למימר פעמים שאפי' תוך שלשה אין מעידין:"],[3,"בכרמי","שם העיר:"],[3,"","ואסקוהו אבי הדיא לבתר תלתא יומין:"],[3,"ואסקוהו אגישרא דשביסתנא","לאחר חמשה יומין:"],[4,"דצמתי","צומתין צורת הפנים ואין מניחין אותו לנפוח ולהשתנות:"],[5,"היכא דאיכא מכה","מקום המכה מרזו מכבידין הכאב ונופח:"],[5,"מיתפח תפח","לאחר שמעלין אותו ליבשה ומשתנית צורתו:"],[6,"מתני' שיש להם סוף","לקמן מפרש היכי דמי:"],[6,"אשתו אסורה","שמא לאחר פרישתו משם יצא והלך לו דסבר רבי מאיר אדם יכול לחיות ולשהות במים יום או יומים:"],[7,"מערה","מים שיש להם סוף הם ופליג ר' יוסי ואמר אשתו מותרת דקסבר אין אדם יכול לשהות במים כל כך ואי משום שמא יצא לאלתר אין זו חששא דהא אי נפק הוו חזו ליה אבל במים שאין להם סוף מודה ר' יוסי דאסורה שמא יצא לאלתר למרחוק ולא ראוהו:"],[7,"מן הארכובה ולמטה","הואיל ויכול לחיות לא תנשא שמא יצא ולא ראוהו דמים שאין להם סוף הן:"],[9,"גמ' מארבע רוחותיה","כגון מערה מלאה מים והרואה שנפל שוהה שם בכדי שאין יכול להיות חי בתוך המים ובא לו:"],[10,"אגמא דסמקי","אגם של אותו מקום אגם מרש\"ט בלע\"ז עומד במקומו ואינם מים חיים:"],[12,"כמים שיש להם סוף דמו","שאינו יכול לשוט על פניהם למרחוק הלכך אם איתא דסליק הוי חזו ליה:"],[12,"גלי אשפלו","למקום רחוק ומשם יצא:"],[13,"לא יאונה לצדיק כל און","שלא באתה תקלה זו לידו של רב לנדות את רב שילא:"],[13,"תשועה ברוב יועץ","תשועתי מן המכשול על ידי שנטלתי עצה משמואל:"],[14,"למחילה של דגים","שחוטטים סמוך לשפת הנהר בין למטה מן המים בין למעלה מן המים בגובה שפתו ואין מתמלאת כולה ואדם הנכנס שם מגביה צוארו בתוך המערה למעלה מן המים:"],[15,"ליחוש למחילה","ושמא ליום מחר יצא והלך:"],[17,"נענעתי לו ראשי","ועבר על גבי והלך לו:"],[18,"ינענע לו ראשו","ידחה מפני השעה ולא יתגרה בהן:"]],[[2,"לקולא פליג או לחומרא פליג","והכי נמי מצי למיבעי בין לקולא ובין לחומרא אלא אכתי לא פשיטא מאי דבעי:"],[16,"ולא היא לא שנא צורבא מרבנן כו'","ואף על גב דרובייהו צורבא מרבנן אי סליק קלא אית ליה מכל מקום לא חיישינן לאותו רוב ולא תנשא לכתחלה כמו גבי (רוב) גוססין דאין מעידין עליהן אף על פי שרובן מתים:"]]],[["שמא חבר הוא ות\"ק אגב איצצא מזקי ליה","תנו רבנן נפל לתוך כבשן האש מעידין עליו ליורה מלאה יין ושמן מעידין עליו משום רבי אחא אמרו של שמן מעידין עליו מפני שהוא מבעיר של יין אין מעידין עליו מפני שהוא מכבה אמרו לו תחלתו מכבה וסופו מבעיר:","א\"ר מאיר מעשה באחד שנפל לבור הגדול וכו': תניא אמרו לו לרבי מאיר אין מזכירין מעשה נסים מאי מעשה נסים אילימא דלא אכיל ולא אישתי והכתיב (אסתר ד, טז) וצומו עלי ואל תאכלו ואל תשתו","אלא דלא ניים דאמר רבי יוחנן שבועה שלא אישן שלשה ימים מלקין אותו ויישן לאלתר","ורבי מאיר מאי טעמא אמר רב כהנא כיפין על גב כיפין הוו ורבנן דשישא הוו ור\"מ א\"א דלא מסריך וניים פורתא","ת\"ר מעשה בבתו של נחוניא חופר שיחין שנפלה לבור הגדול ובאו והודיעו לרבי חנינא בן דוסא שעה ראשונה אמר להם שלום שניה אמר להם שלום שלישית אמר להם עלתה","אמר לה בתי מי העלך אמרה לו זכר של רחלים נזדמן לי וזקן מנהיגו אמרו לו נביא אתה אמר להם לא נביא אנכי ולא בן נביא אנכי אלא דבר שהצדיק מתעסק בו יכשל בו זרעו","אמר רבי אבא אע\"פ כן מת בנו בצמא שנאמר (תהלים נ, ג) וסביביו נשערה מאד מלמד שהקדוש ברוך הוא מדקדק עם סביביו כחוט השערה ר' חנינא אמר מהכא (תהלים פט, ח) אל נערץ בסוד קדושים רבה ונורא על כל סביביו:","\u0001מתני׳\u0002 אפילו שמע מן הנשים אומרות מת איש פלוני דיו ר' יהודה אומר אפי' שמע מן התינוקות אומרים הרי אנו הולכין לספוד ולקבור את איש פלוני בין שהוא מתכוין ובין שאינו מתכוין","ר' יהודה בן בבא אומר בישראל אע\"פ שהוא מתכוין ובעובד כוכבים אם היה מתכוין אין עדותו עדות:","\u0001גמ׳\u0002 ודלמא לא אזלי אמר רב יהודה אמר שמואל דקאמרי הרינו באין מלספוד ומלקבור את איש פלוני","ודלמא קמצא בעלמא שכיב ליה ואסיקו ליה על שמיה דקאמרי כן וכן רבנן הוו התם כן וכן ספדני הוו התם:","ובעובד כוכבים אם היה מתכוין וכו': אמר רב יהודה אמר שמואל לא שנו אלא שנתכוין להתיר אבל נתכוין להעיד עדותו עדות היכי ידעינן אמר רב יוסף בא לבית דין ואמר איש פלוני מת השיאו את אשתו זהו נתכוין להתיר מת סתם זהו נתכוין לעדות","איתמר נמי אמר ריש לקיש לא שנו אלא שנתכוין להתיר אבל נתכוין להעיד עדותו עדות אמר ליה ר' יוחנן לא כך היה מעשה באושעיא ברבי שהתירם עם שמנים וחמשה זקנים אמר להם לא שנו אלא שנתכוין להתיר אבל נתכוין להעיד עדותו עדות ולא הודו לו חכמים","אלא מתניתין דקתני ובעובד כוכבים אם היה מתכוין אין עדותו עדות היכי משכחת לה במסיח לפי תומו כי ההוא דהוה קאמר ואזיל מאן איכא בי חיואי מאן איכא בי חיואי שכיב חיואי ואנסבה רב יוסף לדביתהו ההוא דהוה קאמר ואזיל ווי ליה לפרשא זריזא דהוה בפומבדיתא דשכיב ואנסבה רב יוסף ואיתימא רבא לדביתהו","ההוא דהוה קאמר ואזיל מאן איכא בי חסא טבע חסא אמר רב נחמן האלקים אכלו כוורי לחסא מדיבוריה דרב נחמן אזלא דביתהו דחסא ואינסבא ולא אמרו לה ולא מידי אמר רב אשי שמע מינה הא דאמור רבנן מים שאין להם סוף אשתו אסורה הני מילי לכתחלה אבל אי נסיב לא מפקינן לה מיניה","איכא דאמרי אנסבה רב נחמן לדביתהו אמר חסא גברא רבה איתיה אם איתא דסליק קלא אית ליה למילתא ולא היא לא שנא גברא רבה לא שנא לאו גברא רבה דיעבד אין לכתחלה לא:","ההוא עובד כוכבים דהוה קאמר ליה לישראל קטול אספסתא ושדי לחיואי בשבתא ואי לא קטילנא לך כדקטילנא לפלוני בר ישראל דאמרי ליה בשיל לי קדירה בשבת ולא בשיל לי וקטילתיה שמעה דביתהו ואתאי לקמיה דאביי שהיתא"],[[0,"שמא חבר הוא","יודע ללחוש:"],[0,"אגב איצצא","שדוחקן כשעומד עליהם. אבל גוב אריות רחב הוא ואין עומד עליהן ופעמים שאינם רעבים ואין אוכלין אותו:"],[1,"ליורה מלאה יין ושמן","מרותחת על האור:"],[1,"שהוא מבעיר","כשנפל אדם לתוכו וניתז השמן על האור ומבעירו יותר ויותר ולא שבתה רתיחת היורה וצמקו רגליו ולא יכול לצאת ומת:"],[1,"מפני שהוא מכבה","כשניתז על האור כיבהו. ואע\"פ שלא יכול לצאת לא מת שהיורה נתקררה לאחר זמן ששבתו רתיחותיה כשכבה האש:"],[1,"וסופו מבעיר","דרך בקעת שמכבין אותה במים להיות חוזרת ודולקת יותר מבתחלתה:"],[2,"מעשה נסים","אפילו אינו מת מחמת המים היה לו למות מחמת דבר אחר:"],[4,"כיפין על גבי כיפין","כיפין כמין בנינים ואולמות ונשען עליהן וישן:"],[4,"דשישא הוי","וחלקין ומעומד אין אדם ישן:"],[4,"מסריך","מתחזק ונדבק עליהן מעט:"],[5,"חופר שיחין","לעולי רגלים ומים מתכנסים בהן והיו שותין הן ובהמתן:"],[5,"שלום","שעדיין יכולה לחיות וכן בשניה אבל שלישית שאינה יכולה לחיות אמר להן עלתה לה שידוע היה לו שלא תמות שם כדלקמן דבר שהיה מתעסק בו אותו צדיק אביה לא יכשל בו זרעו:"],[6,"של רחלים","זה אילו של יצחק:"],[6,"זקן אחד מנהיגו","זה אברהם:"],[6,"נביא אתה","לידע שלא תמות:"],[6,"מתעסק בו","בטורח עשייתו:"],[7,"אע\"פ כן מת בנו","של ר' נחוניא בצמא שכך דרכו של מקום לדקדק עם החסידים:"],[7,"וסביביו נשערה","לשון חוט השערה. עם סביביו עם צדיקים ההולכים אחריו:"],[8,"מתני' אפילו שמע מן הנשים","שלא היו מתכוונות להעיד ומסיחות לפי תומן:"],[8,"דיו","ויכול לילך להעיד ולהשיא את אשתו:"],[8,"בין שהוא מתכוין","לעדות:"],[11,"גמ' קמצא בעלמא","חגב או נמלה המיתו התינוקות והעלו לה שם איש פלוני כדרך שהתינוקות משחקין:"],[12,"אבל נתכוין להעיד","ולא להתיר את אשתו:"],[12,"עדותו עדות","ותנשא אשתו:"],[14,"היכי משכחת לה","דלא נתכוין להעיד ולא להתיר:"],[14,"חיואי","שם האיש:"],[14,"מאן איכא בי חיואי","מי מאנשי ביתו של בית חיואי שישמע דברי דשכיב חיואי:"],[14,"לפרשא זריזא","גבור חיל וישראל היה:"],[15,"מדיבוריה דרב נחמן","דאמר אכלוה כוורי ולא אמר מי יתן שיעלה וינצל אזלא דביתהו ואינסבא:"],[17,"קטול אספסתא ושדי","קצוץ שחת לבהמותי:"],[17,"שמעה דביתהו","דההוא דאמר עובד כוכבים עליה קטילתיה ואתת לקמיה דאביי:"]],[[1,"אמרו לו תחלתו מכבה וסופו מבעיר","אית דגרסי לעיל ליורה מלאה יין ושמן אין מעידין עליו והוי האי תנא שלישי ולספרים דגרסי לעיל מעידין עליו הוי תנא קמא וכן פר\"ח דתנא דסיפא לא פליג אתנא קמא אלא מפרש טעמא דמילתיה:"],[2,"אין מזכירין מעשה נסים","תימה לר\"י והא קאמר לעיל נפל לגוב אריות אין מעידים עליו וכן מים שאין להם סוף וי\"ל דאינו ממש מעשה נסים אלא יש לתלות שאינם רעבים ובמים שאין להם סוף יש לתלות בדף של ספינה וגל טורד ומיהו יש בירושל' נפל לגוב של אריות אין מעידין עליו שמא נעשה לו נס כדניאל נפל לכבשן של אש אין מעידין עליו חוששין שמא נעשה לו נס כחנניה מישאל ועזריה רוצה לומר שנפל באש וברח לו מן האש בשום ענין ור' מאיר חולק אברייתא דלעיל:"],[7,"אף על פי כן מת בנו בצמא","מכל מקום לא הוי דבר שנצטער בו הצדיק שלא עשה הבור:"],[10,"הרי אנו באין מלספוד כו'","ומתני' הכי פירושא הרי אנו הולכין לביתינו שבאנו מלספוד:"]]],[["תלתא ריגלי אמר לה רב אדא בר אהבה זיל לקמיה דרב יוסף דחריף סכינא","אזלה קמיה פשט מהא מתניתין עובד כוכבים שהיה מוכר פירות בשוק ואמר פירות הללו של ערלה הן של עזיקה הן של נטע רבעי הן לא אמר כלום לא נתכוון אלא להשביח מקחו","אבא יודן איש ציידן אמר מעשה בישראל ועובד כוכבים שהלכו בדרך ובא עובד כוכבים ואמר חבל על יהודי שהיה עמי בדרך שמת בדרך וקברתיו והשיאו אשתו","ושוב מעשה בקולר של בני אדם שהיו מהלכין לאנטוכיא ובא עובד כוכבים אחד ואמר חבל על קולר של בני אדם שמתו וקברתים והשיאו את נשותיהם ושוב מעשה בששים בני אדם שהיו מהלכין לכרכום ביתר ובא עובד כוכבים ואמר חבל על ששים בני אדם שהיו מהלכין בדרך ביתר שמתו וקברתים והשיאו את נשותיהם:","\u0001מתני׳\u0002 מעידין לאור הנר ולאור הלבנה ומשיאין על פי בת קול מעשה באחד שעמד על ראש ההר ואמר איש פלוני בן פלוני ממקום פלוני מת הלכו ולא מצאו שם אדם והשיאו את אשתו","ושוב מעשה בצלמון באחד שאמר אני איש פלוני בן איש פלוני נשכני נחש והרי אני מת והלכו ולא הכירוהו והלכו והשיאו את אשתו:","\u0001גמ׳\u0002 אמר רבה בר שמואל תנא בית שמאי אומרים אין משיאין על פי בת קול וב\"ה אומרים משיאין על פי בת קול מאי קמ\"ל מתני׳ היא הא קמ\"ל דאי משתכחת סתמא דאין משיאין בית שמאי היא:","והלכו ולא מצאו: ודלמא שד הוה א\"ר יהודה אמר רב שראו לו דמות אדם אינהו נמי דמו דחזו ליה בבואה","ואינהו נמי אית להו בבואה דחזו ליה בבואה דבבואה ודלמא לדידהו אית להו בבואה דבבואה אמר רבי חנינא אמר לי יונתן שידא בבואה אית להו בבואה דבבואה לית להו","ודלמא צרה הואי תנא דבי רבי ישמעאל בשעת הסכנה כותבין ונותנין אף על פי שאין מכירין:","\u0001מתני'\u0002 אמר רבי עקיבא כשירדתי לנהרדעא לעבר השנה מצאתי נחמיה איש בית דלי אמר לי שמעתי שאין משיאין את האשה בארץ ישראל על פי עד אחד אלא יהודה בן בבא ונומיתי לו כן הדברים אמר לי אמור להם משמי אתם יודעים שהמדינה משובשת בגייסות מקובלני מר\"ג הזקן שמשיאין את האשה על פי עד אחד","וכשבאתי והרציתי הדברים לפני ר\"ג שמח לדברי ואמר מצאנו חבר לרבי יהודה בן בבא","מתוך הדבר נזכר ר\"ג שנהרגו הרוגים בתל ארזא והשיא ר\"ג נשותיהן על פי עד אחד והוחזקו להיות משיאין עד מפי עד מפי עבד מפי אשה מפי שפחה ר' אליעזר ורבי יהושע אומרים אין משיאין את האשה על פי עד אחד ר' עקיבא אומר לא ע\"פ אשה ולא על פי עבד ולא על פי שפחה ולא על פי קרובים:","\u0001גמ׳\u0002 וסבר רבי עקיבא ע\"פ אשה לא והתניא רבי שמעון בן אלעזר אומר משום רבי עקיבא אשה נאמנת להביא גיטה מק\"ו ומה נשים שאמרו חכמים אין נאמנות לומר מת בעלה נאמנות להביא גיטיהן זו שנאמנת לומר מת בעלה אינו דין שנאמנת להביא גיטה","נשים שאמרו חכמים הוא דלא מהימני אשה בעלמא מהימנא לא קשיא כאן קודם שהחזיקו כאן לאחר שהחזיקו:","\u0001מתני׳\u0002 אמרו לו מעשה בבני לוי שהלכו לצוער עיר התמרים וחלה אחד מהם והביאוהו בפונדק ובחזרתם אמרו לפונדקית איה חברנו נומית להם מת וקברתיו והשיאו את אשתו ולא תהא כהנת כפונדקית","אמר להו לכשתהא כפונדקית נאמנת הפונדקית הוציאה להם מקלו ותרמילו וספר תורה שהיה בידו:"],[[0,"תלתא ריגלי","שהיו תלמידי חכמים נקבצים לשמוע דרשה הלכות פסח בפסח והיתה שואלת מהם. ובתשובת הגאונים מצאתי כל הנך ריגלי דאמוראי היינו יום שמת בו אדם גדול קובעים אותו לכבודו ומדי שנה בשנה כשמגיע אותו יום מתקבצים תלמידי חכמים מכל סביביו ובאים על קברו עם שאר העם להושיב ישיבה שם:"],[1,"של ערלה הן","פירות נטיעה הן וישנם משובחים מפירות אילן זקן:"],[1,"של עזיקה","מפרדס מעוזק וגדר סביב לו לשומרו והיא שנת שביעית. וקשיא לי דמאי איסור יש כאן אם עבר זמן הביעור לא שנא מן המשומר ול\"ש מן המופקר אסורים וקודם הזמן אלו ואלו מותרים:"],[1,"לא אמר כלום","לאוסרם על כך אלא הלך אחר הרוב שזה משקר ולהשביח מקחו נתכוין וכן נטע רבעי להודיע שפירות נטיעה הן. וכמדומה לי דהאי עזיקה שם העיר שבארץ ישראל ופירותיה משובחים ואם היה עובד כוכבים זה בחוצה לארץ ומשבחם ואמר מעזיקה הבאתי אין חוששין לומר אמת דבריו ושמא לא נתעשרו וישראל מכרם לו אלא להשביח מקחו. והכא נמי לא נתכוין עובד כוכבים זה אלא לאיים על זה שיקצור לו מספוא לבהמותיו:"],[2,"חבל","הפסד ועגמת נפש הוא:"],[3,"קולר","חבורה:"],[3,"לכרכום ביתר","כשבאה ביתר במצור:"],[4,"מתני' על פי בת קול","שמעו קול צועקת פלוני מת ולא ראו אדם בצלמו:"],[6,"גמ' מאי קמ\"ל","רבה בר שמואל דלבית הלל משיאין וניעבד כותייהו סתם מתני' נמי הכי אמרה וממילא הלכתא היא כסתם משנה:"],[6,"בית שמאי היא","ואין הלכה כאותו סתם:"],[7,"שראו לו דמות אדם","מתחלה כשצעק:"],[8,"בבואה דבבואה","צל צלו:"],[8,"לימדני יונתן שידא","שד היה או בקי בהן:"],[9,"ודלמא צרה הואי","שנשא אשה במקום אחר ובאה לקלקלה והלכה לה:"],[9,"בשעת הסכנה","שאדם מסוכן כגון מי שהיה מושלך בבור ואמר כל שומע קולו יכתוב גט לאשתו כותבין ונותנין וסמכינן עליה בכל דבריו שאומר אני הוא פלוני בן פלוני. והכא נמי כשעת הסכנה דמיא שאם לא תאמין לזה לא תמצא אחר ותשב עגונה:"],[10,"מתני' ונומיתי לו","אמרתי לו:"],[10,"כן","הן הדברים שאמרת שכולן חלוקין עליו:"],[10,"משובשת בגייסות","שאיני יכול לילך אצלם ולהעיד זה ששמעתי:"],[13,"גמ' להביא את גיטה","ממדינת הים ואע\"פ שצריכים אנו למאמר פיה שתאמר בפני נכתב ונחתם דאפי' אדם כשר הביאו צריך לומר כן:"],[13,"נשים שאמרו","חמש נשים דפירקין דלעיל (יבמות ד' קיז.):"],[13,"נאמנות להביא גיטה","בפ\"ב דגיטין (דף כג:):"],[15,"מתני' אמרו לו","לרבי עקיבא מעשה בבני לוי כו':"],[15,"נומית להם","אמרה להם:"],[15,"ולא תהא כהנת","כלומר וכי לא תהא בת ישראל או כהנת מיוחסת נאמנת כפונדקית זו גרועה. ובגמ' מפרש מאי גריעותא:"],[16,"אמר להם","רבי עקיבא:"],[16,"לכשתהא הפונדקית נאמנת","כלומר לכשימצא דבר זה אמת שהאמינו את הפונדקית שהרי לא עליה סמכו אלא לפי תומה הסיחה והביאה להם מקלו ותרמילו:"],[16,"[ס\"א לכשתהא כפונדקית נאמנת","כלומר באותו ענין שהאמינו פונדקית הוי נמי שאר אשה נאמנת שהרי פונדקית הוציאה להן ועל הסימנים סמכו]:"]],[[1,"של עזיקה","פי' בקונטרס מפרדס מעוזק ומשומר ושביעית הוא וקשה לו אי (משומר) קודם הביעור לעולם מותר ואין נראה לר\"ת דהא בהדיא תניא בת\"כ ואת ענבי נזיריך לא תבצור מן המשומר אי אתה בוצר אבל אתה בוצר מן המופקר וא\"ת דתניא בת\"כ ובפרק הבית והעליה (ב\"מ קיח.) שומרי ספיחים נוטלין שכרן מתרומת הלשכה קרי כאן ממשקה ישראל מן המותר לישראל ומשומר אסור לישראל כו' כדפי' ואר\"י שלא היו שומרין אותו אלא מונעים רגלי בהמה משם ומודיעין לבני אדם שהם לצורך ומופקר נמי לא שרי לבצור אלא ע\"י שינוי ובת\"כ דקתני מן המשומר אי אתה בוצר היינו אפי' על ידי שינוי ומן המופקר אתה בוצר היינו כלומר אוכל:"],[7,"דחזו ליה בבואה","בירושלמי רבי אחא בר חנינא בשם רבי חמא הדא דתימא בשדה אבל בעיר אפילו לא ראו בבואה של אדם והא תניין מי שהיה מושלך בבור ואמר מי ששומע קולו יכתוב גט לאשתו הרי אלו יכתבו ויתנו וא\"ר נתן והוא שראה בבואה של אדם אמר רבי בון מזיקין מצויין בבורות כדרך שהם מצויין בשדות והא דאמר (מגילה ד' ג.) אל יתן אדם שלום לחברו בלילה דחיישינן שמא שד הוא היינו בשדה דומיא דיהושע שהיה חוץ למחנה ישראל בירושלמי פליגי אמוראי בנמצא כתוב בשטר מת פלוני או נהרג אם משיאין את אשתו:"]]],[["\u0001גמ׳\u0002 מאי גריעותא דפונדקית אמר רב כהנא פונדקית עובדת כוכבים היתה ומסיחה לפי תומה היתה זה מקלו וזה תרמילו וזה קבר שקברתיו בו וכן תני אבא בריה דרב מניומי בר חייא פונדקית עובדת כוכבים היתה ומסיחה לפי תומה היתה זה מקלו וזה תרמילו וזה קבר שקברתיו בו","והא איה חברנו קאמרי לה כיון דחזיתינהו בכיא אמרו לה איה חברנו אמרה להם מת וקברתיו","תנו רבנן מעשה באדם אחד שבא להעיד על האשה לפני רבי טרפון אמר לו בני היאך אתה יודע בעדות אשה זו אמר אני והוא היינו הולכים בדרך ורדף אחרינו גייס ונתלה בייחור של זית ופשחו והחזיר את הגייס לאחוריו","אמרתי לו אריה יישר כחך אמר לי מנין אתה יודע שאריה שמי כך קורין אותי בעירי יוחנן ברבי יהונתן אריה דמכפר שיחיא לימים חלה ומת והשיא רבי טרפון את אשתו","ורבי טרפון לא בעי דרישה וחקירה והתניא מעשה באדם אחד שבא לפני רבי טרפון להעיד עדות אשה אמר לו בני היאך אתה יודע עדות זו אמר לו אני והוא היינו הולכין בדרך ורדף אחרינו גייס ונתלה בייחור תאנה ופשחו והחזיר את הגייס לאחוריו אמרתי לו יישר כחך אריה אמר לי יפה כוונת לשמי שכך קורין אותי בעירי יוחנן בן יונתן אריה דמכפר שיחיא לימים חלה ומת","אמר לו לא כך אמרת לי יוחנן בן יונתן דמכפר שיחיא אריה אמר ליה לא אלא כך אמרתי לך יוחנן בן יונתן אריה דמכפר שיחיא ודקדק עליו שנים ושלשה פעמים וכיון את דבריו והשיא רבי טרפון את אשתו","תנאי היא דתניא אין בודקין עדי נשים בדרישה וחקירה דברי ר\"ע רבי טרפון אומר בודקין","וקמיפלגי בדר' חנינא דאמר רבי חנינא דבר תורה אחד דיני ממונות ואחד דיני נפשות בדרישה וחקירה שנאמר (ויקרא כד, כב) משפט אחד יהיה לכם","ומה טעם אמרו דיני ממונות אין צריכין דרישה וחקירה שלא תנעול דלת בפני לוין","ובמאי קמיפלגי מר סבר כיון דאיכא כתובה למשקל כדיני ממונות דמי ומר סבר כיון דקא שרינן אשת איש לעלמא כדיני נפשות דמי","אמר רבי אלעזר אמר רבי חנינא תלמידי חכמים מרבים שלום בעולם שנאמר (ישעיהו נד, יג) וכל בניך למודי ה' ורב שלום בניך:","\u0001הדרן עלך האשה בתרא וסליקא לה מסכת יבמות\u0002"],[[1,"והא איה חבירנו קאמרי לה","אלמא לאו לפי תומה הוה:"],[1,"הוה בכיא","והיינו לפי תומה דקודם ששאלוה התחילה לומר:"],[2,"ונתלה בייחור של תאנה","אחז בנוף של תאנה ופשחו לעשות ממנו מקל:"],[2,"פשחו","נתקו:"],[4,"יישר כחך אריה","גבור חיל ולב אריה יש לך:"],[4,"יפה כוונת את שמי אריה","שכך קורין אותי בעירי:"],[5,"לא כך אמרת לי יוחנן בן יונתן","דורש וחוקר היה אולי יהפוך את דבריו לא כך אמרת לי דמכפר שיחיא אריה שהכפר היו קורין אריה ולא אותו:"],[6,"דרישה","בדיקות כי האי גוונא לכוין את דבריו:"],[6,"וחקירה","באיזה יום ובאיזה שעה:"],[7,"משפט אחד יהיה לכם","וכיון דאשכחן דכתיב בדיני נפשות ודרשת וחקרת וגו' (דברים יג) הוא הדין לדיני ממונות:"],[9,"כיון דאיכא כתובה למשקל","כשתנשא על פיהם תטול כתובה דמספר כתובה נלמוד כשתנשאי לאחר תטלי מה שכתוב ליכי:"],[9,"כדיני נפשות דמי","דהבא על אשת איש בחנק הלכך עדי נשים בדרישה וחקירה:"],[10,"","הכי גרסינן אמר ר' אלעזר אמר רבי חנינא תלמידי חכמים מרבים שלום בעולם שנאמר וכל בניך למודי ה' ורב שלום בניך:"]],[[0,"פונדקית עובדת כוכבים (אחת) היתה ומסיחה לפי תומה","וא\"ת מאי מייתו רבנן ראיה מן הפונדקית דהא מסיחה לפי תומה היתה ויש לומר דלא היתה ממש מסיחה לפי תומה דמה שהוציאה מקלו ותרמילו (מה) [זה] היתה יכולה לעשות כן לעדות ור' עקיבא אמר להם כי אין זה ראיה דודאי אין לך מסיח לפי תומה גדול מזה כיון דכי [חזיתינהו] בכיא כן משמע קצת בירושלמי דקאמר עשו אותה כמסיחה לפי תומה משמע שלא היתה ממש מסיחה לפי תומה אלא שמביאין ראיה דלא גרעה מעד אחד:"],[6,"אין בודקין עדי נשים בדרישה וחקירה","פירש רבינו חננאל דקיימא לן כהאי תנא דלא בעי דרישה וחקירה:"]]]]};
